/* 注译分片 1: {键: 条目} — 懒加载后并入 window.POEM_NOTES */
window.POEM_NOTES_1={"酒泉子·长忆观潮|潘阆":{"y":"常常回忆观潮的情景，满城的人争着到江上眺望。潮水来时，怀疑沧海全都空了，万面鼓声中。\n弄潮儿站在浪头上，手举红旗，红旗不被水打湿。离别后几次在梦中看到，梦醒还心有余悸。","s":"《酒泉子·长忆观潮》是潘阆的名作，描写了钱塘江大潮的壮观景象。“来疑沧海尽成空，万面鼓声中”以夸张手法写出了潮水的磅礴气势，“弄潮儿向涛头立，手把红旗旗不湿”写出了弄潮儿的英勇。全词气势磅礴，是宋词中少有的描写大潮的作品。"},"苏幕遮·碧云天|范仲淹":{"y":"云天蓝碧，黄叶落满地，天边秋色与秋波相连，波上弥漫着空翠略带寒意的秋烟。远山沐浴着夕阳天空连接着江水。不解思乡之苦的芳草，一直延伸到夕阳之外的天际。\n默默思念故乡黯然神伤，缠人的羁旅愁思难以排遣，每天夜里除非是美梦才能留人入睡。当明月照射高楼时不要独自依倚，端起酒来洗涤愁肠，可是都化作相思的眼泪。","s":"《苏幕遮·碧云天》是范仲淹的代表作，“碧云天，黄叶地”是千古传诵的写景名句，王实甫《西厢记》中“碧云天，黄花地”即由此化用。“酒入愁肠，化作相思泪”将相思之情写得真挚动人。全词上阕写景，下阕抒情，意境开阔，情感深沉。"},"御街行·秋日怀旧|范仲淹":{"y":"纷纷飘落的树叶，在香阶上堆积，夜色寂静，寒声细碎。珍珠帘子卷起，玉楼空寂，天色清淡，银河垂地。年年今夜，月光如白练，总是人在千里之外。\n愁肠已断，无法喝醉，酒还没到，先化成了泪。残灯明灭，枕头倾斜，尝尽了孤眠的滋味。这些事，眉间心上，没有办法回避。","s":"《御街行·秋日怀旧》是范仲淹的名作，“年年今夜，月华如练，长是人千里”以月光的永恒反衬人的分离，“都来此事，眉间心上，无计相回避”将相思之情写得真挚动人。全词意境凄清，情感深沉，是宋词中的佳作。"},"满庭芳·山抹微云|秦观":{"y":"会稽山上，云朵淡淡的像是水墨画中轻抹上去的一半；越州城外，衰草连天，连绵无穷。城门楼上的号角声，时断时续。在北归的客船上，与歌妓举杯共饮，聊以话别。回首多少男女间情爱的往事，此刻已化作缕缕烟云散失而去。眼前夕阳西下，万点寒鸦点缀着天空，一弯流水围绕着孤村。\n悲伤之际又有柔情蜜意，心神恍惚下，解开腰间的系带，取下香囊。徒然赢得青楼中薄情的名声罢了。此一去，不知何时重逢？离别的泪水沾湿了衣襟与袖口。正是伤心悲情的时候，城已不见，万家灯火已起，天色已入黄昏。","s":"《满庭芳·山抹微云》是秦观的代表作，秦观也因此被称为“山抹微云君”。“山抹微云，天连衰草”以极简练的笔墨写出了秋日的苍茫，“斜阳外，寒鸦万点，流水绕孤村”化用隋炀帝诗句，意境优美。全词将离别之情写得真挚动人，是婉约词的杰作。"},"定风波·自春来|柳永":{"y":"自从春天以来，绿叶红花都让人发愁，芳心对什么事都漫不经心。太阳升到花梢，黄莺穿过柳带，还压着香被躺着。肌肤消瘦，头发散乱，整天懒得梳妆。无奈。恨薄情郎一去，连个音信都没有。\n早知道这样，后悔当初没把他的马鞍锁住。在书房里，只给他纸和笔，管束着让他吟诗学习。永远相随，不要抛躲，闲着时拿着针线陪他坐着。和我在一起，免得年少时光白白度过。","s":"《定风波·自春来》是柳永的名作，以市井女子的口吻，描写了对丈夫的思念和对平凡夫妻生活的向往。“针线闲拈伴伊坐”写出了女子对温馨生活的渴望，相传晏殊曾以此词讥讽柳永。全词语言通俗，情感真挚，是柳永俚词的代表作。"},"戚氏·晚秋天|柳永":{"y":"时值深秋，短促的细雨洒落在庭院栏干前。栏边的菊花稀疏，井边的梧桐叶零乱，惹起残烟。凄凉啊，远望江山关隘，飞云暗淡在夕阳之间。当年宋玉悲秋，对着此景临水登山。远道迢迢，行人凄楚，听厌了陇水潺潺。正是蝉在败叶中吟唱，蟋蟀在衰草中鸣叫，相互应和，喧闹不停。\n孤馆中，度日如年。风露渐渐变凉，悄悄到了更深夜阑。长天明净，银河清浅，皓月明媚。思绪绵绵。长夜对景，哪能忍受屈指暗想从前。没有功名没有利禄，在绮陌红楼中，往往一年年拖延。\n京城风光好，当年少的时候，朝朝暮暮宴饮欢乐。何况有狂放怪异的朋友，遇到对酒当歌就竞相留连。别来时光如梭，旧游似梦，烟水路程多么遥远。想名利，憔悴地长久萦绕牵绊。追念往事，空自愁容惨淡。漏箭移动，渐渐觉得微寒。渐渐呜咽，画角几声残响。对着闲窗，灯灭到天亮，抱着影子无眠。","s":"《戚氏》是柳永最长的词调，共212字，是柳永慢词的代表作。全词以凄清的秋景衬托游子的思乡之情和对往事的回忆，“念名利，憔悴长萦绊”道尽了为名利奔波的辛酸。全词结构宏大，情感深沉，是宋词中慢词的杰作。"},"夜半乐·冻云黯淡天气|柳永":{"y":"寒云暗淡的天气，我乘一叶扁舟，乘兴离开江渚。渡过万壑千岩，到了越溪深处。怒涛渐渐平息，山风忽然吹起，又听到商旅相互呼唤。船帆高高举起，画船轻快地驶过南浦。\n望中酒旗闪闪，一簇烟村，几行霜树。残阳下，渔人敲着船舷归去。败荷零落，衰杨掩映，岸边两两三三，是浣纱的游女。躲避行人，含羞笑着相互说话。\n到此因此思念，轻易抛弃了绣阁中的佳人，像浪萍一样难以停留。感叹后约的叮咛究竟有什么凭据。离怀凄惨，空自恨岁晚归期受阻。泪眼凝望，遥远的京城路。孤雁声远，长天暮色。","s":"《夜半乐》是柳永的长调名作，全词分三片，描写了舟行所见的江南景色和对佳人的思念。“败荷零落，衰杨掩映，岸边两两三三，浣纱游女”以细腻的笔触写出了江南水乡的生活气息，“断鸿声远长天暮”以景结情，余味无穷。全词意境优美，是柳永慢词的佳作。"},"玉楼春·春恨|晏殊":{"y":"在绿杨芳草的长亭路上，年少的人轻易地抛下我离去。楼头的残梦被五更钟惊醒，花底的离愁像三月的雨。\n无情的人不像多情的人那样痛苦，一寸相思还能变成千万缕。天涯地角总有尽头，只有相思没有尽头。","s":"《玉楼春·春恨》是晏殊的名作，“无情不似多情苦，一寸还成千万缕”以对比手法写出了多情的痛苦，“天涯地角有穷时，只有相思无尽处”以夸张手法写出了相思的无穷无尽。全词情感真挚，语言清丽，是晏殊婉约词的代表作。"},"踏莎行·小径红稀|晏殊":{"y":"小路边的红花日渐稀少，郊野却被萋萋芳草占遍，绿树成荫高楼台榭若隐若现。春风不懂得去管束杨花柳絮，让它们迷迷蒙蒙乱扑人面。\n翠绿的树叶里藏着黄莺，红色窗帘把燕子隔在外面，静静的炉香像游丝般袅袅升腾。醉酒后一场愁梦醒来时，夕阳正斜照着深深的庭院。","s":"《踏莎行·小径红稀》是晏殊的名作，“春风不解禁杨花，濛濛乱扑行人面”以拟人手法写春风，生动有趣，“一场愁梦酒醒时，斜阳却照深深院”以景结情，将闲愁写得含蓄深沉。全词意境优美，情感细腻，是晏殊婉约词的佳作。"},"清平乐·金风细细|晏殊":{"y":"微微的秋风细细吹，梧桐叶一片片坠下。初尝绿酒人容易醉，在小窗下枕着浓睡。\n紫薇和朱槿花都残了，斜阳正照着栏杆。双燕将要归去的时节，银屏昨夜微微寒冷。","s":"《清平乐·金风细细》是晏殊的名作，以细腻的笔触描写了秋日的闲愁。“金风细细，叶叶梧桐坠”写出了秋日的萧瑟，“双燕欲归时节，银屏昨夜微寒”以双燕归巢反衬人的孤独。全词意境优美，情感细腻，是晏殊婉约词的佳作。"},"浣溪沙·小阁重帘有燕过|晏殊":{"y":"小楼的重重帘幕间有燕子飞过，晚花的红瓣落在庭院的莎草上。曲折的栏杆影子映入凉波。\n一阵好风吹动翠幕，几回疏雨滴在圆荷上。酒醒人散，得到的愁更多。","s":"《浣溪沙·小阁重帘有燕过》是晏殊的名作，以细腻的笔触描写了暮春的景色和闲愁。“几回疏雨滴圆荷”以疏雨滴荷的细节，写出了环境的清幽，“酒醒人散得愁多”将闲愁写得含蓄深沉。全词意境优美，情感细腻。"},"诉衷情·眉意|欧阳修":{"y":"清晨卷起帘幕，看到轻霜，呵着暖手试着画梅妆。都是因为自己有离恨，所以把眉毛画得像远山一样长。\n思念往事，惋惜流逝的芳华，容易成伤。想要唱歌先收敛，想要笑又皱眉，最让人断肠。","s":"《诉衷情·眉意》是欧阳修的名作，以女子画眉的细节，描写了离恨之深。“都缘自有离恨，故画作远山长”将离恨融入画眉的动作中，构思巧妙，“拟歌先敛，欲笑还颦，最断人肠”将女子的复杂心理写得生动传神。全词情感细腻，是婉约词的佳作。"},"南歌子·凤髻金泥带|欧阳修":{"y":"凤凰发髻上束着金泥带，龙纹玉掌梳插在发间。走到窗下笑着相扶，爱问画眉深浅合不合时宜？\n依偎着人摆弄笔很久，初次试着描花。轻易耽误了绣花功夫，笑着问鸳鸯两个字怎么写？","s":"《南歌子·凤髻金泥带》是欧阳修的名作，以细腻的笔触描写了新婚夫妇的甜蜜生活。“爱道画眉深浅入时无”化用朱庆余诗句，“笑问鸳鸯两字怎生书”将少女的娇羞写得生动传神。全词语言明快，充满生活气息，是欧阳修词中少有的轻快之作。"},"临江仙·夜归临皋|苏轼":{"y":"夜里在东坡饮酒，醉而复醒，醒了又饮。回来的时候仿佛已经三更。家里的童仆早已睡熟鼾声如雷鸣。反复敲门里面全不回应，只好独自倚着藜杖倾听江水奔流的吼声。\n长恨身在宦途，这身子已不是我自己所有。什么时候能忘却为功名利禄而奔竞钻营！夜深了，风停了，江面上的水波也平静下来。真想乘上小船从此消逝，在江河湖海中了却余生。","s":"《临江仙·夜归临皋》是苏轼被贬黄州时所作，“小舟从此逝，江海寄余生”表达了诗人对自由生活的向往，相传苏轼写此词后，“挂冠服江边，拏舟长啸去矣”，太守徐君猷闻之大惊，以为苏轼逃走。全词意境旷达，情感真挚，是苏轼豪放词的代表作。"},"西江月·平山堂|苏轼":{"y":"我三次经过平山堂下，半生在弹指声中过去了。十年没见老仙翁欧阳修了，墙壁上他的字迹还龙蛇飞动。\n想要悼念文章太守欧阳修，仍然歌唱他的杨柳春风。不要说万事转头就空，没转头的时候也都是梦。","s":"《西江月·平山堂》是苏轼经过扬州平山堂时，为悼念恩师欧阳修而作。“壁上龙蛇飞动”写出了欧阳修书法的雄健，“休言万事转头空，未转头时皆梦”表达了对人生的深刻感悟。全词情感真挚，意境旷达，是苏轼婉约词的佳作。"},"阮郎归·初夏|苏轼":{"y":"绿槐高柳上，新蝉的鸣叫声咽住了，和暖的南风刚刚入弦。碧纱窗下，水沉香的烟袅袅升起，下棋声惊醒了午睡。\n微雨过后，小荷叶翻卷，石榴花开得像要燃烧。玉盆中纤手拨弄清泉，水珠碎了又圆。","s":"《阮郎归·初夏》是苏轼描写初夏景色的词作，“榴花开欲然”以夸张手法写出了石榴花的鲜艳，“玉盆纤手弄清泉，琼珠碎却圆”以细腻的笔触写出了少女戏水的情景。全词色彩明丽，充满生活气息，是苏轼婉约词的佳作。"},"贺新郎·乳燕飞华屋|苏轼":{"y":"小燕子飞落在华丽的房屋上，静悄悄无人，梧桐阴转到正午，傍晚凉爽，刚洗过澡。手拿着生丝白团扇，扇和手一时都像玉一样。渐渐困倦倚着，孤眠清熟。帘外谁来推绣户？枉自让人梦断瑶台曲。又却是，风敲竹子。\n石榴花半开，像红巾皱起，等浮花浪蕊都谢尽，陪伴你幽独。浓艳的一枝仔细看，芳心千重像束起来。又恐怕被秋风惊绿。如果等得你来到这里，花前对酒不忍触碰。和粉泪一起，两厢簌簌落下。","s":"《贺新郎·乳燕飞华屋》是苏轼的咏物词代表作，以石榴花比喻美人，“待浮花浪蕊都尽，伴君幽独”写出了石榴花的高洁，“共粉泪，两簌簌”将花与人融为一体，意境凄美。全词托物言志，情感深沉，是苏轼婉约词的杰作。"},"永遇乐·明月如霜|苏轼":{"y":"明月如霜，好风如水，清景无限。曲折的港湾里鱼儿跳跃，圆圆的荷叶上露珠滚落，寂寞无人看见。三更鼓声响起，一片叶子铿然落下，黯黯的梦云被惊断。夜色茫茫，重寻无处，醒来后把小园走遍。\n天涯的倦客，山中的归路，望断了故园的视线。燕子楼空，佳人在哪里，空锁住楼中的燕子。古今如梦，何曾从梦中醒来，只有旧欢新怨。他日对着黄楼夜景，会为我长叹。","s":"《永遇乐·明月如霜》是苏轼夜宿燕子楼时所作，“燕子楼空，佳人何在，空锁楼中燕”是千古传诵的名句，将对历史的感慨写得含蓄深沉。全词意境凄清，情感深沉，是苏轼婉约词的杰作，晁补之称“燕子楼空，佳人何在，空锁楼中燕”为“三句说尽张建封事”。"},"洞仙歌·冰肌玉骨|苏轼":{"y":"冰一样的肌肤，玉一般的身骨，自然是遍身清凉没有汗。宫殿里清风徐来幽香弥漫。绣帘被风吹开，一线月光把佳人窥探。佳人还没有入睡，她斜倚绣枕钗横发乱。\n起来携着她的纤纤素手，走到无声的庭院，时时看到稀疏的星星渡过银河。试问夜有多深？已经是三更时分，月光淡了，玉绳星低低转动。屈指算西风几时吹来，又不道流年在暗中偷偷变换。","s":"《洞仙歌·冰肌玉骨》是苏轼根据蜀主孟昶与花蕊夫人的故事改写的词作，“冰肌玉骨，自清凉无汗”写出了花蕊夫人的清丽，“但屈指西风几时来，又不道流年暗中偷换”将时光流逝的感慨写得含蓄深沉。全词意境优美，情感细腻，是苏轼婉约词的佳作。"},"天净沙·秋思|马致远":{"y":"枯萎的藤蔓，苍老的古树，黄昏时归巢的乌鸦；小桥下溪水潺潺，旁边有几户人家；古老的道路上，萧瑟的西风里，走着一匹疲惫的瘦马。夕阳向西边落下，漂泊在外的游子，还远在天涯，愁肠寸断。","s":"《天净沙·秋思》被称为“秋思之祖”，仅用28个字，便勾勒出一幅苍凉的秋日羁旅图。全曲无一“愁”字，却字字含愁，情景交融，是元曲中最广为人知的作品，也是中国古典诗歌中描写乡愁的巅峰之作。"},"汉宫秋·第三折（节选）|马致远":{"y":"呀！我面对着这辽阔荒凉的原野，草已经变黄，野兔早已遇上了秋霜。猎狗褪了毛变得苍灰，战士们扛起了缨枪，马驮着行装，车运着干粮，打猎的围场已经布置好。她伤心地辞别汉主，我携着手送她到河梁。她的随从进入了荒凉的远方，我的车驾返回咸阳。返回咸阳，经过宫墙；经过宫墙，绕着回廊；绕着回廊，靠近椒房；靠近椒房，月色昏黄；月色昏黄，夜里生凉；夜里生凉，寒蝉悲泣；寒蝉悲泣，绿纱窗下；绿纱窗下，怎能不思念！","s":"《汉宫秋》是马致远的杂剧代表作，写王昭君出塞的故事。这段曲词以顶真手法，从“返咸阳”到“不思量”，层层递进，将汉元帝回宫后对王昭君的思念写得缠绵悱恻，是元曲中最著名的唱段之一。"},"山坡羊·潼关怀古|张养浩":{"y":"群山好像从四面八方聚集而来，黄河的波涛汹涌澎湃，像在发怒；潼关外有黄河，内有华山，地势十分险要。遥望古都长安，思绪起伏，久久不能平静。令人伤心的是，当年秦汉盛世的地方，万间宫殿都早已化作了尘土。国家兴盛的时候，受苦的是百姓；国家灭亡的时候，受苦的还是百姓。","s":"《山坡羊·潼关怀古》是元曲中怀古咏史的代表作，作者行经潼关，目睹历代王朝兴衰遗迹，发出了穿透历史的深沉慨叹。结尾“兴，百姓苦；亡，百姓苦”八字，道尽了封建时代百姓的命运，极具思想深度，在抖音等平台被广泛引用。","b":"张养浩作，约作于元文宗天历二年（1329年）。当时关中大旱，张养浩被任命为陕西行台中丞，前往赈灾，途经潼关时作此曲。他目睹百姓苦难，感慨历代兴亡，写下这首千古名作。","n":["山坡羊：曲牌名，属中吕宫","潼关怀古：途经潼关，怀古伤今","峰峦如聚：山峰从四面八方会聚，形容潼关地势险要","波涛如怒：黄河波涛汹涌，像发怒一样","山河表里：外有黄河，内有华山，形容潼关地势险要","潼关：古关口名，在今陕西潼关县，为历代军事要地","西都：指长安（今陕西西安），秦汉时的都城","意踌躇：思绪起伏，心情不安","秦汉经行处：秦汉两朝曾经经营过的地方","宫阙万间都做了土：无数宫殿都化成了尘土","兴：指王朝兴盛","亡：指王朝灭亡"],"r":"按「峰峦如聚—波涛如怒—山河表里—望西都—意踌躇—伤心秦汉—宫阙万间—兴百姓苦—亡百姓苦」背；山坡羊，四十三字；「兴，百姓苦；亡，百姓苦」是核心；议论精辟是特色。"},"一枝花·不伏老（节选）|关汉卿":{"y":"【尾】我是个蒸不烂、煮不熟、捶不扁、炒不爆、响当当的一粒铜豌豆，那些子弟们谁让你们钻进了他锄不断、砍不下、解不开、甩不掉、慢腾腾的千层锦套头？我玩的是梁园的明月，饮的是东京的美酒，赏的是洛阳的名花，攀的是章台的杨柳。我也会围棋、会踢球、会打猎、会插科打诨、会唱歌跳舞、会吹弹乐器、会唱曲、会吟诗、会双陆。你就是打掉了我的牙、打歪了我的嘴、打瘸了我的腿、打断了我的手，上天赐给我的这些毛病，我还是不肯罢休！除非是阎王亲自来召唤，神鬼亲自来勾魂。三魂归了地府，七魄丧了幽冥。天哪！那时候我才不往烟花路上走！","s":"《一枝花·不伏老》是关汉卿的自叙之作，以“铜豌豆”自喻，展现了自己坚韧不屈、放荡不羁的性格。“蒸不烂、煮不熟、捶不匾、炒不爆”的排比，气势磅礴，将关汉卿的叛逆精神和顽强生命力写得淋漓尽致，是元曲中最具个性的作品之一。"},"窦娥冤·第三折（节选）|关汉卿":{"y":"【正宫·端正好】无缘无故犯了王法，没有提防遭受刑罚，叫一声屈动地惊天。顷刻间游魂先赴了阎王殿，怎么不把天地也深深地埋怨。\n【滚绣球】有日月早晚悬挂，有鬼神掌着生死大权。天地啊，只应该把清浊分辨，可怎么混淆了盗跖和颜渊？行善的受贫穷又命短，作恶的享富贵又寿长。天地啊，做得个怕硬欺软，却原来也这般顺水推船！地啊，你不分好歹算什么地？天啊，你错判贤愚枉做天！哎，只落得两泪涟涟。","s":"《窦娥冤》是关汉卿的代表作，也是中国古代悲剧的巅峰之作。这段唱词是窦娥在法场上对天地的控诉，“地也，你不分好歹何为地？天也，你错勘贤愚枉做天！”以震天撼地的呐喊，揭露了封建社会的黑暗与不公，是元曲中最具反抗精神的唱段。"},"天净沙·春|白朴":{"y":"桃红柳绿的春山，煦暖的阳光照耀，和柔的东风吹拂，楼阁上卷起帘拢，凭栏远望。院中杨柳依依，秋千轻轻摇动。黄莺在歌唱，春燕在飞舞，小桥下流水潺潺，柳絮飞花飘扬。","s":"《天净沙·春》是白朴的名作，与马致远《天净沙·秋思》齐名。全曲以白描手法描绘了春日的美好景象，“春山暖日和风”“啼莺舞燕，小桥流水飞红”，色彩明丽，生机盎然，与《秋思》的苍凉形成鲜明对比。"},"墙头马上·第一折（节选）|白朴":{"y":"【后庭花】不要说姻缘难得，这是情意坚定。他用眉眼传递心事，我把心肠写进短笺。我若得见天颜，将他好言相劝，他是宰相家的贵公子，我是总管的女婵娟。\n【柳叶儿】呀，我只怕你情意淡薄，我只怕你日久心变，我只怕你另寻了姻缘。我只怕你等闲间把人轻视，我只怕你话里把人哄骗，我只怕你口是心非把人怠慢。","s":"《墙头马上》是白朴的爱情喜剧代表作，与《西厢记》《拜月亭》《倩女离魂》并称元曲四大爱情剧。这段唱词以女子的口吻，表达了对爱情的渴望和对未来的担忧，心理描写细腻生动，是元曲爱情戏的经典片段。"},"高祖还乡（节选）|睢景臣":{"y":"【般涉调·哨遍】社长挨家挨户通知，只要有差使都不许推脱。这差使不寻常，一边要交纳草料，一边又要出夫役，都要应付。又说是车驾，都说是銮舆，今天要回故乡。王乡老拿着瓦台盘，赵忙郎抱着酒葫芦。新刷的头巾，刚浆过的绸衫，真是装模作样的大户。\n【耍孩儿】瞎王留领着一伙怪男女，乱踢蹬吹笛擂鼓。看见一队人马到庄门，当头几面旗舒展。一面旗白圈套着个迎霜兔，一面旗红圈打着个毕月乌。一面旗鸡学舞，一面旗狗生双翅，一面旗蛇缠葫芦。","s":"《高祖还乡》是睢景臣的代表作，以一个农民的视角，描写了汉高祖刘邦还乡的场面。全曲以幽默讽刺的笔法，将皇帝的仪仗描写得荒诞可笑，撕下了帝王的神圣面纱，表现了对封建皇权的蔑视，是元曲中最具讽刺性的作品之一。"},"醉太平·堂堂大元|无名氏":{"y":"堂堂大元朝，奸臣专权。开河变钞是祸乱的根源，惹起了红巾军万千。官法混乱，刑法严苛，百姓怨恨。人吃人，钞买钞，何曾见过。贼做官，官做贼，愚贤不分，真是可悲可怜！","s":"《醉太平·堂堂大元》是元代末年的民间散曲，以尖锐泼辣的语言揭露了元末社会的黑暗：奸佞专权、官法泛滥、刑法严苛、人吃人、贼做官，是对元末社会现实的真实写照，也是元曲中最具批判精神的作品之一。"},"卖花声·怀古|张可久":{"y":"阿房宫里罗袖翻飞，金谷园中玉楼高耸，隋堤上的古柳系着龙舟。往事不堪回首，东风又吹来了，野花开在暮春时候。","s":"《卖花声·怀古》是张可久的代表作，以阿房宫、金谷园、隋堤三个历史典故，抒发了对历史兴亡的感慨。“不堪回首，东风还又，野花开暮春时候”以景结情，将历史的沧桑与自然的永恒对比，含蓄深沉，是元曲中怀古的佳作。"},"人月圆·山中书事|张可久":{"y":"千古以来的兴亡繁华，都像一场梦，诗人的眼睛已厌倦了天涯漂泊。孔林的乔木，吴宫的蔓草，楚庙的寒鸦，都在诉说着历史的沧桑。几间茅舍，藏书万卷，终老在乡村人家。山中做什么事？用松花酿酒，用春水煎茶。","s":"《人月圆·山中书事》是张可久的代表作，表达了对历史兴亡的感慨和对隐居生活的向往。“松花酿酒，春水煎茶”以极简练的笔墨写出了隐居生活的闲适与美好，全曲意境清雅，语言凝练，是元曲中小令的精品。"},"清江引·秋怀|张可久":{"y":"西风送来家书，家在万里之外，问我什么时候回去？大雁在红叶满天的秋天啼叫，人在黄花满地的地方醉倒，芭蕉叶上的雨声，飘进了秋日的梦里。","s":"《清江引·秋怀》是张可久的名作，以西风、家书、雁啼、红叶、黄花、芭蕉、雨声等意象，营造出凄清的秋日意境，表达了游子的思乡之情。全曲语言凝练，意境优美，是元曲中写秋的佳作。"},"寿阳曲·远浦归帆|马致远":{"y":"夕阳西下，酒旗悠闲地飘着，两三只船还没有靠岸。落花飘在水上，带着香气，茅舍笼罩在暮色中，断桥头上卖鱼的人已经散去。","s":"《寿阳曲·远浦归帆》是马致远《潇湘八景》组曲之一，以极简练的笔墨描绘了一幅渔村晚景图。“夕阳下，酒旆闲”“断桥头卖鱼人散”，画面宁静优美，充满生活气息，是元曲中写景的佳作。"},"四块玉·别情|关汉卿":{"y":"自从送别之后，心中难舍，这一点相思什么时候才能断绝？凭栏远望，衣袖拂过如雪的杨花。溪水又斜，青山又遮，人已经去了！","s":"《四块玉·别情》是关汉卿的小令名作，以女子的口吻写送别后的相思。“凭阑袖拂杨花雪”以动作写思念，“溪又斜，山又遮，人去也”以景结情，将离别的惆怅写得含蓄深沉。全曲语言朴素，情感真挚。"},"沉醉东风·渔夫|白朴":{"y":"黄芦岸边白苹渡口，绿柳堤上红蓼滩头。虽然没有刎颈之交，却有忘机之友。秋江上点染着白鹭沙鸥。傲视人间的万户侯，我是个不识字的烟波钓叟。","s":"《沉醉东风·渔夫》是白朴的名作，以渔夫的生活表达了对自由的向往和对权贵的蔑视。“傲杀人间万户侯，不识字烟波钓叟”将渔夫的自由与权贵的束缚对比，表达了不慕荣利、追求自由的人生态度，是元曲中隐逸题材的佳作。"},"鹦鹉曲·渔父|冯子振":{"y":"我家住在鹦鹉洲边，是个不识字的渔父。浪花中一叶扁舟，在江南烟雨中酣睡。醒来时满眼青山，抖抖绿蓑衣归去。算从前错怨了天公，原来也有安排我的地方。","s":"《鹦鹉曲·渔父》是冯子振的代表作，以渔父的生活表达了随遇而安的人生态度。“浪花中一叶扁舟，睡煞江南烟雨”意境优美，“算从前错怨天公，甚也有安排我处”充满哲理，是元曲中隐逸题材的名篇。"},"小桃红·秋江|倪瓒":{"y":"一江秋水笼罩着淡淡的寒烟，水面明净如白练。眼底的离愁如几行飞雁。雪后初晴，绿苹红蓼参差可见。唱着吴歌荡桨，一声哀怨，惊起了安眠的白鸥。","s":"《小桃红·秋江》是倪瓒的名作，倪瓒是元代著名画家，此曲以画家的笔触描绘了秋江的景色，“一江秋水澹寒烟，水影明如练”画面感极强，“吴歌荡桨，一声哀怨，惊起白鸥眠”以动写静，意境悠远，是元曲中写景的精品。"},"登徒子好色赋（节选）|宋玉":{"y":"大夫登徒子在楚王身边侍奉，说宋玉的坏话：“宋玉这个人，相貌娴雅英俊，口才很好，又生性好色。希望大王不要让他出入后宫。”\n楚王把登徒子的话告诉了宋玉。宋玉说：“相貌娴雅英俊，是上天赐予的；口才很好，是从老师那里学来的；至于好色，臣下没有这回事。”\n楚王说：“你不好色，有什么说法吗？有道理就留下，没有道理就退下。”\n宋玉说：“天下的美女，没有比得上楚国的；楚国的美女，没有比得上我家乡的；我家乡的美女，没有比得上我东边邻居家的女儿。东边邻居家的女儿，增加一分就太高，减少一分就太矮；搽粉就太白，抹胭脂就太红；眉毛像翠鸟的羽毛，肌肤像白雪；腰像一束素绢，牙齿像含着贝壳；嫣然一笑，就能迷惑阳城、下蔡的公子。然而这个女子爬墙偷看我三年，我至今没有答应她。登徒子就不是这样：他的妻子头发蓬乱，耳朵卷曲，嘴唇外翻，牙齿稀疏，走路歪歪扭扭，还长着疥疮和痔疮。登徒子却很喜欢她，让她生了五个孩子。大王仔细考察一下，谁是好色的人呢？”","s":"《登徒子好色赋》是宋玉的代表作，以登徒子与宋玉的对比，讽刺了以貌取人的偏见。“增之一分则太长，减之一分则太短”成为描写美女的千古名句，“登徒子”也成为好色之徒的代名词。全赋语言优美，比喻生动，是先秦赋的代表作。"},"风赋（节选）|宋玉":{"y":"楚襄王在兰台宫游玩，宋玉、景差在旁侍奉。有一阵风飒飒吹来，楚王就敞开衣襟迎着风，说：“这风真痛快啊！这是我和百姓共同享受的吗？”\n宋玉回答说：“这只是大王您的风罢了，百姓怎么能和您共同享受呢！”\n楚王说：“风，是天地间的气，普遍畅通地吹来，不分贵贱高低都吹到。现在你独独认为是我的风，难道有什么说法吗？”\n宋玉回答说：“我从老师那里听说：枳树弯曲的枝桠会招来鸟筑巢，空穴会引来风。它所依托的环境是这样，那么风的气势就不同了。”\n楚王说：“风，最初是从哪里产生的呢？”\n宋玉回答说：“风从大地上产生，从青苹草的末梢兴起。渐渐进入山谷，在山洞口猛烈怒吼。沿着泰山的山坳，在松柏之下飞舞。飘忽澎湃，激荡如烈火怒吼。轰轰如雷声，回旋交错。吹动石头，折断树木，冲击森林。等到它将要衰弱的时候，就四面分散，穿洞动门，光彩灿烂，离散转移。所以那清凉的雄风，就飘举升降，越过高高的城墙，进入深深的宫殿。吹开花叶散发香气，在桂树椒树之间徘徊，在急流之上翱翔。将冲击荷花，掠过蕙草，分开秦衡，掠过新夷，覆盖初生的杨树，回旋冲击，使众芳萧条。然后在庭院中徜徉，向北进入玉堂，穿过罗帐，经过深邃的内室，这才成为大王的风。所以这风吹到人的身上，直让人感到凄凉寒冷，清凉得让人叹息。清清凉凉，能治好病，解除酒醉，使人耳聪目明，身体安宁。这就是所说的大王的雄风。”","s":"《风赋》是宋玉的代表作，以“雄风”与“雌风”的对比，讽刺了统治者与百姓生活的天壤之别。“风起于青苹之末”成为千古名句，比喻事物的发展有一个从小到大的过程。全赋想象丰富，描写细腻，是先秦赋的杰作。"},"子虚赋（节选）|司马相如":{"y":"楚王派子虚出使齐国，齐王征发全部车马，和使者一起外出打猎。打猎结束后，子虚去拜访乌有先生，亡是公也在座。坐定后，乌有先生问道：“今天打猎快乐吗？”子虚说：“快乐。”“收获多吗？”子虚说：“少。”“那为什么快乐呢？”子虚回答说：“我快乐是因为齐王想向我夸耀他的车骑众多，而我却用云梦泽的事来回答他。”乌有先生说：“可以说给我听听吗？”\n子虚说：“可以。齐王驾着千辆马车，挑选了万名骑兵，在海边打猎。士卒布满沼泽，罗网布满山丘，掩捕野兔，车轮碾死鹿，射杀麋鹿，抓住麟。在盐滩上奔驰，切割鲜肉，血染车轮。射中捕获很多，骄傲地自夸功劳。回头对我说：'楚国也有像这样富饶快乐的平原广泽游猎之地吗？楚王打猎和我比怎么样？'我下车回答说：'我是楚国的鄙陋之人，有幸在宫中宿卫十多年，时常跟随出游，在后宫花园游玩，看了一些景色，但还没有全部看完，又怎么能说宫外的大泽呢！'齐王说：'即使这样，你就大致说说你所听到看到的吧。'","s":"《子虚赋》是司马相如的代表作，与《上林赋》并称，是汉大赋的典范。全赋以子虚、乌有先生、亡是公三人的对话展开，极力铺陈楚国云梦泽的富饶和齐王打猎的盛况，规模宏大，辞藻华丽，奠定了汉大赋的体制，对后世影响深远。"},"上林赋（节选）|司马相如":{"y":"亡是公笑着说：“楚国错了，齐国也不算对。让诸侯纳贡，不是为了财物，而是让他们陈述职守。划定疆界，不是为了防守，而是为了禁止放纵。现在齐国作为东方的藩国，却对外私通肃慎，离开本国，越过边界，渡海打猎，这在道义上本来就不可以。而且你们两位的议论，不致力于阐明君臣的道义，端正诸侯的礼仪，只是争着谈论游戏的快乐，苑囿的广大，想以奢侈争胜负，以荒淫比高低，这不能用来扬名传誉，反而足以贬低君主、损害自己。”\n“况且齐楚的事，又哪里值得称道呢！你们没有见过那巨大壮丽的景象，难道没听说过天子的上林苑吗？左边是苍梧，右边是西极。丹水经过它的南边，紫渊穿过它的北边。灞水浐水始终流在苑中，泾水渭水出入其中；酆水镐水潦水潏水，曲折蜿蜒，流经苑内。浩浩荡荡八条河流分流，方向不同，形态各异。东西南北，奔驰往来，从椒丘的阙口流出，在沙洲的水边行进，经过桂林之中，越过广阔的原野。水势浩荡，顺着山坡而下，奔赴狭窄的峡口，撞击巨石，冲击沙堆，沸腾暴怒，汹涌澎湃。水势湍急，相迫相击，横流回旋，翻腾飞溅，水势浩大。波浪如云般回旋，水流曲折纠缠。后浪越过前浪奔向低洼，水石相击流下浅滩。冲击岩石，拍打堤岸，奔腾飞扬。流向小洲，注入深谷，水声潺潺，水势深沉，轰鸣作响，水势汹涌，如鼎沸腾。波浪奔驰，泡沫跳跃，水流迅疾。悠远长流，寂静无声，安然长归。然后水势浩大，缓缓回旋，波光粼粼，向东注入太湖，溢满池塘。”","s":"《上林赋》是司马相如的代表作，与《子虚赋》连为一体，是汉大赋的巅峰之作。全赋以亡是公之口，极力铺陈天子上林苑的壮丽和天子打猎的盛况，规模宏大，辞藻华丽，气势磅礴，最后归于节俭，体现了“劝百讽一”的赋颂传统，对后世辞赋影响极大。"},"归田赋|张衡":{"y":"在京城游历已久，没有高明的谋略辅佐时政。只是临河羡鱼，等待黄河水清却遥遥无期。感慨蔡泽的慷慨，跟随唐举决断疑惑。实在是天道幽微不明，追随渔父一同嬉戏。超脱尘世远去，与世事永远辞别。\n于是在美好的仲春二月，气候温和，天气清明；平原低地草木茂盛，百草繁荣。雎鸠展翅，黄鹂哀鸣；交颈上下翻飞，关关嘤嘤和鸣。在这里逍遥自在，姑且愉悦心情。\n于是在大泽边龙吟，在山丘上虎啸。仰射飞鸟，俯钓长流。鸟中箭而死，鱼贪饵吞钩。射落云间的飞鸟，钓起深渊中的鱼。\n这时太阳西斜，接着月亮升起。极尽游乐的至乐，虽然到了傍晚也忘记了疲劳。有感于老子的遗诫，将驾车回到茅屋。弹奏五弦琴的妙曲，诵读周公孔子的图书。挥笔作文，陈述三皇的法度。只要纵情于物外，哪里知道荣辱的所在。","s":"《归田赋》是张衡的代表作，也是中国文学史上第一篇描写田园隐居乐趣的赋作。全赋篇幅短小，语言清丽，一改汉大赋的铺张扬厉，开创了抒情小赋的先河，对后世陶渊明的田园诗产生了深远影响。"},"登楼赋|王粲":{"y":"登上这座楼向四面眺望啊，姑且借闲暇的日子消解忧愁。看这座楼所处的位置啊，确实明亮宽敞少有匹敌。旁临清澈漳水的河口啊，倚靠曲折沮水的长洲。背后是高而平的广阔陆地啊，面前是低洼湿地的肥沃水流。北边直到陶牧，西边连接昭丘。花果遮蔽原野，黍稷长满田畴。虽然确实美好却不是我的故乡啊，又怎么值得稍稍停留。\n遭遇乱世而迁徙流亡啊，漫漫超过十二年直到如今。情意眷恋而思归啊，谁能承受这样的忧思？靠着栏杆遥望啊，迎着北风敞开衣襟。平原遥远极目远望啊，被荆山的高峰遮蔽。道路曲折而漫长啊，河水荡漾而渡口深。悲伤故乡被阻隔啊，眼泪纵横落下而不能禁止。从前孔子在陈国啊，有“归欤”的叹息。钟仪被囚禁而奏楚乐啊，庄舄显贵而仍越吟。人的感情都同样怀念故土啊，难道会因穷困显达而改变心意！\n想到时光流逝啊，等待黄河水清却没有尽头。希望王道统一太平啊，凭借大道施展才力。害怕像匏瓜那样白白悬挂啊，担心井已淘清却无人饮用。徘徊漫步啊，太阳忽然将要西沉。风声萧瑟四起啊，天色惨淡无光。野兽惊慌回顾寻找群伴啊，鸟儿相鸣而展翅。原野寂静无人啊，征夫行走不停。心中凄怆感慨啊，情意悲伤哀痛。沿着台阶走下楼啊，怨气交结充满胸中。到了半夜还不能入睡啊，惆怅徘徊翻来覆去。","s":"《登楼赋》是王粲的代表作，也是建安文学的名篇。王粲避难荆州，登当阳城楼，写下此赋，抒发了思乡之情和怀才不遇的感慨。“虽信美而非吾土兮，曾何足以少留”“人情同于怀土兮，岂穷达而异心”都是千古传诵的名句。全赋抒情真挚，语言清丽，是魏晋抒情小赋的典范。"},"洛神赋（节选）|曹植":{"y":"黄初三年，我到京师朝见，回来时渡过洛水。古人说，这洛水的神，名叫宓妃。有感于宋玉对楚王说的神女之事，于是作了这篇赋。辞说：\n我从京城出发，回到东方的藩国。离开伊阙，越过轘辕，经过通谷，登上景山。太阳已经西斜，车困马乏。于是在长满杜蘅的岸边停车，在种满芝草的田里喂马，在阳林漫步，放眼眺望洛川。这时精神恍惚，忽然思绪飘散。低头没有看清，抬头却看到奇异的景象，看见一位美人，在山崖边。于是拉着车夫告诉他说：“你看见那个人了吗？那是谁啊？这样美丽！”车夫回答说：“我听说河洛的神，名叫宓妃。那么君王所见的，莫非就是她吗？她的样子怎样？我想听听。”\n我告诉他说：“她的形态，轻盈如惊飞的鸿雁，婉曲如游动的蛟龙。容光如秋菊般灿烂，风华如春松般茂盛。隐隐约约如轻云遮住月亮，飘飘摇摇如流风吹起回旋的雪花。远远望去，皎洁如朝阳升起在朝霞中；走近细看，鲜明如荷花出清水。肥瘦适中，高矮合度。肩膀如削成一般，腰肢如一束素绢。脖颈修长，洁白的肌肤显露。不施芳香，不涂脂粉。发髻高耸如云，眉毛修长弯曲。红唇鲜明，皓齿洁白，明亮的眼睛善于顾盼，面颊有美丽的酒窝。姿态瑰丽艳逸，仪态文静娴雅。柔情绰约，言语娇媚。服饰奇特举世无双，骨相应图。披着璀璨的罗衣，戴着华美的瑶碧玉佩。戴着金翠首饰，缀着明珠照耀身躯。穿着远游的花鞋，拖着薄雾般的轻裙。幽兰的芳香微微散发，在山边徘徊漫步。”","s":"《洛神赋》是曹植的代表作，以浪漫主义的笔法描写了人神相恋的故事。“翩若惊鸿，婉若游龙”“仿佛兮若轻云之蔽月，飘飖兮若流风之回雪”成为描写美女的千古名句。全赋想象瑰丽，辞藻华美，情感真挚，是中国文学史上最著名的赋作之一，也是后世绘画、戏曲的重要题材。","b":"曹植作，写于魏文帝黄初三年（222年）。曹植当时被封为鄄城王，到洛阳朝见魏文帝曹丕后，返回封地途经洛水时作此赋。赋中写他在洛水边遇见洛水女神宓妃，两人相互爱慕，但因人神殊途，最终不得不含恨分别。关于此赋的主旨，历来有多种说法：一说为感念甄后（曹丕之妻甄氏）而作，故又名《感甄赋》；一说为借洛神比喻君主，表达自己怀才不遇、报国无门的苦闷；一说为纯粹的人神恋爱题材。无论主旨如何，此赋以其华美的辞藻、细腻的描写、浪漫的想象，成为中国文学史上最著名的赋作之一。","n":["黄初三年：魏文帝黄初三年，即公元222年。黄初，魏文帝曹丕的年号","余朝京师：我到京都洛阳朝见皇帝。余，我，曹植自称。京师，指洛阳","还济洛川：回来时渡过洛水。济，渡。洛川，洛水，在今河南","斯水之神：这水的神。斯，这","名曰宓妃：名叫宓妃。宓妃，传说中伏羲氏的女儿，溺死于洛水，遂为洛水之神","感宋玉对楚王神女之事：有感于宋玉回答楚王巫山神女之事。宋玉，战国时楚国辞赋家，作有《高唐赋》《神女赋》，写楚王与巫山神女相遇之事","遂作斯赋：于是写了这篇赋。斯，这","余从京域：我从京都洛阳出发。京域，京都地区","言归东藩：回到东方的藩国。言，语助词。东藩，东方的藩国，指曹植的封地鄄城（今山东鄄城），在洛阳以东","背伊阙：越过伊阙。背，离开、越过。伊阙，山名，在今河南洛阳南，两山相对如阙门","越轘辕：翻过轘辕山。轘辕，山名，在今河南偃师东南，道路曲折","经通谷：经过通谷。通谷，山谷名，在今河南洛阳南","陵景山：登上景山。陵，登。景山，山名，在今河南偃师南","日既西倾：太阳已经西斜。既，已经。西倾，西斜","车殆马烦：车驾危险，马匹疲惫。殆，危险。烦，疲惫","尔乃税驾乎蘅皋：于是在长满杜蘅的岸边停车。尔乃，于是。税驾，停车。税，通「脱」，解下。乎，于。蘅皋，长满杜蘅的岸边。蘅，杜蘅，香草名。皋，水边高地","秣驷乎芝田：在长着芝草的田地里喂马。秣，喂牲口。驷，一车四马，这里指马。芝田，长着芝草的田地","容与乎阳林：在阳林漫步。容与，从容漫步的样子。阳林，地名，一作「杨林」","流眄乎洛川：放眼眺望洛水。流眄，纵目眺望。眄，斜视，这里指看","于是精移神骇：这时精神恍惚，心神不定。精移神骇，精神恍惚、心神不定的样子","忽焉思散：忽然思绪飘散。忽焉，忽然。思散，思绪分散","俯则未察：低头看还没有看清。俯，低头。察，看清","仰以殊观：抬头却看到了奇异的景象。仰，抬头。殊观，奇异的景象","睹一丽人：看见一个美人。睹，看见。丽人，美人","于岩之畔：在山崖旁边。岩，山崖。畔，旁边","乃援御者而告之曰：于是拉着车夫告诉他说。乃，于是。援，拉。御者，车夫","尔有觌于彼者乎：你看见那个人了吗？尔，你。觌，看见。彼，那，指丽人","彼何人斯：她是什么人？斯，语助词","若此之艳也：竟这样美丽！若此，如此。艳，美丽","御者对曰：车夫回答说","臣闻河洛之神：我听说洛水的神。臣，古人对君的自称。河洛，洛水","名曰宓妃：名叫宓妃","然则君王所见：那么君王所看见的。然则，既然这样，那么。君王，指曹植，当时为鄄城王","无乃是乎：莫非就是她吧？无乃，莫非、恐怕。是，这，指宓妃","其状若何：她的样子怎么样？其，她。状，样子、形貌","臣愿闻之：我愿意听听。闻，听","余告之曰：我告诉他说","其形也：她的形貌啊。其，她。形，形貌","翩若惊鸿：轻盈得像惊飞的鸿雁。翩，轻盈飞舞的样子。惊鸿，惊飞的鸿雁，形容体态轻盈","婉若游龙：柔婉得像游动的蛟龙。婉，柔婉。游龙，游动的蛟龙，形容体态柔婉","荣曜秋菊：容光焕发像秋天的菊花。荣曜，容光焕发。秋菊，秋天的菊花，比喻光彩照人","华茂春松：华美茂盛像春天的松树。华茂，华美茂盛。春松，春天的松树，比喻生机勃勃","仿佛兮若轻云之蔽月：隐隐约约像轻云遮住了月亮。仿佛，隐隐约约、看不清楚的样子。兮，语气词，相当于「啊」。轻云之蔽月，轻云遮住月亮，形容姿态的朦胧美","飘飖兮若流风之回雪：飘飘摇摇像流风吹起了回旋的雪花。飘飖，飘荡、摇摆。流风之回雪，流风吹起回旋的雪花，形容体态的轻盈美","远而望之：远远地望去。远，远远地。望，看","皎若太阳升朝霞：洁白明亮像太阳从朝霞中升起。皎，洁白明亮。太阳升朝霞，太阳从朝霞中升起，形容光彩夺目","迫而察之：走近仔细看。迫，靠近、走近。察，仔细看","灼若芙蕖出渌波：鲜艳明丽像荷花从清澈的水波中长出。灼，鲜艳明丽。芙蕖，荷花。渌波，清澈的水波","秾纤得衷：肥瘦适中。秾，丰满。纤，纤细。得衷，适中、恰到好处。衷，通「中」","修短合度：高矮合度。修，长、高。短，矮。合度，合乎标准","肩若削成：肩膀像削成的一样（形容肩线柔美）。削成，削成的，形容肩膀窄而柔美","腰如约素：腰像一束白绢（形容腰细而柔软）。约素，一束白绢。约，束。素，白绢","延颈秀项：脖颈修长秀美。延、秀，都是修长的意思。颈、项，都是脖子","皓质呈露：洁白的肌肤显露出来。皓质，洁白的肌肤。呈露，显露","芳泽无加：不施脂粉。芳泽，芳香的脂粉。无加，不施、不用","铅华弗御：不涂粉黛。铅华，粉黛，古代妇女用的化妆品。弗御，不用。弗，不。御，用","云髻峨峨：发髻高耸如云。云髻，像云一样的发髻。峨峨，高耸的样子","修眉联娟：眉毛细长而弯曲。修眉，长眉。联娟，细长弯曲的样子","丹唇外朗：红唇鲜明。丹唇，红唇。外朗，外表鲜明","皓齿内鲜：白齿洁净。皓齿，白齿。内鲜，里面洁净","明眸善睐：明亮的眼睛善于顾盼。明眸，明亮的眼睛。善睐，善于顾盼。睐，斜视、顾盼","靥辅承权：酒窝在脸颊下。靥辅，酒窝。承，承接。权，颧骨，指脸颊","瑰姿艳逸：姿态瑰丽，艳逸超群。瑰姿，瑰丽的姿态。艳逸，艳逸超群","仪静体闲：仪容文静，体态娴雅。仪静，仪容文静。体闲，体态娴雅","柔情绰态：情意温柔，姿态美好。柔情，温柔的情意。绰态，美好的姿态","媚于语言：言语娇媚。媚，娇媚。语言，言语","奇服旷世：服饰奇特，举世无双。奇服，奇特的服饰。旷世，举世无双、当代没有","骨像应图：骨相容貌，合于图画中的美人。骨像，骨相容貌。应图，合于图画","披罗衣之璀粲兮：穿着璀璨的罗衣。披，穿。罗衣，丝罗做的衣服。璀粲，光彩鲜明的样子","珥瑶碧之华琚：戴着瑶碧美玉的佩饰。珥，戴、插。瑶碧，美玉。华琚，华美的佩玉。琚，佩玉名","戴金翠之首饰：戴着金翠的首饰。金翠，金和翡翠。首饰，头上的装饰品","缀明珠以耀躯：点缀着明珠来光耀身躯。缀，点缀。明珠，明亮的珍珠。耀躯，光耀身躯","践远游之文履：穿着远游的花鞋。践，穿、踏。远游，鞋名，一种远游时穿的鞋。文履，有花纹的鞋","曳雾绡之轻裾：拖着薄雾般的轻纱裙裾。曳，拖。雾绡，薄雾般的轻纱。绡，生丝织成的薄纱。轻裾，轻盈的裙裾。裾，衣服的前后襟","微幽兰之芳蔼兮：微微散发着幽兰的芳香。微，微微。幽兰，幽静的兰花。芳蔼，芳香。蔼，通「馤」，芳香","步踟蹰于山隅：在山角徘徊漫步。步，漫步。踟蹰，徘徊不前的样子。山隅，山角、山边"],"m":"翩若惊鸿，婉若游龙。","r":"按「黄初三年—余朝京师—还济洛川—古人有言—斯水之神—名曰宓妃—感宋玉—遂作斯赋—余从京域—言归东藩—背伊阙—越轘辕—经通谷—陵景山—日既西倾—车殆马烦—尔乃税驾—秣驷乎芝—容与乎阳—流眄乎洛—于是精移—忽焉思散—俯则未察—仰以殊观—睹一丽人—于岩之畔—乃援御者—尔有觌于—彼何人斯—若此之艳—御者对曰—臣闻河洛—名曰宓妃—然则君王—无乃是乎—其状若何—臣愿闻之—余告之曰—其形也—翩若惊鸿—婉若游龙—荣曜秋菊—华茂春松—仿佛兮若—飘飖兮若—远而望之—皎若太阳—迫而察之—灼若芙蕖—秾纤得衷—修短合度—肩若削成—腰如约素—延颈秀项—皓质呈露—芳泽无加—铅华弗御—云髻峨峨—修眉联娟—丹唇外朗—皓齿内鲜—明眸善睐—靥辅承权—瑰姿艳逸—仪静体闲—柔情绰态—媚于语言—奇服旷世—骨像应图—披罗衣之—珥瑶碧之—戴金翠之—缀明珠以—践远游之—曳雾绡之—微幽兰之—步踟蹰于」背；洛神赋（节选），约八百字；「翩若惊鸿，婉若游龙」是核心；辞藻华美是特色。"},"酒德颂|刘伶":{"y":"有一位大人先生，把天地当作一天，把万年当作片刻，把日月当作门窗，把八方荒远之地当作庭院道路。行走没有车辙痕迹，居住没有房屋，以天为幕，以地为席，随心所欲。停下来就拿着酒杯，走动就提着酒壶，只致力于饮酒，哪里知道其他的事？\n有尊贵的公子和士大夫，听到我的名声，议论我的作为。于是挥袖挽襟，怒目咬牙，陈说礼法，是非纷起。先生这时正捧着酒坛接着酒槽，含着酒杯漱口酒，抖动胡须，箕踞而坐，枕着酒曲，垫着酒糟，无思无虑，其乐陶陶。昏然醉倒，豁然醒来。静听听不到雷霆的声音，细看看不见泰山的形状，不觉得寒暑侵入肌肤，利欲触动感情。俯视万物，纷纷扰扰，像江汉水中漂浮的浮萍；两位贵人侍立在旁，就像蜾蠃和螟蛉一样。","s":"《酒德颂》是刘伶的代表作，也是魏晋名士风度的集中体现。全文以大人先生的形象，表达了蔑视礼法、纵酒放达的人生态度，“幕天席地，纵意所如”成为千古名句。文章短小精悍，气势磅礴，是魏晋文学的名篇。"},"闲情赋（节选）|陶渊明":{"y":"那是何等瑰丽超逸的美好姿容，举世无双，秀出群伦。展现出倾城的艳丽姿色，期望有美德流传。佩戴鸣玉来比洁白，与幽兰比芬芳。在世俗中保持淡泊柔情，怀抱高雅之志上凌云天。悲叹晨曦容易西斜，感慨人生长久辛劳。同样都在百年后穷尽，为何欢乐少而忧愁多。撩起红色帷幕端坐，弹奏清瑟自娱。纤细的手指传送余韵，洁白的衣袖挥动缤纷。美丽的眼睛转动流盼，含着言笑难以分辨。\n曲调将到一半，日影落到西窗。悲风叩击树林，白云依傍山峦。仰望天路，俯身催促琴弦。神态妩媚，举止安详妍丽。清音激越感动了我，希望促膝交谈。想亲自前往结下誓言，又怕冒犯礼法成为过错。等待凤鸟传话，又怕别人抢在我前面。心意惶惑不安，魂魄片刻之间九次变迁。\n愿做衣服的领子，承受美发的余香；悲叹罗衣夜里脱下，怨恨秋夜漫长。愿做裙子的腰带，束住窈窕的纤腰；嗟叹温凉变化，有时脱旧换新。愿做头发的油脂，涂抹在垂肩的黑发上；悲叹佳人多次洗发，随白水煎熬干枯。愿做眉毛的黛色，随着顾盼而舒展；悲叹脂粉求鲜，有时在华妆中被毁。愿做蒲草席，在三秋安托柔弱的身体；悲叹花纹褥子取代，要等一年才被用。愿做丝线做鞋，附着白足周旋；悲叹行止有节，白白被抛弃在床前。愿做白天的影子，常依身形或西或东；悲叹高树多荫，有时不能相随。愿做夜晚的蜡烛，在两楹之间照亮玉容；悲叹太阳升起，忽然灭影藏光。愿做竹子做扇，在柔握中含着清风；悲叹白露晨降，看着襟袖而遥远。愿做树木做桐，做膝上的鸣琴；悲叹乐极哀来，最终推开我而停止弹奏。","s":"《闲情赋》是陶渊明唯一的爱情赋作，“十愿”（愿在衣而为领、愿在裳而为带……）以奇特的想象，表达了对美人的深情爱慕，是中国文学史上最著名的爱情描写之一。全赋辞藻华美，情感真挚，与陶渊明平时平淡自然的风格形成鲜明对比，萧统评价为“白璧微瑕”，实则是陶渊明才情的另一种展现。"},"芜城赋|鲍照":{"y":"广陵平原连绵起伏，向南可达苍梧、涨海，向北可到紫塞、雁门。以漕渠为舵，以昆岗为轴。是重关复江的险要之地，四方通达的要道。当它全盛的时候，车轴相碰，人肩相摩，房屋遍地，歌声震天。盐田滋生财富，铜山开采利益，财力雄厚，兵马精良。所以能超越秦法，超过周令，修筑高墙，挖掘深沟，图谋永世的好运。因此板筑城墙的盛状，建造望楼的辛勤，高度超过五岳，广度超过三坟，险峻如断岸，高耸如长云。用磁石制作防御，用红泥涂抹飞文。看这城防的坚固，将万年一君。经历三代，五百多年，竟然瓜剖豆分。\n井边长满青苔，道路缠绕野葛。庭院中遍布毒蛇，台阶上獐鼠相斗。木魅山鬼，野鼠城狐，在风雨中嚎叫，黄昏出现，清晨奔走。饥鹰磨嘴，寒鸥吓雏。潜伏猛虎，吸血食肉。崩倒的榛树堵塞道路，古老的大道险峻。白杨早落，寒草先衰。霜气凛冽，风威肃杀。孤蓬自飞，惊沙乱卷。灌木茫茫无际，草丛纷杂相依。城壕已经填平，城楼已经坍塌。直视千里之外，只见黄尘飞扬。凝神静听，心伤已碎。\n至于雕花的门、绣花的帐，歌堂舞阁的基址；玉池碧树，射猎垂钓的馆舍；吴蔡齐秦的音乐，鱼龙爵马的玩物；都香消烟灭，光沉响绝。东都的美女，南国的丽人，蕙心纨质，玉貌红唇，无不埋魂于幽石，委骨于穷尘。哪里还会记得同辇的欢乐，离宫的苦辛呢？\n天道如何，抱恨的人多。拿琴奏曲，作芜城之歌。歌道：边风急啊城上寒，井径灭啊丘垄残。千年啊万代，同归于尽啊又何言。","s":"《芜城赋》是鲍照的代表作，描写了广陵城（今扬州）从繁华到荒芜的巨变。“千龄兮万代，共尽兮何言”以苍凉的笔调抒发了对历史兴亡的感慨。全赋对比强烈，辞藻瑰丽，情感深沉，是南朝抒情小赋的巅峰之作。"},"别赋（节选）|江淹":{"y":"最让人黯然销魂的，只有离别而已！何况秦吴是相隔绝远的国家，燕宋又相隔千里。有时春苔才开始生长，忽然秋风又暂时吹起。因此游子肠断，百感凄恻。风声萧萧而异响，云色漫漫而奇色。船在水边停滞，车在山侧徘徊。船桨迟缓怎能前进，马寒鸣不停。掩住金杯谁能饮，横放琴柱泪沾轼。在家的人愁卧，恍然若失。日影下墙而光彩沉，月亮上楼而飞光。见红兰承受露水，望青楸遭受寒霜。沿着高柱空掩门，抚摸锦幕空凄凉。知道离梦徘徊，料想别魂飞扬。\n所以离别虽是一种情绪，事情却有万种。至于龙马银鞍，朱车绣轴，在东都设帐饯饮，在金谷送客。琴羽奏响啊箫鼓陈列，燕赵悲歌啊美人伤心，珠玉啊艳于暮秋，罗绮啊娇于初春。惊得驷马仰头嚼食，耸动深渊鱼的红鳞。到分手时含泪，感到寂寞而伤神。\n又有剑客感恩，少年报士，像聂政刺韩相，豫让伏赵厕，专诸刺吴王，荆轲在燕市。割舍慈爱，离开邦国乡里，洒泪诀别，擦血相视。驱征马不回头，只见行尘时时扬起。正是因一剑感恩，不是为了买名于黄泉。金石震动而色变，骨肉悲痛而心死。","s":"《别赋》是江淹的代表作，与《恨赋》并称。“黯然销魂者，唯别而已矣”开篇便点明主旨，成为千古传诵的名句。全赋铺写了各种类型的离别，辞藻华丽，情感真挚，是南朝骈赋的典范之作，对后世影响深远。"},"滕王阁序（节选）|王勃":{"y":"时当九月，正值深秋。雨后的积水已经消尽，寒冷的潭水十分清澈；烟雾凝聚，傍晚的山峦呈现出一片紫色。我们在高高的山路上驾车前行，到崇山峻岭中寻访风景。来到滕王营建的长洲上，看见了这座仙人般的楼阁。层叠的山峦耸起一片苍翠，向上直插云霄；凌空的楼阁丹漆流动，往下看，深不见底。白鹤、野鸭栖息的沙洲，极尽岛屿曲折回环的景致；桂木、兰木修建的宫殿，依着山峦的起伏排列。\n推开雕花的阁门，俯视华美的屋脊，辽阔的山川平原尽收眼底，迂回的江河湖泽令人惊叹。房屋遍地，都是钟鸣鼎食的富贵人家；船只停满渡口，都是青雀、黄龙造型的大船。乌云消散，雨过天晴，阳光普照，天空明朗。落日的晚霞与孤单的野鸭一同飞翔，秋天的江水和辽阔的天空浑然一色。傍晚渔舟中传来歌声，响彻彭蠡湖畔；雁群被寒气惊扰，叫声消失在衡阳的水边。\n胸怀顿时舒畅，超逸的兴致迅速飞扬。排箫声起，清风徐来，柔歌缭绕，白云停飞。睢园的绿竹，豪气胜过陶渊明的酒樽；邺水的朱华，光彩照过谢灵运的诗笔。四种美好都具备，两种难得也齐全。极目远望长空，在假日尽情游乐。天高地远，感到宇宙无穷；兴尽悲来，知道盛衰有定。远望长安在日下，遥看吴会在云间。地势尽而南海深，天柱高而北极远。关山难越，谁为迷路的人悲伤？萍水相逢，都是他乡之客。思念宫门却不得见，等待宣室召见又在哪一年？\n唉！时运不齐，命运多舛。冯唐容易衰老，李广难得封侯。贾谊被贬到长沙，不是没有圣明的君主；梁鸿逃到海边，难道不是政治清明的时代？所依赖的是君子看到征兆，达人知道命运。老当益壮，怎能改变白发之心？穷且益坚，不堕青云之志。喝贪泉的水更觉清爽，处干涸的车辙依然欢乐。北海虽远，乘风可到；早晨虽过，傍晚不晚。孟尝高洁，空有报国之情；阮籍猖狂，岂能学他穷途之哭！","s":"《滕王阁序》是骈文的巅峰之作，也是王勃的千古绝唱。全文辞藻华丽，对仗工整，意境开阔，“落霞与孤鹜齐飞，秋水共长天一色”更是千古名句。“老当益壮，宁移白首之心？穷且益坚，不坠青云之志”激励了无数身处逆境的人。全文是中国古代赋体文学最具代表性的作品。"},"前赤壁赋|苏轼":{"y":"壬戌年的秋天，七月十六日，我和客人乘船在赤壁之下游玩。清风缓缓吹来，水面波澜不惊。我举起酒杯劝客人同饮，吟诵《诗经》中关于明月的诗篇。不一会儿，月亮从东山上升起，在斗宿和牛宿之间徘徊。白茫茫的水汽笼罩江面，水光与天空连成一片。我们任凭小船像一片苇叶般飘荡，越过茫茫万顷的江面。浩浩荡荡的，好像凌空驾风而行，不知道要停在哪里；飘飘然的，好像脱离了尘世，无牵无挂，变成了神仙飞上了天。\n这时候喝酒喝得高兴起来，用手叩击船舷应声而歌。歌词说：“桂木做的棹啊兰木做的桨，拍击着清澈的江水啊，在月光浮动的江面逆流而上。我的心怀悠远啊，遥望美人啊在天的一方。”客人中有吹洞箫的，按着歌声伴奏。那箫声呜呜咽咽，像怨恨又像思慕，像哭泣又像倾诉，尾声婉转悠长，像不断的细丝。能使深谷中的蛟龙起舞，能使孤舟上的寡妇哭泣。\n我的神色变得忧愁，整理好衣襟端坐，问客人说：“箫声为什么这样悲凉呢？”客人说：“'月明星稀，乌鹊南飞'，这不是曹孟德的诗吗？向西望是夏口，向东望是武昌，山水环绕，一片苍翠，这不是曹孟德被周瑜围困的地方吗？当他攻破荆州，攻下江陵，顺流东下的时候，战船相连千里，旌旗遮蔽天空，在江边斟酒，横执长矛吟诗，本是一代枭雄，如今又在哪里呢？何况我和你在江中小洲打鱼砍柴，以鱼虾为伴，以麋鹿为友，驾着一叶小船，举起酒杯互相劝酒。像蜉蝣一样寄生在天地之间，渺小得像大海中的一粒粟。哀叹我们生命的短暂，羡慕长江的无穷无尽。想和飞仙一起遨游，和明月相拥而永存。知道这些不可能轻易得到，只能把箫声的余音寄托给悲凉的秋风。”\n我说：“你也知道那江水和月亮吗？江水像这样不断流逝，却并没有真正流走；月亮像那样时圆时缺，却终究没有增减。如果从变化的一面去看，天地间的万事万物，连一眨眼的工夫都不曾保持原样；从不变的一面去看，万物和我们都是永恒的，又有什么可羡慕的呢？况且天地之间，万物各有其主，如果不是我所有的，即使一丝一毫也不能索取。只有江上的清风，和山间的明月，耳朵听到就成为声音，眼睛看到就成为颜色，取之不尽，用之不竭，这是大自然无穷无尽的宝藏，是我和你可以共同享受的。”\n客人高兴地笑了，洗了酒杯重新斟酒。菜肴和果品都吃完了，杯子盘子杂乱地放着。大家互相枕着靠着睡在船中，不知不觉东方已经发白。","s":"《前赤壁赋》是宋代文赋的典范，苏轼借赤壁夜游，探讨了变与不变、短暂与永恒的哲学命题。全文写景、抒情、议论浑然一体，既有泛舟江上的诗意，又有通透豁达的人生智慧。“惟江上之清风，与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭”成为千古名句，是中国古代散文中的不朽名篇。"},"秋声赋|欧阳修":{"y":"欧阳先生夜里正在读书，听到有声音从西南方向传来，惊恐地侧耳倾听，说：“奇怪啊！”起初是淅淅沥沥的雨声夹杂着萧飒的风声，忽然奔腾澎湃起来，像波涛在夜间惊起，风雨突然到来。它碰到物体上，鏦鏦铮铮，像金属兵器相击；又像奔赴敌阵的士兵，衔枚快跑，听不到号令，只听到人马的行进声。我对童子说：“这是什么声音？你出去看看。”童子说：“星月皎洁，银河在天，四周没有人声，声音在树间。”\n我说：“唉，可悲啊！这是秋声，为什么而来呢？秋天的样子是：它的颜色惨淡，烟飞云收；它的容貌清明，天高气爽，阳光灿烂；它的气候寒冷，刺人肌骨；它的意境萧条，山川寂静。所以它发出的声音，凄凄切切，呼号奋发。茂盛的草碧绿繁茂，美好的树木葱茏可爱；可是草被秋风一吹就变色，树被秋风一刮就落叶。它之所以能摧败零落，是因为这一股肃杀之气的余威。秋天，是刑官，在时令上属阴；又是兵象，在五行中属金。这叫做天地的义气，常以肃杀为心。天对于万物，春生秋实，所以在音乐上，商声是西方的音，夷则是七月的律。商，就是伤，万物老了就悲伤；夷，就是戮，万物过盛就当杀。\n唉！草木无情，有时还要飘零。人是动物，是万物之灵；百忧触动他的心，万事劳累他的身体；心中有所触动，必然动摇他的精神。何况要思考他力量所不及的事，忧虑他智慧所不能的事；当然会使红润的容颜变成枯木，乌黑的头发变成花白。为什么要用不是金石的体质，想和草木争荣呢？想想是谁伤害了自己，又何必怨恨这秋声呢！”\n童子没有回答，低头睡着了。只听到四壁虫声唧唧，像在附和我的叹息。","s":"《秋声赋》是欧阳修的代表作，以秋声为线索，抒发了对人生的感慨。“草木无情，有时飘零。人为动物，惟物之灵”将草木与人对比，表达了对人生劳碌的感慨。全赋以无形的秋声为描写对象，想象丰富，描写生动，是宋代文赋的典范。"},"杂曲歌辞·行路难三首·二|李白":{"y":"大道虽宽广如青天，唯独我没有出路。\n耻于追随长安城中的纨绔子弟，以赤鸡白雉赌梨栗为乐。\n像冯谖那样弹剑作歌，发出苦声，在王侯门下做食客，不合心意。\n淮阴市井之人嘲笑韩信，汉朝公卿嫉妒贾谊。\n你不见从前燕昭王重用郭隗，拿着扫帚扫地，屈身相待，毫无猜忌。\n剧辛、乐毅感恩图报，输肝剖胆效忠英才。\n如今昭王的白骨已缠绕蔓草，还有谁来打扫黄金台呢？\n行路难啊，归去来！","s":"《行路难·其二》是李白的名作，“大道如青天，我独不得出”以极强烈的对比，写出了怀才不遇的悲愤。全诗借古讽今，以燕昭王筑黄金台招贤的历史，讽刺了当朝统治者不重人才的现实，情感深沉，气势磅礴。"},"清平调词三首·三|李白":{"y":"名花和倾国美人两相映衬，相得益彰，常使君王面带笑容观赏。\n春风中无限的怅恨都被消解，君王和贵妃在沉香亭北倚靠着栏杆。","s":"《清平调·其三》将名花与美人合写，“名花倾国两相欢”写出了花美与人美的交融，“解释春风无限恨”写出了君王与贵妃的恩爱。全诗辞藻华丽，意境优美，是李白七绝中的佳作。"},"渔父·一|张志和":{"y":"西塞山前白鹭在自由地翱翔，江岸桃花盛开，江水中肥美的鳜鱼欢快地游来游去。\n渔翁头戴青色斗笠，身披绿色蓑衣，冒着斜风细雨，悠然自得地垂钓，连下了雨都不回家。","s":"《渔歌子》是张志和的代表作，描绘了一幅江南水乡的渔乐图。“青箬笠，绿蓑衣，斜风细雨不须归”写出了渔翁的悠闲自在，表达了诗人对隐居生活的向往。全词色彩明丽，意境优美，是小学课本中的经典篇目。"},"杂曲歌辞·忆江南·一|白居易":{"y":"江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？","s":"《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"},"沁园春·雪|毛泽东":{"s":"上片写景，以「北国风光，千里冰封，万里雪飘」总写北国雪景，意境壮阔；「望长城内外，惟余莽莽；大河上下，顿失滔滔」远望长城黄河，写雪后的苍茫；「山舞银蛇，原驰蜡象，欲与天公试比高」以动写静，群山如银蛇舞动、高原如蜡象奔驰，「欲与天公试比高」赋予山河以人的精神；「须晴日，看红装素裹，分外妖娆」想象雪后初晴的美景，红日白雪交相辉映。下片议论抒情，以「江山如此多娇，引无数英雄竞折腰」承上启下；「惜秦皇汉武，略输文采；唐宗宋祖，稍逊风骚。一代天骄，成吉思汗，只识弯弓射大雕」以「惜」字统领，评说历代帝王，指出他们武功有余而文治不足；「俱往矣，数风流人物，还看今朝」以「俱往矣」收束历史，「还看今朝」推向高潮，指出真正的风流人物是当今的无产阶级和人民大众。全词意境壮阔、气势磅礴、写景议论抒情融为一体，是中国词史上的千古绝唱。","b":"1936年2月，毛泽东率红军抗日先锋军东渡黄河，途经陕北清涧县袁家沟时，适逢大雪，他攀登海拔千米的高原视察地形，目睹「千里冰封」的北国风光，写下了这首气吞山河的壮丽词篇。1945年10月，毛泽东赴重庆谈判时书赠柳亚子，随后在重庆《新民报晚刊》发表，轰动全国。","n":["北国：指我国北方","惟余莽莽：只剩下白茫茫的一片。惟余，只剩；莽莽，无边无际","大河上下：指黄河的上游和下游","顿失滔滔：指黄河因结冰而立刻失去了波涛滚滚的气势。顿，立刻","山舞银蛇：群山好像（一条条）银蛇在舞动","原驰蜡象：高原（上的丘陵）好像（许多）白象在奔跑。原，指秦晋高原；蜡象，白色的象","红装素裹：形容雪后天晴，红日和白雪相映衬的壮丽景色。红装，红色的装束；素裹，白色的包裹","妖娆：娇艳美好。娆音ráo","折腰：弯腰行礼，这里是倾倒的意思","秦皇汉武：秦始皇嬴政、汉武帝刘彻","略输文采：文采方面稍微差一些。输，差","唐宗宋祖：唐太宗李世民、宋太祖赵匡胤","稍逊风骚：文学才华稍微差一些。逊，差；风骚，《诗经》的《国风》和《楚辞》的《离骚》，代指文学才华","天骄：天之骄子","成吉思汗：元太祖铁木真。汗音hán","只识弯弓射大雕：只知道拉弓射大雕。雕，一种猛禽","风流人物：这里指能建功立业的英雄人物"]},"忆秦娥·娄山关|毛泽东":{"s":"上片写景，「西风烈，长空雁叫霜晨月」以「西风烈」「雁叫」「霜晨月」三个意象，勾勒出一幅凄冷肃杀的战地黎明图——西风猛烈，长空雁叫，寒霜晨月；「霜晨月，马蹄声碎，喇叭声咽」以叠句「霜晨月」承上，以「马蹄声碎」「喇叭声咽」写红军急行军的场景——马蹄声细碎急促，军号声低沉悲凉，「碎」「咽」二字传神地写出了战斗的紧张和悲壮；下片抒情，「雄关漫道真如铁，而今迈步从头越」以「雄关漫道真如铁」写娄山关的险要——不要说雄关真的像铁一样坚固，以「而今迈步从头越」写红军的英勇——如今我们迈开大步从它头顶跨越过去，「真如铁」与「从头越」形成强烈对比，突出了红军无坚不摧的英雄气概；「从头越，苍山如海，残阳如血」以叠句「从头越」承上，以「苍山如海，残阳如血」写战斗结束后的景色——青山起伏如大海波涛，夕阳鲜红如血，「如海」「如血」两个比喻，意境壮阔、色彩浓烈，既是写景，也象征着革命道路的漫长和战斗的惨烈。全词意境壮阔、气势磅礴、写景抒情融为一体、语言精炼、色彩浓烈，是毛泽东诗词中的精品。","b":"1935年1月，遵义会议确立了毛泽东在党和红军中的领导地位。会后，毛泽东指挥红军二渡赤水，回师遵义，于2月26日攻占娄山关，28日再占遵义，取得了长征以来最大的一次胜利。这首词就是在攻占娄山关后写下的，描绘了红军在娄山关战斗中激烈悲壮的场面，表达了红军不怕牺牲、勇往直前的革命英雄主义精神。","n":["忆秦娥：词牌名，又名《秦楼月》。李白有「箫声咽，秦娥梦断秦楼月」句，故名","娄山关：在贵州遵义北大娄山中，是贵州进入四川的要道，地势险要，历来为兵家必争之地","西风烈：西风猛烈。烈，猛烈","长空雁叫霜晨月：辽阔的天空中大雁在叫，寒霜的早晨挂着残月","霜晨月：这是词牌规定的叠句，重复上句末尾三字","马蹄声碎：马蹄声细碎急促。碎，细碎","喇叭声咽：军号声低沉悲凉。喇叭，指军号；咽音yè，声音因阻塞而低沉","雄关漫道真如铁：不要说雄伟的关隘真的像铁一样坚固。雄关，指娄山关；漫道，不要说，别说","而今迈步从头越：如今我们迈开大步从它的头顶跨越过去。迈步，迈开大步；从头越，从娄山关的山顶跨越过去","从头越：叠句","苍山如海：青山起伏像大海的波涛。苍山，青山","残阳如血：夕阳像血一样鲜红。残阳，夕阳"]},"清平乐·六盘山|毛泽东":{"s":"上片写景抒情，「天高云淡，望断南飞雁」以「天高云淡」写秋日高原的晴朗天空，以「望断南飞雁」写词人目送大雁南飞的情景——望到看不见南飞的大雁，「望断」二字既写了眺望之久，也寄托了对南方革命根据地和战友的思念；「不到长城非好汉，屈指行程二万」以「不到长城非好汉」写红军的坚定信念——不到达目的地绝不是好汉，以「屈指行程二万」写长征的历程——弯指一算已经走了二万里，「非好汉」「二万」充满了革命自豪感；下片展望未来，「六盘山上高峰，红旗漫卷西风」写六盘山顶的景色——高峰之上，红旗在西风中飘扬，「漫卷」二字写出了红旗飘扬的自由和豪迈；「今日长缨在手，何时缚住苍龙？」以「长缨在手」写革命武装力量已经掌握在手中，以「何时缚住苍龙」写对革命胜利的期盼和信心——什么时候能捆住苍龙（国民党反动派）呢？「何时」不是疑问，而是充满信心的展望。全词意境开阔、气势豪迈、写景抒情融为一体、语言精炼、充满革命自豪感和胜利信心，是毛泽东诗词中的名篇。","b":"1935年10月，毛泽东率领中央红军翻越六盘山，这是红军长征途中翻越的最后一座大山。翻越六盘山后，红军即将到达陕北，长征胜利在望。毛泽东在六盘山顶峰，面对秋日高原的壮阔景色，回顾长征的战斗历程，展望革命的未来，写下了这首词。","n":["清平乐：词牌名","六盘山：在宁夏回族自治区南部和甘肃东部，海拔2928米，是红军长征途中翻越的最后一座大山","天高云淡：天空高远，云彩淡薄","望断南飞雁：望到看不见南飞的大雁。望断，望到看不见；南飞雁，秋天向南飞的大雁","不到长城非好汉：不登临长城关口绝不是英雄好汉。长城，这里指长征的目的地，也指抗日前线","屈指行程二万：弯着手指头计算，已经走了二万里。屈指，弯着手指头计算；行程二万，指二万五千里长征的约数","红旗漫卷西风：红旗在西风中随意飘扬。漫卷，随意飘扬","长缨：长绳子。缨，绳子。这里指革命武装力量","苍龙：太岁神的别名，这里指国民党反动派。古代方士以太岁为凶神"]},"水调歌头·游泳|毛泽东":{"s":"上片写游泳的感受，「才饮长沙水，又食武昌鱼」以「才饮」「又食」写行程的紧凑和轻松——刚喝了长沙水，又吃了武昌鱼，化用民谣「宁饮建业水，不食武昌鱼」而反其意，充满生活情趣；「万里长江横渡，极目楚天舒」写横渡长江的壮阔——横渡万里长江，放眼远望楚天开阔，「万里」「极目」「舒」写出了长江的壮阔和词人的舒畅；「不管风吹浪打，胜似闲庭信步，今日得宽余」写游泳的豪迈——不管风吹浪打，胜过在庭院里散步，今天得到了舒展，「风吹浪打」与「闲庭信步」对比，突出了词人的从容和自信；「子在川上曰：逝者如斯夫！」引用孔子的话，感叹时光流逝，也暗示要珍惜时间、加快建设；下片写建设宏图，「风樯动，龟蛇静，起宏图」以「风樯动」「龟蛇静」写长江两岸的景色，以「起宏图」引出建设规划；「一桥飞架南北，天堑变通途」写武汉长江大桥——一座大桥飞架南北，天堑变成通途，「飞架」二字写出了大桥的气势，「天堑变通途」写出了大桥的作用；「更立西江石壁，截断巫山云雨，高峡出平湖」写三峡工程的宏伟蓝图——还要在长江西部建立大坝，拦住巫山云雨，高峡出平湖，想象奇特、气势磅礴；「神女应无恙，当惊世界殊」以巫山神女的惊叹收束——神女应该还健康吧，一定会惊叹世界的巨大变化，用神话传说增添浪漫色彩，也表达了对社会主义建设成就的自豪。全词意境开阔、气势磅礴、写景抒情议论融为一体、用典自然、想象奇特、充满建设豪情，是毛泽东诗词中的名篇。","b":"1956年6月，毛泽东从长沙到武汉，三次畅游长江，写下了这首词。当时我国正处于第一个五年计划时期，社会主义建设蓬勃发展，武汉长江大桥正在建设中，三峡工程也在规划中。词人通过畅游长江的感受，抒发了对社会主义建设的豪情壮志和对未来的美好展望。","n":["水调歌头：词牌名","才饮长沙水：刚喝了长沙的水。长沙水，长沙白沙古井的水，以清冽甘甜闻名","又食武昌鱼：又吃了武昌的鱼。武昌鱼，湖北鄂城（古武昌）出产的团头鲂，味道鲜美","万里长江横渡：横渡万里长江","极目楚天舒：放眼远望，湖北一带的天空开阔舒展。极目，放眼远望；楚天，湖北古属楚国，故称楚地的天空；舒，舒展，开阔","不管风吹浪打：不管风吹浪打","胜似闲庭信步：比在清静的庭院里随意散步还要自在。胜似，胜过；闲庭，清静的庭院；信步，随意散步","宽余：宽裕，舒缓","子在川上曰：逝者如斯夫：孔子在河边说：「消逝的时光就像这河水一样啊！」用《论语·子罕》「子在川上曰：『逝者如斯夫，不舍昼夜。』」","风樯动：风帆在动。樯音qiáng，桅杆","龟蛇静：龟山和蛇山静静地矗立着。龟蛇，龟山在汉阳，蛇山在武昌，两山隔江对峙","起宏图：开始了宏伟的建设规划。宏图，宏伟的规划","一桥飞架南北：一座大桥飞架南北。指武汉长江大桥，1957年建成通车","天堑变通途：天然的险阻变成了畅通的大道。天堑音qiàn，天然的壕沟，这里指长江；通途，畅通的大道","更立西江石壁：还要在长江西部建立一道拦河大坝。西江，指长江上游；石壁，指拦河大坝","截断巫山云雨：拦住巫山的云雨。巫山，在四川巫山县东，长江穿流其中，形成巫峡；巫山云雨，用宋玉《高唐赋》「旦为朝云，暮为行雨」典故，这里指长江上游的雨水","高峡出平湖：在高山峡谷中出现一个平静的大湖。指三峡水库","神女应无恙：神女应该还健康吧。神女，指巫山神女，用宋玉《高唐赋》巫山神女的典故；恙音yàng，病","当惊世界殊：一定会惊叹世界发生了巨大的变化。殊，不同，变化"]},"浪淘沙·北戴河|毛泽东":{"s":"上片写景，「大雨落幽燕，白浪滔天」以「大雨落幽燕」写雨势之大——大雨落在幽燕大地上，以「白浪滔天」写浪势之猛——白色的波浪滔天，两个意象勾勒出一幅壮阔的雨中海景图；「秦皇岛外打鱼船，一片汪洋都不见，知向谁边？」写打鱼船在大雨中的命运——秦皇岛外的打鱼船，在一片汪洋中都看不见了，不知道漂向哪里去了，「都不见」「知向谁边」既写了雨大海深，也寄托了对渔民的关切；下片怀古抒情，「往事越千年，魏武挥鞭，东临碣石有遗篇」以「往事越千年」引出历史回忆——往事已经过去了一千年，以「魏武挥鞭，东临碣石有遗篇」写曹操的往事——魏武帝曹操挥鞭策马，东登碣石山留下了《观沧海》；「萧瑟秋风今又是，换了人间」以「萧瑟秋风今又是」呼应曹操《观沧海》中的「秋风萧瑟，洪波涌起」——萧瑟的秋风今天又吹起来了，以「换了人间」点明主旨——人间已经换了样子，曹操时代是封建社会，今天是社会主义新时代，「今又是」与「换了人间」形成对比，突出了时代的巨变。全词意境壮阔、气势磅礴、写景怀古抒情融为一体、用典自然、抚今追昔、充满时代自豪感，是毛泽东诗词中的名篇。","b":"1954年夏，毛泽东在北戴河休养期间，面对大海的壮丽景色，联想到一千七百多年前曹操在此写下《观沧海》的往事，抚今追昔，写下了这首词。词人通过对北戴河大雨中海景的描绘，抒发了对新时代的赞美和对历史的感慨。","n":["浪淘沙：词牌名","北戴河：在河北秦皇岛西南，是著名的避暑胜地","大雨落幽燕：大雨落在幽燕大地上。幽燕，指河北北部和辽宁一带，古属幽州和燕国","白浪滔天：白色的波浪滔天。滔天，形容水势极大","秦皇岛外打鱼船：秦皇岛外面的打鱼船。秦皇岛，在河北，因秦始皇曾在此入海求仙而得名","一片汪洋都不见：一片汪洋都看不见了。都不见，指打鱼船都看不见了","知向谁边：不知道漂向哪里去了。谁边，何处，哪里","往事越千年：往事已经过去了一千年。越，超过，过去了","魏武挥鞭：魏武帝曹操挥鞭策马。魏武，指曹操，曹丕称帝后追尊曹操为魏武帝；挥鞭，挥鞭策马，指驰骋征战","东临碣石有遗篇：向东登上碣石山留下了诗篇。碣石，山名，在今河北昌黎西北，一说在北戴河附近；遗篇，遗留下来的诗篇，指曹操的《观沧海》。公元207年，曹操北征乌桓，途经碣石山，写下了《观沧海》","萧瑟秋风今又是：萧瑟的秋风今天又吹起来了。萧瑟，形容风吹树木的声音；曹操《观沧海》有「秋风萧瑟，洪波涌起」句","换了人间：人间已经换了样子。指社会发生了翻天覆地的变化"]},"卜算子·咏梅|毛泽东":{"s":"上片写梅花在严寒中开放，「风雨送春归，飞雪迎春到」以「风雨」「飞雪」写环境的恶劣——风雨送走了春天，飞雪迎来了春天，「送」「迎」二字赋予风雨飞雪以人的动作；「已是悬崖百丈冰，犹有花枝俏」以「悬崖百丈冰」写严寒的程度——悬崖上已经结了百丈冰，以「犹有花枝俏」写梅花的傲然——仍然有梅花俏丽地开放，「已是」与「犹有」形成强烈对比，突出了梅花不畏严寒的精神；下片写梅花的品格，「俏也不争春，只把春来报」以「不争春」写梅花的无私——虽然俏丽，但不与百花争春，以「只把春来报」写梅花的奉献——只是把春天到来的消息报告给人们；「待到山花烂漫时，她在丛中笑」以「山花烂漫」写春天的繁盛——等到满山遍野的花都盛开了，以「她在丛中笑」写梅花的欣慰和谦逊——梅花在百花丛中欢笑，「笑」字写出了梅花的乐观和无私——自己开放不是为了争春，而是为了报春，当百花盛开时，她在花丛中欣慰地笑。全词意境优美、形象鲜明、对比强烈、拟人巧妙、托物言志、充满革命乐观主义精神，是毛泽东诗词中托物言志的名篇。陆游的咏梅写「寂寞开无主」「零落成泥碾作尘，只有香如故」，充满孤独悲凉；毛泽东反其意，写梅花的乐观自信和无私奉献，境界远高于陆游。","b":"1961年12月，毛泽东在广州期间，读了陆游的《卜算子·咏梅》，「反其意而用之」，写下了这首咏梅词。当时我国正处于三年困难时期，国际上也面临着反华势力的围攻。毛泽东以梅花自喻，通过对梅花在严寒中傲然开放的描写，表达了中国共产党人不畏艰难、敢于斗争、无私奉献的革命精神和乐观主义态度。词前有小序：「读陆游咏梅词，反其意而用之。」","n":["卜算子：词牌名","读陆游咏梅词，反其意而用之：毛泽东自注：读了陆游的《卜算子·咏梅》，反其意而用之。陆游的咏梅词写梅花的寂寞孤独，毛泽东反其意，写梅花的乐观自信","风雨送春归：风雨把春天送走了","飞雪迎春到：飞雪又把春天迎来了","已是悬崖百丈冰：已经是悬崖上结了百丈冰的时候。百丈冰，形容冰很厚","犹有花枝俏：仍然有梅花俏丽地开放。犹，仍然；俏，俊俏，美丽","俏也不争春：梅花虽然俏丽，但不与百花争春。争春，争占春光","只把春来报：只是把春天到来的消息报告给人们","待到山花烂漫时：等到满山遍野的花都盛开的时候。烂漫，颜色鲜明而美丽，这里指花盛开的样子","她在丛中笑：梅花在花丛中欢笑。她，指梅花；丛中，百花丛中"]},"七律·人民解放军占领南京|毛泽东":{"s":"首联「钟山风雨起苍黄，百万雄师过大江」以「钟山风雨起苍黄」写南京的形势——钟山风雨骤起，天色昏黄，暗指国民党政权仓皇崩溃，以「百万雄师过大江」写解放军渡江的壮举——百万雄师渡过长江，气势磅礴；颔联「虎踞龙盘今胜昔，天翻地覆慨而慷」以「虎踞龙盘今胜昔」写南京的新生——虎踞龙盘的南京今天胜过以往，以「天翻地覆慨而慷」写革命变化的巨大——天翻地覆的变化令人慷慨激昂；颈联「宜将剩勇追穷寇，不可沽名学霸王」是全诗的主旨——应该用剩余的勇气追剿穷途末路的敌人，不能为了虚名而学楚霸王项羽放走刘邦，用项羽的典故告诫全党将革命进行到底，不要给敌人喘息的机会；尾联「天若有情天亦老，人间正道是沧桑」以「天若有情天亦老」用李贺诗句写革命变革的必然性——天如果有感情也会因悲伤而衰老，以「人间正道是沧桑」点明主旨——人间的正道就是沧海桑田的巨大变化，革命变革是历史发展的必然规律。全诗气势磅礴、用典贴切、对仗工稳、情感激昂、哲理深刻，是中国革命诗歌史上的千古名篇。","b":"1949年4月21日，毛泽东、朱德发布《向全国进军的命令》，百万人民解放军强渡长江。4月23日，人民解放军占领南京，宣告了国民党反动统治的覆灭。毛泽东在北平香山双清别墅得知这一消息后，心潮澎湃，写下了这首气势磅礴的诗篇，歌颂了人民解放军的伟大胜利，表达了将革命进行到底的决心。","n":["钟山：即紫金山，在南京市东，这里代指南京","风雨起苍黄：风雨骤起，天色昏黄。苍黄，同「仓皇」，这里指天色昏黄，也暗指国民党政权仓皇崩溃","百万雄师过大江：百万雄壮的人民解放军渡过长江。1949年4月21日，毛泽东、朱德发布《向全国进军的命令》，百万雄师在西起湖口东至江阴的千里战线上强渡长江","虎踞龙盘今胜昔：南京的地势比以往更加雄伟。虎踞龙盘，形容南京地势险要，诸葛亮曾说南京「钟山龙盘，石头虎踞，此帝王之宅」；今胜昔，今天胜过以往","天翻地覆慨而慷：天翻地覆的变化令人慷慨激昂。慨而慷，即慷慨，情绪激昂。曹操《短歌行》有「慨当以慷」","宜将剩勇追穷寇：应该用剩余的勇气去追剿穷途末路的敌人。剩勇，剩余的勇气；穷寇，穷途末路的敌人，指国民党残余势力","不可沽名学霸王：不能为了虚名而学楚霸王项羽。沽名，故意做作或用某种手段猎取名誉；霸王，指项羽，项羽在鸿门宴上为了「仁义」之名放走刘邦，最终被刘邦所败。这里告诫全党不要给国民党喘息的机会","天若有情天亦老：天如果有感情，也会因为悲伤而衰老。用唐李贺《金铜仙人辞汉歌》「衰兰送客咸阳道，天若有情天亦老」句","人间正道是沧桑：人间的正道是沧海桑田的巨大变化。沧桑，「沧海桑田」的略语，比喻世事变化很大。这里指革命变革是人间的正道"]},"蝶恋花·答李淑一|毛泽东":{"s":"上片写烈士忠魂飞上月宫，「我失骄杨君失柳，杨柳轻飏直上重霄九」以「我失骄杨君失柳」开篇，「骄杨」二字饱含对杨开慧的深情和骄傲——我失去了骄傲的杨开慧，你失去了柳直荀，「杨柳」双关，既指两位烈士，也指柳絮，「轻飏直上重霄九」写忠魂轻轻地飘飞上九重云霄，想象浪漫；「问讯吴刚何所有，吴刚捧出桂花酒」写忠魂到了月宫，吴刚捧出桂花酒招待——询问吴刚有什么，吴刚捧出桂花酒，以神话传说中的人物接待烈士，表达了对烈士的敬意；下片写嫦娥起舞和喜讯传来，「寂寞嫦娥舒广袖，万里长空且为忠魂舞」写寂寞的嫦娥也舒展广袖，在万里长空中为忠魂翩翩起舞，连月宫中的嫦娥都被烈士的忠魂感动；「忽报人间曾伏虎，泪飞顿作倾盆雨」以「忽报」转折——忽然传来人间已经降服猛虎（革命胜利）的消息，烈士的忠魂激动得泪飞如雨，顿时化作倾盆大雨，「泪飞顿作倾盆雨」想象奇特、情感浓烈，将对革命胜利的喜悦和对烈士的悼念融为一体。全词想象奇特、浪漫主义色彩浓厚、用神话传说写革命情怀、情感深沉、意境壮美，是毛泽东诗词中浪漫主义的代表作。","b":"1957年1月，毛泽东的老友李淑一（杨开慧的好友、柳直荀的夫人）给毛泽东写信，附上她1933年悼念丈夫柳直荀的词《菩萨蛮·惊梦》，并请求毛泽东把早年写给杨开慧的词抄给她。毛泽东5月11日回信，信中说：「大作读毕，感慨系之。开慧所述那一首不好，不要写了吧。有《游仙》一首为赠。」这首《游仙》即《蝶恋花·答李淑一》，发表时改题。词中通过浪漫主义的想象，写杨开慧、柳直荀两位烈士的忠魂飞上月宫，受到吴刚、嫦娥的热情接待，当听到革命胜利的消息时，激动得泪飞如雨，表达了对革命先烈的深切悼念和崇高敬意。","n":["蝶恋花：词牌名","答李淑一：李淑一，柳直荀的夫人，杨开慧的好友。1957年1月，李淑一给毛泽东写信，附上她悼念柳直荀的词《菩萨蛮·惊梦》，毛泽东回信并写了这首词答她","我失骄杨君失柳：我失去了骄傲的杨开慧，你失去了柳直荀。骄杨，指杨开慧，毛泽东的妻子，1930年被国民党杀害；骄，以为骄傲；君，你，指李淑一；柳，指柳直荀，李淑一的丈夫，1932年在洪湖苏区牺牲","杨柳轻飏直上重霄九：杨开慧和柳直荀的忠魂轻轻地飘扬，一直飞上九重云霄。杨柳，双关，既指杨开慧和柳直荀，也指柳絮；轻飏，轻轻飘扬；重霄九，即九重霄，天的最高处","问讯吴刚何所有：询问吴刚有什么东西。吴刚，神话传说中的人物，因学仙有过，被罚在月宫砍桂树","吴刚捧出桂花酒：吴刚捧出桂花酒来招待他们。桂花酒，用桂花酿制的酒","寂寞嫦娥舒广袖：寂寞的嫦娥舒展宽大的袖子翩翩起舞。嫦娥，神话传说中后羿的妻子，因偷吃不死药而奔月；舒广袖，舒展宽大的袖子，指跳舞","万里长空且为忠魂舞：在万里长空中暂且为忠魂翩翩起舞。且，暂且；忠魂，指杨开慧和柳直荀的忠魂","忽报人间曾伏虎：忽然传来人间已经降服了猛虎的消息。伏虎，降服猛虎，比喻革命胜利，推翻了国民党反动派","泪飞顿作倾盆雨：泪水顿时飞洒，化作倾盆大雨。顿作，顿时化作；倾盆雨，形容雨下得极大"]},"西江月·井冈山|毛泽东":{"s":"上片写战斗场面，「山下旌旗在望，山头鼓角相闻」以「山下旌旗」「山头鼓角」写战斗的紧张气氛——山下的军旗看得见，山头上的鼓角声互相听得见，视听结合，勾勒出一幅战地画面；「敌军围困万千重，我自岿然不动」以「敌军围困万千重」写敌军的嚣张——敌军把井冈山围困了千万重，以「我自岿然不动」写红军的镇定——我们依然巍然屹立毫不动摇，「万千重」与「岿然不动」形成强烈对比，突出了红军的英雄气概；下片写胜利原因和结果，「早已森严壁垒，更加众志成城」以「森严壁垒」写防御工事的坚固——早就构筑了严整的防御工事，以「众志成城」写军民的团结——更加上大家同心协力像城墙一样坚固，从物质和精神两个方面写胜利的原因；「黄洋界上炮声隆，报道敌军宵遁」以「黄洋界上炮声隆」写战斗的激烈——黄洋界上炮声隆隆，以「报道敌军宵遁」写战斗的结果——报告说敌军在夜里逃跑了，「宵遁」二字写出了敌军的狼狈。全词意境壮阔、对比鲜明、视听结合、叙事写景抒情融为一体、充满革命自豪感，是毛泽东诗词中描写战斗的名篇。","b":"1928年8月，毛泽东率领红军主力去湘南迎还红军大队，湘赣两省的国民党军队趁机对井冈山发动第二次「会剿」。留守井冈山的红军以不足一个营的兵力，在黄洋界哨口凭借险要地形，击退了敌军四个团的进攻，取得了黄洋界保卫战的胜利。毛泽东在率领红军大队回井冈山的途中，得知黄洋界保卫战胜利的消息，写下了这首词，歌颂了井冈山军民团结抗敌的革命精神。","n":["西江月：词牌名","井冈山：在江西西部和湖南东部交界处，是中国第一个农村革命根据地","山下旌旗在望：山下的军旗在视线之内。旌旗，军旗；在望，在视线之内，看得见","山头鼓角相闻：山头上的战鼓声和号角声互相听得见。鼓角，战鼓和号角；相闻，互相听得见","敌军围困万千重：敌军把井冈山围困了千万重。万千重，千万层，形容围困之严密","我自岿然不动：我们依然巍然屹立，毫不动摇。岿然，高大独立的样子。岿音kuī","早已森严壁垒：早就构筑了严整的防御工事。森严，严整；壁垒，古代军营的围墙，这里指防御工事","更加众志成城：更加上大家同心协力，像城墙一样坚固。众志成城，大家同心协力，就像城墙一样坚固，比喻团结一致力量无比强大","黄洋界上炮声隆：黄洋界上炮声隆隆。黄洋界，井冈山五大哨口之一，地势险要；隆，形容声音大","报道敌军宵遁：报告说敌军在夜里逃跑了。宵遁，夜里逃跑。宵，夜；遁音dùn，逃跑"]},"菩萨蛮·黄鹤楼|毛泽东":{"s":"上片写景，「茫茫九派流中国，沉沉一线穿南北」以「茫茫九派」写长江的壮阔——茫茫的长江九条支流连贯中国中部，以「沉沉一线」写铁路的延伸——沉沉的一条铁路线贯穿南北，一横一纵，勾勒出武汉的地理形势；「烟雨莽苍苍，龟蛇锁大江」以「烟雨莽苍苍」写景色的迷茫——烟雨迷茫一片苍茫，以「龟蛇锁大江」写龟山蛇山的雄姿——龟山和蛇山锁住了长江，「锁」字写出了两山的险要，也暗喻了革命形势的压抑；下片抒情，「黄鹤知何去？剩有游人处」以「黄鹤知何去」用崔颢诗意发问——黄鹤知道飞到哪里去了，以「剩有游人处」写黄鹤楼的现状——只剩下供游人游览的地方，暗含对世事变迁的感慨；「把酒酹滔滔，心潮逐浪高」以「把酒酹滔滔」写词人的动作——端起酒洒在滔滔的江水中，以「心潮逐浪高」写词人的心情——心潮随着波浪越来越高，「逐浪高」三字将心潮与江浪融为一体，表达了词人在革命危急关头不屈不挠的斗争精神和将革命进行到底的决心。全词意境壮阔、写景抒情融为一体、用典自然、情感深沉、充满革命激情，是毛泽东诗词中的名篇。","b":"1927年春，毛泽东在武汉担任全国农民协会总干事，面对大革命失败前夕的严峻形势——蒋介石发动「四一二」反革命政变，汪精卫也在酝酿「分共」，革命处于危急关头。毛泽东登临黄鹤楼，面对长江的壮丽景色和阴沉的政治形势，心潮澎湃，写下了这首词，表达了对革命形势的忧虑和将革命进行到底的决心。","n":["菩萨蛮：词牌名","黄鹤楼：在湖北武汉武昌蛇山黄鹤矶头，是江南三大名楼之一，始建于三国吴黄武二年（223年），历代屡毁屡建","茫茫九派流中国：茫茫的长江九条支流在中国大陆上奔流。九派，相传长江在湖北江西一带分为九派；流中国，流贯中国中部。中国，这里指中国中部","沉沉一线穿南北：沉沉的一条铁路线贯穿南北。一线，指京汉铁路和粤汉铁路（今京广铁路的前身）；穿南北，贯穿南北","烟雨莽苍苍：烟雨迷茫，一片苍茫。莽苍苍，迷茫辽阔的样子","龟蛇锁大江：龟山和蛇山锁住了长江。龟蛇，龟山在汉阳，蛇山在武昌，两山隔江对峙，像锁住了长江","黄鹤知何去：黄鹤知道飞到哪里去了？用崔颢《黄鹤楼》「昔人已乘黄鹤去，此地空余黄鹤楼」诗意","剩有游人处：只剩下供游人游览的地方","把酒酹滔滔：端起酒洒在滔滔的江水中。把酒，端起酒；酹音lèi，把酒洒在地上表示祭奠；滔滔，指滔滔的江水","心潮逐浪高：心潮随着波浪越来越高。心潮，心中的激情像潮水一样；逐，随着"]},"采桑子·重阳|毛泽东":{"s":"上片写重阳，「人生易老天难老，岁岁重阳」以「人生易老天难老」开篇，对比人生与自然——人生容易衰老，天却难以衰老，以「岁岁重阳」写时间的永恒——年年都有重阳节；「今又重阳，战地黄花分外香」以「今又重阳」写今年的重阳节，以「战地黄花分外香」写战场上的菊花——战场上的菊花格外芳香，「战地」二字点明了革命战争的环境，「分外香」写出了词人对革命战争的赞美——在战场上开放的菊花比平时更香，因为它是革命战士用鲜血浇灌的；下片写秋景，「一年一度秋风劲，不似春光。胜似春光，寥廓江天万里霜」以「一年一度秋风劲」写秋风的强劲——一年一度的秋风强劲，以「不似春光。胜似春光」对比秋天和春天——秋天不像春天的风光，但胜过春天的风光，为什么呢？因为「寥廓江天万里霜」——辽阔的江天之上万里都是霜，秋天的景色比春天更壮阔、更雄浑。全词意境开阔、对比鲜明、写景抒情融为一体、充满革命乐观主义精神，「战地黄花分外香」「胜似春光」表达了词人对革命战争的赞美和对革命前途的乐观态度，是毛泽东诗词中咏秋的名篇。","b":"1929年10月，毛泽东在闽西革命根据地，当时他因受到「左」倾路线的排挤，离开了红军主要领导岗位，在地方指导工作。重阳节这天，他面对闽西秋天的壮丽景色，回顾革命的战斗历程，写下了这首词，表达了对革命战争的赞美和对革命前途的乐观态度。","n":["采桑子：词牌名","重阳：农历九月初九，重阳节，有登高、赏菊的习俗","人生易老天难老：人生容易衰老，天却难以衰老","岁岁重阳：年年都有重阳节。岁岁，年年","今又重阳：今天又到了重阳节","战地黄花分外香：战场上的菊花格外芳香。战地，战场；黄花，菊花；分外，格外","一年一度秋风劲：一年一度的秋风强劲。劲，强劲","不似春光：不像春天的风光","胜似春光：胜过春天的风光","寥廓江天万里霜：辽阔的江天之上，万里都是霜。寥廓，高远空旷；江天，江和天；万里霜，万里都是霜，形容秋霜之广"]},"七律·和柳亚子先生|毛泽东":{"s":"首联「饮茶粤海未能忘，索句渝州叶正黄」回忆与柳亚子的两次交往——1926年在广州一起饮茶，1945年在重庆互相唱和，「未能忘」「叶正黄」充满了对旧友的深情；颔联「三十一年还旧国，落花时节读华章」写三十一年后回到北京，在落花时节读到了柳亚子的诗篇，「三十一年」「落花时节」既写了时间的跨度，也暗含了对世事变迁的感慨；颈联「牢骚太盛防肠断，风物长宜放眼量」是全诗的主旨——牢骚太多了要防止伤身体，对世间万物应该放长远眼光去衡量，以委婉的语气批评了柳亚子的牢骚情绪，劝他以大局为重、放眼未来；尾联「莫道昆明池水浅，观鱼胜过富春江」以「昆明池水浅」「观鱼胜过富春江」劝慰柳亚子——不要说昆明湖的水浅，在这里观鱼胜过在富春江隐居，用严子陵富春江隐居的典故，劝柳亚子留在北京参加新中国建设，比退隐回乡更有意义。全诗用典贴切、对仗工稳、语气委婉、情感真挚、既批评又劝慰、充满政治家的胸怀和人情味，是毛泽东诗词中唱和劝慰的名篇。","b":"1949年3月，柳亚子作为民主人士参加中国人民政治协商会议的筹备工作，因对工作安排和生活待遇不满，写了《七律·感事呈毛主席》，诗中有「安得南征驰捷报，分湖便是子陵滩」句，流露出退隐回乡之意。毛泽东读到这首诗后，于4月29日写了这首和诗，既肯定了柳亚子的历史贡献，又委婉地批评了他的牢骚情绪，劝他以大局为重，留在北京参加新中国建设。","n":["和柳亚子先生：和，依照别人诗词的题材和体裁做诗词；柳亚子，诗人，国民党左派人士，毛泽东的诗友。1949年3月，柳亚子写了《七律·感事呈毛主席》，诗中流露出退隐之意，毛泽东写这首诗劝慰他","饮茶粤海未能忘：在广州一起喝茶的事不能忘怀。饮茶粤海，1926年毛泽东在广州主持农民运动讲习所时，与柳亚子相识，曾一起饮茶；粤海，指广州","索句渝州叶正黄：在重庆索取诗句时树叶正黄。索句，索取诗句，指互相唱和；渝州，指重庆；叶正黄，指秋天，1945年8月至10月，毛泽东赴重庆谈判，与柳亚子重逢，曾书赠《沁园春·雪》","三十一年还旧国：三十一年后回到了旧都。三十一年，从1918年毛泽东第一次到北京到1949年回到北京，正好三十一年；旧国，指北京，北京曾是元明清三代的都城","落花时节读华章：在落花时节读到了你的华美诗篇。落花时节，指暮春，用杜甫《江南逢李龟年》「正是江南好风景，落花时节又逢君」诗意；华章，华美的诗篇，指柳亚子的《感事呈毛主席》","牢骚太盛防肠断：牢骚太多了要防止肠子断。牢骚，抑郁不满的情绪；太盛，太多；防肠断，防止伤身体","风物长宜放眼量：对世间万物应该放长远眼光去衡量。风物，风光景物，这里指世间的事物；长宜，应该经常；放眼量，放开眼界去衡量","莫道昆明池水浅：不要说昆明湖的水浅。昆明池，指北京颐和园的昆明湖；水浅，比喻地方小、条件差","观鱼胜过富春江：在昆明湖观鱼胜过在富春江隐居。观鱼，用《庄子·秋水》「庄子与惠子游于濠梁之上，观鱼之乐」典故，也暗指柳亚子诗中「分湖便是子陵滩」的退隐之意；富春江，在浙江，东汉严子陵曾在此隐居垂钓。这里劝柳亚子留在北京参加新中国建设，比去富春江隐居更好"]},"浣溪沙·和柳亚子先生|毛泽东":{"s":"上片写旧中国的黑暗，「长夜难明赤县天，百年魔怪舞翩跹，人民五亿不团圆」以「长夜难明」比喻旧社会的黑暗漫长——漫长的黑夜难以天亮，以「百年魔怪舞翩跹」比喻一百多年来帝国主义、封建主义和官僚资本主义的横行——一百多年来妖魔鬼怪翩翩起舞，以「人民五亿不团圆」写旧中国人民的苦难——五亿人民不能团圆，三句层层递进，写出了旧中国的黑暗和人民的苦难；下片写新中国的光明，「一唱雄鸡天下白，万方乐奏有于阗，诗人兴会更无前」以「一唱雄鸡天下白」比喻新中国的成立——雄鸡一叫天就亮了，黑暗的旧时代结束了，以「万方乐奏有于阗」写新中国各民族的大团结——全国各地都演奏起欢乐的乐曲，其中还有来自新疆于阗的乐曲，以「诗人兴会更无前」写诗人的兴奋——诗人的兴致前所未有，「更无前」三字将欢乐的气氛推向高潮。全词对比鲜明、用典自然、意境开阔、情感激昂、充满对新中国的赞美和对各民族大团结的歌颂，是毛泽东诗词中歌颂新中国的名篇。","b":"1950年10月3日，新中国成立一周年之际，全国各民族代表在北京怀仁堂举行联欢晚会，西南各民族文工团、新疆文工团、吉林省延边文工团、内蒙古文工团联合演出了歌舞节目。毛泽东、刘少奇、周恩来等党和国家领导人出席了晚会。柳亚子当场填了一首《浣溪沙》，毛泽东当场和了这首词，通过新旧社会的对比，歌颂了新中国的成立和各民族的大团结。","n":["浣溪沙：词牌名","和柳亚子先生：1950年10月，新中国成立一周年之际，全国各民族代表在北京怀仁堂举行联欢晚会，柳亚子即席填了一首《浣溪沙》，毛泽东当场和了这首词","长夜难明赤县天：漫长的黑夜难以天亮，这是旧中国的天空。长夜难明，比喻旧社会的黑暗漫长；赤县，指中国，战国时邹衍称中国为「赤县神州」","百年魔怪舞翩跹：一百多年来妖魔鬼怪翩翩起舞。百年，指1840年鸦片战争以来的一百多年；魔怪，比喻帝国主义、封建主义和官僚资本主义；翩跹音piānxiān，形容轻快地跳舞","人民五亿不团圆：五亿人民不能团圆。人民五亿，当时中国人口约五亿；不团圆，指国家分裂、人民不能团聚","一唱雄鸡天下白：雄鸡一叫，天就亮了。比喻新中国成立，黑暗的旧时代结束了。用唐李贺《致酒行》「雄鸡一声天下白」句","万方乐奏有于阗：全国各地都演奏起欢乐的乐曲，其中还有来自新疆于阗的乐曲。万方，全国各地；乐奏，演奏乐曲；于阗音tián，汉西域国名，在今新疆和田一带，这里指新疆各民族的文工团","诗人兴会更无前：诗人的兴致更是前所未有。诗人，指柳亚子，也可泛指与会的诗人；兴会，兴致；更无前，前所未有"]},"清平乐·会昌|毛泽东":{"s":"上片抒情，「东方欲晓，莫道君行早」以「东方欲晓」写时间——东方快要天亮了，以「莫道君行早」写词人的行动——不要说你走得早，暗含「莫道君行早，更有早行人」之意，也暗示革命的道路还很长；「踏遍青山人未老，风景这边独好」以「踏遍青山」写革命的历程——走遍了青山，转战南北，以「人未老」写革命精神的旺盛——人还没有衰老，以「风景这边独好」写对会昌一带的赞美——这里的风景特别好，「独好」二字既写了自然风景，也暗含了对革命根据地的感情；下片写景，「会昌城外高峰，颠连直接东溟」写会昌城外的高峰——山峰连绵不断，一直连接到东海，「直接东溟」写出了山峰的连绵和壮阔；「战士指看南粤，更加郁郁葱葱」写战士们指着南方的广东方向看——那里的草木更加茂盛，「郁郁葱葱」既写了草木的茂盛，也比喻革命的生机和希望。全词意境开阔、写景抒情融为一体、充满革命乐观主义精神和对革命胜利的坚定信念，「踏遍青山人未老，风景这边独好」成为名句，是毛泽东诗词中的名篇。","b":"1934年夏，中央革命根据地第五次反「围剿」失利，形势十分危急。当时毛泽东因受到「左」倾路线的排挤，被调离红军主要领导岗位，在会昌一带做地方工作。7月的一天清晨，毛泽东登上会昌城外的岚山岭，面对南方的壮丽景色，回顾革命的战斗历程，写下了这首词，表达了对革命前途的乐观态度和对革命胜利的坚定信念。","n":["清平乐：词牌名","会昌：县名，在江西南部，是中央革命根据地的南大门","东方欲晓：东方快要天亮了。欲，将要","莫道君行早：不要说你走得早。君，你，这里是词人自指，也可指红军战士","踏遍青山人未老：走遍了青山，人还没有衰老。踏遍青山，指转战南北；人未老，指革命精神还很旺盛","风景这边独好：这里的风景特别好。这边，指会昌一带；独好，特别好","会昌城外高峰：会昌城外的高峰，指会昌城外的岚山岭","颠连直接东溟：山峰连绵不断，一直连接到东海。颠连，山峰连绵不断；东溟，东海。溟音míng","战士指看南粤：战士们指着南方的广东方向看。指看，指着看；南粤，指广东，广东古属南越","更加郁郁葱葱：更加草木茂盛，充满生机。郁郁葱葱，草木茂盛的样子，也比喻气象旺盛"]},"十六字令三首|毛泽东":{"s":"第一首写山之高，「山，快马加鞭未下鞍。惊回首，离天三尺三」以「快马加鞭未下鞍」写红军行军的急促——快马加鞭还没有下马，以「惊回首，离天三尺三」写山之高——猛然回头一看，山离天只有三尺三了，「惊」字写出了红军翻越高山时的惊叹，「离天三尺三」以夸张的手法极言山之高；第二首写山之势，「山，倒海翻江卷巨澜。奔腾急，万马战犹酣」以「倒海翻江卷巨澜」写群山的气势——群山像翻江倒海卷起巨大的波澜，以「奔腾急，万马战犹酣」写群山的动态——群山奔腾急促，像万马正在激烈地战斗，把静止的山写成了奔腾的万马，充满了战斗的激情；第三首写山之坚，「山，刺破青天锷未残。天欲堕，赖以拄其间」以「刺破青天锷未残」写山的锋利——山像宝剑一样刺破了青天，剑锋还没有残缺，以「天欲堕，赖以拄其间」写山的作用——天好像要塌下来，全靠山支撑在天地之间，把山写成了顶天立地的擎天柱，象征着红军和中国共产党顶天立地的英雄气概。三首小令各有侧重，第一首写高、第二首写势、第三首写坚，合起来塑造了一个高大、雄伟、坚定的山的形象，也象征着红军的英雄形象。全词想象奇特、比喻新颖、夸张巧妙、气势磅礴、充满革命英雄主义精神，是毛泽东诗词中短小精悍的名篇。","b":"1934年至1935年间，红军长征途中翻越了无数崇山峻岭。毛泽东在长征途中，面对连绵起伏的群山，写下了这三首小令，通过对山的三种不同形象的描绘，歌颂了红军不怕艰难险阻的革命英雄主义精神和顶天立地的英雄气概。","n":["十六字令：词牌名，全词仅十六字，是最短的词牌之一","山，快马加鞭未下鞍：山啊，快马加鞭还没有下鞍。快马加鞭，跑得很快的马再加上几鞭，比喻快上加快；未下鞍，还没有下马","惊回首，离天三尺三：猛然回头一看，山离天只有三尺三了。惊，猛然；回首，回头看；离天三尺三，极言山之高，是夸张的说法","山，倒海翻江卷巨澜：山啊，像翻江倒海卷起巨大的波澜。倒海翻江，形容声势浩大；巨澜，巨大的波澜。这里把山比作翻江倒海的波澜","奔腾急，万马战犹酣：群山奔腾急促，像万马正在激烈地战斗。奔腾急，奔腾急促；万马战犹酣，像万马战斗正激烈。酣音hān，激烈，尽兴","山，刺破青天锷未残：山啊，刺破了青天，剑锋还没有残缺。锷音è，刀剑的刃；未残，没有残缺。这里把山比作刺破青天的宝剑","天欲堕，赖以拄其间：天好像要塌下来，全靠山支撑在天地之间。欲堕，将要塌下来；赖以，依靠它；拄音zhǔ，支撑；其间，指天地之间"]},"七律·冬云|毛泽东":{"s":"首联「雪压冬云白絮飞，万花纷谢一时稀」以「雪压冬云白絮飞」写严冬的景象——大雪压着冬云，雪花像白絮一样飞舞，以「万花纷谢一时稀」写百花的凋谢——各种花纷纷凋谢，一时之间显得稀少，比喻在严峻的形势下，一些人动摇退缩了；颔联「高天滚滚寒流急，大地微微暖气吹」以「高天滚滚寒流急」写寒流的猛烈——高空的寒流滚滚而来十分急促，以「大地微微暖气吹」写暖气的微弱——大地上微微有暖气吹来，「寒流」与「暖气」对比，寒流虽然猛烈，但暖气已经在大地上萌生，比喻革命的力量虽然还微弱，但正在生长；颈联「独有英雄驱虎豹，更无豪杰怕熊罴」以「独有英雄驱虎豹」写英雄的无畏——只有英雄豪杰才能驱赶虎豹，以「更无豪杰怕熊罴」写豪杰的勇敢——更没有豪杰害怕熊罴，「虎豹」「熊罴」比喻凶恶的敌人，「独有」「更无」突出了革命战士不畏强暴的英雄气概；尾联「梅花欢喜漫天雪，冻死苍蝇未足奇」以「梅花欢喜漫天雪」写梅花的品格——梅花喜欢漫天的大雪，越是严寒越开放，以「冻死苍蝇未足奇」写苍蝇的下场——冻死了苍蝇也不值得奇怪，「梅花」比喻革命战士，「苍蝇」比喻微不足道的敌人，在严寒中梅花傲然开放，苍蝇却被冻死了，对比鲜明，寓意深刻。全诗比喻丰富、对比鲜明、对仗工稳、气势磅礴、充满革命英雄主义精神，是毛泽东诗词中托物言志的名篇。","b":"1962年冬，国际上反华势力猖獗，苏联领导人推行霸权主义，对中国施加压力，国内也面临着严重的经济困难。面对严峻的国际国内形势，毛泽东写下了这首诗，以冬云、寒流、虎豹、熊罴、苍蝇比喻凶恶的敌人和困难，以梅花比喻革命战士，表达了中国共产党和中国人民不畏强暴、敢于斗争的革命英雄主义精神。","n":["冬云：冬天的云","雪压冬云白絮飞：大雪压着冬天的云，白色的雪花像棉絮一样飞舞。白絮，白色的棉絮，比喻雪花","万花纷谢一时稀：各种花纷纷凋谢，一时之间显得稀少了。万花纷谢，各种花纷纷凋谢；一时稀，一时之间显得稀少","高天滚滚寒流急：高空的寒流滚滚而来，十分急促。高天，高空；滚滚，形容水流翻腾，这里形容寒流的猛烈","大地微微暖气吹：大地上微微有暖气吹来。微微，轻微；暖气，指春天的暖气，也比喻革命的力量","独有英雄驱虎豹：只有英雄豪杰才能驱赶虎豹。独有，只有；英雄，指革命战士；驱，驱赶；虎豹，比喻凶恶的敌人","更无豪杰怕熊罴：更没有豪杰害怕熊罴。更无，更没有；豪杰，英雄豪杰；熊罴音pí，熊和罴，比喻凶恶的敌人。罴，棕熊","梅花欢喜漫天雪：梅花喜欢漫天的大雪。欢喜，喜欢；漫天，满天","冻死苍蝇未足奇：冻死了苍蝇也不值得奇怪。苍蝇，比喻微不足道的敌人；未足奇，不值得奇怪"]},"满江红·和郭沫若同志|毛泽东":{"s":"上片写反华势力的猖獗和衰落，「小小寰球，有几个苍蝇碰壁」以「小小寰球」写地球之小，以「苍蝇碰壁」比喻反华势力的猖獗和失败——小小的地球上，有几个苍蝇在墙壁上乱撞；「嗡嗡叫，几声凄厉，几声抽泣」以「嗡嗡叫」「凄厉」「抽泣」写反华势力的叫嚣和悲哀——嗡嗡地叫，几声凄凉尖厉，几声抽抽泣泣，形象生动；「蚂蚁缘槐夸大国，蚍蜉撼树谈何易」用「南柯一梦」和「蚍蜉撼树」两个典故，写反华势力的狂妄和不自量力——蚂蚁沿着槐树爬还夸耀国家大，蚍蜉想摇动大树谈何容易；「正西风落叶下长安，飞鸣镝」以「西风落叶」比喻反华势力的衰落，以「飞鸣镝」写革命的攻势——正当西风落叶飘满长安的时候，我们射出了响箭；下片写革命形势和战斗决心，「多少事，从来急；天地转，光阴迫。一万年太久，只争朝夕」以「从来急」「光阴迫」写时间的紧迫，以「一万年太久，只争朝夕」写只争朝夕的战斗精神——一万年太久了，要争取早晨和晚上的时间，这是全词的名句，也是毛泽东革命精神的生动写照；「四海翻腾云水怒，五洲震荡风雷激」以「四海翻腾」「五洲震荡」写世界革命形势的高涨——四海之内翻腾，云水发怒；五大洲震荡，风雷激荡；「要扫除一切害人虫，全无敌」以「扫除一切害人虫」写战斗目标，以「全无敌」写革命的必胜信念——要扫除一切害人的虫子，全世界没有敌手。全词比喻丰富、用典贴切、气势磅礴、情感激昂、充满革命精神，「一万年太久，只争朝夕」成为千古名句，是毛泽东诗词中战斗精神的代表作。","b":"1962年冬至1963年初，国际上反华势力猖獗，苏联领导人推行霸权主义，与中国共产党的分歧日益加深。1963年元旦，郭沫若写了《满江红·1963年元旦抒怀》，词中表达了对国际形势的看法。毛泽东读了之后，于1月9日写了这首和词，以苍蝇、蚂蚁、蚍蜉比喻反华势力，以「四海翻腾」「五洲震荡」写革命形势，表达了中国共产党和中国人民不畏强暴、敢于斗争的革命精神。","n":["满江红：词牌名","和郭沫若同志：1963年1月，郭沫若写了《满江红·1963年元旦抒怀》，毛泽东读了之后写了这首和词","小小寰球：小小的地球。寰球，地球","有几个苍蝇碰壁：有几个苍蝇在墙壁上乱撞。苍蝇，比喻国际上反华势力；碰壁，比喻遭到失败","嗡嗡叫：嗡嗡地叫，比喻反华势力的叫嚣","几声凄厉：几声凄凉尖厉的叫声。凄厉，凄凉尖厉","几声抽泣：几声抽抽搭搭的哭泣声。抽泣，低声哭泣","蚂蚁缘槐夸大国：蚂蚁沿着槐树爬，还夸耀自己的国家大。用唐李公佐《南柯太守传》「槐安国」典故——淳于棼梦入槐安国，当了驸马和南柯太守，醒来发现槐安国原来是槐树下的蚂蚁窝。缘，沿着；夸大国，夸耀自己的国家大","蚍蜉撼树谈何易：蚂蚁想摇动大树，谈何容易。蚍蜉音pífú，大蚂蚁；撼，摇动。用唐韩愈《调张籍》「蚍蜉撼大树，可笑不自量」诗意","正西风落叶下长安：正当西风把落叶吹到长安城下的时候。西风落叶，比喻反华势力的衰落；长安，汉唐都城，这里代指中国。用唐贾岛《忆江上吴处士》「秋风生渭水，落叶满长安」诗意","飞鸣镝：射出响箭。鸣镝音dí，响箭，古代射出时发出声响的箭，比喻革命的攻势","多少事，从来急：多少事情，从来都是急迫的","天地转，光阴迫：天地在运转，光阴紧迫。迫，紧迫","一万年太久，只争朝夕：一万年太久了，要争取早晨和晚上的时间。朝夕，早晨和晚上，形容时间短暂","四海翻腾云水怒：四海之内翻腾，云和水都在发怒。四海，指全世界；翻腾，指革命运动高涨；云水怒，云和水都发怒，比喻革命形势的猛烈","五洲震荡风雷激：五大洲震荡，风和雷都在激荡。五洲，指全世界；震荡，震动激荡；风雷激，风雷激荡，比喻革命运动的激烈","要扫除一切害人虫，全无敌：要扫除一切害人的虫子，全世界没有敌手。害人虫，比喻一切敌人；全无敌，全世界没有敌手"]},"水调歌头·重上井冈山|毛泽东":{"s":"上片写重上井冈山的所见所感，「久有凌云志，重上井冈山」以「久有凌云志」写词人的远大志向——很早就有了凌云的壮志，以「重上井冈山」写这次行动——重新登上了井冈山；「千里来寻故地，旧貌变新颜」以「千里来寻故地」写行程之远——从千里之外来寻找旧地，以「旧貌变新颜」写井冈山的变化——旧的面貌变成了新的容颜，38年过去，井冈山发生了翻天覆地的变化；「到处莺歌燕舞，更有潺潺流水，高路入云端」以「莺歌燕舞」「潺潺流水」「高路入云端」写井冈山的新貌——到处莺歌燕舞，更有潺潺流水，高高的公路直通云端，描绘了一幅生机勃勃的井冈山新貌图；「过了黄洋界，险处不须看」以「过了黄洋界」写行程，以「险处不须看」写词人的豪迈——过了黄洋界，险要的地方也不必看了，「不须看」三字充满了对艰难险阻的蔑视；下片写革命的豪情和壮志，「风雷动，旌旗奋，是人寰」以「风雷动」「旌旗奋」写革命形势——风雷在动，旌旗在奋飞，这就是人间；「三十八年过去，弹指一挥间」以「三十八年过去」写时间的跨度，以「弹指一挥间」写时间的短暂——三十八年过去了，如同弹一下手指、挥一下手那样短暂；「可上九天揽月，可下五洋捉鳖，谈笑凯歌还」以「九天揽月」「五洋捉鳖」写革命的豪情壮志——可以上九天摘月，可以下五洋捉鳖，在谈笑声中高唱凯歌胜利归来，想象奇特、气势磅礴；「世上无难事，只要肯登攀」以「世上无难事」写革命的信念，以「只要肯登攀」写革命的精神——世界上没有困难的事情，只要肯攀登，这是全词的名句，也是毛泽东革命精神的生动写照。全词意境开阔、想象奇特、气势磅礴、情感激昂、充满革命豪情和乐观主义精神，「可上九天揽月，可下五洋捉鳖」「世上无难事，只要肯登攀」成为千古名句，是毛泽东诗词中革命豪情的代表作。","b":"1965年5月22日至29日，毛泽东重上井冈山，这是他1927年秋收起义后率部上井冈山创建中国第一个农村革命根据地以来，时隔38年第一次重上井冈山。在井冈山期间，毛泽东视察了井冈山的建设，会见了老红军、烈士家属和当地群众，回顾了井冈山的斗争历史，展望了革命的未来，写下了这首词，表达了将革命进行到底的决心和「世上无难事，只要肯登攀」的革命精神。","n":["水调歌头：词牌名","重上井冈山：1965年5月，毛泽东重上井冈山，这是他1927年秋收起义后率部上井冈山以来，时隔38年第一次重上井冈山","久有凌云志：很早就有了凌云的壮志。凌云志，凌云的壮志，比喻远大的革命志向","重上井冈山：重新登上了井冈山","千里来寻故地：从千里之外来寻找旧地。故地，旧地，指井冈山革命根据地","旧貌变新颜：旧的面貌变成了新的容颜。指井冈山发生了翻天覆地的变化","到处莺歌燕舞：到处都是黄莺歌唱燕子飞舞。莺歌燕舞，形容春天的美好景象，也比喻革命形势的大好","更有潺潺流水：更有潺潺的流水。潺潺音chán，形容水流动的声音","高路入云端：高高的公路直通云端。高路，指盘山公路；入云端，直通云端，形容公路之高","过了黄洋界：过了黄洋界哨口。黄洋界，井冈山五大哨口之一","险处不须看：险要的地方也不必看了。不须，不必","风雷动，旌旗奋，是人寰：风雷在动，旌旗在奋飞，这就是人间。风雷动，比喻革命运动；旌旗奋，旌旗奋飞，比喻革命力量；人寰，人间","三十八年过去：三十八年过去了。从1927年毛泽东率部上井冈山到1965年重上井冈山，正好三十八年","弹指一挥间：如同弹一下手指、挥一下手那样短暂。弹指，佛家语，比喻时间极短；一挥间，一挥手之间","可上九天揽月：可以上到九天的高处去摘取月亮。九天，天的最高处；揽月，摘取月亮。揽，采摘","可下五洋捉鳖：可以下到五大洋的深处去捉鳖。五洋，指太平洋、大西洋、印度洋、北冰洋、南冰洋，泛指全世界的海洋；捉鳖，捉甲鱼，比喻擒拿敌人。鳖音biē，甲鱼","谈笑凯歌还：在谈笑声中高唱凯歌胜利归来。凯歌，胜利的歌","世上无难事：世界上没有困难的事情","只要肯登攀：只要肯攀登。登攀，攀登"]},"念奴娇·昆仑|毛泽东":{"s":"上片写昆仑山的雄伟和功过，「横空出世，莽昆仑，阅尽人间春色」以「横空出世」写昆仑山的雄伟——横亘在空中，超出人世，以「莽昆仑」写昆仑山的辽阔——莽莽的昆仑山，以「阅尽人间春色」写昆仑山的古老——看尽了人间的春天景色；「飞起玉龙三百万，搅得周天寒彻」以「玉龙三百万」比喻积雪的山峰——飞起了三百万条玉龙，以「搅得周天寒彻」写昆仑山的寒冷——搅得整个天地都寒冷透了，想象奇特、气势磅礴；「夏日消溶，江河横溢，人或为鱼鳖」写昆仑山的「过」——夏天冰雪消融，江河洪水泛滥，人们有的被淹死变成了鱼鳖；「千秋功罪，谁人曾与评说」以反问写昆仑山的功过无人评论——千年的功绩和罪过，谁曾经给过评论？下片写改造昆仑山的伟大理想，「而今我谓昆仑：不要这高，不要这多雪」以「我谓昆仑」直接对昆仑山说话——现在我对昆仑山说，不要这么高，不要这么多雪；「安得倚天抽宝剑，把汝裁为三截？」以「倚天抽宝剑」写词人的豪情——怎么能够靠着天抽出宝剑，把你裁成三截？想象奇特、气势磅礴；「一截遗欧，一截赠美，一截还东国」写改造昆仑山的方案——一截送给欧洲，一截赠给美洲，一截还给东方各国，把昆仑山的雪水分给全世界；「太平世界，环球同此凉热」以「太平世界」写理想，以「环球同此凉热」写世界大同——太平的世界，全世界都同样享受这凉爽和温暖，表达了改造世界、实现世界大同的伟大理想。全词想象奇特、气势磅礴、意境壮阔、情感激昂、充满改造世界的伟大理想，「安得倚天抽宝剑，把汝裁为三截」「太平世界，环球同此凉热」成为名句，是毛泽东诗词中浪漫主义的代表作。","b":"1935年10月，毛泽东率领中央红军翻越岷山，即将到达陕北。在岷山上，毛泽东远望昆仑山的壮丽景色，回顾长征的战斗历程，展望革命的未来，写下了这首词。词人通过对昆仑山的描绘和评论，表达了改造世界、实现世界大同的伟大理想。","n":["念奴娇：词牌名","昆仑：昆仑山，西起帕米尔高原，横贯新疆、西藏，东延入青海，是中国最大的山脉之一","横空出世：横亘在空中，超出人世。横空，横亘在空中；出世，超出人世","莽昆仑：莽莽的昆仑山。莽，莽莽，形容无边无际","阅尽人间春色：看尽了人间的春天景色。阅尽，看尽；春色，春天的景色，比喻人间的美好事物","飞起玉龙三百万：飞起了三百万条玉龙。玉龙，比喻积雪的山峰，昆仑山终年积雪，山峰连绵，像无数条玉龙；三百万，极言其多","搅得周天寒彻：搅得整个天地都寒冷透了。周天，整个天地；寒彻，寒冷透了","夏日消溶：夏天冰雪消融。消溶，消融","江河横溢：江河洪水泛滥。横溢，洪水泛滥","人或为鱼鳖：人们有的变成了鱼鳖。或，有的；为，变成；鱼鳖，鱼和鳖，指被淹死。鳖音biē","千秋功罪：千年的功绩和罪过。千秋，千年；功罪，功绩和罪过","谁人曾与评说：谁曾经给过评论。评说，评论","而今我谓昆仑：现在我对昆仑山说。谓，对……说","不要这高：不要这么高","不要这多雪：不要这么多雪","安得倚天抽宝剑：怎么能够靠着天抽出宝剑。安得，怎么能够；倚天，靠着天，形容宝剑之长","把汝裁为三截：把你裁成三截。汝，你，指昆仑山；裁，裁剪","一截遗欧：一截送给欧洲。遗音wèi，赠送","一截赠美：一截赠给美洲","一截还东国：一截还给东方各国。东国，东方各国","太平世界：太平的世界","环球同此凉热：全世界都同样享受这凉爽和温暖。环球，全世界；同此凉热，同样享受这凉热，比喻世界大同"]},"贺新郎·读史|毛泽东":{"s":"上片写人类社会的发展史，「人猿相揖别。只几个石头磨过，小儿时节」以「人猿相揖别」写人类的起源——人和猿拱手相别，以「只几个石头磨过」写旧石器时代——只有几个磨过的石头，以「小儿时节」比喻人类社会的早期——像小孩子的时代；「铜铁炉中翻火焰，为问何时猜得？不过几千寒热」以「铜铁炉中翻火焰」写青铜器和铁器时代——铜铁炉中翻起火焰，以「不过几千寒热」写时间的短暂——不过几千年的冷暖，从石器时代到铜器铁器时代，人类社会经历了漫长的发展；「人世难逢开口笑，上疆场彼此弯弓月。流遍了，郊原血」以「人世难逢开口笑」写人生的苦难——人生在世难得开口一笑，以「上疆场彼此弯弓月」写战争的残酷——到战场上彼此弯弓如月，以「流遍了，郊原血」写战争的灾难——流遍了郊外原野上的血，人类社会的历史充满了战争和苦难；下片写对历史的评论，「一篇读罢头飞雪，但记得斑斑点点，几行陈迹」以「一篇读罢头飞雪」写读史的感慨——一篇历史读完头发已经白了像飞雪，以「斑斑点点」「几行陈迹」写历史的痕迹——只记得斑斑点点的几行陈旧遗迹；「五帝三皇神圣事，骗了无涯过客」以「五帝三皇神圣事」写传统的历史观——五帝三皇的神圣事业，以「骗了无涯过客」写对传统历史观的批判——欺骗了无数的后人，所谓「神圣事业」不过是欺骗后人的谎言；「有多少风流人物？盗跖庄蹻流誉后，更陈王奋起挥黄钺」以反问「有多少风流人物」引出真正的英雄——盗跖和庄蹻的名声流传到后世，更有陈胜奋起挥动黄钺，词人把农民起义领袖看作真正的风流人物，表达了历史唯物主义观点——人民群众是历史的创造者；「歌未竟，东方白」以「歌未竟」写词还没有写完，以「东方白」写革命即将胜利——歌还没有唱完，东方已经发白了，以景结情，表达了对革命胜利的信心。全词气势磅礴、概括力强、观点鲜明、用典自然、充满历史唯物主义精神，「盗跖庄蹻流誉后，更陈王奋起挥黄钺」「歌未竟，东方白」成为名句，是毛泽东诗词中咏史的代表作。","b":"1964年春，毛泽东在读了大量历史书籍后，写下了这首词，通过对人类社会发展史的概括和评论，表达了他的历史唯物主义观点——人民群众是历史的创造者，农民起义是推动历史发展的动力。词人以磅礴的气势概括了从人类起源到现代社会的历史，评论了历史上的英雄人物，歌颂了农民起义领袖，表达了对革命胜利的信心。","n":["贺新郎：词牌名","读史：读历史","人猿相揖别：人和猿拱手相别。揖别，拱手告别，指人类从猿进化而来","只几个石头磨过：只有几个磨过的石头。指旧石器时代，人类使用打制石器","小儿时节：像小孩子的时代。比喻人类社会的早期","铜铁炉中翻火焰：铜铁炉中翻起火焰。指青铜器时代和铁器时代，人类使用铜器和铁器","为问何时猜得：请问什么时候能够猜得到。为问，请问；猜得，猜得到","不过几千寒热：不过几千年的冷暖。寒热，冷暖，指岁月。从铜器时代到毛泽东时代不过几千年","人世难逢开口笑：人生在世难得开口一笑。用唐杜牧《九日齐山登高》「尘世难逢开口笑」句","上疆场彼此弯弓月：到战场上彼此弯弓如月。疆场，战场；弯弓月，把弓拉得像月亮一样圆","流遍了，郊原血：流遍了，郊外原野上的血。郊原，郊外原野","一篇读罢头飞雪：一篇历史读完，头发已经白了像飞雪。头飞雪，头发白了像飞雪","但记得斑斑点点：只记得斑斑点点的历史痕迹。斑斑点点，形容历史痕迹的零散","几行陈迹：几行陈旧的遗迹。陈迹，陈旧的遗迹","五帝三皇神圣事：五帝三皇的神圣事业。五帝三皇，传说中的古代帝王；神圣事，神圣的事业","骗了无涯过客：欺骗了无数的过往行人。无涯，无数；过客，过往行人，指后人","有多少风流人物：有多少杰出的人物。风流人物，杰出的人物","盗跖庄蹻流誉后：盗跖和庄蹻的名声流传到后世。盗跖音zhí，春秋末期奴隶起义领袖；庄蹻音qiāo，战国末期楚国农民起义领袖；流誉，名声流传","更陈王奋起挥黄钺：更有陈胜奋起挥动黄色的大斧。陈王，陈胜，秦末农民起义领袖，曾称王；黄钺音yuè，黄色的大斧，古代帝王征伐时用的器具，这里指起义的武器","歌未竟，东方白：歌还没有唱完，东方已经发白了。竟，完毕；东方白，东方天亮了，比喻革命即将胜利"]},"七绝·为女民兵题照|毛泽东":{"s":"首两句「飒爽英姿五尺枪，曙光初照演兵场」写女民兵的英姿——英姿飒爽地握着五尺步枪，清晨的阳光刚刚照在练兵场上，「飒爽英姿」写出了女民兵的豪迈矫健，「曙光初照」写出了练兵场的清晨景象，画面鲜明；后两句「中华儿女多奇志，不爱红装爱武装」写女民兵的精神——中华儿女多有不平凡的志向，不喜爱红装喜爱武装，「多奇志」写出了新中国女性的远大志向，「不爱红装爱武装」对比鲜明，写出了女民兵「不爱红装爱武装」的精神风貌，是全诗的名句。全诗画面鲜明、对比鲜明、语言精炼、情感激昂、充满对新中国女性的赞美和对全民皆兵的期望，「中华儿女多奇志，不爱红装爱武装」成为千古名句，是毛泽东诗词中歌颂女民兵的名篇。","b":"1961年，毛泽东的机要员小李参加民兵训练，拍了一张手持步枪的照片，送给毛泽东看。毛泽东看后非常高兴，当即题写了这首诗，歌颂了新中国女民兵的英姿飒爽和「不爱红装爱武装」的精神风貌，表达了对全民皆兵、保家卫国的期望。","n":["七绝：七言绝句","为女民兵题照：为女民兵的照片题诗。1961年，毛泽东的机要员小李参加民兵训练，拍了一张持步枪的照片，毛泽东看后题写了这首诗","飒爽英姿五尺枪：英姿飒爽地握着五尺长的步枪。飒爽，豪迈矫健；英姿，英俊的姿态；五尺枪，五尺长的步枪","曙光初照演兵场：清晨的阳光刚刚照在练兵场上。曙光，清晨的阳光；初照，刚刚照耀；演兵场，练兵场","中华儿女多奇志：中华儿女多有不平凡的志向。奇志，不平凡的志向","不爱红装爱武装：不喜爱红色的装束，喜爱武装。红装，红色的装束，指女性的打扮；武装，军装，指军事训练"]},"七律·登庐山|毛泽东":{"s":"首联「一山飞峙大江边，跃上葱茏四百旋」写庐山的雄伟和登山的豪迈——一座山飞峙在长江边，跃上了苍翠的山峦盘旋了四百个弯，「飞峙」二字写出了庐山的雄伟，「跃上」二字写出了登山的豪迈；颔联「冷眼向洋看世界，热风吹雨洒江天」写对世界形势的观察和庐山的景色——用冷静的眼光向着海洋看世界，热风吹着细雨洒在江天之上，「冷眼向洋」写出了词人对世界形势的冷静观察，「热风吹雨」写出了庐山夏天的景色，一冷一热，对比鲜明；颈联「云横九派浮黄鹤，浪下三吴起白烟」写长江的壮丽景色——云横亘在长江九条支流之上，黄鹤在云中飘浮；波浪向下游的三吴地区冲去，泛起白色的烟雾，「云横九派」「浪下三吴」写出了长江的壮阔，「浮黄鹤」「起白烟」增添了浪漫色彩；尾联「陶令不知何处去，桃花源里可耕田」以陶渊明和桃花源的典故收尾——陶渊明不知道到哪里去了，桃花源里还可以耕田吗？用《桃花源记》的典故，问桃花源里是否还能耕田，暗含对理想社会的思考——理想中的世外桃源是否还能存在？全诗意境壮阔、用典自然、对仗工稳、情感深沉、充满对世界形势的观察和对理想社会的思考，「冷眼向洋看世界，热风吹雨洒江天」成为名句，是毛泽东诗词中写景抒情的名篇。","b":"1959年7月，毛泽东在庐山召开中共中央政治局扩大会议（即庐山会议），会议初期旨在总结「大跃进」以来的经验教训，纠正「左」的错误。会议期间，毛泽东登上庐山，面对庐山的壮丽景色和复杂的国内外形势，写下了这首诗，表达了对世界形势的观察和对理想社会的思考。","n":["七律：七言律诗","登庐山：1959年7月，毛泽东在庐山召开中共中央政治局扩大会议（即庐山会议）期间，登上庐山，写下了这首诗","一山飞峙大江边：一座山飞峙在长江边。飞峙，飞耸屹立；大江，指长江。庐山在长江南岸，九江市南","跃上葱茏四百旋：跃上了苍翠的山峦，盘旋了四百个弯。葱茏，草木苍翠茂盛，这里指庐山；四百旋，指盘山公路有四百个弯道。旋，转弯","冷眼向洋看世界：用冷静的眼光向着海洋看世界。冷眼，冷静的眼光；向洋，向着海洋；看世界，观察世界形势","热风吹雨洒江天：热风吹着细雨洒在江天之上。热风，夏天的热风；洒，洒落；江天，江和天","云横九派浮黄鹤：云横亘在长江九条支流之上，黄鹤在云中飘浮。九派，长江在湖北江西一带的九条支流；浮黄鹤，飘浮着黄鹤，用崔颢《黄鹤楼》「黄鹤一去不复返，白云千载空悠悠」诗意","浪下三吴起白烟：波浪向下游的三吴地区冲去，泛起白色的烟雾。三吴，指吴郡、吴兴、会稽，泛指长江下游的江浙一带；白烟，白色的烟雾","陶令不知何处去：陶渊明不知道到哪里去了。陶令，陶渊明，曾任彭泽县令，故称陶令","桃花源里可耕田：桃花源里还可以耕田吗？桃花源，用陶渊明《桃花源记》的典故，指理想中的世外桃源。可耕田，可以耕田，这里问桃花源里是否还能耕田，暗含对理想社会的思考"]},"七律二首·送瘟神·其一|毛泽东":{"s":"首联「绿水青山枉自多，华佗无奈小虫何」写血吸虫病的危害——绿水青山空自很多，华佗也对这小小的虫子无可奈何，「枉自多」写出了绿水青山的徒然，「华佗无奈小虫何」写出了血吸虫病的难治，连名医华佗也无可奈何；颔联「千村薜荔人遗矢，万户萧疏鬼唱歌」写血吸虫病造成的灾难——上千个村庄长满了薜荔，人们拉稀便；上万户人家萧条冷落，鬼在唱歌，「千村薜荔」「万户萧疏」写出了村庄的荒芜，「人遗矢」「鬼唱歌」写出了人民的苦难，画面触目惊心；颈联「坐地日行八万里，巡天遥看一千河」以浪漫主义的想象写词人的思绪——坐在地上一天就走了八万里，在天上巡游远远地看一千条银河，「坐地日行八万里」用地球自转的科学知识，「巡天遥看一千河」用宇宙运行的想象，想象奇特、气势磅礴，是全诗的名句；尾联「牛郎欲问瘟神事，一样悲欢逐逝波」以牛郎的典故收尾——牛郎想要问瘟神的事情，一样的悲欢离合都随着流逝的波浪而去了，牛郎是农民出身，关心民间疾苦，他问瘟神的事情，得到的回答是「一样悲欢逐逝波」——在旧中国，人民的悲欢离合都随着流逝的波浪而去了，瘟神肆虐，人民苦难。全诗意境壮阔、想象奇特、对比鲜明、情感深沉、充满对人民苦难的同情和对血吸虫病的控诉，「坐地日行八万里，巡天遥看一千河」成为千古名句，是毛泽东诗词中浪漫主义的代表作。","b":"1958年6月30日，《人民日报》发表了《第一面红旗——记江西余江县根本消灭血吸虫病的经过》的报道。毛泽东读了这篇报道后，非常激动，「浮想联翩，夜不能寐。微风拂煦，旭日临窗。遥望南天，欣然命笔」，于7月1日写下了《七律二首·送瘟神》。第一首写旧中国血吸虫病的危害和人民的苦难，第二首写新中国消灭血吸虫病的胜利和人民的欢乐。","n":["七律二首·送瘟神：1958年7月1日，毛泽东读了《人民日报》关于江西省余江县消灭血吸虫病的报道后，「浮想联翩，夜不能寐」，写下了这两首诗。瘟神，指血吸虫病。送瘟神，送走瘟神，即消灭血吸虫病","绿水青山枉自多：绿水青山空自很多。枉自，空自，徒然","华佗无奈小虫何：华佗也对这小小的虫子无可奈何。华佗，东汉末年的名医；无奈……何，对……无可奈何；小虫，指血吸虫","千村薜荔人遗矢：上千个村庄长满了薜荔，人们拉稀便。薜荔音bìlì，一种蔓生植物，这里形容村庄的荒芜；人遗矢，人们拉稀便，遗矢，拉屎，矢同「屎」，血吸虫病的症状之一是腹泻","万户萧疏鬼唱歌：上万户人家萧条冷落，鬼在唱歌。萧疏，萧条冷落；鬼唱歌，形容死人多，鬼在唱歌","坐地日行八万里：坐在地上一天就走了八万里。地球赤道周长约四万公里，即八万里，地球自转一周，人坐在地上就随地球自转了八万里","巡天遥看一千河：在天上巡游，远远地看一千条银河。巡天，在天上巡游，指地球在宇宙中运行；一千河，一千条银河，指无数的星系","牛郎欲问瘟神事：牛郎想要问瘟神的事情。牛郎，神话传说中的牛郎，他是农民出身，关心民间疾苦","一样悲欢逐逝波：一样的悲欢离合都随着流逝的波浪而去了。悲欢，悲哀和欢乐；逐逝波，随着流逝的波浪而去"]},"七律二首·送瘟神·其二|毛泽东":{"s":"首联「春风杨柳万千条，六亿神州尽舜尧」写新中国的欣欣向荣——春风吹拂着万千条杨柳，六亿中国人民都是尧舜一样的圣人，「春风杨柳」写出了新中国的欣欣向荣，「六亿神州尽舜尧」写出了对人民力量的赞美——六亿中国人民都是尧舜一样的圣人，这是对人民群众的高度评价；颔联「红雨随心翻作浪，青山着意化为桥」写新中国人民改造自然的力量——红色的雨随着心意翻作波浪，青山有意化为桥梁，「随心」「着意」写出了人民改造自然的主观能动性，红雨可以翻作浪，青山可以化为桥，人民的力量可以改变一切；颈联「天连五岭银锄落，地动三河铁臂摇」写人民劳动的壮阔场面——天连着五岭，银色的锄头落下；大地震动，三条河流的铁臂在摇动，「银锄落」「铁臂摇」写出了人民劳动的壮阔场面，「天连五岭」「地动三河」写出了劳动范围的广阔，气势磅礴；尾联「借问瘟君欲何往，纸船明烛照天烧」以送瘟神的仪式收尾——请问瘟君想要到哪里去？纸船和明烛照着天空焚烧，「借问瘟君欲何往」用反问写瘟神的末日，「纸船明烛照天烧」写送瘟神的仪式，欢庆消灭血吸虫病的胜利。全诗意境壮阔、想象奇特、对比鲜明、情感激昂、充满对人民力量的赞美和对胜利的欢庆，「春风杨柳万千条，六亿神州尽舜尧」「借问瘟君欲何往，纸船明烛照天烧」成为名句，与第一首形成鲜明对比，是毛泽东诗词中歌颂新中国的名篇。","b":"这是《七律二首·送瘟神》的第二首，写新中国消灭血吸虫病的胜利和人民的欢乐。与第一首写旧中国的苦难形成鲜明对比，表达了对新中国人民力量的赞美和对消灭血吸虫病胜利的欢庆。","n":["春风杨柳万千条：春风吹拂着万千条杨柳","六亿神州尽舜尧：六亿中国人民都是尧舜一样的圣人。六亿，当时中国人口约六亿；神州，指中国；尽，都；舜尧，尧舜，传说中的古代圣君，这里指品德高尚的人","红雨随心翻作浪：红色的雨随着心意翻作波浪。红雨，红色的雨，这里指落花，也比喻革命的潮流；随心，随着心意","青山着意化为桥：青山有意化为桥梁。着意，有意；化为桥，化为桥梁","天连五岭银锄落：天连着五岭，银色的锄头落下。五岭，大庾岭、骑田岭、萌渚岭、都庞岭、越城岭；银锄，银色的锄头，指农民的劳动工具","地动三河铁臂摇：大地震动，三条河流的铁臂在摇动。三河，指黄河、淮河、海河，也泛指全国的河流；铁臂，铁一样的臂膀，指劳动人民的臂膀","借问瘟君欲何往：请问瘟君想要到哪里去。借问，请问；瘟君，对瘟神的戏称；欲何往，想要到哪里去","纸船明烛照天烧：纸船和明烛照着天空焚烧。纸船，民间送瘟神时用纸折的船；明烛，明亮的蜡烛；照天烧，照着天空焚烧，指送瘟神的仪式"]},"虞美人·枕上|毛泽东":{"s":"上片写夜晚的愁苦，「堆来枕上愁何状，江海翻波浪」以「堆来枕上」写愁之多——愁堆积在枕上，以「江海翻波浪」比喻愁之深——像江海翻起了波浪，比喻奇特、情感深沉；「夜长天色总难明，寂寞披衣起坐数寒星」以「夜长天色总难明」写夜的漫长——夜很长，天色总是难以亮，以「寂寞披衣起坐数寒星」写词人的寂寞——寂寞地披上衣服起来坐着数寒星，「数寒星」三字写出了词人的寂寞和无聊，因思念而无法入睡，只能起来数星星；下片写清晨的思念，「晓来百念都灰尽，剩有离人影」以「晓来百念都灰尽」写天亮后的感受——天亮了，各种念头都像灰烬一样消失了，以「剩有离人影」写对妻子的思念——只剩下离人的影子，各种念头都消失了，只有对妻子的思念还在；「一钩残月向西流，对此不抛眼泪也无由」以「一钩残月向西流」写清晨的景色——一钩残月向西边流去，以「对此不抛眼泪也无由」写词人的伤感——面对这样的景色不抛眼泪也没有理由，「向西流」的「流」字写出了月亮移动的样子，也暗示了时光的流逝和离别的愁苦。全词情感真挚、婉约动人、比喻奇特、情景交融、充满对妻子的深切思念和离别的愁苦，是毛泽东诗词中唯一的一首纯爱情词，「堆来枕上愁何状，江海翻波浪」成为名句，与毛泽东后来气势磅礴的诗词风格形成鲜明对比，展现了毛泽东情感世界的另一面。","b":"1921年，毛泽东与杨开慧结婚后不久，因革命工作需要，不得不与杨开慧分别。在一个夜晚，毛泽东思念杨开慧，写下了这首词，表达了对妻子的深切思念和离别的愁苦。这是毛泽东诗词中唯一的一首纯爱情词，也是毛泽东最早的词作之一，情感真挚、婉约动人，与他后来气势磅礴的诗词风格截然不同。","n":["虞美人：词牌名","枕上：在枕上。这是毛泽东1921年写给杨开慧的词，是毛泽东诗词中唯一的一首纯爱情词","堆来枕上愁何状：堆在枕上的愁是什么样子。堆来，堆积而来；愁何状，愁是什么样子","江海翻波浪：像江海翻起了波浪。形容愁之多、愁之深","夜长天色总难明：夜很长，天色总是难以亮。夜长，夜很长；总难明，总是难以亮","寂寞披衣起坐数寒星：寂寞地披上衣服起来坐着数寒星。披衣，披上衣服；数寒星，数着寒冷的星星","晓来百念都灰尽：天亮了，各种念头都像灰烬一样消失了。晓来，天亮了；百念，各种念头；灰尽，像灰烬一样消失了","剩有离人影：只剩下离人的影子。离人，离别之人，指杨开慧；影，影子","一钩残月向西流：一钩残月向西边流去。一钩残月，一弯残月；向西流，向西边移动，「流」字写出了月亮移动的样子","对此不抛眼泪也无由：面对这样的景色不抛眼泪也没有理由。抛眼泪，流泪；无由，没有理由"]},"虽有嘉肴|《礼记》":{"s":"文章以「嘉肴弗食不知旨」类比「至道弗学不知善」，就近取譬，把抽象道理讲得平易可亲；再从学、教两面分写「知不足」「知困」后的自省与自强，最后引《尚书》一语收束，层层推进，逻辑严密。","b":"选自《礼记·学记》，是战国时期儒家论述教育作用与教学规律的名篇，借日常饮食类比讲清「教学相长」的道理。","n":["嘉肴：美味的肉食。肴，做熟的鱼肉","旨：甘美，味美","至道：最好的道理，指圣贤之道","自反：反躬自问，反省自己","自强：自我勉励、奋发图强。强，音qiǎng","教学相长：教和学两方面互相促进、共同提高","《兑命》：《尚书》篇名，「兑」音yuè","学学半：教人是学习的一半；前一「学」音xiào，同「敩」，教导"],"m":"学然后知不足，教然后知困。故曰：教学相长也。","r":"按「类比立论—学教分述—引经作结」三层记诵；重点记两对因果句「知不足→能自反」「知困→能自强」；易错字：嘉、肴、弗、兑。"},"大道之行也|《礼记》":{"s":"文章以对比结构展开：先铺陈「大同」之世天下为公、人得其所、夜不闭户的图景，再写「大道既隐」后以礼义纲纪维系的「小康」，一理想一现实，对照鲜明；大量排比句式使理想社会的画面层层展开，气势充沛。","b":"选自《礼记·礼运》，记孔子在蜡祭之后与弟子言偃的谈话，提出「大同」「小康」两种社会理想，是儒家社会政治思想的经典表述。","n":["天下为公：天下是公众的，天子之位传贤不传子","选贤与能：选拔贤德、推举有才能的人。与，同「举」","讲信修睦：讲求诚信，培养和睦风气","矜寡孤独：矜，同「鳏」，老而无妻；寡，老而无夫；孤，幼而无父；独，老而无子","分、归：分，职分；归，女子出嫁，此指各有归宿","外户而不闭：大门不用上锁。外户，从外面把门带上","大同：儒家理想中的太平盛世","小康：政教清明、礼义有序的社会，较「大同」次一等","世及：世袭，父传子为世，兄传弟为及"],"m":"大道之行也，天下为公。选贤与能，讲信修睦。","r":"抓住「大同—小康」两大块对比背；大同段按「总纲—人际—货力—结果」、小康段按「现状—礼纪—六君子」顺序；易错字：与（举）、矜（鳏）、笃、篡。"},"桃夭|佚名":{"s":"三章重章叠句，以桃花、桃实、桃叶层层推进，暗合新娘由新婚之美到多子多福、家族兴旺的祝愿；「灼灼」二字写花光如火，开后世以花喻美人的先河，欢快明朗，充满生活气息。","b":"出自《诗经·周南》，是周代祝贺新娘出嫁的喜庆乐歌，以桃花起兴，三章分别以花、果、叶祝愿新娘宜室宜家。","n":["夭夭：桃花茂盛、枝条摇曳的样子","灼灼：花朵鲜艳明亮的样子。华，同「花」","之子于归：这位姑娘要出嫁。子，你；归，古代女子出嫁","宜：和顺、适宜，使家庭和睦","有蕡：果实硕大的样子。蕡，音fén","蓁蓁：树叶繁密茂盛的样子。蓁，音zhēn"],"m":"桃之夭夭，灼灼其华。之子于归，宜其室家。","r":"三章结构相同，只换「华—实—叶」「室家—家室—家人」，记住递进线索即可成诵；韵脚华/家、实/室、蓁/人；易错字：灼、蕡、蓁。"},"静女|佚名":{"s":"全诗以男子口吻写成：先写赴约不见恋人、搔首徘徊的焦急，再写收到彤管、荑草后的欢喜；末章翻进一层——物以人重，草本寻常，因是美人所赠便觉「洵美且异」，痴情之态跃然纸上。","b":"出自《诗经·邶风》，写一对青年男女城角约会、互赠信物的情景，是《诗经》中最富生活情趣的爱情小诗之一。","n":["静女：娴静的姑娘","姝：美丽。音shū","俟：等待。城隅，城角僻静处","爱而不见：故意躲藏起来不露面。爱，同「萲」，隐藏","踟蹰：徘徊、心里迟疑。音chíchú","娈：美好。音luán","贻我彤管：赠我一支红色的管草（或指红色管乐器）。贻，赠送","说怿女美：喜爱你的美丽。说怿，喜爱；女，同「汝」，指彤管","牧归荑：从郊外采来荑草赠我。归，同「馈」，赠送","洵：实在、确实","匪女之为美：不是这草本身美。匪，同「非」；女，同「汝」"],"m":"匪女之为美，美人之贻。","r":"按「约会等候—赠管—赠荑抒怀」三章背；重点通假字：爱（萲）、说（悦）、女（汝）、归（馈）、匪（非）。"},"硕人|佚名":{"s":"诗分四章：首章以一连串亲族身份写其出身高贵，次章连用六个比喻工笔细描容貌，尤以「巧笑倩兮，美目盼兮」化静为动，神韵全出；后两章写婚礼车驾之盛与齐国风物之饶，铺张得体，开后世铺陈写人的先河。","b":"出自《诗经·卫风》，写齐女庄姜出嫁卫庄公时的盛况与美貌，是中国文学史上最早、最著名的女性肖像描写之一。","n":["硕人：高大白胖的美人，指卫庄公夫人庄姜","颀：身材修长。衣锦褧衣：内穿锦衣、外罩麻纱罩衣。褧，音jiǒng","柔荑：柔嫩的白茅嫩芽，喻手指纤细","凝脂：凝结的油脂，喻皮肤洁白细腻","蝤蛴：天牛幼虫，白而长，喻脖颈。音qiúqí","瓠犀：葫芦籽，洁白整齐，喻牙齿。音hùxī","螓首蛾眉：额如螓（小蝉）般方正，眉如蚕蛾触须般弯长","巧笑倩兮：笑靥美好。倩，两颊酒窝","美目盼兮：眼珠黑白分明、顾盼动人","敖敖：修长高大的样子","说于农郊：在城郊歇息。说，同「税」，停舍","庶姜孽孽：陪嫁的姜姓女子众多盛装"],"m":"手如柔荑，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首蛾眉，巧笑倩兮，美目盼兮。","r":"按「身份—容貌—车驾—故国风物」四章背；肖像章六个比喻成对记；生僻字多：褧、荑、蝤蛴、瓠犀、螓、罛、濊、鳣鲔，重点认读。"},"黍离|佚名":{"s":"三章重章叠唱，以稷由「苗」而「穗」而「实」的生长过程，对应愁绪由「摇摇」而「如醉」而「如噎」的层层加深，情景相生；「知我—不知我」的对照与呼天一问，把无人理解的孤愤推向极致，苍凉沉郁。","b":"出自《诗经·王风》。旧说东周大夫行役经过西周故都镐京，见宗庙宫室尽为禾黍，悲悯周室倾覆而作，后世遂以「黍离之悲」代指故国之思、亡国之痛。","n":["黍、稷：黄米和高粱，泛指庄稼","离离：庄稼成行、繁茂的样子","行迈靡靡：脚步沉重迟缓。靡靡，缓慢","中心摇摇：心中恍惚、摇摇不安","此何人哉：这（亡国局面）是什么人造成的啊","如噎：喉咙堵塞，喻忧思难舒。噎，音yē"],"m":"知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？","r":"三章只换六处关键字，按「苗/穗/实—摇摇/如醉/如噎」对应背；韵脚离/靡、求/哉；注意「行」音xíng、「噎」音yē。"},"君子于役|佚名":{"s":"诗人巧选黄昏这一最惹愁思的时刻：鸡归埘、牛羊下括，万物各有所归，唯独征人归期无定，以禽畜知归反衬人不归，朴素白描中愈见深情；末句「苟无饥渴」退一步作祝愿语，体贴入微，语淡而悲。","b":"出自《诗经·王风》，写一位山村农妇在黄昏时分思念久役不归的丈夫，是最早的「闺怨」题材作品之一。","n":["君子：此指从军在外的丈夫","于役：在外服徭役、兵役","曷至哉：什么时候才能回来。曷，何","埘：墙壁上挖成的鸡窝。音shí","不日不月：归期无定，没法用日月计算","佸：相会、团聚。音huó","桀：木桩，此指鸡栖的木架","下括：下来聚集。括，会集","苟无饥渴：但愿他不至于受饥受渴。苟，姑且、表祝愿"],"m":"日之夕矣，羊牛下来。君子于役，如之何勿思！","r":"两章对读，抓「鸡栖—日夕—牛羊下」三幅黄昏小景；易错读：埘shí、佸huó、桀jié、括kuò。"},"78456:无衣|佚名":{"s":"两章短章重叠，先说自己并非无衣可穿，却偏觉「不如子之衣」，以退为进，把对赠衣者的感念写得真挚含蓄；「安且吉」「安且燠」从称心与温暖两处落笔，小中见情。","b":"出自《诗经·唐风》（注意与传诵的《秦风·无衣》「岂曰无衣，与子同袍」不是同一篇）。旧说为晋大夫感念晋武公命服之赐而作，全诗借衣怀人、因物感恩。","n":["七、六：指衣上的章饰等级：侯伯之衣七章、卿六章，此以礼数之盛作比","子之衣：你（所赠、所制）的衣，旧说指晋武公命服","安且吉兮：舒适又美善","燠：暖和。音yù"],"m":"岂曰无衣七兮？不如子之衣，安且吉兮！","r":"两章只换「七/六」「吉/燠」三处，对比《秦风·无衣》记，避免张冠李戴；「燠」读yù。"},"七月|佚名":{"s":"全诗八章，以「衣食」为经纬：授衣、采桑、染织、狩猎写其劳，食郁枣、烹葵菽、筑场纳稼写其食，凿冰献羔、跻堂称觥写其岁时祭祀；历法上周历夏历并用，物候与人事交织，铺陈细密而井然，既见农人艰辛，也见古朴和乐，是研究上古社会的史诗性篇章。","b":"出自《诗经·豳风》，是《国风》中最长的一首叙事诗，以月令为线索，详记西周早期农人一年四季的生产劳动与生活，堪称上古农耕社会的风俗长卷。","n":["七月流火：七月大火星偏西下行，标志暑退秋来。火，大火星（心宿二）","九月授衣：九月分发寒衣","一之日、二之日：周历正月、二月，当夏历十一月、十二月；下文三之日、四之日类推","觱发、栗烈：寒风呼啸、寒气凛冽。觱发音bìbō","褐：粗麻短衣","何以卒岁：靠什么度到年终","于耜、举趾：修理耒耜、抬脚下田耕作。耜音sì","馌彼南亩：把饭送到南边田头。馌音yè","田畯：农官。音jùn","载阳：开始暖和","仓庚：黄莺","懿筐：深筐","微行：小路。行音háng","爰求柔桑：于是采摘柔嫩桑叶","采蘩祁祁：采的白蒿很多。蘩，白蒿；祁祁，众多","殆及公子同归：怕被公子带走（写女心伤悲）","萑苇：芦苇，用以制蚕箔。萑音huán","蚕月条桑：养蚕之月修剪桑枝","斧斨：斧类工具，装柄孔方者为斨。音qiāng","猗彼女桑：拉住嫩枝采叶。猗同「掎」，牵引","鵙：伯劳鸟。音jú","载绩：开始纺麻线","载玄载黄，我朱孔阳：染成黑红、黄色，那朱红色尤其鲜亮。孔，很；阳，鲜明","秀葽：远志结子。葽音yāo","鸣蜩：蝉鸣。蜩音tiáo","陨萚：草木落叶。萚音tuò","于貉：去猎貉子。貉音hé","载缵武功：继续进行田猎习武。缵，继续","言私其豵，献豜于公：小兽归己、大兽献公。豵，一岁小猪；豜，三岁大猪，音jiān","斯螽、莎鸡：蚱蜢、纺织娘","穹窒熏鼠：堵好墙洞熏走老鼠","塞向墐户：堵上北窗、用泥涂好门缝。向，北窗；墐，涂泥，音jìn","改岁：过年","郁、薁：郁李、野葡萄。薁音yù","亨葵及菽：煮葵菜和豆子。亨同「烹」","剥枣：打枣。剥音pū，击","春酒、介眉寿：冬酿春成的酒；祈求长寿。介，助","断壶、叔苴：摘葫芦、拾麻籽。叔，拾取；苴音jū","采荼薪樗：挖苦菜、臭椿当柴。荼，苦菜；樗音chū","筑场圃：把菜园改筑成晒谷场","纳禾稼：把粮食收进仓","黍稷重穋：晚熟作物叫重、早熟叫穋。穋音lù","上入执宫功：还要到公家服劳役","宵尔索綯：夜里搓绳子。綯，绳","亟其乘屋：赶紧上房修缮。亟，急；乘，登","凿冰冲冲：凿冰声咚咚","纳于凌阴：藏进冰窖。凌阴，冰窖","蚤：同「早」，指早朝祭祖","献羔祭韭：献上羔羊、韭菜祭庙","肃霜、涤场：天高气爽、场院清扫干净","朋酒斯飨：捧上两樽酒聚饮。飨，享","跻彼公堂：登上公堂。跻，登","称彼兕觥：举起犀牛角杯。兕觥音sìgōng"],"m":"七月流火，九月授衣。春日载阳，有鸣仓庚。","r":"篇幅最长，按「月份物候+相应劳作」的月令体背，抓每章时间词（七月/九月/一之日/春日/蚕月/四月五月/六月……）作路标；生僻字极多：觱发、耜、馌、畯、萑、斨、鵙、蜩、萚、豵、豜、墐、薁、樗、穋、綯、兕觥，先认读再成诵。"},"鹿鸣|佚名":{"s":"三章以鹿得苹草呦呦相呼起兴，喻主人以美酒音乐、币帛礼遇嘉宾；一章重结纳之道、二章重立德示范、三章重和乐交心，层层写出宾主相得的雍雍气象，温厚和平，为宴饮诗之祖。","b":"出自《诗经·小雅》，是周王宴飨群臣嘉宾的乐歌，后来曹操《短歌行》曾化用其句表达求贤若渴之意。","n":["呦呦：鹿鸣声。音yōu","苹、蒿、芩：三种可食的野草。芩音qín","鼓瑟吹笙：弹瑟吹笙宴乐宾客","承筐是将：主人命人捧上筐中布帛礼物赠客。将，奉上","周行：大道，此指治国的正道。行音háng","德音孔昭：美好的声名十分昭著。孔，很","视民不恌：给百姓做不轻薄的榜样。视，同「示」；恌，同「佻」","是则是效：以此为法则、去效仿","旨酒：美酒","式燕以敖：尽情宴饮遨游。燕，同「宴」","湛：深厚、尽兴。音dān，同「耽」"],"m":"呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。","r":"三章起句相同，按「赠物示道—垂范效德—琴酒交心」分背；通假：视（示）、燕（宴）、湛（耽）。"},"采薇|佚名":{"s":"全诗六章，前五章以薇菜的生长和战事的反复写久戍之苦、军容之壮，末章陡然收束于归途：以杨柳春日之乐景写昔日别哀，以雨雪严冬之哀景写今日归悲，今昔、物我、哀乐四重对照，被王夫之赞为「以乐景写哀，以哀景写乐，一倍增其哀乐」。","b":"出自《诗经·小雅》，写一位戍边士兵多年征战归来途中的回忆与悲慨，是中国最早的边塞征戍诗杰作。","n":["薇：野豌豆苗，可食，戍卒采以充饥","作、柔、刚：薇菜初生、柔嫩、粗老，写时序推移","莫：同「暮」，岁暮","玁狁：北方游牧部族，即后来的匈奴。音xiǎnyǔn","不遑启居：没空安稳坐下。遑，闲暇","归聘：捎信回家。聘，问讯","王事靡盬：王室差事没有尽头。盬，止息，音gǔ","孔疚：非常痛苦。疚，病痛","尔：同「薾」，花盛开貌","路：同「辂」，高大的战车","四牡业业：四匹雄马高大健壮","骙骙：马强壮貌。音kuí","小人所腓：士兵借战车掩蔽。腓，庇护，音féi","象弭鱼服：象牙装饰的弓梢、鲨鱼皮箭袋","今我来思：如今我归来。思，语气词","雨雪霏霏：大雪纷纷飘落。雨，音yù，落"],"m":"昔我往矣，杨柳依依。今我来思，雨雪霏霏。","r":"前五章重章递进（作/柔/刚），末章四句为千古名句须单独背熟；易错读：玁狁xiǎnyǔn、盬gǔ、腓féi、霏fēi、雨yù雪。"},"愚公移山|列御寇":{"s":"故事以「二山阻路」起、以「二山被负」终，结构完整；愚公与智叟的辩论是全篇文眼——愚公以发展的眼光看世代与山的消长，智叟以静止的眼光看残年与土石，命名上「愚」智「叟」的反讽更见褒贬，对比中凸显恒心的力量。","b":"选自《列子·汤问》，相传战国列御寇撰，以寓言形式讲述愚公率众移山、感动天帝的故事，阐明人定胜天、有志竟成的道理。","n":["方七百里：方圆七百里","仞：古代七尺（一说八尺）为一仞","惩山北之塞：苦于山北道路阻塞。惩，苦于","迂：绕远","聚室而谋：集合全家商量","杂然相许：纷纷表示赞同","献疑：提出疑问","如……何：把……怎么办","焉置土石：把土石放到哪里","荷担者：能挑担的人。荷，扛","始龀：刚换牙，约七八岁。龀，音chèn","寒暑易节，始一反焉：冬夏换季才往返一次。反，同「返」","惠：同「慧」，聪明","其如土石何：又能把土石怎么样","长息：长叹","固不可彻：顽固到不能开窍。彻，通","穷匮：穷尽。匮，音kuì","亡以应：无话可答。亡，同「无」","厝：放置。音cuò","陇断：山冈阻隔。陇，同「垄」"],"m":"子子孙孙无穷匮也，而山不加增，何苦而不平？","r":"按「山阻议移—全家定策—智叟笑阻—愚公正答—神助成功」五段背；通假字集中：反（返）、惠（慧）、亡（无）、厝（措）、陇（垄）。"},"两小儿辩日|列御寇":{"s":"短文以对话推进：两小儿分别从「视觉大小」和「触觉凉热」两个角度各执一理，论据都来自日常观察，合乎经验却结论相反；结尾孔子「不能决」并遭小儿一笑，非但不损圣人形象，反而彰显「知之为知之」的求真精神，机锋隽永。","b":"选自《列子·汤问》，写孔子路遇两个小孩争论太阳远近而不能决断，说明人的认识总有局限、求知应实事求是。","n":["辩斗：辩论、争论","以：认为","去人：距离人","车盖：古代车上遮阳挡雨的圆伞","盘盂：盛物的圆盘和方器","沧沧凉凉：清凉微寒","探汤：把手伸进热水里。汤，热水","决：判断、判定","孰为汝多知乎：谁说你知识渊博呢。为，同「谓」；知，同「智」"],"m":"孰为汝多知乎？","r":"按「问故—两儿各陈理由—孔子不能决—笑结」背；两小儿论证句式对称（此不为……乎），成对记忆；通假：为（谓）、知（智）。"},"生于忧患，死于安乐|孟子":{"s":"文章先以六个排比事例铺陈「生于忧患」的历史依据，再由个别上升到一般，层层推导个人成才与国家存亡的共同规律；句式短促整齐，使动用法密集，读来如重锤击鼓，最后「生于忧患，死于安乐」八字点题，警策千古。","b":"选自《孟子·告子下》，孟子列举舜、傅说等六位圣贤起于微贱的事例，论证忧患磨砺成才、安逸招致败亡的道理。","n":["发、举：被起用、被选拔","畎亩：田间。畎，音quǎn","版筑：筑墙的活计","鱼盐：鱼盐贩子之列","士：狱官","故天将降大任：所以上天将要降下重大使命","苦、劳、饿、空乏：使……痛苦/劳累/挨饿/资财匮乏，均为使动用法","行拂乱其所为：使他所做的事颠倒不顺。拂，违背","动心忍性：使内心受到震动、性格变得坚韧","曾益：增加。曾，同「增」","恒过：常常犯错","衡于虑：思虑阻塞。衡，同「横」，梗塞","作：奋发有所作为","征于色，发于声：表现在脸色上、流露在言谈中","入、出：在国内、在国外","法家拂士：守法度的大臣和辅弼的贤士。拂，同「弼」"],"m":"故天将降大任于是人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身。然后知生于忧患而死于安乐也。","r":"记牢六人事例的固定顺序（舜—傅说—胶鬲—管夷吾—孙叔敖—百里奚）；第二段按「个人改过—国家存亡—结论」背；通假：曾（增）、衡（横）、拂（弼）。"},"鱼我所欲也|孟子":{"s":"全文以比喻起论，由「舍鱼取熊掌」自然引出「舍生取义」的中心论点；再以正反对比——行道之人不食嗟来之食与为宫室妻妾而受万钟——批判见利忘义者丧失本心，设喻浅显而逻辑层层进逼，气势浩然。","b":"选自《孟子·告子上》，孟子以鱼与熊掌设喻，阐明「义重于生」、人应保有羞恶本心的主张。","n":["熊掌：熊的脚掌，古人视为珍贵食物","兼得：同时得到","苟得：苟且偷生","患：祸患。辟，同「避」","何不用也：什么手段不用呢","由是：凭借这种办法","贤者能勿丧耳：贤人能够不丧失（本心）罢了","箪、豆：古代盛饭、盛羹的器具","呼尔而与之：吆喝着施舍给人","蹴尔：用脚踢着。蹴，音cù","不屑：认为不值得接受","万钟：很厚的俸禄。钟，古量器","何加：有什么益处","得我：感激我。得，同「德」，感恩","乡为身死而不受：从前宁可死也不接受。乡，同「向」","已：停止、罢休","本心：天性，此指羞恶之心"],"m":"生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。","r":"抓「比喻提出论点—正面讲道理—举例对比—批判失其本心」四段；通假字多：辟（避）、得（德）、与（欤）、乡（向）；易错读：蹴cù。"},"得道多助，失道寡助|孟子":{"s":"文章开门见山提出论点，随即以攻城不胜、守城弃逃两个战例逐层论证天时、地利、人和的轻重次序，再由军事推及治国，最后以「多助—寡助」的对比和「顺—畔」的结局收束，论证如剥笋，结论掷地有声。","b":"选自《孟子·公孙丑下》，孟子通过战争胜负的分析，提出「人和」是决定成败的根本，阐发其仁政思想。","n":["天时、地利、人和：有利的时令气候、有利的地理条件、人心的团结","三里之城，七里之郭：内城方圆三里、外城七里","环而攻之：包围起来攻打","委而去之：弃城逃跑。委，放弃","域民：限制百姓定居","固国：巩固国防","威天下：威慑天下","寡助之至：帮助他的人少到极点","亲戚畔之：内外亲属都背叛他。畔，同「叛」","君子有不战：君子要么不战"],"m":"天时不如地利，地利不如人和。得道者多助，失道者寡助。","r":"按「总论点—两战例分证—治国推论—对比结论」背；通假：畔（叛）；古今异义：亲戚（古指内外亲属）、郭（外城）。"},"富贵不能淫|孟子":{"s":"文章是一段精彩的驳论：先引景春之论立靶，再以「妾妇之道」类比揭穿公孙衍、张仪一味顺从君王的本质，最后正面提出居仁、由义、守礼的大丈夫标准；三个「不能」构成排比，如洪钟大吕，成为中华民族气节的经典宣言。","b":"选自《孟子·滕文公下》，孟子批驳纵横家以顺从权术为能的「妾妇之道」，树立儒家「大丈夫」的人格标准。","n":["景春、公孙衍、张仪：均为战国纵横家，后两人以合纵连横游说诸侯","诚大丈夫：真正是大丈夫","安居而天下熄：他们安居家中，天下战火就平息","焉：怎么、哪里","丈夫之冠：男子二十行冠礼。冠音guàn","父命之：父亲给以训导","往之女家：到了你夫家。女，同「汝」","无违夫子：不要违背丈夫","以顺为正：把顺从当作正道","广居、正位、大道：朱熹释为仁、礼、义","与民由之：与百姓一同遵循正道而行","淫、移、屈：使……迷惑/动摇/屈服，使动用法"],"m":"富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。","r":"按「树靶（景春语）—批驳（妾妇之道）—立论（大丈夫三句）」背；使动三动词淫/移/屈重点理解；通假：女（汝）。"},"湘夫人|屈原":{"s":"全诗以候人不至为线索：开篇「袅袅秋风」二句以水边秋景写尽怅惘，被称为「千古言秋之祖」；中段铺陈水中筑室、百草充庭的华美幻境，越写越热闹，愈显梦醒后的失落；末段捐袂遗褋、搴杜若以待远者，缠绵悱恻，香草意象处处映衬高洁痴情。","b":"选自屈原《九歌·湘夫人》，是祭湘水女神的乐歌，写湘君（男神）期约湘夫人不至的思慕与惆怅，与《湘君》为姊妹篇。","n":["帝子：天帝之女，指尧女娥皇、女英，舜妃，此即湘水女神","北渚：北边的小洲。渚，水中小块陆地","眇眇：极目远望的样子。愁予，使我发愁","袅袅：秋风轻柔吹拂貌","洞庭波兮木叶下：洞庭泛起波澜、树叶纷纷飘落","登白薠兮骋望：登上长满白薠的高地纵目。薠，草名，音fán","与佳期兮夕张：与佳人约会，傍晚张设帷帐","萃、罾：聚集；鱼网。鸟本当栖木却聚于水草、渔网本在水中却张到树上，喻所愿难遂","沅、醴：沅水、澧水；茝、兰皆香草","水裔：水边","济兮西澨：渡到西边水涯。澨，音shì","葺之兮荷盖：用荷叶盖屋顶","荪壁兮紫坛：荪草饰壁、紫贝铺庭","罔薜荔：编结薜荔。罔，同「网」","擗蕙櫋：剖开蕙草做屋檐板。擗音pǐ，櫋音mián","九嶷：九嶷山诸神。缤，众多貌","捐余袂、遗余褋：抛袖、弃单衣于水，寄情远者。褋，音dié","搴：拔取。汀洲，水中平地","骤得：屡次得到、轻易得到","容与：从容徘徊"],"m":"袅袅兮秋风，洞庭波兮木叶下。","r":"按「秋景骋望—驰马赴约—水中筑室—九嶷纷迎—捐袂寄情」五段背；兮字为楚辞标志，按「上六字+兮+下六字（或五字）」节奏读；生僻字：薠、罾、澨、櫋、褋、搴。"},"国殇|屈原":{"s":"诗分两段：前段以白描再现短兵相接、车马交错的惨烈鏖战，节奏急促如金戈交鸣；后段直抒礼赞，歌颂将士视死如归、刚强不屈的精魂。通篇刚健雄浑，在《九歌》凄婉迷离的整体风格中独呈悲壮之色。","b":"选自屈原《九歌·国殇》，是追悼楚国阵亡将士的祭歌，约作于楚与秦争战失利之后，充满同仇敌忾的悲壮之气。","n":["国殇：指为国战死的将士。殇，本指未成年而死，此指牺牲","操吴戈兮被犀甲：手持吴地利戈、身披犀牛皮甲。被，同「披」","车错毂：敌我车轮交错。毂，车轮中心，音gǔ","短兵接：短兵相接肉搏","凌余阵兮躐余行：敌军冲犯我阵、践踏我行列。躐，音liè","左骖殪兮右刃伤：左骖马倒地而死、右骖马被刃所伤","霾两轮兮絷四马：把两轮埋住、四马绊住，以示死战不退。霾同「埋」，絷音zhí","援玉枹：拿起玉饰鼓槌。枹，鼓槌，音fú","天时怼兮威灵怒：天昏地暗、神灵震怒。怼，怨恨，音duì","严杀尽兮弃原野：战士全部壮烈战死、尸骨弃于原野","首身离兮心不惩：身首分离而忠心不悔。惩，悔恨","神以灵：精神化为神灵、永不泯灭","鬼雄：鬼中豪杰"],"m":"诚既勇兮又以武，终刚强兮不可凌。身既死兮神以灵，魂魄毅兮为鬼雄。","r":"按「激战全过程—礼赞阵亡魂」两大段背；战斗句按「披甲—交兵—破阵—埋轮击鼓—尽弃原野」顺序；通假：被（披）、霾（埋）；易错读：毂gǔ、躐liè、絷zhí、枹fú、怼duì。"},"涉江|屈原":{"s":"诗作集纪行、写景、言志于一体：先以奇服宝璐的自我画像和驾龙游仙的想象表白高洁，中段写溯江南行的幽寂凄寒之景，景中见孤愤；再以接舆、伍子胥、比干自况，把个人不幸纳入自古忠贤的谱系，乱辞以善恶异位的比喻痛斥时世，悲而弥厉。","b":"选自屈原《九章·涉江》，为屈原第二次被放逐、渡江南下时所作，借纪行抒写守正不移、九死未悔的情志。","n":["奇服：奇伟的服饰，喻高洁不同流俗的品格","长铗：长剑。陆离，长而错落貌","切云：高冠名，言其高可触云","被明月兮佩宝璐：披挂夜光珠、佩带美玉。被同「披」，璐，美玉","高驰：高高地驰骋于理想之境","青虬、白螭：青龙、白龙。螭音chī","重华：舜的名字。瑶之圃，昆仑仙境花园","南夷：指楚国南方僻远之地","鄂渚：地名，在今武昌一带","欸秋冬之绪风：叹息于秋冬余寒之风。欸，叹息，音ǎi","乘舲船：乘着有窗的小船。上沅，溯沅水而上","齐吴榜以击汰：齐举大桨击水。汰，水波","淹回水而疑滞：停留在回旋水流中难以前进。疑同「凝」","枉渚、辰阳、溆浦：皆沅水流域地名","儃徊：徘徊。音chánhuái","猿狖：猿猴。狖音yòu","霰：雪珠。垠，边际","接舆髡首、桑扈臝行：春秋楚国隐士接舆剃发、桑扈裸行以避世。髡音kūn，臝同「裸」","伍子逢殃、比干菹醢：伍子胥遭祸、比干被剁成肉酱。菹醢音zūhǎi，酷刑","董道：坚守正道。董，正","重昏：处于层层黑暗之中","乱：楚辞篇末总括全篇的乐章","鸾鸟凤皇：贤士；燕雀乌鹊，小人","巢堂坛：占据朝廷","露申辛夷：香草，喻君子；林薄，草木丛杂处","腥臊并御，芳不得薄：奸佞并进，贤人不得靠近。薄，接近","怀信侘傺：怀抱忠信而失意。侘傺音chàchì"],"m":"苟余心其端直兮，虽僻远之何伤。吾不能变心而从俗兮，固将愁苦而终穷。","r":"篇幅长，按「自表高洁—渡江纪行—溆浦独处—以古贤自况—乱辞总括」五段背；兮字句注意节拍；生僻字密集：铗、螭、欸、舲、汰、儃徊、狖、霰、髡、菹醢、侘傺。"},"橘颂|屈原":{"s":"全诗处处写橘、又处处写人：写橘「受命不迁」「深固难徙」，正是写自己眷恋宗国、九死不悔；写橘「精色内白」「秉德无私」，正是写内修外洁的人格。咏物与言志妙合无痕，四言为主、兮字助声，清峻挺拔，开后世咏物诗「体物写志」的传统。","b":"选自屈原《九章·橘颂》，是中国诗歌史上第一首完整的咏物诗，借咏橘言志，寄托自己扎根南国、忠贞不移的怀抱。","n":["后皇嘉树：天地间美好的橘树。后，后土；皇，皇天","橘徕服兮：橘树生来适应南国水土。徕同「来」","受命不迁：秉受天性、不可迁徙（古谓橘过淮则化为枳）","素荣：白色的花","曾枝剡棘：枝条层叠、尖刺锐利。曾同「层」，剡音yǎn，锐利","圆果抟：果实圆滚滚。抟同「团」，音tuán","青黄杂糅：橘子青皮黄实相杂，色彩斑斓","精色内白：外表色泽鲜明、内瓤洁白","类任道：像担当道义的君子","纷缊宜修：香气馥郁、修饰合宜。缊音yūn","姱：美好。音kuā","廓其无求：心胸开阔、无所贪求","苏世独立：清醒地独立于世间。苏，苏醒","横而不流：特立独行而不随波逐流","闭心自慎：坚心守志、谨慎自持","秉德无私：持守美德、毫无私心","参天地：与天地并列","愿岁并谢，与长友：愿与橘树共度岁月、长为友朋","淑离不淫：美好而不过分。离同「丽」","梗其有理：枝干刚正、纹理分明，喻人有原则","行比伯夷：品行可比不食周粟的伯夷","置以为像：立为榜样。像，法式、榜样"],"m":"深固难徙，更壹志兮。苏世独立，横而不流兮。","r":"分两大层：前半写橘之形质（叶花—枝果—色味），后半写橘之品格（不迁—独立—无私—可师）；通假：徕（来）、曾（层）、抟（团）、离（丽）；生僻字：剡yǎn、缊yūn、姱kuā。"},"曹刿论战|左丘明":{"s":"文章以「论战」为核心而非铺陈战阵：战前写曹刿与鲁庄公三问三答，得出民心向背才是战争根本；战中只用「未可」「可矣」两处节制之语制造悬念；战后「视辙望旗」的补叙和「彼竭我盈」的分析，把一位深谋远虑的平民战略家写得跃然纸上，剪裁精当。","b":"选自《左传·庄公十年》，记齐鲁长勺之战，是中国历史上以弱胜强的著名战例，也是《左传》战争描写与记言艺术的典范。","n":["十年：鲁庄公十年（前684年）","齐师伐我：齐国军队攻打鲁国。我，《左传》以鲁纪年，故称我","肉食者：居高位享厚禄的人","间：参与。音jiàn","鄙：鄙陋，目光短浅","衣食所安：衣食这类安身之物","专：独自享用","牺牲玉帛：祭祀用的牛羊猪和玉帛","加：虚夸、虚报","孚：使人信服","小大之狱：大大小小的诉讼案件","虽不能察，必以情：即使不能一一明察，也一定按实情判断","忠之属也：这是尽职分一类的事","驰之：驱车追击","辙、轼：车轮碾痕、车前横木","既克：战胜以后","一鼓作气：第一次击鼓能振作士气","再而衰：第二次击鼓士气就衰减","三而竭：第三次士气耗尽","彼竭我盈：敌竭我盛。盈，饱满","靡：倒下"],"m":"夫战，勇气也。一鼓作气，再而衰，三而竭。彼竭我盈，故克之。","r":"按「战前论凭—战中指挥—战后释疑」三段背；三问三答与两个「未可/可矣」是骨架；古今异义：牺牲、狱、可以、间。"},"烛之武退秦师|左丘明":{"s":"全文以说辞为核心：烛之武不谈郑之存亡，只站在秦国立场层层算账——亡郑只利晋、舍郑反利秦、晋历来背信且贪得无厌，最终「阙秦以利晋」一句击中要害，使秦伯反与郑盟。说辞迂回曲折、步步紧逼，不卑不亢，是「一言兴邦」的辞令典范。","b":"选自《左传·僖公三十年》，记公元前630年秦晋围郑、烛之武夜入秦营凭一席话说退秦师的史事，展现高超的辞令艺术。","n":["以其无礼于晋：因为郑国曾对晋文公无礼","贰于楚：表面从晋、暗中亲楚","军：驻军。函陵、氾南皆地名","佚之狐、烛之武：皆郑国大夫","缒而出：用绳子从城墙上吊下出城","执事：对秦伯的敬称，字面指办事人员","越国以鄙远：越过晋国把远方的郑国作边邑。鄙，边邑，作动词","焉用亡郑以陪邻：何必灭郑来增加邻国（晋）的土地。陪，增加","东道主：东方道路上招待过客的主人，后泛指请客主人","行李之往来：出使的人往来。行李，外交使者","共其乏困：供给他们缺少的物资。共同「供」","尝为晋君赐：曾对晋君施恩","朝济而夕设版焉：早上渡河回国、晚上就筑城防御，言晋背信之快","何厌之有：哪有满足的时候。厌同「餍」，满足","既东封郑：在东边使郑国成为它的疆界后","肆其西封：扩张西边的疆界","阙秦：使秦国受损。阙，损害，音quē","说：同「悦」","戍之：派兵驻守郑国","子犯：晋文公舅父狐偃","微夫人之力：没有那人（秦穆公）的力量。微，没有","因人之力而敝之：依靠过别人却去损害他。敝，损害","失其所与，不知：失掉同盟国是不明智的。知同「智」","以乱易整，不武：用冲突代替联合不算威武"],"m":"若舍郑以为东道主，行李之往来，共其乏困，君亦无所害。","r":"按「围郑—荐贤—临危受命—夜说秦伯（四层利害）—晋师退兵」背；说辞四层：亡郑陪邻→舍郑有益→晋曾背信→晋必阙秦；通假：共（供）、说（悦）、知（智）、厌（餍）。"},"北冥有鱼|庄周":{"s":"庄子以极度夸张的数字与想象塑造鲲鹏形象：鱼之化鸟、翼若垂云、水击三千里、抟上九万里，境界雄奇；又以野马尘埃作对照，提出大小虽殊、皆「有所待」的思考，奇诡汪洋，寓哲理于形象，开浪漫主义散文先河。","b":"选自《庄子·逍遥游》开篇，以鲲鹏展翅的宏阔想象阐发「有待—无待」的哲理，是庄子散文浪漫风格的代表。","n":["北冥：北方的大海。冥同「溟」","鲲：传说中的大鱼","化而：变化成为","怒而飞：振奋地展翅。怒，奋发","垂天之云：天边垂下的巨云，形容鹏翼之大","海运：海水运动、海风起时","南冥、天池：南海；天然形成的大池","《齐谐》：记载怪异事物的书","志怪：记载怪异","水击三千里：翅膀拍击水面达三千里","抟扶摇而上：乘着旋风盘旋而上。抟，盘旋；扶摇，旋风","去以六月息：凭借六月的大风离开。息，气息，此指风","野马：春日野外蒸腾如奔马的雾气","生物之以息相吹：都是生物用气息互相吹拂","正色：真正的颜色","无所至极：没有尽头","其视下也：大鹏从天上往下看"],"m":"鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。","r":"按「北冥有鱼—化而为鹏—徙于南冥—《齐谐》为证—以小衬大」背；通假：冥（溟）；重点词：怒、海运、扶摇、息。"},"劝学|荀况":{"s":"文章最突出的特色是博喻连翩：以青蓝、冰寒、木轮、金砺喻学习能改变和提升人，以登高、舆马、舟楫喻善假于物，以积土成山、骐骥驽马、朽木金石、蚓蟹对比喻积累与专一，二十余喻层见叠出而说理条贯，句式整散结合，朗朗可诵。","b":"选自《荀子·劝学》，系统论述学习的意义、态度与方法，是先秦论说文中劝学名篇，多用比喻和排比说理。","n":["已：停止","青，取之于蓝，而青于蓝：靛青从蓝草中提取，却比蓝草更青。于，从/比","木直中绳：木材直得合于墨线。中，符合，音zhòng","輮以为轮：用火烤弯做成车轮。輮同「煣」","虽有槁暴：即使又晒干。有同「又」，槁暴，晒干，暴同「曝」","金就砺则利：金属刀剑拿到磨石上磨就锋利","参省乎己：对自己检验反省。参，检验；省音xǐng","知明：智慧明达。知同「智」","须臾：片刻","跂而望：踮起脚跟远望","彰：清楚","假舆马：借助车马。假，借助","利足：脚走得快","致千里：到达千里之外","绝江河：横渡江河","生非异：天性并无不同。生同「性」","跬步：半步。跨一脚为跬，跨两脚为步","骐骥、驽马：骏马、劣马","十驾：马拉车十天的路程","锲：刻","镂：雕刻","用心一也、用心躁也：因为用心专一/浮躁。一，专一"],"m":"青，取之于蓝，而青于蓝。不积跬步，无以至千里；不积小流，无以成江海。锲而舍之，朽木不折；锲而不舍，金石可镂。","r":"按「学不可以已（总论）—学习意义—善假于物—积累坚持专一」四块背；每段首尾论点句必背；通假：輮（煣）、有（又）、暴（曝）、知（智）、生（性）。"},"扁鹊见蔡桓公|韩非":{"s":"文章以时间为序层层推进：病由腠理→肌肤→肠胃→骨髓，扁鹊态度由劝告→复见→再劝→「望而还走」，桓公则由「寡人无疾」到体痛遂死，两条线索对照分明；最后以「逃秦」反衬无力回天，叙事极简而寓意深刻。","b":"选自《韩非子·喻老》，以扁鹊四见蔡桓公、病情逐层加深而桓公拒医致死的故事，阐明防微杜渐、虚心纳谏的道理。","n":["立有间：站了一会儿。间，音jiān","腠理：皮肤的纹理，此指体表。腠音còu","将恐深：恐怕要加深","好治不病以为功：喜欢给没病的人治病来当作功劳","居十日：过了十天","肌肤：肌肉","不应：不回应","还走：转身就跑。还同「旋」，掉转","故使人问之：特意派人问他","汤熨：用热水焐、用药物热敷。汤同「烫」","针石：金针、石针","火齐：清火的汤药。齐同「剂」","司命之所属：司命神所管辖，医药已无能为力","无奈何：没有办法","索：寻找"],"m":"疾在腠理，汤熨之所及也；……在骨髓，司命之所属，无奈何也。","r":"按病情四阶段（腠理—肌肤—肠胃—骨髓）对应治法（汤熨—针石—火齐—无奈何）背；通假：汤（烫）、齐（剂）、还（旋）。"},"过秦论·上|贾谊":{"s":"全文用的是「蓄势于前、逆转于后」的笔法：以极写秦国之强、六国之众、始皇之威层层铺垫，铺张扬厉；再以陈涉之卑微疲敝与之对比，「成败异变、功业相反」的巨大反差逼出最后一问一答，结论「仁义不施」水到渠成，气势磅礴而警策深刻，是汉代政论散文的巅峰之作。","b":"《过秦论》分上中下三篇，此为上篇，西汉贾谊所作，旨在总结秦朝速亡的历史教训，为汉文帝提供治国借鉴，「过秦」即指责秦政之失。","n":["崤函：崤山、函谷关，关中险塞","雍州：古九州之一，今陕西一带","窥周室：暗中图谋夺取周室天下","席卷、包举、囊括：并吞之意，三词叠用","八荒：八方极远之地","商君：商鞅","连衡、合从：秦「连横」分化六国、六国「合纵」联合抗秦。从同「纵」","拱手：两手相合，言毫不费力","蒙故业，因遗策：继承旧基业、沿袭既定策略","膏腴：肥沃","致天下之士：招纳天下人才","相与为一：互相结盟成为一体","四君：孟尝君、平原君、春申君、信陵君","逡巡：犹豫不前。音qūnxún","亡矢遗镞：损失一支箭、一个箭头，言代价极小。镞，箭头","追亡逐北：追赶败逃的军队。北，败北","流血漂橹：血流成河能漂起盾牌","奋六世之余烈：振兴六代先王遗留的功业","振长策而御宇内：举起长鞭驾驭天下","吞二周而亡诸侯：吞并东西二周、灭亡各国","履至尊而制六合：登上帝位、控制天下","执敲扑：拿着刑具，喻以严刑统治","俯首系颈：低头降服、颈上系绳","委命下吏：把性命交给秦的小吏","却匈奴：使匈奴退却","焚百家之言：焚烧诸子百家著作","以愚黔首：使百姓愚昧。黔首，百姓","隳名城：毁坏名城。隳音huī","销锋镝：销毁兵器","践华为城，因河为池：据华山为城墙、就黄河为护城河","谁何：盘诘呵问行人","殊俗：不同风俗的边远之地","瓮牖绳枢：以破瓮为窗、以草绳系门轴，极言出身贫贱","氓隶、迁徙之徒：下层平民、被征发戍边的人","中人：平常人","蹑足行伍：投身军队行伍之间","揭竿为旗：举起竹竿当旗帜","赢粮而景从：担着粮食如影随形地跟从。景同「影」","山东：崤山以东","度长絜大：量量长短、比比大小。絜音xié，衡量","万乘：天子级别的势力","序八州而朝同列：使八州就位、使同等诸侯来朝","一夫作难而七庙隳：陈涉一人发难、秦宗庙尽毁。七庙，天子宗庙","身死人手：秦王子婴死于项羽之手","仁义不施而攻守之势异也：（结论）不施仁义，攻取与守成的形势就变了"],"m":"仁义不施而攻守之势异也。","r":"篇幅长，按「秦之崛起—六国合纵而败—始皇一统之威—陈涉揭竿而亡—对比归结」五段背；大量排比同义叠词（席卷/包举/囊括）按组记；通假：从（纵）、景（影）、衡（横）；生僻字：崤、腴、镞、隳、牖、絜。"},"涉江采芙蓉|佚名":{"s":"诗仅八句却有两层转折：前四句由采芙蓉起兴，乐景写哀——花再美，所思在远道，采之何用；后四句以望乡长路浩浩收束，空间的辽阔反衬人的孤独。语言浅近自然，情意含蓄不尽，代表《古诗十九首》「一字千金」的风格。","b":"选自《古诗十九首》，东汉末年无名文人所作，写游子涉江采莲、欲赠远方所思而不得的忧伤，是五言抒情诗成熟的标志。","n":["芙蓉：荷花","兰泽：生有兰草的水泽","遗：赠送。音wèi","远道：远方","还顾：回头看","漫浩浩：无边无际","同心而离居：感情深厚却分居两地","终老：度过余生"],"m":"同心而离居，忧伤以终老。","r":"按「采花—欲赠—望乡—叹离居」背；「遗」读wèi；注意两层空间：江泽之近与远道之远。"},"庭中有奇树|佚名":{"s":"全诗以「奇树—繁花—折荣—馨香」一线贯穿，由景入情：花愈香、怀袖愈盈，路远莫致的怅惘愈深；末句反挑一笔——花不足贵，可贵的是别后的相思，卒章显志，温柔敦厚。","b":"选自《古诗十九首》，写一位思妇攀树折花、欲寄远人而路远难达，在一树繁花中写尽绵长相思。","n":["奇树：佳美的树","华滋：花朵繁盛。滋，繁茂","攀条折其荣：攀着枝条折下花。荣，花","遗所思：赠给思念的人","馨香盈怀袖：花香沾满衣襟衣袖","致之：送到（他手中）","何足贵：有什么珍贵","但感别经时：只是因离别太久而感慨。但，只"],"m":"馨香盈怀袖，路远莫致之。此物何足贵？但感别经时。","r":"八句一气，抓「树→花→折→香→莫致→感别」的动作情感链；「遗」读wèi、「但」释为只。"},"邹忌讽齐王纳谏|刘向":{"s":"文章结构精巧：先写邹忌与徐公比美、三问三答、窥镜自视的家庭小事，再写他「暮寝而思」悟出私、畏、有求三种蒙蔽；继而以小喻大，由「一家之蔽」推及「一国之蔽」，讽齐王纳谏。叙事生动、推理自然，最后以「门庭若市—时时间进—无可进者」写改革成效，余味悠长。","b":"选自《战国策·齐策一》，写齐相邹忌以自身「比美」的生活体悟讽喻齐威王广开言路、革除蔽政，是「讽谏」艺术的名篇。","n":["修：长，此指身高","昳丽：光艳美丽。昳音yì","朝服衣冠：早晨穿戴好衣帽。服，穿戴","窥镜：照镜子","孰与：与……相比，谁更……","旦日：第二天","孰视：仔细看。孰同「熟」","暮寝而思之：晚上躺着想这件事","私我：偏爱我","地方千里：土地方圆千里","宫妇左右：宫中姬妾和身边近臣","四境：全国","蔽：受蒙蔽","面刺：当面指责","谤讥于市朝：在公共场合议论（过失）","闻寡人之耳：使我听到","时时而间进：偶尔有人进谏。间，间或，音jiàn","期年：满一年。音jī","战胜于朝廷：在朝廷上修明政治就战胜了别国"],"m":"吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求于我也。","r":"按「三问三答—自视醒悟—入朝讽谏—下令三赏—成效四国朝」背；三问三答、三赏、三阶段变化是天然骨架；通假：孰（熟）；古今异义：地方、左右、谤讥。"},"赠从弟·其二|刘桢":{"s":"全诗以松喻人：先写松立高山、风盛而枝劲，再写冰霜惨凄而松姿端正，一问一答点出「本性」二字。咏物即咏怀，寄托了建安士人在乱世中追求的坚贞人格，语言质朴而骨力遒劲。","b":"刘桢，「建安七子」之一。《赠从弟》共三首，此为其二，以山上青松勉励堂弟坚贞自守、不因外力压迫而改变本性。","n":["亭亭：挺拔直立的样子","瑟瑟：寒风声","一何：多么","劲：刚劲","惨凄：严酷凛冽","终岁：一年到头","罹凝寒：遭受严寒。罹，遭受，音lí","本性：天生的品性"],"m":"岂不罹凝寒？松柏有本性。","r":"八句四联，按「立松—风劲—冰霜—本性」背；「罹」读lí，意思是遭受。"},"大风歌|刘邦":{"s":"全诗仅三句却跌宕生姿：首句以风云起兴，写群雄逐鹿、定鼎天下的壮阔；次句写衣锦还乡的帝王之威；末句陡然一转，透出守成之难与求才之渴，豪迈中含苍凉，故被鲁迅称许为「楚风」遗响。","b":"汉高祖刘邦平定英布叛乱后归乡，置酒沛宫、自击筑而歌此诗，抒发帝业既成而渴求猛士镇守天下的豪情与隐忧。","n":["兮：楚辞式语气词，相当于「啊」","威加海内：威望施加于天下。海内，天下","安得：怎样才能得到","猛士：勇猛的将士","守四方：镇守四方疆土"],"m":"大风起兮云飞扬。威加海内兮归故乡。安得猛士兮守四方！","r":"三句三意层（风起—威归—求士），逐句记；每句「兮」字拖长诵读；末句是情感落点，要读出深沉。"},"木兰诗|北朝民歌":{"s":"叙事诗按「叹息缘由—备装出征—征战生涯—辞官还乡—合家欢聚—兔喻作结」次第展开，繁简极具匠心：十年征战只用六句带过，而东市西市买马、归家理妆却不厌其详，以详略突出木兰的女儿本色与至孝至勇；复沓、排比、顶真、比喻交错使用，民歌风味浓郁。","b":"又名《木兰辞》，北朝乐府民歌，与《孔雀东南飞》并称「乐府双璧」，写少女木兰女扮男装、代父从军、功成辞赏的传奇。","n":["唧唧：叹息声（一说织布机声）","当户织：对着门织布","机杼：织布机上的器件。杼音zhù","军帖：征兵文书","可汗大点兵：君主大规模征兵。可汗音kèhán","军书十二卷：征兵名册一卷接一卷，十二言其多","爷：父亲","市鞍马：买鞍马，代指备办战具","鞯、辔头：马鞍下的垫子、马笼头和缰绳","溅溅、啾啾：流水声、马鸣声","赴戎机：奔赴军机战事","度若飞：像飞一样越过","朔气传金柝：北方寒气中传来打更声。金柝，军中打更器具，音tuò","策勋十二转：记很大的功。策勋，记功；转，军功升一级为一转","百千强：成百上千还多。强，有余","尚书郎：尚书省的官","千里足：日行千里的坐骑","郭：外城","扶将：扶持","理红妆：梳妆打扮","霍霍：磨刀声","著我旧时裳：穿上从前的衣裙。著同「着」","帖花黄：在额上贴花黄（妇女面饰）。帖同「贴」","火伴：同伍的士兵。火同「伙」","扑朔、迷离：脚爬搔、眼眯缝的样子","傍地走：贴着地面跑","安能：怎能"],"m":"万里赴戎机，关山度若飞。朔气传金柝，寒光照铁衣。将军百战死，壮士十年归。雄兔脚扑朔，雌兔眼迷离；双兔傍地走，安能辨我是雄雌？","r":"按时间线分六段背；「东市西市南市北市」「旦辞—暮宿」两组复沓成对记；通假：帖（贴）、火（伙）、著（着）；易错读：杼zhù、鞯jiān、辔pèi、柝tuò、朔shuò。"},"敕勒歌|北朝民歌":{"s":"小诗先以「穹庐」喻天，写出草原民族独特的天地观——天如毡帐笼盖四野，亲切而壮阔；末句最妙：草高没牛羊，风过处牛羊时隐时现，静景化为动景，一派水草丰美、牛羊成群的生机，雄浑中含悠然。","b":"北朝乐府民歌，本为鲜卑语歌谣，译为汉语，歌咏阴山脚下敕勒川草原的辽阔丰美，境界雄浑。","n":["敕勒川：敕勒族聚居的平原。敕勒，古代北方游牧民族，音chìlè","阴山：今内蒙古阴山山脉","穹庐：游牧民族的圆顶毡帐，即蒙古包","笼盖四野：像帐篷一样笼罩四面原野。野，旧读yǎ","苍苍：深青色","茫茫：辽阔无边","风吹草低见牛羊：风过处牧草伏低、露出成群牛羊。见同「现」"],"m":"天苍苍，野茫茫，风吹草低见牛羊。","r":"仅七句，按「地点—天似穹庐—天地苍茫—风草牛羊」背；「见」同「现」、「野」旧读yǎ押韵。"},"与朱元思书|吴均":{"s":"文章先以「奇山异水，天下独绝」总领，再分写水之「异」（缥碧见底、急湍猛浪，动静相生）与山之「奇」（负势竞上、泉响鸟鸣，以闹写静）；在工笔写景中插入「望峰息心」两句抒怀，使山水之美与厌弃尘俗之志交融，骈散相间、声韵铿锵。","b":"南朝梁吴均写给友人朱元思的书信节选，是六朝骈体山水小品的名作，描绘富春江富阳至桐庐一段的奇山异水。","n":["风烟俱净：烟雾都消散净尽","天山共色：天与山融为一色","从流飘荡：任船随江流漂荡","自富阳至桐庐：今浙江境内富春江一段","缥碧：青白色。缥音piǎo","急湍甚箭：急流比箭还快","猛浪若奔：猛浪像奔马","负势竞上：山峦凭依地势争相向上","互相轩邈：彼此争着往高处、远处伸展。轩，高；邈，远","泠泠：清越的水声。音líng","嘤嘤：鸟鸣相和声。音yīng","千转不穷：长久不断地鸣啭。转同「啭」","鸢飞戾天：像鸢鸟高飞冲天，喻追求名利到极点。戾，至，音lì","望峰息心：望见雄峰便平息了竞进之心","经纶世务：经营筹划世俗事务。经纶，整理丝缕，引申为筹划","窥谷忘反：看到幽谷便流连忘返。反同「返」","横柯上蔽：横斜的树枝在上边遮蔽","疏条交映：稀疏枝条交错掩映"],"m":"鸢飞戾天者，望峰息心；经纶世务者，窥谷忘反。","r":"按「总起—异水—奇山—抒怀—密林余韵」背；通假：转（啭）、反（返）；易错读：缥piǎo、泠líng、戾lì、柯kē。"},"七步诗|曹植":{"s":"诗以煮豆为喻：萁在釜下燃、豆在釜中泣，拟人写来字字含泪；「同根」点出血缘，「相煎」直指迫害，取譬浅近而锋芒直指，七步成章，才思与悲愤俱在其中。","b":"相传魏文帝曹丕忌惮弟弟曹植，命其七步之内成诗，否则治罪，曹植应声吟成此诗，以豆萁煮豆讽喻骨肉相残。","n":["豆萁：豆秸。萁音qí","釜：锅","燃：烧","本是同根生：豆子和豆秸本是同一条根上长出来的，喻同胞兄弟","相煎何太急：煎熬我何必这么急迫，喻兄长逼迫太甚。煎，煎熬"],"m":"本是同根生，相煎何太急？","r":"四句二十字，按「燃萁—豆泣—同根—反问」背；「萁」读qí；末句反问语气要读出沉痛。"},"梁甫行|曹植":{"s":"诗以「八方风雨」起笔拉开视野，随即聚焦边海之民：寄身草野、妻儿如兽、柴门萧条、狐兔登堂，白描之中见触目惊心；末句以狐兔出入写人迹之稀、村落之荒，不言同情而同情自见，体现曹植后期诗歌沉郁的现实关怀。","b":"曹植晚年备受曹丕、曹叡猜忌，徙封无定、处境困窘。《梁甫行》写海边底层贫民的蛮荒生活，寄寓深切的悲悯，也暗含自身流离之慨。","n":["八方各异气：八方气候各不相同","千里殊风雨：千里之内风雨不一","剧哉：多么艰难啊。剧，艰难","边海民：海边贫民","寄身草野：栖身在荒草野地","妻子象禽兽：妻子儿女像禽兽一样生活（极言其困苦）","行止依林阻：一举一动都依傍险阻山林","翔我宇：在我的屋檐下窜来窜去。翔，游走；宇，屋檐"],"m":"柴门何萧条，狐兔翔我宇。","r":"八句按「天地起兴—边民之苦（身—家—门）」背；「妻子」为古今异义（妻与子女）；「翔」释为游走。"},"陈情表|李密":{"s":"全文以「情」字驱动：先陈孤苦身世与祖孙相依为命，再陈进退两难的狼狈，继而以「圣朝以孝治天下」为依据消解武帝猜忌，最后提出「先尽孝、后尽节」的两全之策。融叙事、抒情、说理于一炉，四字句密集，骈散结合，凄恻动人，被誉为「读《陈情表》不哭者不孝」。","b":"李密曾任蜀汉尚书郎，蜀亡后晋武帝征他为太子洗马，他以祖母刘氏年迈病重为由上《陈情表》辞官，情辞恳切，终获准许。","n":["险衅：命运坎坷、罪孽。衅，音xìn","夙遭闵凶：早年就遭遇不幸。闵同「悯」，此指父丧","见背：背弃我，是父亲去世的婉辞","舅夺母志：舅舅强迫母亲改变守节之志而改嫁","愍：怜惜。音mǐn","九岁不行：九岁还不能走路","零丁孤苦：孤苦无依。零丁同「伶仃」","成立：长大成人","终鲜兄弟：终究没有兄弟。鲜，少，音xiǎn","门衰祚薄：家门衰微、福分浅薄。祚，福分","期功强近之亲：关系较近的亲属。期、功为古代丧服名称，音jī","应门五尺之僮：照应门户的童仆","茕茕孑立，形影相吊：孤孤单单，只有身体和影子互相安慰。孑音jié；吊，安慰","婴疾病：被疾病缠身。婴，缠绕","蓐：草垫子，此指病床","逮奉圣朝：到了本朝（晋朝）","沐浴清化：蒙受清明教化","察臣孝廉、举臣秀才：察举、荐举为孝廉、秀才","供养无主：无人主持供养（祖母）","拜臣郎中、除臣洗马：任命为郎中、太子洗马。除，授官；洗音xiǎn","猥以微贱：像我这样卑微。猥，谦词","东宫：太子居处，代指太子","陨首：掉脑袋，言以死相报","切峻：急切严厉","责臣逋慢：责备我逃避怠慢。逋，逃避，音bū","急于星火：比流星火光还急","日笃：一天比一天沉重","告诉不许：申诉不被允许","狼狈：进退两难","伏惟：我恭恭敬敬地想（下对上的敬辞）","故老：遗老","矜育：怜悯养育","少仕伪朝：年轻时在伪朝（蜀汉）做官","郎署：郎官衙署","不矜名节：不自夸名节（打消晋武猜忌）","亡国贱俘：亡国的低贱俘虏，自谦","宠命优渥：恩宠优厚。渥，厚","盘桓：逗留不进","日薄西山：太阳接近西山，喻寿命将尽。薄，迫近","气息奄奄：呼吸微弱","朝不虑夕：早晨保不住晚上","更相为命：互相依靠维持性命。更相，互相","区区不能废远：拳拳孝心使我不能废止奉养而远离","乌鸟私情：乌鸦反哺之情，喻奉养长辈的孝心","愿乞终养：请求奉养（祖母）到最后","二州牧伯：梁州、益州的长官","皇天后土：天地神明","矜愍愚诚：怜悯我愚拙的诚心","听臣微志：准许我微小的心愿","保卒余年：保全祖母度过余年","死当结草：死后也当报恩（用魏颗结草典故）","犬马怖惧之情：像犬马一样惶恐的心情，表文套语"],"m":"茕茕孑立，形影相吊。日薄西山，气息奄奄，人命危浅，朝不虑夕。臣无祖母，无以至今日；祖母无臣，无以终余年。","r":"按「孤苦身世—奉诏进退两难—以孝立论陈情—先孝后忠之请」四段背；成语链（茕茕孑立/形影相吊/日薄西山/气息奄奄/朝不虑夕）是记忆抓手；易错读：衅xìn、愍mǐn、祚zuò、鲜xiǎn、茕qióng、孑jié、蓐rù、逋bū、渥wò、笃dǔ。"},"长歌行|汉乐府":{"s":"全诗托物言志：先以朝露易干、春荣秋枯写万物盛衰有时，再以百川东去不复返比喻时光一去不回，最后水到渠成逼出「少壮不努力，老大徒伤悲」的警策；由景入理，层层蓄势，结句朴素而力量千钧。","b":"汉代乐府《相和歌辞》名篇，以园葵起兴、以百川归海作比，劝人珍惜青春年华、及时努力，是最早的惜时劝学诗之一。","n":["葵：葵菜，古代重要蔬菜","朝露待日晞：清晨的露水等待太阳晒干。晞，晒干，音xī","阳春布德泽：温暖的春天布施恩泽","焜黄华叶衰：花叶枯黄凋零。焜黄，颜色枯黄；华同「花」","百川东到海：千百条江河东流入海","复西归：再向西流回来","老大：年老"],"m":"少壮不努力，老大徒伤悲。","r":"十句按「葵露—春泽—秋衰—川海—劝勉」背；「华」同「花」、「晞」音xī、「焜」音kūn；末两句为千古警句。"},"十五从军征|汉乐府":{"s":"全诗纯用白描，不着一字议论而批判自深：归乡的欣喜与「松柏冢累累」的真相迎头相撞；兔入雉飞、野谷野葵的荒宅细节，以及「饭熟不知饴阿谁」的一幕，把无家可归的悲怆写到极致；末句老泪纵横，无声胜有声。","b":"汉代乐府民歌，以一位十五岁从军、八十岁才还乡的老兵视角，写战乱之后家破人亡的惨状，是反战诗的杰作。","n":["十五从军征，八十始得归：极言服役时间之长","阿谁：谁。阿，词头","遥看是君家：远远看去那就是你的家","冢累累：坟墓一个挨一个。冢，坟墓，音zhǒng","狗窦：给狗进出的墙洞","雉：野鸡","旅谷、旅葵：野生的谷子、葵菜。旅，不种自生","舂谷：捣掉谷壳。舂音chōng","持作饭、作羹：拿来做饭、做汤","饴：送给。音sì","沾我衣：浸湿衣裳"],"m":"出门东向看，泪落沾我衣。","r":"按「归途问人—远望见坟—家园残破—做饭无亲—东望泪落」五幕背；「饴」读sì（喂、送）；数字「十五/八十」的对比是诗眼。"},"兰亭集序|王羲之":{"s":"文章由「乐」起、以「痛」转、以「感」收：先写兰亭良辰美景、群贤雅集之乐，笔致明丽；继而由聚散无常想到人生短促、死生之大，情调转入苍凉；最后批判庄子「一死生」「齐彭殇」的虚无，肯定生命的价值。骈散结合、清新自然，在玄言诗风行的东晋独树一帜。","b":"公元353年三月初三，王羲之与谢安等四十一位名士会于会稽兰亭，曲水流觞、饮酒赋诗，本文是王羲之为诗集所作的序，既是散文名篇，也是「天下第一行书」的法帖内容。","n":["永和九年：东晋穆帝永和九年（353年）","岁在癸丑：干支纪年为癸丑年。癸guǐ","暮春之初：农历三月初，此指三月上巳日","会稽山阴：今浙江绍兴。会音kuài","修禊：古代三月上巳临水洗濯、祓除不祥的祭礼。禊音xì","群贤毕至，少长咸集：众多贤士都到了、年长年少者齐集","崇山峻岭：高峻的山岭","茂林修竹：茂密的林木、高高的竹子","清流激湍：清澈湍急的水流","映带左右：环绕映衬在亭子四周","流觞曲水：把酒杯放在弯曲水道上顺流而下，停在谁前谁就饮酒赋诗","列坐其次：依次坐在水边。次，旁边","一觞一咏：边饮酒边赋诗","幽情：深远的情怀","惠风：和风","仰观宇宙之大，俯察品类之盛：抬头观览天地之大、低头审视万物之多","游目骋怀：纵目浏览、舒展胸怀。骋，放开","信可乐也：实在快乐。信，确实","相与：相处、相交","俯仰一世：一生转瞬即逝","取诸怀抱，悟言一室之内：把胸怀抱负在室内与朋友面对面畅谈。悟同「晤」","因寄所托，放浪形骸之外：寄托情怀、放纵形骸于世俗之外","趣舍万殊：取舍千差万别。趣同「取」","暂得于己：一时感到自得","不知老之将至：竟忘了衰老将至（语出《论语》）","所之既倦：对所喜爱或得到的事物已经厌倦","感慨系之：感慨随之而生","向之所欣：从前感到欢欣的","俯仰之间：转瞬之间","修短随化：寿命长短听凭造化","终期于尽：最终都要归于死亡","死生亦大矣：死生也是人生大事（语出《庄子》）","兴感之由：发生感慨的缘由","若合一契：像符契一样吻合","临文嗟悼：面对古人文章叹息哀伤","不能喻之于怀：心里又不能明白释然","一死生为虚诞：把死和生等同起来是荒诞的。一，看作一样","齐彭殇为妄作：把长寿的彭祖与夭折的儿童等量齐观是虚妄的。彭，彭祖；殇，夭折者","列叙时人：一一记下当时与会的人","世殊事异：时代不同、事情变化","致一：情致相同"],"m":"群贤毕至，少长咸集。仰观宇宙之大，俯察品类之盛，所以游目骋怀，足以极视听之娱，信可乐也。固知一死生为虚诞，齐彭殇为妄作。","r":"三段式：「宴集之乐—死生之痛—古今之感」；第一段写景记宴、第二段抒情议论、第三段作序明旨；通假：悟（晤）、趣（取）；易错读：癸guǐ、禊xì、骋chěng、殇shāng。"},"诫子书|诸葛亮":{"s":"文章以「静」字立骨：修身在静、成学在静，而「淫慢」「险躁」正是其反面；正面立论与反面警示交错，双重否定句式斩钉截铁；末段以「年与时驰」的紧迫感收束，把立志、为学、惜时一以贯之，言近旨远。","b":"诸葛亮晚年写给八岁儿子诸葛瞻的家书，短短八十六字，凝聚修身立志、为学做人的训诫，是千古传诵的家训名篇。","n":["夫君子之行：君子的品行操守。夫，发语词","静以修身：以宁静专一来修养身心","俭以养德：以节俭来培养品德","淡泊：内心恬淡、不慕名利","明志：明确志向","宁静：摒除杂念、安宁专一","致远：达到远大目标","广才：增长才干","淫慢则不能励精：放纵懈怠就不能振奋精神。淫，过度；慢，懈怠","险躁则不能治性：轻薄浮躁就不能修养性情。治，修养","年与时驰：年华随同时光飞逝","意与日去：意志随同岁月消磨","枯落：像枯叶般凋落，喻人老而无成","多不接世：大多对社会没有贡献","穷庐：破房子","将复何及：又怎么来得及"],"m":"非淡泊无以明志，非宁静无以致远。","r":"按「修身养德—明志致远—为学须静—慢躁之害—惜时警策」背；对偶句成对记（淡泊/宁静、淫慢/险躁）；「治性」的治释为修养。"},"三峡|郦道元":{"s":"文章先以正面描写与侧面烘托结合写山之高峻连亘，再按夏、春冬、秋的时序写水：夏水奔放、春冬清幽、秋景凄异，动静相生；结尾引渔者歌谣，以猿鸣哀转收束，把三峡的险与旅人的愁融为一体，炼字精当，节奏张弛有致。","b":"选自北魏郦道元《水经注·江水》，为古书《水经》作注时综合前人记载写成，仅用百余字就写尽三峡四季的雄奇幽美。","n":["自三峡七百里中：在三峡七百里之间。三峡，瞿塘峡、巫峡、西陵峡","两岸连山，略无阙处：两岸山连着山，几乎没有中断处。阙同「缺」","重岩叠嶂：层层悬崖、排排峭壁。嶂，直立像屏障的山","隐天蔽日：遮蔽天空和太阳","自非亭午夜分：如果不是正午和半夜。自非，如果不是","曦月：日月。曦，日光，此指太阳，音xī","夏水襄陵：夏天江水漫上山陵。襄，冲上、漫上","沿溯阻绝：顺流而下和逆流而上的航路都被阻断。溯音sù","王命急宣：皇帝的命令要急速传达","朝发白帝，暮到江陵：早晨从白帝城出发、傍晚到江陵","乘奔御风：骑着奔马、驾着疾风","不以疾也：也不如它快","素湍绿潭：雪白的急流、碧绿的深潭","回清倒影：回旋着清波、倒映着景物","绝巘：极高的山峰。巘音yǎn","悬泉瀑布，飞漱其间：悬泉瀑布在山峰间飞流冲荡。漱，冲荡","清荣峻茂：水清、树荣、山高、草茂","良：甚、实在","晴初霜旦：雨后初晴或下霜的早晨","林寒涧肃：树林山涧清冷寂静","属引凄异：声音连续不断、凄凉异常。属音zhǔ，连接；引，延长","空谷传响：空荡的山谷传来回声","哀转久绝：悲哀婉转的声音很久才消失。转同「啭」"],"m":"重岩叠嶂，隐天蔽日，自非亭午夜分，不见曦月。巴东三峡巫峡长，猿鸣三声泪沾裳。","r":"按「总写山势—夏水—春冬之景—秋景—渔歌」背；通假：阙（缺）、转（啭）；易错读：曦xī、溯sù、巘yǎn、漱shù、属zhǔ。"},"答谢中书书|陶弘景":{"s":"文章以「山川之美，古来共谈」总起，随即从高低（高峰清流）、色彩（石壁青林）、晨昏（晓雾夕日）、动静（猿鸟沉鳞）多角度铺陈，对仗工整而画面流转；末以谢灵运作衬，自豪地表示自己方能与古人同赏此奇，寥寥数笔，仙意盎然。","b":"陶弘景是南朝齐梁时的道教思想家，这是他写给友人谢中书的一封书信，短短六十八字，写尽江南山水之美，是六朝山水小品名作。","n":["五色交辉：石壁色彩斑斓、交相辉映","四时俱备：四季景色都有","晓雾将歇：清晨薄雾将要消散","夕日欲颓：夕阳将要坠落。颓，坠落","沉鳞竞跃：潜游水中的鱼争相跃出。沉鳞，潜游的鱼","欲界之仙都：人间的仙境。欲界，佛家语，此指人间","康乐：指南朝宋山水诗人谢灵运，袭封康乐侯","与其奇者：欣赏这种奇丽山水。与，参与，此指欣赏，音yù"],"m":"高峰入云，清流见底。晓雾将歇，猿鸟乱鸣；夕日欲颓，沉鳞竞跃。","r":"按「总起—山水—晨昏—叹仙都—追怀康乐」背；「与」读yù（参与、欣赏）；「沉鳞」是借代（以鳞代鱼）。"},"归去来兮辞|陶渊明":{"s":"全赋以「归」字为线索：首段写辞官归途的如释重负，二段写抵家后的天伦田园之乐，三段写躬耕出游的春日生机，末段纵论生死、委心乘化。叙事、写景、抒情、议论水乳交融，语言平淡自然而意蕴深远，「云无心以出岫」二句物我两忘，成为隐逸情怀的千古写照。","b":"陶渊明四十一岁辞去彭泽县令、归隐田园，本篇即辞官之初所作，是其归隐之志的宣言书，也是魏晋抒情小赋的代表作。","n":["归去来兮：回去吧。来、兮皆语气词","田园将芜胡不归：田园将要荒芜，为什么还不回去。胡，为什么","以心为形役：让心灵被形体役使，即为免于饥寒而违心做官","奚惆怅而独悲：为什么还独自惆怅悲伤。奚，为什么","悟已往之不谏：认识到过去的已不可挽回。谏，止、挽回","知来者之可追：知道未来的还来得及补救","迷途其未远：误入迷途还不算远","今是而昨非：如今归隐对、从前出仕错","舟遥遥以轻飏：船轻快漂荡。飏，飞扬","征夫：行人","恨晨光之熹微：恨天亮得太慢。熹微，天色微明","乃瞻衡宇：终于望见自家简陋的房屋。衡同「横」，横木为门","载欣载奔：一边高兴一边奔跑","三径就荒：院中小路已近荒芜，用汉代蒋诩归隐典故","眄庭柯以怡颜：看看院中的树就露出喜色。眄，斜视，音miǎn","寄傲：寄托傲世之情","审容膝之易安：深知狭小之地也易安居。容膝，仅容双膝，极言屋小","策扶老以流憩：拄着拐杖随处歇息","矫首而遐观：抬头远望","云无心以出岫：云气自然而然从山间飘出。岫，山峰，音xiù","景翳翳以将入：日光暗淡、太阳将落。景同「影」，日光；翳翳，昏暗","盘桓：徘徊","请息交以绝游：让我断绝与官场的交游","复驾言兮焉求：还驾车出游追求什么。驾言，驾车，语出《诗经》","悦亲戚之情话：以与亲人说知心话为乐","将有事于西畴：要到西边田地里耕作。畴，田地","巾车、孤舟：有帷幕的小车、小船","窈窕、崎岖：幽深曲折、高低不平","欣欣以向荣：草木蓬勃生长","涓涓：细水缓流貌","善万物之得时：羡慕万物各得其时","感吾生之行休：感叹我的一生将要结束","已矣乎：算了吧","寓形宇内：寄身天地之间","委心任去留：随自己心意决定去留","遑遑：匆忙不安","帝乡不可期：成仙成神不可企及","怀良辰以孤往：爱惜美好时光独自出游","植杖而耘耔：放下手杖除草培苗。耔，培苗，音zǐ","登东皋以舒啸：登上东边高岗放声长啸","聊乘化以归尽：姑且顺着自然变化走向生命尽头","乐夫天命复奚疑：乐天知命还有什么可疑虑的"],"m":"悟已往之不谏，知来者之可追。云无心以出岫，鸟倦飞而知还。木欣欣以向荣，泉涓涓而始流。聊乘化以归尽，乐夫天命复奚疑！","r":"按「决意归去—归途抵家—园居出游—乘化乐天」四段背；注意序与赋的分工（本文为赋文）；通假：衡（横）、景（影）；易错读：飏yáng、熹xī、眄miǎn、岫xiù、翳yì、畴chóu、耔zǐ。"},"读山海经·其十|陶渊明":{"s":"诗前四句咏叹二神：精卫以微木填沧海、刑天断首犹舞干戚，力量悬殊而斗志不灭，「猛志常在」四字掷地有声；后四句一转，「徒设」「讵可待」在同情神话英雄壮志难酬的同时寄寓自身的悲慨，鲁迅因此称陶诗并非浑身静穆，也有「金刚怒目」的一面。","b":"陶渊明《读山海经》共十三首，此为第十首，借精卫、刑天两个神话形象抒发对不屈抗争精神的赞颂，也暗含自己壮志未酬的感慨。","n":["精卫：神话中炎帝之女溺死东海后所化之鸟，衔木石填海","微木：细小的木枝","刑天：神话人物，与天帝争神被砍头，仍以乳为目、以脐为口，挥舞盾斧","干戚：盾与斧","猛志固常在：勇猛的斗志永远存在。固，本来","同物既无虑：化为异物（精卫、刑天）后已无顾虑","化去不复悔：身死化去也毫不后悔","徒设在昔心：空有昔日的壮志。徒，徒然","良辰讵可待：实现壮志的好时机又怎能等到。讵，岂，音jù"],"m":"精卫衔微木，将以填沧海。刑天舞干戚，猛志固常在。","r":"八句分两层：前四咏神（精卫—刑天）、后四寄慨（无虑不悔—徒设难待）；「干」读gān（盾牌）、「讵」读jù。"},"五柳先生传|陶渊明":{"s":"传文以「不知何许人」的模糊开篇，故意隐去姓名里籍，凸显超脱世俗的隐士形象；接着以「好读书、性嗜酒、安贫贱、著文章」四事白描，笔墨省净而风神毕现；赞语引黔娄之妻之言，以「不戚戚、不汲汲」点睛，再以无怀、葛天之民作结，平淡中见高趣。","b":"陶渊明以自况笔法为一位安贫乐道、好读书、性嗜酒、常著文的「五柳先生」作传，实为作者的自我画像，是中国文学史上第一篇自传体别传。","n":["何许人：什么地方的人","不详其姓字：不清楚他的姓名","因以为号焉：就用（五柳）作为自己的号","不慕荣利：不羡慕功名利禄","不求甚解：读书只求领会要旨，不在字句上过分深究（与今义不同）","会意：有所领会","性嗜酒：生性酷爱喝酒","亲旧：亲戚旧友","或置酒而招之：有时备酒招待他","造饮辄尽：去喝酒就一定要喝尽兴。造，往、到；辄，就","期在必醉：图的是一醉。期，期望","曾不吝情去留：竟毫不掩饰去留的态度。曾不，竟不","环堵萧然：居室四壁空空、冷冷清清","短褐穿结：粗布短衣打满补丁","箪瓢屡空：饭篮水瓢常常空着，写贫困","晏如：安然自若的样子","兹若人之俦：这人应是五柳先生一类人吧。俦，类","戚戚、汲汲：忧愁不安、急切营求的样子","衔觞赋诗：饮酒作诗。觞，酒杯","无怀氏、葛天氏：传说中的上古太平时代帝王"],"m":"好读书，不求甚解；每有会意，便欣然忘食。不戚戚于贫贱，不汲汲于富贵。","r":"按「名号由来—性格—三爱好（读书/饮酒/著文）—贫居—赞语」背；古今异义重点：不求甚解（古为褒义）；易错读：嗜shì、辄zhé、箪dān、俦chóu、戚qī、汲jí、觞shāng。"},"垓下歌|项羽":{"s":"全诗仅四句，情感却两度跌宕：首句以拔山盖世自许，何等雄豪；二三句叹时运不济、骏马不驰，英雄失路之悲扑面而来；末句连呼「虞兮」，把对爱人的不舍与无力回天的痛惜交织在一起，刚极而柔，成为千古末路英雄的典型心声。","b":"楚汉相争末期，项羽被汉军围于垓下、夜闻四面楚歌，于帐中饮酒，对爱姬虞姬慷慨悲歌，此即《垓下歌》，是英雄末路的绝命词。","n":["力拔山兮气盖世：力气能拔起大山、气概笼盖一世","时不利兮骓不逝：时运不利，连乌骓马也不肯奔驰。骓，青白杂色马，音zhuī","可奈何：能怎么办","虞兮虞兮奈若何：虞姬啊虞姬，把你怎么安排呢。若，你"],"m":"力拔山兮气盖世。时不利兮骓不逝。骓不逝兮可奈何！虞兮虞兮奈若何！","r":"四句按「自雄—叹时—唤骓—呼虞」背；两个「骓不逝」重叠是情感递进；「奈若何」的若释为你。"},"春山夜月|于良史":{"s":"颔联是千古名句：捧水则月影入怀、弄花则香气沾衣，把水月、花香与人的动作融为一体，物我两惬；全诗由「忘归」起、以「惜芳菲」承、以钟声楼台收，清幽高远，兴致盎然。","b":"于良史为唐代天宝至大历间诗人，生平不详。此诗写春山夜游、赏月弄花的雅兴，是其传世名作。","n":["胜事：美好的事","掬：双手捧起","芳菲：花草的芬芳，代指春景","翠微：青翠掩映的山腰幽深处"],"m":"掬水月在手，弄花香满衣。","r":"五律八句，按「夜赏起兴—掬弄二联—欲去还惜—远望钟声」背；「掬」读jū。"},"行宫|元稹":{"s":"诗以「宫花寂寞红」的乐景反衬行宫寥落，以「白头宫女」与「说玄宗」构成巨大的时间落差——盛世已成闲谈，无限沧桑尽在「闲坐」二字中，以少总多，含蓄隽永，被潘德舆誉为「十个字足赅《连昌宫赋》」。","b":"元稹此诗写安史之乱后洛阳行宫的冷落：红颜入宫、白头犹在，闲说玄宗旧事，以二十字包藏一代盛衰。","n":["行宫：皇帝出巡暂住的离宫，此指洛阳上阳宫","寥落：冷落萧条","玄宗：唐玄宗李隆基，开天盛世的缔造者，亦亲历安史之乱"],"m":"白头宫女在，闲坐说玄宗。","r":"四句抓「寥落—花红—白头—说玄宗」的今昔对比；「行」旧读xíng。"},"闻乐天授江州司马|元稹":{"s":"全诗以残灯、暗影、暗风、寒雨层层渲染凄凉，「惊坐起」三字于病体难支中陡然发力，惊的是友人命运、亦是自己身世；结句以景结情，风雨寒窗既是实景，也是两位迁客凄苦心境的外化。","b":"元和十年（815）白居易被贬江州司马，时元稹也因得罪权贵贬谪通州、正卧病，闻讯惊作此诗，写患难友情与同病相怜之痛。","n":["乐天：白居易字乐天","江州司马：白居易被贬为江州（今九江）司马","幢幢：影子摇晃不定的样子。音chuáng","谪：贬官。音zhé","垂死病中：重病将死之时，夸张写病势沉重"],"m":"垂死病中惊坐起，暗风吹雨入寒窗。","r":"四句按「灯景—闻谪—惊起—风雨」背；「幢」读chuáng、「谪」读zhé。"},"离思五首·一|元稹":{"s":"小诗不直言情，而以「残妆—环钗—日射—红颊」四笔白描晨起情态，末句以「一朵红苏」喻胭脂颊上的鲜活，「欲融」二字化静为动，细腻传神，秾丽而不轻薄。","b":"此为元稹《离思五首》之一，组诗多为悼念亡妻韦丛而作，本篇截取晨起对镜的一个片段，写女子娇慵明艳之态，是组诗中偏于闺情刻画的一首。","n":["残妆晓镜：清晨镜中残留昨夜妆色","环钗谩𥮾：环钗随意插在发间。谩，漫、随意；𥮾同「簪」，插","须臾：片刻","燕脂：即胭脂","一朵红苏旋欲融：红晕上脸、如红花复苏般几乎要融化。旋，随即"],"m":"须臾日射燕脂颊，一朵红苏旋欲融。","r":"四句按「晓镜残妆—钗横—日照胭脂—红颊欲融」背；生僻字：谩mán、𥮾zān、旋xuán。"},"春怨|刘方平":{"s":"全诗以时间推移写愁绪加深：日落黄昏、金屋无人、空庭春晚、梨花满地，层层设色而终归于「不开门」的封闭；「梨花满地」既写暮春之景，又暗喻青春零落，情景双关，凄婉欲绝。","b":"刘方平，唐代诗人。此诗写一位幽居深宫（或深闺）的女子在春晚黄昏独自垂泪的寂寞，是宫怨诗的名篇。","n":["金屋：用汉武帝「金屋藏娇」典故，此指华美而孤寂的宫室","春欲晚：春光将尽","梨花满地：梨花飘落满地，暗喻青春凋零"],"m":"寂寞空庭春欲晚，梨花满地不开门。","r":"四句以「纱窗日落—金屋泪痕—空庭春晚—梨花闭门」为序；「金屋」藏娇典故要知。"},"蜀先主庙|刘禹锡":{"s":"首联以「英雄气」笼罩全篇、笔力千钧；颔联写创业之艰（三分鼎、复汉业），颈联以「得相开国」与「生儿不贤」作尖锐对比，尾联以蜀妓舞魏宫的凄凉画面收束，兴亡之叹尽在不言中，用典精切、对仗工稳。","b":"刘禹锡任夔州刺史时谒刘备庙所作，全诗凭吊蜀汉兴亡，寄托对治乱兴衰的感慨。","n":["蜀先主：蜀汉先主刘备，庙在夔州","凛然：令人敬畏的样子","三足鼎：魏蜀吴三分天下如鼎三足","业复五铢钱：以汉武帝五铢钱代指复兴汉室（王莽废五铢，光武复之）","得相：得到诸葛亮为相","不象贤：后嗣不肖，指后主刘禅昏庸。象，效法","蜀故妓来舞魏宫：蜀亡后，刘禅被迁洛阳，在司马昭宴上闻蜀伎歌舞而嬉笑，用《三国志》事"],"m":"天地英雄气，千秋尚凛然。","r":"五律按「英雄总赞—创业—得相/不肖—亡国凄凉」背；「五铢钱」「象贤」两个典故是理解关键。"},"始闻秋风|刘禹锡":{"s":"诗以与秋风对话起笔，去年别、今年回，亲切而有岁月之慨；颈联最为警拔——战马思念边塞秋草而卷毛耸动、雄鹰顾盼青云而睡眼睁开，借马与雕的意象写出诗人老而弥坚的用世之心；末句扶病登台，豪情振起，一反悲秋老调。","b":"刘禹锡晚年多病，闻秋风而作此诗。与传统悲秋之作不同，本诗偏写秋风中奋厉向上的豪情，是其「诗豪」性格的写照。","n":["君：此指秋风，以拟人语相呼","玄蝉：寒蝉，秋天黑色的蝉","五夜：五更天，将晓之时","飕飗：风声。音sōuliú","颜状：容貌，此指衰老之态","拳毛：卷曲的马毛","雕眄青云：雄鹰斜望青云。眄，斜视，音miǎn","肃清：秋气肃杀、天地清旷","扶病：抱病、带病"],"m":"马思边草拳毛动，雕眄青云睡眼开。","r":"按「别而又回—枕上镜中—马雕自况—登台远望」背；生僻字：飕飗sōuliú、眄miǎn、拳（卷曲）。"},"西塞山怀古|刘禹锡":{"s":"前四句以雄浑笔力写灭吴之战：楼船东下、王气黯然、铁锁沉江、降幡出城，一「收」一「出」，胜败如见；后四句由史入景，几回往事与山形依旧对举，人事代谢而江山不改，末以故垒芦荻的萧瑟秋景收束，怀古苍凉，被誉为唐人怀古七律压卷之一。","b":"长庆四年（824）刘禹锡由夔州赴和州，途经西塞山，触景生情，借西晋灭吴的史事慨叹六朝兴亡、国家统一之可贵。","n":["西塞山：在今湖北大冶东，长江要塞","西晋楼船：晋将王濬率高大战船顺江灭吴。益州，今成都","金陵王气：金陵（今南京，吴都）的帝王之气","千寻铁锁：吴国在长江设千寻铁链横锁江面拦晋军。寻，八尺","沈江底：王濬以火炬烧断铁锁、沉入江底。沈同「沉」","降旛出石头：投降的旗子从石头城举起。旛同「幡」","四海为家：天下一统","故垒：旧时营垒"],"m":"千寻铁锁沈江底，一片降旛出石头。人世几回伤往事，山形依旧枕江流。","r":"按「晋军灭吴（四句叙事）—人世山形对比—一统之日故垒秋景」背；通假：沈（沉）、旛（幡）；「寻」为长度单位。"},"竹枝词二首·一|刘禹锡":{"s":"前两句以青柳平江、歌声隐隐铺出明丽背景；后两句是全诗神髓，借江南「太阳雨」的常见景象，以「晴」谐「情」，把初恋少女似有若无、忐忑试探的心理写得既含蓄又明朗，谐音双关天然入妙，是学习民歌的典范。","b":"刘禹锡任夔州刺史时学习民歌所作《竹枝词》之一，以少女口吻写江上闻歌、捉摸情人心意的微妙心理。","n":["竹枝词：巴渝一带民歌，刘禹锡依声填词、多写风土爱情","唱歌声：西南男女恋爱以歌声传情","晴：谐音「情」，双关语"],"m":"东边日出西边雨，道是无晴却有晴。","r":"四句背时抓住「晴—情」谐音双关这个诗眼；「唱歌」一作「踏歌」，以库文为准。"},"秋词二首·一|刘禹锡":{"s":"开篇即以议论立异——「秋日胜春朝」，断然否定悲秋老调；后两句以晴空孤鹤排云直上的明丽画面作论据，鹤之高举即诗人情志之高举，情景理三者合一，明快刚健，尽显贬中不馁的胸襟。","b":"刘禹锡贬朗州时作《秋词》二首，此为其一，以昂扬之笔翻写自古悲秋的传统主题。","n":["悲寂寥：悲叹秋天冷落萧条","春朝：春天的早晨，代指春天。朝音zhāo","排云上：冲破云层、凌云直上","碧霄：碧蓝的高空"],"m":"晴空一鹤排云上，便引诗情到碧霄。","r":"四句短章，按「反传统立论—鹤飞引诗」背；「朝」读zhāo、「排」是推开、冲破。"},"杨柳枝词九首·一|刘禹锡":{"s":"诗以两首前朝旧曲起兴作衬：梅花羌笛、淮南桂词，虽美皆属「前朝」；后两句直陈主张，「莫奏」与「听唱」对举，鲜明提出文学要与时俱进、翻为新声。以诗论艺，寓革新之志，爽朗明快。","b":"刘禹锡《杨柳枝词》九首之一，主张文学艺术应随时代创新，不要一味因袭旧曲。","n":["塞北梅花羌笛吹：塞北羌笛吹奏《梅花落》古曲。羌音qiāng","淮南桂树小山词：西汉淮南王门客小山作《招隐士》，有「桂树丛生兮山之幽」句","新翻：新创作、翻新曲调","杨柳枝：即《杨柳枝词》，源于古横吹曲，刘禹锡翻新为新声"],"m":"请君莫奏前朝曲，听唱新翻杨柳枝。","r":"四句按「两种旧曲—莫奏旧曲—听唱新声」背；「羌」读qiāng。"},"再游玄都观|刘禹锡":{"s":"诗以「百亩半苔、桃花净尽」写当年炙手可热的新贵烟消云散，以菜花取代桃花暗示政局翻覆；「前度刘郎今又来」一句倔强幽默，在戏谑中见不屈，十四年贬谪的傲骨尽在「又」字之中。","b":"刘禹锡因咏玄都观桃花诗讥讽权贵再度被贬，十四年后重还长安、再游玄都观而作此诗，是前诗《元和十年自朗州至京戏赠看花诸君子》的续篇。","n":["玄都观：长安道观。观音guàn","苔：青苔，言游人绝迹","种桃道士：暗指当年扶植新贵的当权者","前度刘郎：上次来过的刘郎，诗人自指。度，次"],"m":"种桃道士归何处，前度刘郎今又来。","r":"结合前诗背景背：苔/菜花之景—道士何往—刘郎又来；「度」释为次、回。"},"金陵五题·石头城|刘禹锡":{"s":"全诗无一句人语，纯以山水明月写「空」字：青山依旧环拥故都、潮水拍打空城又寂寞退回，只有曾照六朝繁华的旧时明月，深夜还照例越过女墙。「寂寞」二字拟人，山、潮、月皆有情而人踪已绝，怀古之思苍茫无尽。","b":"刘禹锡《金陵五题》组诗之一，写六朝故都石头城的荒凉，寄托国运兴亡之叹，白居易曾「掉头苦吟，叹赏良久」。","n":["石头城：今南京，六朝古都，此为《金陵五题》之一","故国：旧都、故都","周遭：四周环绕","淮水：秦淮河","女墙：城墙上凹凸的矮墙，即城垛"],"m":"山围故国周遭在，潮打空城寂寞回。淮水东边旧时月，夜深还过女墙来。","r":"四句抓「山—潮—月」三个意象与「故国/空城/旧时」三个时间词；「女墙」即城垛。"},"和乐天春词|刘禹锡":{"s":"前两句写新妆下楼、一院春愁，「锁」字双关院锁与心锁；后两句以「数花朵」写百无聊赖，更以蜻蜓误把美人当花、飞上玉簪的细节作结，灵动巧妙——人静如静物，愈显其孤寂，以美写愁，韵味悠长。","b":"刘禹锡此诗写一位新妆下楼、深院春愁的女子，以数花朵、蜻蜓停簪的细节写其寂寞无聊，是唱和白居易的宫怨佳作。","n":["和乐天春词：酬和白居易《春词》之作","新妆面面：一作「新妆宜面」，言脂粉与面容相宜","深锁春光：春光被深锁院中，喻人被深锁楼中","玉搔头：玉簪的别称"],"m":"行到中庭数花朵，蜻蜓飞上玉搔头。","r":"四句按「新妆下楼—深院锁愁—中庭数花—蜻蜓上簪」背；「玉搔头」即玉簪。"},"逢雪宿芙蓉山主人|刘长卿":{"s":"前两句写日暮途远、天寒屋贫，渲染清冷孤寂；后两句于静极处忽闻犬吠、又见归人，以声破静、以动写静，「风雪夜归人」五字既写主人冒雪归家，也含诗人投宿得依的温暖，画面感极强。","b":"刘长卿逢雪夜投宿芙蓉山贫家所作，以短短二十字勾勒出一幅寒山雪夜投宿图。","n":["芙蓉山主人：芙蓉山中的人家（主人是对居停人家的称呼）","白屋：以白茅覆盖的贫家屋","柴门：柴木编的门","夜归人：夜里冒雪归来的人"],"m":"柴门闻犬吠，风雪夜归人。","r":"五绝按「日暮—屋贫—犬吠—归人」背；时间由暮到夜、色调由苍到白。"},"听弹琴|刘长卿":{"s":"前两句以泠泠琴声、松风寒意写琴调高古；后两句由琴及人、由乐及世——古调自爱而今人不弹，正是诗人怀才不遇、不合时俗的自况，言浅意深，慨叹含蓄。","b":"刘长卿借听琴咏怀，慨叹世风不古、知音难觅，是一首托物言志的五言绝句。","n":["泠泠：清越的琴声。音líng","七丝：七弦琴","松风寒：琴曲有《风入松》，此兼写琴声如松间寒风","古调：古雅的曲调，亦双关古朴的操守"],"m":"古调虽自爱，今人多不弹。","r":"四句按「琴声—松风—自爱—不弹」背；「泠」读líng；「古调」双关是关键。"},"送灵澈上人|刘长卿":{"s":"全诗如一幅淡墨送客图：苍苍竹林、杳杳晚钟交代环境与时分，后两句写灵澈荷笠披一身夕阳、独自隐入青山，「带夕阳」三字尤妙，仿佛夕阳可披可戴；清寂高远，禅意悠然，别情不着一字而风神自远。","b":"刘长卿在润州（今镇江）送诗僧灵澈归山所作，是中唐送别诗中的清隽小品。","n":["灵澈上人：中唐诗僧灵澈，上人是对僧人的敬称","竹林寺：在今江苏镇江","杳杳：深远幽暗，此指钟声悠远","荷笠：背着斗笠。荷，扛、背","独归远：独自向青山深处归去"],"m":"荷笠带夕阳，青山独归远。","r":"四句按「竹林—钟声—荷笠—归山」背；「荷」读hè（背负）、「杳」读yǎo。"},"送李中丞之襄州|刘长卿":{"s":"首联「曾驱十万师」极写昔日威风，与「流落」对举，盛衰立见；颈联「轻生一剑知」最为沉郁——将军出生入死的忠勇唯有随身长剑知晓，写尽功臣无人相知的悲凉；末以茫茫汉江、日暮何之收束，身世苍茫。","b":"刘长卿送别一位罢职流落、暮年漂泊的老将，对其功高失所寄予深切同情，也暗含对朝廷薄待功臣的微词。","n":["李中丞：一位李姓御史中丞，曾为征南名将","之襄州：前往襄州","旧业：家乡产业","明时：政治清明的时代（含对朝廷的期许）","三朝：经历三朝","轻生：看轻性命、奋不顾身","何之：去往何处。之，往"],"m":"独立三朝识，轻生一剑知。","r":"五律按「流落—曾驱—罢归—恋朝—三朝一剑—江上何之」背；「之」作动词往。"},"秋日登吴公台上寺远眺寺即陈将吴明彻战场|刘长卿":{"s":"首联以摇落秋景起乡思；颔联野寺云峰写其荒僻；颈联是名句——残阳斜照旧垒、寒磬声满空林，视听交织，「依」「满」二字尤见苍凉；尾联由战场故垒想到南朝纷争，唯长江自流至今，吊古之情悠然而尽。","b":"刘长卿秋日登吴公台寺远眺，此地原为古战场，全诗吊古伤怀、兼写羁旅乡思。","n":["吴公台：在今扬州，南朝陈将吴明彻战场遗址，后建寺","摇落：草木凋零，用宋玉「悲哉秋之为气也」意","旧垒：旧日营垒、战场工事","寒磬：寒空中传来的磬声。磬，寺中铜制打击乐器","南朝事：南朝兴亡旧事"],"m":"夕阳依旧垒，寒磬满空林。","r":"按「登台起兴—寺荒—夕阳寒磬—吊古长江」背；「磬」读qìng。"},"逢病军人|卢纶":{"s":"诗不写征战之壮而写还乡之惨：行、病、无粮、未到乡，四层困厄层层叠加；末句「秋气入金疮」以寒气催裂旧伤的细节，把伤兵的痛楚写得具体可感，字字含泪，是对战争创伤的冷峻记录。","b":"卢纶这首七绝写一位在战争中负伤、带病乞讨还乡的退伍士兵，是中唐边塞诗中直面伤兵疾苦的现实主义佳作。","n":["行多有病：行路既久、又带着病","住无粮：停下又没有口粮","万里还乡：从万里之外的边塞返乡","蓬鬓：鬓发蓬乱","金疮：刀剑创伤，此指战伤复发、遇秋寒而痛"],"m":"蓬鬓哀吟古城下，不堪秋气入金疮。","r":"四句按「行病无粮—万里未归—蓬鬓哀吟—金疮秋痛」背；「金疮」即刀剑战伤。"},"和张仆射塞下曲·一|卢纶":{"s":"前两句以雕翎良箭、燕尾绣旗两件军物起笔，装备精良已见军容；后两句写将军独立台上、一声令下而千营同呼，以「一」与「千」的对比凸显号令严明、上下同心，短短二十字，声威如闻。","b":"卢纶《和张仆射塞下曲》六首之一，写将军登台发令、千营齐应的军威，是盛唐气象在中唐边塞诗中的回响。","n":["张仆射：张延赏（一说张建封），仆射为官名。射音yè","鹫翎：雕翎，制箭羽的材料。鹫音jiù","金仆姑：良箭名","燕尾：旗上燕尾形飘带","蝥弧：春秋诸侯的旗名，此指军旗。蝥音máo","扬新令：发布新将令"],"m":"独立扬新令，千营共一呼。","r":"四句按「箭—旗—发令—齐呼」背；易错读：仆射yè、鹫jiù、蝥máo。"},"晚次鄂州|卢纶":{"s":"颔联是写江行的名句：商人昼眠、舟人夜语，皆从听觉与推想落笔，于细微处见江上行船的生活气息；颈联由景入情，衰鬓逢秋色、归心对明月，乡思浩茫；尾联追及战乱根源，旧业已尽而鼓鼙又闻，把个人漂泊与时代丧乱拧在一起，沉郁苍凉。","b":"安史之乱中卢纶南逃避乱，途经鄂州泊舟所作，写战乱中归心似箭又前路茫茫的愁绪。","n":["晚次鄂州：傍晚停船于鄂州（今武昌）。次，停宿","估客：商人。估同「贾」","舟人：船家","三湘：湘江流域统称","旧业：家乡产业","更堪：哪堪、怎能再受","鼓鼙：军中战鼓，代指战乱。鼙音pí"],"m":"估客昼眠知浪静，舟人夜语觉潮生。","r":"七律按「远见汉阳—江行见闻—逢秋思归—战乱之叹」背；「估」同贾、「鼙」读pí。"},"贼平后送人北归|司空曙":{"s":"首联以「同南去」与「独北还」对举，一别一留之间见出战乱离散；颔联是名句——他乡熬白了头发，故乡却只有青山依旧，人事之老与山河之常对举，悲慨深沉；后两联设想友人一路晓月残垒、寒禽衰草相伴，处处是战后荒凉，处处是送者愁心。","b":"安史之乱平定后，司空曙送友人北归故乡，自己却仍滞留南方，诗中既有劫后余生之慨，也有自伤留滞之情。","n":["贼平：安史之乱平定","时清：时局清平","旧国：故乡","残垒：残破的营垒","故关：旧关隘","愁颜：带愁的面容"],"m":"他乡生白发，旧国见青山。","r":"按「乱时同去—清时独还—途中所见—愁颜作结」背；「残垒/故关」是战后荒凉的标志意象。"},"云阳馆与韩绅宿别|司空曙":{"s":"首联写江海一别、山川久隔；颔联是千古传诵的写重逢名句——乱世久别，忽然相见反疑是梦，悲从中来又互问年岁，「疑梦」「问年」把惊喜、苍老、辛酸和盘托出；颈联孤灯寒雨、湿竹浮烟渲染凄凉，尾联「明朝恨」使今宵之聚更显珍贵。","b":"司空曙在云阳驿馆与老友韩绅久别重逢、翌日又别，诗写乱世中骤逢乍别的悲喜交集。","n":["云阳馆：云阳县的驿馆","宿别：同宿一夜又分别","几度：多少年","乍见：忽然相见","翻疑梦：反而怀疑是在梦里","问年：询问年岁","湿竹暗浮烟：湿润的竹林间浮动着如烟夜雾","离杯：饯别的酒杯","惜共传：珍惜地互相传递"],"m":"乍见翻疑梦，相悲各问年。","r":"按「久别—重逢疑梦—孤灯夜景—明朝又别」背；「翻」释为反而。"},"江村即事|司空曙":{"s":"全诗以「不系船」立骨：钓罢、月落、人眠，本应系船而偏不系；后两句自答其故——纵使一夜风吹，船也不过漂在芦花浅水之边，何碍之有？于理是写江村水缓风平，于情是写人心无挂碍，疏懒闲远之趣跃然。","b":"司空曙这首小诗写渔者（或隐者）夜钓归来、任船自漂的洒脱，表现江村生活的闲适与安宁。","n":["江村即事：就江村眼前之事赋诗","不系船：不把船拴在岸上。系，拴，音jì","正堪眠：正适合睡觉","纵然：即使","芦花浅水边：长满芦花的浅水边"],"m":"钓罢归来不系船，江村月落正堪眠。","r":"七绝按「不系船—堪眠—风吹去—芦花边」的设问自答背；「系」读jì。"},"喜外弟卢纶见宿|司空曙":{"s":"首联写静夜荒居、四邻无邻的清贫；颔联是名句——雨中飘零的黄叶树、灯下相对的白头人，树之将枯与人之将老互为比喻，兴象悲凉而对仗精工；后四句写沉沦之久、愧见亲情频顾，又以「蔡家亲」点明姑表之谊，悲中有温。","b":"司空曙家境清贫、仕途失意，表弟卢纶来访留宿，诗写荒居贫居中得亲人慰藉的悲喜。","n":["外弟：表弟，卢纶是司空曙的表弟","见宿：来访并留宿。见，表动作指向自己","旧业：祖上产业","以我独沈久：因为我长久沉沦下僚。沈同「沉」","分：情谊、缘分。音fèn","蔡家亲：用羊祜为蔡邕外孙典故，指表亲关系"],"m":"雨中黄叶树，灯下白头人。","r":"按「荒居—黄叶白头—沉沦愧见—表亲情分」背；「分」读fèn、「沈」同沉。"},"题龙阳县青草湖|唐温如":{"s":"前两句以秋风「吹老」洞庭波、一夜愁白湘君头，奇想惊人，把无形秋意写成催人老去之物；后两句更入化境——醉后忘却是天空倒映水中，只觉一船清梦沉甸甸地压在璀璨星河之上，亦真亦幻，缥缈如仙。","b":"唐温如生平无考，仅存此诗（一说为晚唐诗）。写秋夜洞庭醉后所见的奇幻景象，是唐诗中极具浪漫色彩的名篇。","n":["龙阳县青草湖：在今湖南洞庭湖畔","湘君：湘水女神","天在水：天空倒映水中","清梦压星河：清梦仿佛压在银河之上。星河，银河"],"m":"醉后不知天在水，满船清梦压星河。","r":"四句抓「吹老—白发—天在水—梦压星河」的奇想链；「压」字是炼字典范。"},"宿业师山房期丁大不至|孟浩然":{"s":"全诗以时间推移写山中向晚：夕阳度岭、众壑渐暝是暮色初临，松间月上、风泉满听是夜色全至，视觉与听觉交错，凉意可触；樵人归尽、烟鸟栖定以人鸟各归反衬候人不至，末以孤琴候径作结，静候之中自有雅人深致。","b":"孟浩然夜宿业师山房、等候友人丁大不至而作，写山中薄暮清幽之景与候人不至的悠然。","n":["业师：一位法名含「业」字的禅师","山房：山中僧房","期丁大不至：约丁大来宿却未到。期，约定","群壑倏已暝：山谷忽然暗下来。倏，忽然；暝，昏暗","满清听：满耳都是清越声响","烟鸟：暮烟中的归鸟","之子：这个人，指丁大","萝迳：藤萝掩映的小路。迳同「径」"],"m":"松月生夜凉，风泉满清听。","r":"按「夕阳—松月风泉—樵人归鸟—孤琴候人」背；「倏」读shū、「暝」读míng。"},"宿桐庐江寄广陵旧游|孟浩然":{"s":"首联以山暝猿愁、沧江夜流奠定凄清基调；颔联名句以风声叶鸣、月照孤舟写尽江上独宿的孤清——「两岸」之阔对「一舟」之孤，叶声可闻、月色可见，羁愁弥漫；后四句由建德异乡转到维扬旧游，泪寄海西，情深一往。","b":"孟浩然漫游吴越、夜泊桐庐江时作，写江上旅愁并寄怀扬州旧友。","n":["桐庐江：即桐江，在今浙江","广陵旧游：扬州的旧友。广陵，今扬州","山暝：山色昏暗","建德：今浙江建德一带","非吾土：不是我的故乡（用王粲「虽信美而非吾土」意）","维扬：扬州别称","海西头：扬州地处东海西头"],"m":"风鸣两岸叶，月照一孤舟。","r":"按「山暝江流—风叶月舟—异乡忆旧—遥寄两行泪」背；「维扬」即扬州。"},"与诸子登岘山|孟浩然":{"s":"开篇「人事有代谢，往来成古今」如格言破空而来，道出宇宙人生的普遍规律，笼罩全篇；中间写登临所见水落泽深的寒旷之景；尾联落到羊公碑——羊祜有德于民、碑传后世，对比自己功名未立，读碑泪下，吊古正所以自伤，平淡中见深慨。","b":"孟浩然隐居襄阳时与友人登岘山，凭吊西晋名将羊祜，抒发人事代谢、怀古伤今之感。","n":["岘山：在今湖北襄阳，西晋羊祜曾登此山。岘音xiàn","代谢：更替、兴衰交替","胜迹：名胜古迹，此指羊公碑等","鱼梁：渔梁洲，汉江中沙洲","梦泽：云梦泽，古大泽","羊公碑：百姓为纪念羊祜所立的碑，人见其碑莫不流泪，又名「堕泪碑」"],"m":"人事有代谢，往来成古今。羊公碑字在，读罢泪沾襟。","r":"按「代谢之理—登临—水落天寒—读碑下泪」背；「岘」读xiàn；羊祜堕泪碑典故必知。"},"晚泊浔阳望庐山|孟浩然":{"s":"诗以「几千里名山都未逢」作铺垫，欲扬先抑；「始见香炉峰」一「始」字，写出千里逢山的惊喜；后半由山及人，因读慧远之传而永怀尘外之踪，末以「日暮但闻钟」收束——望而不见、唯闻钟声，空灵淡远，余韵不尽。","b":"孟浩然泊舟浔阳、遥望庐山，因怀想东晋高僧慧远而作，写名山始见的欣喜与向慕隐逸的情怀。","n":["晚泊浔阳：傍晚停船浔阳（今九江）","挂席：扬帆。席，船帆","郭：外城","香炉峰：庐山名峰","远公：东晋高僧慧远，曾在庐山建东林寺","尘外踪：超尘出世的踪迹","东林精舍：东林寺。精舍，僧道居所","但闻钟：只听见钟声"],"m":"泊舟浔阳郭，始见香炉峰。","r":"按「千里未逢名山—泊舟始见香炉—怀想慧远—闻钟寄意」背；「精舍」此指佛寺。"},"岁暮归南山|孟浩然":{"s":"首联「休上书」「归敝庐」看似自决，实含怨愤；颔联是全诗焦点——以「不才」「多病」自抑，以「明主弃」「故人疏」暗写见弃之怨，似哀实愤；后两联白发催年、青阳逼岁、永怀不寐、松月窗虚，把失意老至的孤苦写得清冷入骨。","b":"相传孟浩然在王维处偶遇唐玄宗，奉命诵诗，诵及「不才明主弃」，玄宗不悦，孟由此归山。此诗写求仕无门、岁暮归隐的怅惘。","n":["岁暮归南山：年终归隐终南山（一题《归故园作》）","北阙：宫殿北面的门楼，代指朝廷。阙音què","休上书：不要再上书求仕","敝庐：破旧的家园","不才：不成材，自谦（实为怨语）","青阳逼岁除：新春催着旧岁过去。青阳，春天；岁除，年终","夜窗虚：月光下窗内空寂。虚，空寂"],"m":"不才明主弃，多病故人疏。","r":"按「休上归庐—见弃见疏—白发岁除—愁寐窗虚」背；「阙」读què、「除」释为逝去。"},"送朱大入秦|孟浩然":{"s":"前两句写友人将游武陵、腰间宝剑价值千金，为后两句蓄势；临别解剑相赠，赠的不只是千金之剑，更是平生相知的一片肝胆。语言质朴而豪气干云，颇有「宝剑赠烈士」的古侠遗风。","b":"孟浩然送别友人朱大入秦，以解剑相赠写任侠重义的豪情，是盛唐赠别诗中的短章精品。","n":["朱大：一位朱姓友人，排行老大","入秦：到长安一带（秦地）去","游人：游子，指朱大","直千金：价值千金。直同「值」","脱：解下（相赠）"],"m":"分手脱相赠，平生一片心。","r":"四句按「游人远游—宝剑千金—解剑相赠—一片真心」背；「直」同「值」。"},"宿建德江|孟浩然":{"s":"首句点题泊舟，次句「客愁新」直启愁绪；后两句是千古名句：因野旷而觉天低于树、因江清而觉月近于人，一「低」一「近」体察入微——旷野苍茫反添孤愁，唯有水中明月可亲可近，以景写情，淡而有味，清绝千古。","b":"孟浩然漫游浙东、夜泊建德江所作，是写羁旅夜愁的五绝典范。","n":["建德江：新安江流经建德的一段","移舟：移动小船靠岸","烟渚：烟雾笼罩的小洲。渚，水中小块陆地","客愁新：旅愁新添","野旷天低树：原野空旷，远处天空仿佛低于树木","江清月近人：江水清澈，水中月影仿佛近在身边"],"m":"野旷天低树，江清月近人。","r":"四句按「泊舟—新愁—野旷天低—江清月近」背；「渚」读zhǔ；后两句的因果关系要讲清。"},"渡浙江问舟中人|孟浩然":{"s":"首句「潮落江平未有风」写尽渡江的平稳惬意，次句「扁舟共济」点出同舟之缘；后两句写频频引颈遥望天边、辨认何处青山是目的地越中，期待之情如在目前，语言浅白而风神散朗。","b":"孟浩然渡钱塘江时作，写与同舟人共渡、遥望越中的情景，于行旅中见从容兴致。","n":["浙江：钱塘江","扁舟共济：乘小船一同渡江。扁音piān","引领：伸长脖子远望","天末：天边","越中：今浙江绍兴一带，古越国地"],"m":"时时引领望天末，何处青山是越中。","r":"四句按「潮平风静—同舟共济—引颈望天—青山辨越」背；「扁」读piān、「引领」即伸长脖子望。"},"杂曲歌辞·游子吟|孟郊":{"s":"前四句白描慈母缝衣：手中线、身上衣，临行密密缝、意恐迟迟归，细节越细，母爱越深；后两句翻进一层作比——子女如寸草、母爱如三春阳晖，小草怎能报答春光于万一？以常景喻至情，朴素真挚，成为母爱的千古绝唱。","b":"孟郊任溧阳县尉时迎养母亲而作，以缝衣细节歌颂深挚母爱，是千古传诵的母爱诗，白居易曾评「诗到孟东野，天地为之清」。","n":["游子：远游在外的人","临：将要","意恐：担心","寸草心：小草般微薄的心意，喻子女之心","三春晖：春天三个月的阳光，喻母爱深厚。晖，阳光"],"m":"谁言寸草心，报得三春晖。","r":"六句按「线衣—缝/归—寸草/春晖」背；「三春」指孟仲季三春；末两句比喻关系是核心。"},"古怨别|孟郊":{"s":"诗以秋风飒飒起兴，渲染悲凉；「欲语气先咽」捕捉临别瞬间——千言万语堵在喉头，情态真切；「心曲千万端，悲来却难说」道尽情到深时反无言的共感；末句以天涯共月自慰，悲而不伤，留下温厚的余味。","b":"孟郊这首古体写情人（或友人）秋风中黯然话别的情景，刻画临别无言、悲从中来的复杂心理。","n":["飒飒：风声","相向：相对","气先咽：话未出口先已哽咽。咽，哽咽，音yè","心曲：内心深处、心事","天涯共明月：远隔天涯共此一轮明月（后为张九龄「海上生明月」、苏轼「千里共婵娟」同调）"],"m":"含情两相向，欲语气先咽。别后唯所思，天涯共明月。","r":"按「秋风—相向哽咽—心曲难说—天涯共月」背；「咽」读yè。"},"武威送刘判官赴碛西行军|岑参":{"s":"首句以五月火山、行人稀少反衬使者「马去疾如鸟」的迅疾豪壮；后两句更奇——行营远在太白星西，一声号角吹开胡天晓色，既写军营地之辽远，又暗喻唐军一令而边地重光，气象雄阔，盛唐边塞的豪迈跃然纸上。","b":"岑参在武威送同僚刘判官赴安西军前所作，以雄奇想象写边地行军的壮阔与唐军声威。","n":["武威：今甘肃武威","刘判官：一位刘姓节度判官","碛西：沙漠以西，指安西都护府。碛音qì","火山：即火焰山，在今新疆吐鲁番，极言炎热","都护行营：都护的临时军营。太白西，太白星以西，极言其远","角：画角，军中号角","胡天晓：边地天色破晓"],"m":"都护行营太白西，角声一动胡天晓。","r":"四句按「火山行少—马去如鸟—行营辽远—角声破晓」背；「碛」读qì、「太白」是金星。"},"山房春事二首·一|岑参":{"s":"前两句总写风恬日暖、蝶蜂乱入，春光烂漫到「乱入房」；后两句特写：门柳垂枝低拂衣架、山花落瓣飘满笔床，以柳低、花落写山居与自然相融的闲趣，动静相宜，明丽如画。","b":"岑参《山房春事》二首之一，写春日山房明媚热闹、生机盎然的景象，于边塞雄浑之外另见清新一面。","n":["山房春事：山居春日所见。此为组诗其一","风恬日暖：风和日丽。恬，安适","衣桁：晾衣架。桁音hàng","笔床：卧放毛笔的器具"],"m":"数枝门柳低衣桁，一片山花落笔床。","r":"四句按「风暖春光—蝶蜂入房—门柳低桁—山花落床」背；「桁」读hàng。"},"碛中作|岑参":{"s":"首句「走马西来欲到天」以夸张写大漠与天相接的苍茫；次句以月两回圆计时，见出辞家之久而不言愁，愁在其中；后两句一问一答，今夜宿处不知、唯见万里平沙杳无人烟，视野愈阔、孤寂愈深，苍凉雄浑。","b":"岑参出塞途中行经大漠所作，写沙漠行军的辽阔荒远与辞家思乡之情。","n":["碛中：沙漠之中。碛，沙漠，音qì","欲到天：仿佛要走到天尽头，极言大漠辽阔","见月两回圆：两次见月圆，言离家已两月","平沙：平坦无边的沙漠","绝人烟：没有人烟"],"m":"今夜不知何处宿，平沙万里绝人烟。","r":"四句按「西来欲到天—见月两圆—何处宿—平沙无人」背；「碛」读qì。"},"赵将军歌|岑参":{"s":"前两句以「风似刀」「缩寒毛」极写九月天山奇寒，环境越酷烈，越反衬后两句将军的豪兴——博戏场场皆胜，连单于的貂袍都赢了来，苦寒之地反成英雄用武之场，豪迈乐观，妙趣横生。","b":"岑参这首七绝写边塞将军冬日围猎博戏、豪气纵横的生活，是盛唐边将精神风貌的生动剪影。","n":["赵将军：一位赵姓边将","天山：在今新疆境内","缩寒毛：马因寒冷而鬃毛缩起","纵博：纵情博戏（军中赌赛游戏）","单于：匈奴君主称号，此指少数民族首领。音chányú","貂鼠袍：貂皮袍子，贵重御寒衣物"],"m":"将军纵博场场胜，赌得单于貂鼠袍。","r":"四句按「风刀寒马—将军纵博—场场胜—赢得貂袍」背；「单于」读chányú。"},"春梦|岑参":{"s":"前两句交代春风入房、故人远隔湘江，现实空间被江水阻隔；后两句转入梦境——枕上片刻春梦，竟走遍江南数千里，以梦境时间之短与空间之长对举，把刻骨相思托于迷离春梦，含蓄而奇警。","b":"岑参这首春梦诗写春夜怀人、梦中片时而行尽江南数千里，极写思念之深与梦境之快。","n":["洞房：幽深的居室（非新婚洞房）","故人：老友（或所思之人）","片时：片刻","行尽：走遍"],"m":"枕上片时春梦中，行尽江南数千里。","r":"四句按「春风入房—故人远隔—片时春梦—梦行千里」背；注意「洞房」古义是深室。"},"巴山道中除夜书怀|崔涂":{"s":"首联迢递三巴、羁危万里，写尽空间之远与身世之危；颔联名句以乱山、残雪、孤烛、异乡四词密集叠加，除夕本当团圆，诗人却独对孤烛迎「异乡春」，凄清入骨；颈联「渐与骨肉远，转于僮仆亲」道尽旅人微妙心理，真实动人；尾联以明日岁新反衬今夜漂泊，感慨弥深。","b":"崔涂，晚唐诗人，久在巴蜀漂泊。此诗作于巴山道中除夕，写乱山残雪之夜、异乡孤烛逢年的凄苦。","n":["除夜：除夕之夜","迢遰：路途遥远。音tiáodì，同「迢递」","三巴：巴郡、巴东、巴西，今四川东部一带","羇危：漂泊在艰险之地。羇同「羁」","孤烛：一支孤烛","转于僮仆亲：反而与僮仆更亲近（写旅途孤苦）","岁华新：新的一年、岁月更新"],"m":"乱山残雪夜，孤烛异乡春。","r":"按「路远身危—残雪孤烛—骨肉远僮仆亲—漂泊逢新岁」背；「遰」同递、「羇」同羁。"},"宿王昌龄隐居|常建":{"s":"首联以清溪、孤云写隐者之高；颔联最妙——松梢微月初露、清辉洒落，仿佛仍为旧主人（王昌龄）而照，物犹有情，人何以堪；颈联茅亭花影、药院苔纹写居处幽寂；尾联直抒「余亦谢时去」的归隐之志，景清而志洁。","b":"常建游王昌龄旧日隐居处所作，既写隐居环境的清幽，也表达自己辞官归隐、与鸾鹤为群的志向。","n":["王昌龄隐居：王昌龄早年隐居之处","隐处：隐居的地方","宿花影：花影仿佛静宿于茅亭","药院：种药的庭院","滋苔纹：长出青苔纹路","谢时：辞去世俗（出尘归隐）","鸾鹤群：与鸾鹤为群，指归隐山林"],"m":"松际露微月，清光犹为君。","r":"按「清溪孤云—松月清光—茅亭药院—谢时归山」背；「为君」的君指旧隐者王昌龄。"},"题破山寺后禅院|常建":{"s":"全诗沿游踪展开：入寺、见日、穿竹径、到禅院，渐入幽深；颈联是禅意名句——山光使鸟性怡悦、潭影使人心空，物我两忘；尾联以万籁俱寂、唯余钟磬作结，以声写静，袅袅钟磬把禅院的幽静与诗人的禅心融为一体，意境浑成。","b":"常建此诗题写于破山寺后禅院，是盛唐山水诗中融禅理于景物的千古名篇，宋代大书法家米芾曾书之。","n":["破山寺：今江苏常熟虞山兴福寺","后禅院：僧人修行的后院","初日：初升的太阳","竹迳：竹林小路。迳同「径」","禅房：僧房","悦鸟性：使鸟儿性情欢悦","空人心：使人心境空明、涤除尘念","万籁：自然界一切声响。籁，孔穴发出的声音","钟磬：寺院诵经、斋饭时敲打的乐器。磬音qìng"],"m":"竹迳通幽处，禅房花木深。山光悦鸟性，潭影空人心。万籁此都寂，但余钟磬音。","r":"按游踪背：入寺初日—竹径禅房—山光潭影—万籁钟磬；「空人心」的空是使动用法；「籁」读lài。"},"塞下曲四首·一|常建":{"s":"诗不写征战之苦、也不写武功之盛，而写「朝回」之后的宁静：乌孙归心、不再称王，天涯静处再无征战，战争戾气消融于日月清辉。想象瑰伟、立意高远，表达了各族和睦、天下太平的美好愿望。","b":"常建《塞下曲》四首之一，借汉代乌孙和亲的史事，歌颂化干戈为玉帛、边塞安宁的太平理想，在边塞诗中别具一格。","n":["塞下曲：此写和亲之后边塞安宁","玉帛：朝聘的礼物，此指乌孙与汉通好","帝乡：京城长安，代指汉朝","乌孙：汉代西域国名，曾与汉和亲","不称王：不再与汉分庭抗礼","兵气销为日月光：战争之气化为日月清辉，言天下太平"],"m":"天涯静处无征战，兵气销为日月光。","r":"四句按「朝回望乡—乌孙归服—天涯无战—兵气化光」背；「玉帛」与「干戈」相对，是和平的象征。"},"书边事|张乔":{"s":"首联以角声、戍楼勾出边塞轮廓；颔联写昭君青冢沐于春风、梁州边城落日安详，以「春风」「白日」暖色调暗示边地和平的可贵；颈联「大汉无兵阻，穷边有客游」——道路因无战事而畅通，游客可至，正反衬战时之苦；尾联以蕃情如水愿向南流作喻，寄托民族团结之愿。","b":"张乔，晚唐诗人。此诗写晚唐一度边和时的边塞景象，表达盼望民族和睦、边地长治的愿望。","n":["书边事：记述边地之事","调角：吹角。调，吹奏。角，画角","断清秋：角声划破清秋","戍楼：边防城楼","青冢：王昭君墓，在今呼和浩特，相传草色常青","梁州：此指西北边地","穷边：极远的边塞","蕃情：吐蕃等少数民族的心意","向南流：心向中原（如江水南流般归顺）"],"m":"春风对青冢，白日落梁州。","r":"按「角声戍楼—青冢梁州—无兵有客—蕃情南流」背；「冢」读zhǒng、「蕃」读fān。"},"赋得自君之出矣|张九龄":{"s":"前两句写丈夫离家后织机不复整理，以机残写心乱、以动作停摆写相思刻骨；后两句是神来之笔——思君之貌本如十五满月，却因夜夜相思而如月亮般一天天减却清辉，比喻新颖贴切，把抽象的憔悴化为可见的月相，含蓄温婉。","b":"张九龄沿用汉乐府旧题所作闺怨诗，以织机荒废、月渐亏缺写思妇念远之情。","n":["赋得：按乐府旧题或限定题作诗的标志","自君之出矣：乐府《杂曲歌辞》旧题，「出矣」即出门离家","残机：残破的织机，因无心织布而搁置","满月：圆月","减清辉：月光一夜夜亏减，喻容颜因相思而憔悴"],"m":"思君如满月，夜夜减清辉。","r":"四句按「君出—机残—思如满月—夜夜减辉」背；「矣」读yǐ；月相变化喻容颜憔悴是核心。"},"宫词二首·一|张祜":{"s":"全诗仅二十字却嵌进四个数字：三千里写空间之远、二十年写时间之长，空间与时间的双重囚禁压顶而来；后两句一声悲歌、双泪齐落，以「一」与「双」对举，二十年的委屈在一声哀歌中决堤。对仗天成，凝练沉痛。","b":"张祜这首宫词写一位远离家乡、幽闭深宫二十年的宫女，以一曲《何满子》倾泻积怨，是宫怨诗的绝唱，相传曾为宫人广泛传唱。","n":["宫词：写宫中生活的诗","故国：故乡","河满子：唐教坊曲名，相传沧州歌者何满子临刑所唱，声调哀婉，一作「何满子」","君：皇帝"],"m":"故国三千里，深宫二十年。一声河满子，双泪落君前。","r":"四句抓四个数字（三千/二十/一/双）背；「河满子」是哀婉曲名。"},"集灵台二首·一|张祜":{"s":"前两句以日光斜照、红树迎露铺写集灵台晨景，看似庄重明丽；后两句以「新授箓」「含笑入帘」轻轻一点——杨氏本为寿王妃，借出家为女道士（号太真）的名义入宫，「含笑」二字含蓄而讽刺入骨，体现宫词「婉而多讽」的特色。","b":"张祜《集灵台》二首之一，表面写上皇授箓、太真入帘，实则微讽唐玄宗纳儿媳杨玉环为妃的宫闱旧事。","n":["集灵台：在骊山华清宫，为祭祀神灵之台","上皇：指唐玄宗（安史之乱后退位为太上皇）","授箓：道教传授符箓的仪式。箓，道教秘文，音lù","太真：杨贵妃为女道士时号太真","入帘来：进入帘内，暗讽其以道箓为名入宫"],"m":"昨夜上皇新授箓，太真含笑入帘来。","r":"四句按「灵台晓景—花迎晓露—上皇授箓—太真入帘」背；「箓」读lù；讽谕之意要结合杨玉环来历理解。"},"题金陵渡|张祜":{"s":"首句点出地点与「行人自可愁」的旅愁；后两句是写江夜的名句：潮落、夜江、斜月，清冷的大背景上，对岸瓜洲只有两三点如星灯火，以星火之「小」反衬江夜之「阔」，以明灭灯火反衬旅人之孤，宁静优美而愁思悠然。","b":"张祜旅途夜宿镇江金陵渡小楼，因羁愁难眠而作，写江上夜色与旅人孤寂。","n":["金陵渡：在今江苏镇江（唐时亦称金陵渡，非南京）","津渡：渡口","小山楼：渡口小楼","行人：旅人，诗人自指","自可愁：自然要生愁","斜月：西斜的夜月","星火：灯火如星","瓜州：瓜洲，长江北岸渡口，与镇江隔江相望"],"m":"潮落夜江斜月里，两三星火是瓜州。","r":"四句按「津渡小楼—行人夜愁—潮落斜月—星火瓜洲」背；此金陵渡在镇江。"},"成都曲|张籍":{"s":"前两句写锦江烟水碧绿、雨后山头荔枝红熟，绿与红相映，色彩明丽，已见蜀中物产丰美；后两句写万里桥边酒家林立、游人竟不知宿于何家，以问句收束，写尽成都的繁华好客与游人的惬意，轻快活泼。","b":"张籍此诗写成都锦江一带雨后清新明丽的风光与市井繁华，是一幅成都风土小画。","n":["锦江：在成都，传说濯锦其中则锦色鲜艳","烟水：烟霭笼罩的江面","万里桥：在成都南，三国费祎使吴，诸葛亮饯行于此，曰「万里之行始于此」","向：在、到"],"m":"万里桥边多酒家，游人爱向谁家宿。","r":"四句按「锦江烟绿—雨后荔红—桥边酒家—游人择宿」背；万里桥的得名可作注释补充。"},"没蕃故人|张籍":{"s":"首联交代前年全军覆没之惨；颔联「死生长别离」五字沉痛；颈联是名句，以废帐无人收、归马识残旗的战场细节侧面写全军覆灭，马犹识旗、人已无存，触目惊心；尾联「欲祭疑君在」捕捉最微妙的心理——存一线侥幸便不忍设祭，终于绝望，唯有天涯一哭，深挚入骨。","b":"张籍此诗悼念一位在唐蕃战争中全军覆没、生死不明的老友，写尽战争残酷与故人至情。","n":["没蕃故人：与吐蕃作战中阵亡的老友。没，死；蕃音bō","伐月支：攻打月支（此借指吐蕃）。月支音yuèzhī","没全师：全军覆没","蕃汉：吐蕃与唐朝","废帐：废弃的军帐","归马识残旗：逃归的战马还认得残破军旗","欲祭疑君在：想祭奠又疑心你还活着"],"m":"无人收废帐，归马识残旗。欲祭疑君在，天涯哭此时。","r":"五律按「战事—消息断绝—战场残景—疑在终哭」背；「没」读mò、「蕃」读bō、「月支」读yuèzhī。"},"秋思|张籍":{"s":"诗以「见秋风」起——秋风无形而可「见」，一个见字写出游子敏感；后三句全在一个「又开封」的细节上发力：信已写好、行人将发，又匆匆拆开补写，生怕遗漏半分，把抽象的「意万重」化为可触可见的动作，于细微处见深情。（「忽恐」通行本多作「复恐」，本文从库内原文。）","b":"张籍客居洛阳，见秋风起而作家书，本诗捕捉寄信前「又开封」的细节，成为写乡思的千古名篇。","n":["秋思：秋日思乡之情","归书：家信。意万重，要说的话千头万绪。重音chóng","行人：捎信的人","临发：将要出发","开封：打开已封好的信"],"m":"忽恐匆匆说不尽，行人临发又开封。","r":"四句按「见秋风—作归书—恐说不尽—临发开封」背；「重」读chóng、「开封」是拆开信封。"},"相和歌辞·春江花月夜|张若虚":{"s":"全诗以月为轴心，按「月升—月悬—月斜—月落」组织：先写春江花月的澄澈宇宙，继而生发出「何人初见月、何年初照人」的千古天问，在永恒江月与代代人生的对照中获得豁达；后半转入人间离愁，扁舟游子、明月楼思妇两两相望，最后以落月摇情收束。景、情、理水乳交融，音韵婉转，洗净六朝宫体铅华。","b":"张若虚传世仅存诗两首，此为其一，沿乐府旧题写春江月夜之景与游子思妇之情，被闻一多誉为「诗中的诗，顶峰上的顶峰」。","n":["滟滟：水波闪光貌。音yàn","宛转遶芳甸：江流曲折绕过花草遍生的郊野。遶同「绕」；甸，郊野","霰：细密雪珠，此喻月光下花林洁白。音xiàn","空里流霜：空中月色如飞霜而不觉其飞","汀：沙滩","纤尘：微尘","穷已：穷尽","但见：只见","青枫浦：地名，亦泛指游子所在。浦，水边","扁舟子：乘小舟漂泊的游子。扁音piān","明月楼：思妇的妆楼","裴回：同「徘徊」，月光流连不去","玉户：华美的门户，指闺中","𢭏衣砧：捶捣衣裳的砧石。𢭏同「捣」；砧音zhēn","逐月华：追随月光","鸿雁长飞光不度：鸿雁善飞也飞不出月光（度不去此情）","水成文：水面荡起波纹。文同「纹」","闲潭：幽静的水潭","碣石潇湘：北有碣石、南有潇湘，泛指天南海北","乘月：趁着月色","落月摇情满江树：落月的余晖摇动情思、洒满江边树林"],"m":"春江潮水连海平，海上明月共潮生。江畔何人初见月？江月何年初照人？人生代代无穷已，江月年年望相似。不知乘月几人归，落月摇情满江树。","r":"长诗分四层背：月下江景（起至孤月轮）—天问人生（江畔何人至送流水）—人间相思（白云至水成文）—梦归月落（昨夜至结尾）；韵脚九换，随韵脚分层；通假：遶（绕）、裴（徘）、文（纹）。"},"早梅|张谓":{"s":"首句以「白玉条」喻寒梅满枝之洁白；次句点出早梅独临溪桥的环境；后两句是点睛之笔：远望不知是近水之梅先发，还疑心是去冬残雪未消，以「疑雪」写梅之早、之白，又暗合「近水楼台先得月」的物候之理，构思灵巧。","b":"张谓这首早梅诗写水边寒梅先发、远望疑雪的惊喜，是咏梅名篇。","n":["白玉条：梅花枝条洁白如玉条","迥临：远远地靠近。迥，远","傍谿桥：依傍溪桥。谿同「溪」","近水花先发：临近溪水的梅花因水暖而先开","经春雪未销：过了一冬（一作经冬）的雪还没融化"],"m":"不知近水花先发，疑是经春雪未销。","r":"四句按「梅如玉条—临村傍桥—近水先发—疑雪未销」背；「迥」读jiǒng、「销」同消。"},"除夜宿石头驿|戴叔伦":{"s":"首联以旅馆无人相问、唯寒灯可亲写尽孤况；颔联是千古名联——「一年将尽夜」对「万里未归人」，时间之末与空间之远十字相激，除夕本当团圆而己独为客，凄怆逼人；后两联追怀前事、自笑支离，愁颜衰鬓又逢新春，以「又」字写出年年漂泊的无奈。","b":"戴叔伦除夕之夜羁旅石头驿，寒灯独对、一年将尽而万里未归，写尽岁暮旅愁。","n":["除夜：除夕","石头驿：在今江西南昌的驿站。驿，驿馆","相问：相慰问","支离：流离多病","衰鬓：衰老的鬓发"],"m":"一年将尽夜，万里未归人。","r":"按「寒灯独亲—将夜未归—寥落支离—愁颜逢春」背；「驿」读yì。"},"兰溪棹歌|戴叔伦":{"s":"前两句写静景：眉月挂湾、越山如镜，清凉澄澈；后两句化静为动——连下三日桃花春雨、溪水新涨，半夜鲤鱼泼剌跃上浅滩，生机盎然。以民歌笔调、明快画面写出江南春夜的灵动，凉月之静与鲤鱼之动相映成趣。","b":"戴叔伦这首仿民歌的棹歌写兰溪春夜月下的清新山水与渔家生机，是中唐山水小诗精品。","n":["兰溪：在今浙江兰溪，富春江上游","棹歌：船歌、渔歌。棹，船桨，音zhào","凉月如眉：新月如眉","柳湾：栽柳的水湾","越中：今浙江一带，古越地","镜中看：山色如在镜中","桃花雨：桃花开放时节的春雨","上滩：鲤鱼趁春水新涨跃上浅滩"],"m":"兰溪三日桃花雨，半夜鲤鱼来上滩。","r":"四句按「眉月柳湾—山色如镜—桃花春雨—鲤鱼上滩」背；「棹」读zhào。"},"苏溪亭|戴叔伦":{"s":"首句亭上草漫，已见暮春寥落；「谁倚东风十二阑」以倚阑之人暗逗相思；后两句情景交融——燕子不归暗喻所期之人不至，春事已晚；一汀烟雨、杏花生寒，把暮春的清冷与内心的怅惘打成一片，迷蒙含蓄。","b":"戴叔伦暮春登苏溪亭，借迷蒙烟雨、迟暮杏花写怀人未遇、春光将逝的怅惘。","n":["苏溪亭：在今浙江义乌","草漫漫：春草繁茂无边","十二阑：曲折的栏杆，十二言其多","春事晚：春光将暮","一汀烟雨：整片沙洲笼罩在如烟细雨中。汀，水洲","杏花寒：雨中杏花透出寒意"],"m":"燕子不归春事晚，一汀烟雨杏花寒。","r":"四句按「草漫—倚阑—燕不归春晚—烟雨杏花寒」背；「汀」读tīng、「阑」同栏。"},"霜月|李商隐":{"s":"前两句写实：征雁初闻、寒蝉已绝，百尺高楼上水光接天，交代时令与眺望角度；后两句由实景生发奇想——霜是青女所洒、月为素娥所居，两位冰雪女神都耐得住寒冷，正在月中霜里争妍斗美。把霜月之寒、之美写得有性格、有精神，想象瑰奇。","b":"李商隐这首《霜月》写深秋登楼所见霜月交辉之景，以神话想象写出霜月的高洁之美。","n":["征雁：南飞的大雁","已无蝉：秋深蝉声已绝","水接天：月光水光相接，言楼之高","青女：主管霜雪的女神","素娥：嫦娥，月宫仙女","耐冷：经得起寒冷","鬬婵娟：比斗美好。鬬同「斗」；婵娟，美好貌，此指霜月争辉"],"m":"青女素娥俱耐冷，月中霜里鬬婵娟。","r":"四句按「雁蝉时节—高楼水天—青女素娥—霜月争辉」背；「鬬」是斗的异体。"},"蝉|李商隐":{"s":"咏蝉即自咏：蝉栖高饮露而难饱、费声传恨而徒劳，正是诗人才高而清贫、陈情而无应的写照；「一树碧无情」尤妙——树自青翠，对蝉之悲鸣无动于衷，正是世态凉薄的象征；后半由蝉及己，薄宦漂泊、故园荒芜，末以「举家清」人蝉双收，物我合一。","b":"李商隐一生羁旅幕府、职位卑微，此诗借咏蝉自伤身世，是咏物诗「不即不离」的典范。","n":["高难饱：蝉栖高树、饮清露，故难以饱腹","徒劳恨费声：悲鸣传恨也是白费力气","疏欲断：蝉声稀疏、几近断绝","一树碧无情：树自碧绿、全然不解蝉之悲","薄宦：卑微的官职","梗犹泛：如桃梗木偶般漂泊无定（用《战国策》土偶桃梗典）","芜已平：荒草已长得没路","相警：相提醒","举家清：全家清贫，亦以蝉之清高自况"],"m":"五更疏欲断，一树碧无情。薄宦梗犹泛，故园芜已平。","r":"按「蝉之高饱费声—疏断树无情—己之薄宦故园—以清相警」背；「梗泛」用桃梗典故。"},"忆梅|李商隐":{"s":"首句「定定住天涯」叠词突兀，写尽身不由己的滞留；次句「依依向物华」写对春光的留恋；后两句翻出新意——寒梅最「堪恨」，因它开在岁末，等春回大地、百花争发时它早已开过，成了「去年花」。言梅实自怜：自己如寒梅早秀而不逢其时，含蓄自伤。","b":"李商隐羁旅异乡、春日忆梅而作，以早梅「常作去年花」的特点自比先春而发、生不逢时。","n":["定定：牢牢地、动不了，写滞留之苦","天涯：此指诗人滞留的异乡","依依：深切留恋","物华：美好春光","去年花：寒梅多在腊前冬末开放，到春日已是「去年之花」"],"m":"寒梅最堪恨，常作去年花。","r":"四句按「滞留天涯—留恋物华—寒梅堪恨—去年之花」背；「定定」是传神叠词。"},"风雨|李商隐":{"s":"首联以《宝剑篇》起，慨叹壮志销磨于羁泊穷年；颔联名联以「黄叶风雨」与「青楼管弦」作强烈对比——自己如风雨中飘零的黄叶，豪贵之家却自顾笙歌，一冷一热、一悲一乐，世情如见；后写新遭薄俗、旧好隔绝，唯有以酒销愁，沉郁顿挫。","b":"李商隐中年羁泊异乡、交游零落，面对风雨凄其、他人宴乐，借《宝剑篇》与马周典故抒发怀才不遇之愤。","n":["宝剑篇：唐初郭震所上名篇，喻壮志未酬","羁泊：羁旅漂泊","欲穷年：将这样潦倒一辈子","仍：更、兼","青楼：富贵人家的华楼（非后世妓院义）","管弦：音乐宴乐","薄俗：浅薄的世俗","旧好：旧交","心断新丰酒：想用新丰美酒浇愁也不可得（用马周困居新丰典）。新丰，在长安附近","斗几千：一斗酒值几千钱，言酒美价高"],"m":"黄叶仍风雨，青楼自管弦。","r":"按「宝剑羁泊—黄叶青楼对比—新旧交零落—酒销愁」背；马周新丰典、郭震宝剑篇典需知。"},"寄令狐郎中|李商隐":{"s":"前两句写两地睽违、忽接来书：嵩云秦树各在一方，「双鲤迢迢一纸书」见珍重；后两句以两个典故自况——自己正如梁园旧客、茂陵病中的司马相如，秋雨闭门、潦倒多病。「休问」二字含无限身世之感，用典贴切、语淡情深。","b":"李商隐在洛阳患病，收到长安旧友令狐绹来信问讯，作此诗答谢，感念旧谊并自陈病况。","n":["令狐郎中：令狐绹，时任考功郎中，诗人旧友","嵩云秦树：嵩山云（诗人在洛阳）、秦中树（友在长安），喻两地相望","双鲤：指书信（古乐府「客从远方来，遗我双鲤鱼」）","迢迢：遥远","梁园旧宾客：司马相如、枚乘等曾为梁孝王宾客，此自比曾在令狐家为客","茂陵秋雨病相如：司马相如晚年病居茂陵，此以病相如自况"],"m":"休问梁园旧宾客，茂陵秋雨病相如。","r":"四句按「两地离居—接到来书—梁园旧客—病中相如」背；双鲤代书信、相如自比是关键。"},"落花|李商隐":{"s":"首联客去、花飞并起，人散花谢同其寥落；颔联写落花参差连路、随夕阳远飘，凄迷辽阔；颈联「肠断未忍扫，眼穿仍欲归」，惜花人不忍扫花、盼春留而春仍去，痴情如见；尾联双关收束——花之芳心随春而尽，所得只是落瓣沾衣；人之芳心随望成空，所得只是清泪沾衣，人花同慨。","b":"李商隐这首咏落花诗，借花伤己，在客去花飞的暮春景象中寄寓身世飘零之感。","n":["客竟去：客人终于离去","参差：错落、纷繁，此指落花纷飞。音cēncī","曲陌：曲折的小路","迢遰：遥远，此指落花被余晖送向远方。同「迢递」","斜晖：夕阳","眼穿：望眼欲穿，盼春留","芳心：双关花之心与诗人惜春之心","沾衣：泪落沾衣，亦双关花瓣落衣"],"m":"芳心向春尽，所得是沾衣。","r":"按「客去花飞—纷飞斜晖—忍扫眼穿—芳心沾衣」背；「芳心」「沾衣」的双关是核心。"},"为有|李商隐":{"s":"诗以「云屏无限娇」极写闺中人之娇贵，以「寒尽怕春宵」反挑——春宵本千金，何以言怕？后两句作答：只怨嫁了个佩金龟的高官夫婿，每每辜负香衾、赶去早朝。以华贵写幽怨，以「无端」的娇嗔写尽少年夫妻的离别滋味，构思新颖。","b":"李商隐这首闺怨（一作宫怨）诗写一位嫁与高官的少妇，在丈夫勤于早朝、独守春宵时的娇怨，含蓄微讽。","n":["为有：取首二字为题（李商隐无题诗惯例）","云屏：云母屏风，言闺房华贵","无限娇：无比娇媚","凤城：京城","春宵：春夜","无端：没来由地、不料","金龟婿：佩金龟的高官夫婿（武则天时改佩鱼为佩龟）","辜负香衾：辜负了温暖的衾被。衾，被子","事早朝：为了赶早朝"],"m":"无端嫁得金龟婿，辜负香衾事早朝。","r":"四句按「云屏娇贵—怕此春宵—金龟夫婿—早朝负衾」背；「衾」读qīn；金龟是唐代官员品级佩饰。"},"马嵬二首·一|李商隐":{"s":"前两句写叛军动地而来、红粉顷刻成灰，两个「自」字冷峻——祸到临头，所谓恩宠连爱妃也保不住；后两句以反问作诛心之论：若说真是美色倾覆国家，那玄宗车驾又何至于仓皇逃经马嵬？把亡国之责从「女祸」拉回君王自身，笔锋犀利。","b":"李商隐《马嵬》二首之一，针对唐玄宗与杨贵妃马嵬兵变事作翻案反思，批判君王误国。","n":["马嵬：马嵬坡，安史之乱中杨贵妃赐死处。嵬音wéi","冀马燕犀：河北叛军的精锐兵马（冀、燕皆安禄山据地），犀指犀甲","动地来：铺天盖地杀来","自埋红粉自成灰：玄宗亲手赐死贵妃、杨亦化为尘土","倾国：双关绝色美人和倾覆国家","玉辇：皇帝车驾。辇音niǎn"],"m":"君王若道能倾国，玉辇何由过马嵬。","r":"四句按「叛军压境—红粉成灰—倾国反问—玉辇过嵬」背；「倾国」双关是诗眼；「嵬」读wéi、「辇」读niǎn。"},"瑶池|李商隐":{"s":"前两句写西王母绮窗长开、等待穆王，而《黄竹》哀歌动地，生死之悲已伏；后两句反问冷峻：八骏神速如此，穆王为何终究不能重来赴约？——连最受神仙眷顾、有神骏可乘的穆王都难免一死，求仙长生之妄不言自明，以神话外壳包裹现实讽刺。","b":"李商隐借周穆王会见西王母的神话，讽刺唐代帝王迷信神仙、妄求长生终究虚妄。","n":["瑶池：神话中西王母居所","阿母：西王母又称玄都阿母","绮窗：雕饰华美的窗户","黄竹歌：周穆王曾作《黄竹歌》哀冻死者，「动地哀」言其声哀","八骏：周穆王的八匹神马，日行万里","穆王何事不重来：穆王曾与西王母约三年后复会，终因身死不能重来"],"m":"八骏日行三万里，穆王何事不重来。","r":"四句按「瑶池窗开—黄竹哀歌—八骏神速—穆王不返」背；西王母、周穆王典故是理解前提。"},"板桥晓别|李商隐":{"s":"前两句写回望高城、晓河渐落、长亭窗影压着微波，凄清的晓色中含无限留恋；后两句全用比兴——行人如乘鲤水仙飘然欲去，送者如芙蓉泣露、一夜红泪，「红泪」兼花露与人泪，亦人亦花，绮艳中见深情，典型的李商隐式朦胧美。","b":"李商隐这首小诗写清晨板桥送别，以神话和鲜花喻离别，绮丽而哀婉。","n":["板桥：浮桥、木板桥","高城：指所别者所居之城","落晓河：天渐晓、银河西沉","长亭：送别处","水仙欲上鲤鱼去：用琴高乘鲤成仙典，喻行人将乘舟远去","芙蓉红泪：以荷花带露喻别泪（兼用薛灵芸泣别、泪红如血典）"],"m":"水仙欲上鲤鱼去，一夜芙蓉红泪多。","r":"四句按「回望高城—长亭微波—乘鲤欲去—芙蓉红泪」背；琴高乘鲤、薛灵芸红泪两个典故要知。"},"夕阳楼|李商隐":{"s":"首句「花明柳暗」本是美景，却接「绕天愁」，以乐景写哀、愁弥天地；次句「上尽重城更上楼」写层层登高、层层求索；后两句最妙：本想问孤鸿飞向何处，却蓦然惊觉自己的身世也如孤鸿、悠悠无依——问鸿正是自问，人鸿合一，孤愤旷远。","b":"此诗为李商隐登夕阳楼感怀而作，时恩人萧澣遭贬，诗人亦自伤身世，故望孤鸿而兴叹。","n":["夕阳楼：在荥阳（今郑州），李商隐受知于刺史萧澣时所登，后萧被贬","绕天愁：愁绪弥漫如绕天际","重城：层叠的城","孤鸿：孤雁，自喻身世飘零","悠悠：邈远、无可依托"],"m":"欲问孤鸿向何处，不知身世自悠悠。","r":"四句按「花柳绕愁—登楼—欲问孤鸿—自伤悠悠」背；孤鸿自喻是关键。"},"晚晴|李商隐":{"s":"首联点明深居俯城、夏初清和；颔联是千古名句——天意仿佛怜惜幽僻小草而放晴，人间也格外珍视这傍晚的晴光，「晚晴」既写实景，又喻人生晚年或困顿中短暂的美好，哲理深邃；后写高阁因晴而显高远、小窗因余晖而明亮，越鸟巢干、归飞体轻，明快中见自奋之意。","b":"李商隐任职桂林幕府时，逢久雨晚晴而作，在幽草晚晴、越鸟归飞中寄寓身世之感与短暂慰藉。","n":["夹城：宫城间的复道","春去夏犹清：春已去而夏日清和","幽草：背阴处的小草，自喻卑微","重晚晴：珍视傍晚初晴的天色（亦喻晚年短暂清明）","并添：更添","迥：高远","微注：夕阳微微流注、照入","越鸟：南方的鸟（诗人时在桂林，古越地）","巢干后：雨停巢干","体更轻：归飞之鸟身姿轻快"],"m":"天意怜幽草，人间重晚晴。","r":"按「深居清和—怜草重晴—阁迥窗明—越鸟归轻」背；「晚晴」的象征义是核心；「迥」读jiǒng。"},"天涯|李商隐":{"s":"前两句「春日在天涯，天涯日又斜」以顶真蝉联，春光虽好却身在天涯，天涯之上又是日暮，两层美好（春）与两层难堪（天涯、日斜）叠加，愁绪逼人；后两句奇想：黄莺啼鸣若也有泪，请为我打湿枝头最高的那朵花——最高花最先承受风雨，正是诗人自况，凄艳绝伦。","b":"李商隐春日漂泊天涯，见莺啼花落而作，以春日斜阳、莺啼最高花写迟暮飘零之悲。","n":["天涯：天边，此指异乡","日又斜：夕阳又西沉","如有泪：好像带着眼泪","最高花：枝头最高处的花"],"m":"莺啼如有泪，为湿最高花。","r":"四句抓顶真（天涯—天涯）与拟人（莺啼有泪）背；二十字短章，意境要整体记。"},"贾生|李商隐":{"s":"诗先扬后抑：前两句极写汉文帝「求贤」——宣室召见、逐臣才调无伦，似是千古君臣遇合盛事；后两句陡然一转：如此倾心听问，问的却不是天下苍生而是鬼神之事，「虚前席」的「虚」字一针见血——知遇之态越殷，不任贤才之实越显，托古讽今，警策深刻。","b":"李商隐借汉文帝在宣室夜召贾谊、不问治国只问鬼神的史事，托古讽今，慨叹贤才不被重用、帝王不恤民瘼。","n":["贾生：贾谊，西汉青年政论家，曾被贬长沙","宣室：汉未央宫前殿正室","访逐臣：召见被贬之臣（贾谊）","才调：才气、才情","无伦：无人能比","可怜：可惜","虚前席：汉文帝听得入神，移坐向前（古人席地而坐），「虚」言徒然如此","苍生：百姓","鬼神：鬼神之事（贾谊被问的本是鬼神之本）"],"m":"可怜夜半虚前席，不问苍生问鬼神。","r":"四句按「求贤召贾—才调无伦—夜半前席—不问苍生」背；先扬后抑的结构是关键；「虚」字是诗眼。"},"凉思|李商隐":{"s":"首联客去波平、蝉休露满，秋夜清寂；颔联「永怀」「倚立移时」以伫立之久写思念之深；颈联由近及远——北望长安，春天已远、人更远；滞留南陵，归使迟迟，时空双重寥落；尾联写屡次占梦、甚至疑故人有了新知，把久滞无音者的敏感多疑写得细腻真切。","b":"李商隐奉使滞留南方，秋夜怀人（或怀京洛友人），写客中孤寂与对友情的忐忑。","n":["凉思：秋凉中的思绪","波平槛：槛外水波平息。槛，栏杆","蝉休：秋蝉停鸣","永怀：深长的思绪","移时：过了好一阵","北斗兼春远：北斗所指的北方（长安）连同逝去的春天一样遥远","南陵寓使迟：出使滞留南陵、归期迟迟","占梦数：屡次据梦境占卜归期。数音shuò，屡次","疑误有新知：疑心对方是否有了新交而忘了旧友"],"m":"北斗兼春远，南陵寓使迟。","r":"按「客去秋景—倚立永怀—北斗南陵—占梦疑误」背；「数」读shuò（屡次）。"},"北青萝|李商隐":{"s":"诗按访僧行程写来：残阳入崦、茅屋访僧，落叶满山、人踪何在，寒云叠叠、山路几层；「独敲初夜磬，闲倚一枝藤」以磬声和藤杖勾勒孤僧的闲适；尾联由访僧而悟禅——大千世界不过微尘，一身之爱憎又何足挂怀，在凄清旅思中透出禅悦的旷达。","b":"李商隐秋日傍晚入山寻访孤僧，在清幽禅境中获得「爱憎两忘」的顿悟。","n":["北青萝：地名，在王屋山中，僧人居处","崦：崦嵫山，传说日落处，此指夕阳西下。音yān","初夜磬：入夜时分的磬声","一枝藤：一根藤杖","世界微尘里：佛家言大千世界俱在微尘之中","吾宁爱与憎：我何必再执着于爱憎呢。宁，岂、何"],"m":"世界微尘里，吾宁爱与憎。","r":"按「残阳访僧—寻人不遇—磬声藤杖—微尘悟禅」背；「崦」读yān、「宁」释为岂、难道。"},"鼓吹曲辞·将进酒|李白":{"s":"全诗以两组「君不见」领起：黄河奔海喻时光一去不返、朝暮成雪喻人生短促，悲感至极而以豪语出之；「天生我材必有用」是全诗脊梁，于失意中透出极强自信；钟鼓馔玉不足贵、圣贤寂寞饮者名，是愤激的反语；末以马裘换酒、同销万古愁收束，大起大落，纵横开合，为李白浪漫诗风的巅峰之作。","b":"约天宝十一载（752）李白与友人岑勋、元丹丘嵩山饮宴所作，时诗人被赐金放还已近十年，借酒抒怀，一吐长安失意的万古愁闷。","n":["将进酒：汉乐府旧题，「将」音qiāng，请","天上来：言黄河发源高远、势如从天而落","高堂明镜悲白发：于高堂明镜前悲白发之生","得意：有兴致、得志之时","金尊：华美酒杯。尊同「樽」","会须：应当、正应该","岑夫子、丹丘生：岑勋、元丹丘，李白好友","钟鼓馔玉：鸣钟列鼎而食、饮食精如玉，指富贵生活。馔音zhuàn","陈王：陈思王曹植","平乐：平乐观，曹植《名都篇》「归来宴平乐，美酒斗十千」","恣欢谑：纵情欢乐戏谑。谑音xuè","径须：只管、干脆","酤取：买酒","五花马：名贵的马（鬃毛剪成五瓣花形）","千金裘：价值千金的皮衣","将出：拿出去。将，拿","尔：你"],"m":"君不见黄河之水天上来，奔流到海不复回。天生我材必有用，千金散尽还复来。五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。","r":"长诗按「起兴悲时光—尽欢须饮（天生我材）—劝酒歌（钟鼓不足贵/陈王宴平乐）—主人何言少钱—换酒销愁」五段背；易错读：将qiāng、馔zhuàn、谑xuè、酤gū；通假：尊（樽）。"},"塞下曲六首·一|李白":{"s":"前四句写边地苦寒：五月天山尚雪、无花唯寒，笛中虽闻《折杨柳》而春色终不可见，以「闻折柳」与「未曾看」对写，愈显荒寒；后四句陡然振起——晓战随鼓、宵眠抱鞍，征战之苦只作铺垫，逼出「愿将腰下剑，直为斩楼兰」的誓言，用傅介子典，豪迈刚烈。","b":"李白《塞下曲》六首之一，写边塞五月犹寒、将士昼夜苦战、誓斩敌王的报国豪情。","n":["天山：今新疆天山","祗有：只有。祗同「只」","折柳：笛曲《折杨柳》，本是春曲，边地闻之而春色未见","金鼓：以金钲、鼓指挥进退","宵：夜","玉鞍：精美的马鞍","直为：就要、径直去。为，语气词","斩楼兰：用西汉傅介子计斩楼兰王典故，喻平定边患"],"m":"晓战随金鼓，宵眠抱玉鞍。愿将腰下剑，直为斩楼兰。","r":"按「天山雪寒—闻笛无春—晓战宵眠—誓斩楼兰」背；「祗」同只；楼兰典必知。"},"秋浦歌十七首·三|李白":{"s":"前两句直写锦驼鸟羽毛似锦、珍异罕有；后两句用衬托之法——素以自爱羽毛、临水照影著称的山鸡，见了锦驼鸟竟自惭形秽、不敢照水，以山鸡之「羞」反衬驼鸟之美，不正面写其羽而其美自见，诙谐灵动。","b":"李白漫游秋浦时所作组诗之三，专咏当地罕见的锦驼鸟，是一首别致的咏物小诗。","n":["秋浦：今安徽池州贵池，李白漫游此地作《秋浦歌》十七首","锦驼鸟：羽毛如锦的鸵鸟（一说秋浦所产锦鸡类珍禽）","人间天上稀：人间罕有、天上也稀","山鸡：锦鸡，自爱其羽，常照水而舞","羞渌水：面对碧水自惭不如（衬托驼鸟之美）。渌，清澈","毛衣：羽毛"],"m":"山鸡羞渌水，不敢照毛衣。","r":"四句按「驼鸟珍稀—人间天上稀—山鸡照水而羞—不敢比羽」背；「渌」读lù，清澈义。"},"沙丘城下寄杜甫|李白":{"s":"前两句自问来此何事、高卧沙丘，已见百无聊赖；三四句城边古树、日夕秋声，以萧瑟秋景衬离思；颈联「鲁酒不可醉，齐歌空复情」——酒也醉不了、歌也不解愁，正因思念太深；尾联以汶水为喻，思君之情如汶水浩荡、随君南流，即景取喻，情深无际。","b":"李白与杜甫分别后寓居沙丘，思念友人而作此诗寄怀，李杜交谊的千古见证。","n":["沙丘：在今山东兖州一带，李白曾寓居","竟何事：究竟为了什么","高卧：闲居","日夕：朝夕","鲁酒、齐歌：鲁地的酒、齐地的歌（齐鲁皆今山东）","空复情：徒然有情（酒不能醉、歌不解愁）","汶水：山东大汶河。汶音wèn","浩荡：水势浩大，喻思情绵长","南征：向南远行，指杜甫将南游"],"m":"思君若汶水，浩荡寄南征。","r":"按「高卧沙丘—古树秋声—酒歌不解愁—汶水寄思」背；「汶」读wèn。"},"金乡送韦八之西京|李白":{"s":"首联「客自长安来，还归长安去」平平而起，似口语却见友人往返、自己留滞；颔联突发奇想——一颗心竟被狂风吹起、高挂在长安的树上，把抽象的依恋写得可见可触，是李白式的天真与夸张；后写此情难述、后会难期，末以望而不见、连山烟雾收束，怅惘不尽。","b":"李白在金乡送别归长安的友人韦八，以奇特想象写心随友人西去的惜别深情。","n":["韦八：一位韦姓友人，排行第八","之西京：往长安去","狂风吹我心，西挂咸阳树：心随友人西去、仿佛被风吹挂在长安树上（咸阳代长安）","不可道：说不尽","望望：一再瞻望","连山：连绵的山","烟雾：云雾"],"m":"狂风吹我心，西挂咸阳树。","r":"按「客来又去—心挂咸阳—情难道、别难遇—望断烟雾」背；「之」作动词去、往。"},"鲁郡东石门送杜二甫|李白":{"s":"首联忆别前数日醉复登临、遍游池台的快意；颔联「何时石门路，重有金樽开」预想后会，珍重中含期待；颈联写别时秋景——泗水秋波、徂徕海色，明丽开阔；尾联以飞蓬喻各自天涯，且尽杯中酒，不作儿女沾巾之态，旷达中藏深情，正见李白性情。","b":"天宝四载（745）李白与杜甫在鲁郡东石门最后一次分别，此诗写二人同游之乐与别后相念。","n":["杜二甫：杜甫，排行第二","石门：鲁郡东石门山","登临遍池台：一同游遍了山水台榭","金樽开：举杯重聚","泗水：在今山东","徂徕：山名，在今山东泰安。音cúlái","飞蓬：飘飞的蓬草，喻各自漂泊","且尽手中杯：姑且饮尽杯中酒"],"m":"飞蓬各自远，且尽手中杯。","r":"按「醉别登临—何日重聚—秋波海色—飞蓬尽杯」背；「徂徕」读cúlái。"},"秋登宣城谢朓北楼|李白":{"s":"首联「江城如画」总领、山晓晴空写环境；颔联是名句——两水如明镜相夹、双桥似彩虹飞落，对仗工巧、色彩明丽；颈联「寒」「老」二字最见炼字之功：橘柚间升起人烟而带寒意、梧桐染秋色而显苍老，把秋意写得可触可感；尾联临风怀谢公，古今诗人遥相呼应。","b":"李白秋日登宣城谢朓北楼，写景怀人，表达对南齐诗人谢朓的追慕。","n":["宣城：今安徽宣城","谢朓北楼：南齐诗人谢朓任宣城太守时所建，又名谢公楼。朓音tiǎo","江城：宣城，有水阳江绕城","两水：句溪、宛溪","夹明镜：两水如两面明镜相夹","双桥：凤凰桥、济川桥","落彩虹：桥如天上落下的彩虹","橘柚：南方果木","老梧桐：梧桐秋色深而显老","谢公：谢朓"],"m":"两水夹明镜，双桥落彩虹。人烟寒橘柚，秋色老梧桐。","r":"按「江城晴空—两水双桥—橘柚梧桐—临风怀谢」背；「朓」读tiǎo；「寒、老」的使动意味要体会。"},"苏台览古|李白":{"s":"诗以「旧苑荒台」与「杨柳新」对举，台荒而柳新，人事已非而自然依旧；菱歌清唱、春意无穷，越写春之永恒，越显宫苑之易朽；后两句点题——如今唯有西江明月，曾照见过当年吴宫美人，以月为历史见证，把吊古之思推向苍茫，含蓄不尽。","b":"李白游苏州姑苏台遗址，见杨柳新绿、菱歌依旧而吴宫成尘，抒发昔盛今衰之感。","n":["苏台：姑苏台，吴王夫差为西施所建，在苏州","旧苑荒台：昔日宫苑、如今荒台","菱歌：采菱歌","不胜春：春意无穷。胜音shēng，尽","只今：如今","西江月：西边江上之月","吴王宫里人：西施等吴宫中人"],"m":"只今惟有西江月，曾照吴王宫里人。","r":"四句按「苑荒台柳新—菱歌春无尽—唯有西江月—曾照吴宫人」背；与《越中览古》对读，同为览古名作。"},"越中览古|李白":{"s":"此诗章法独特：前三句一气铺张盛——勾践破吴、义士锦衣、宫女如花满殿，把胜利的繁华写到极处；末句陡然一落，「只今惟有鹧鸪飞」，盛与衰、热与冷在一句之内翻转，以盛衬衰，其衰倍哀，篇幅短小而冲击力极强。","b":"李白游览越中（今绍兴）越王勾践故宫遗址，以昔日灭吴盛况反衬今日荒凉，是七绝怀古的典范。","n":["越王句践：春秋越王勾践，卧薪尝胆灭吴。句同「勾」","义士还乡尽锦衣：灭吴将士凯旋、皆着锦衣（衣锦还乡）","春殿：宫殿春光","只今惟有鹧鸪飞：如今只剩鹧鸪飞于故址"],"m":"宫女如花满春殿，只今惟有鹧鸪飞。","r":"四句按「破吴—锦衣—如花满殿—鹧鸪乱飞」背；前三句盛、末句衰的结构是核心；「句践」同勾践。"},"访戴天山道士不遇|李白":{"s":"全诗沿访道行踪展开：犬吠水声、桃花带露写进山之初的幽美；树深见鹿、正午不闻钟，以「见鹿」之幽、「不闻钟」之静暗写无人；野竹分云、飞泉挂峰写山间清奇；尾联「无人知所去，愁倚两三松」点出不遇，余韵悠然，景中有人。","b":"李白早年在戴天山寻访道士不遇而作，以一路清幽山景写访隐的兴致与不遇的惆怅，是其现存较早的律诗。","n":["戴天山：又名大匡山，在今四川江油，李白少年读书处","不遇：没有遇到","带雨浓：带着浓露（一作露浓）","溪午不闻钟：走到溪边已正午，却听不到寺钟（暗示道士不在）","青霭：青色云气。霭，云气","飞泉：瀑布","愁倚：惆怅地倚着"],"m":"树深时见鹿，溪午不闻钟。野竹分青霭，飞泉挂碧峰。","r":"按「犬吠桃花—树深溪午—野竹飞泉—不遇倚松」背；「霭」读ǎi。"},"越女词五首·一|李白":{"s":"小诗以白描勾勒吴地女儿：先以「眉目艳新月」写面容之姣好，再特写木屐之上双足白如霜、不穿鸦头袜，抓住吴越女子赤足着屐的地方风习，写得天然清新、健康明朗，全无脂粉气，深得南朝民歌神韵。","b":"李白漫游吴越时作《越女词》五首，此首写吴地少女天足自然之美，富民歌风情。","n":["越女词：写吴越女子的组诗，此为其一","长干：金陵里巷名（长干里），此泛指吴地","儿女：女儿、女子","眉目艳新月：眉目比新月还要明艳","屐：木屐，木底鞋","足如霜：脚肤白如霜","鸦头袜：分叉如鸦头形的袜子（着屐时穿）"],"m":"屐上足如霜，不着鸦头袜。","r":"四句按「长干女儿—眉目新月—屐上如霜—不着鸦袜」背；「着」读zhuó（穿）。"},"喜见外弟又言别|李益":{"s":"首联「十年离乱后，长大一相逢」交代时代背景；颔联是写重逢的千古名句——分别时都是孩童，重逢竟先问姓氏、待报上名字才忆起旧容，把久别乍逢的惊疑、追忆写得极其真切；颈联叙谈间沧海桑田、不觉暮钟，见话之长；尾联预想明日巴陵道上秋山万重，刚逢又别，悲喜交集。","b":"李益这首五律写安史乱后与表弟久别重逢、翌日又别的情景，是写乱世离合的名篇。","n":["外弟：表弟","言别：话别、道别","一相逢：才相逢、忽然相逢","问姓：先问姓氏（因分别太久已不相识）","称名：报出名字","忆旧容：才忆起儿时面容","沧海事：如沧海桑田般的世事巨变","巴陵道：通往巴陵（今岳阳）的路"],"m":"问姓惊初见，称名忆旧容。别来沧海事，语罢暮天钟。","r":"按「十年相逢—问姓称名—叙谈到暮钟—明日山重」背；「一」释为忽然、才。"},"7153:夜上受降城闻笛|李益":{"s":"首联入夜思归、笛声哀切，奠定愁绪；颔联最妙——本是愁人怕听哀笛，笛声却偏「自到枕前来」，躲无可躲，把征人欲避乡愁而不得的无奈写活；颈联风起云断、夜深月出，清冷之景衬孤愁；尾联平明独惆怅、一庭梅落，以景结情，一夜无眠自见。","b":"李益久在边塞，此诗写征人夜闻笛声、思乡难眠，是其边塞诗的代表作之一（与名篇「回乐烽前沙似雪」同题而异辞）。","n":["受降城：唐代为防御突厥所筑东、西、中三受降城，此为边塞泛称","思归切：思归之情急切","清更哀：清越而哀伤","自到枕前来：笛声自己飘到枕边","塞云断：边云被风刮散","关月开：关塞上空云散月出","平明：天亮","落尽一庭梅：（一作）庭中梅花落尽，烘托一夜无眠"],"m":"愁人不愿听，自到枕前来。","r":"按「夜思笛哀—怕听偏来—风断云月—平明梅落」背；注意库内此首与「回乐烽前」是同题另一首，勿混。"},"度破讷沙二首·一|李益":{"s":"前两句写大漠实景：风卷沙移、经年不见寸草，极写环境之荒；后两句翻进一层作议论——不要说塞北没有春天，纵然春天真的来了，在这寸草不生的沙海里又从何处感知？以反问写尽边地无春的苦寒，也暗喻征人青春虚掷，含蓄深沉。","b":"李益《度破讷沙》二首之一，写塞北大漠终年风沙、无春可见的荒寒，寄征人感慨。","n":["破讷沙：沙漠名，又作普纳沙，在今内蒙古","沙旋移：沙尘被风卷着旋转移动","经年不省：整年看不见。省，记得、看见，音xǐng","莫言：不要说","总有春来何处知：就算春天来了，又从哪里能知道呢"],"m":"莫言塞北无春到，总有春来何处知。","r":"四句按「风沙旋移—经年无草—莫言无春—春来何知」背；「省」读xǐng、「总」释为纵然、即使。"},"汴河曲|李益":{"s":"前两句构成强烈对比：汴水东流、年年春色无限，隋家宫阙却已化为尘土，自然永恒与王朝短促对举；后两句以劝人莫上长堤作转——只因风起杨花漫天，最易牵动兴亡之愁。汴河柳、隋宫尘本是一体之两面，吊古伤今，绵邈苍凉。","b":"李益沿汴河而行，见春光依旧、隋宫成尘，借杨花抒写对隋炀帝荒淫亡国的历史感慨。","n":["汴河：通济渠，隋炀帝开凿的大运河一段，两岸植柳","隋家宫阙：隋朝宫殿","已成尘：早已化为尘土","长堤：汴河堤","杨花：柳絮","愁杀人：愁煞人"],"m":"行人莫上长堤望，风起杨花愁杀人。","r":"四句按「汴水春无限—隋宫已成尘—莫上长堤望—杨花愁煞人」背；汴河与隋亡的关系是背景关键。"},"边思|李益":{"s":"前两句写武将装束与戍边经历：锦带吴钩、走马防秋，英气勃勃；后两句一转——莫笑我这关西将门之后，没能立功封侯，只把满腹诗情带到了凉州。于自嘲中见自负：边塞风霜皆入诗篇，正是李益边塞诗独步中唐的自况，苍凉而不失风骨。","b":"李益曾五次从军、久历边塞，此诗自写从戎经历——本是将门之子，最终却以诗名传于边地，自豪中含自嘲。","n":["吴钩：吴地所产弯形宝刀，泛指利剑","走马：驰马","防玉塞秋：秋天戍守玉门关边塞（秋高马肥，胡人常入寇，故秋防）","关西将家子：函谷关以西多出将才，诗人自谓将门之后","秪将：只把。秪同「只」","诗思入凉州：作诗的情思都融入了凉州边地。凉州，今武威一带"],"m":"莫笑关西将家子，秪将诗思入凉州。","r":"四句按「悬钩佩刀—走马防秋—莫笑将门—诗思入凉」背；「秪」同只、「凉州」代边地。"},"从军北征|李益":{"s":"前两句写环境与笛声：天山雪后、海风刺骨，偏偏横笛吹起凄苦的《行路难》，以景衬声、以声引情；后两句是宏大特写——三十万征人竟在同一刻回头凝望明月，「一时」二字写尽乡心的普遍与齐一，不言愁而处处是愁，场面壮阔而悲怆。","b":"李益这首七绝写雪后风寒的大漠上，一支三十万征人的队伍因一支《行路难》笛曲而齐望明月的动人场面。","n":["从军北征：随军北征途中","天山：此泛指边塞之山","海风：从内陆大湖（如蒲类海）吹来的风","行路难：乐府旧曲，声情凄苦","碛里：沙漠中。碛音qì","三十万：极言征人众多","回向月明看：都回头望向明月（望乡）"],"m":"碛里征人三十万，一时回向月明看。","r":"四句按「雪后风寒—笛吹行路难—三十万征人—一时望月」背；「碛」读qì；望月即望乡。"},"隋宫燕|李益":{"s":"诗以燕子的口吻感受兴亡：燕语呢喃，仿佛在感伤旧国之春；宫花一落、霸业成尘；自从行宫封闭、风光不再，燕子几度归来，再不见当年宫人。以燕子的「几度飞来」见证时间流逝，以「不见人」写尽荒凉，角度新巧、感慨深沉。","b":"李益以年年归来的春燕为视角，写隋宫封闭后的荒凉，借燕语寄托兴亡之感。","n":["隋宫：隋炀帝行宫","旧国春：故都（隋朝）的春色","宫花一落：宫花凋落，喻隋亡","一闭风光：行宫一旦封闭、繁华散尽","几度：多少次"],"m":"自从一闭风光后，几度飞来不见人。","r":"四句按「燕语伤春—宫花落尘—一闭风光—飞来不见人」背；燕子是历史见证者，为全诗视角。"},"江南曲|李益":{"s":"前两句写雨收花明、江城日暮、游人相邀，透出江南生活的悠然；后两句用工致对句写风物——春楼虚掩、连锁不闭，见民风之安闲；绿水回环、桥随水转，见地势之玲珑。色彩明丽、音韵流转，如一幅江南水乡小品。","b":"李益这首小诗写江南江城日暮、雨收花明、春楼不锁、绿水桥回的明丽风光与闲适人情。","n":["江南曲：写江南风物的诗","长乐：长乐坡（或长乐里），在长安/江南地名","雨点销：雨点渐稀渐止。销同「消」","相邀：相互邀约游赏","葳蕤锁：雕饰繁复、可屈折的连锁。葳蕤音wēiruí","回连：回环相连","宛转桥：曲折回转的桥"],"m":"春楼不闭葳蕤锁，绿水回连宛转桥。","r":"四句按「花枝雨销—日暮相邀—春楼不锁—绿水桥回」背；「葳蕤」读wēiruí。注意此首与「嫁得瞿塘贾」同题异篇。"},"拜新月|李端":{"s":"前两句以连贯动作写少女的天真：开帘忽见新月，便立刻下阶而拜，「便即」二字见其情急可爱；后两句写她对着月儿轻声许愿，旁人听不真切，只有北风吹动裙带——以「人不闻」制造私密感，以风吹裙带的细节勾勒月下亭亭身影，含蓄灵动，余味悠然。","b":"李端这首小诗写一位少女开帘见月、匆匆下拜、临风细语的娇憨情态，清新如画。","n":["拜新月：古代妇女有七夕或月初拜新月、许愿的习俗","便即：随即","下阶拜：走下台阶对月下拜","细语：轻声诉说心愿","裙带：系裙的带子"],"m":"细语人不闻，北风吹裙带。","r":"四句按「开帘见月—下阶拜月—细语人不闻—风吹裙带」背；拜新月是古代民俗。"},"古风二首·一|李绅":{"s":"前两句极写丰收：春种一粒、秋收万颗，以「一」与「万」的对比写劳动创造之丰；第三句再推一层，四海之内再无一块闲田，丰收已写到极处；末句陡然逆转——农夫「犹饿死」！丰收越被铺陈，饿死越显触目，不言原因而原因自见，冷峻深刻。","b":"李绅《悯农》二首之一，以春种秋收的丰收与农夫饿死的强烈对比，揭露社会不公，是千古传诵的悯农诗。","n":["古风二首：即《悯农二首》，此为其一（另一首「锄禾日当午」）","粟：谷子，泛指粮食","秋成：秋天收获（一作秋收）","四海：普天之下","闲田：撂荒的田地","犹：还、仍然"],"m":"四海无闲田，农夫犹饿死。","r":"四句按「春种—秋收—无闲田—犹饿死」背；前三句蓄势、末句逆转的结构是核心。"},"过华清宫绝句三首·一|杜牧":{"s":"前两句写长安回望骊山、宫阙如绣、千门次第开启，庄严隆重，设下悬念；后两句揭谜——驿马绝尘、妃子一笑，没人知道这十万火急的军国般排场，竟只是为送几颗荔枝！「妃子笑」与「一骑红尘」并置，以小见大，讽刺入木三分而不着一字议论。","b":"杜牧途经华清宫所作三首之一，截取驿马送荔枝的典型场景，讽刺唐玄宗为博妃子一笑而疲民劳驿。","n":["华清宫：唐玄宗与杨贵妃的骊山行宫","回望：从长安回望骊山","绣成堆：骊山花木建筑如团团锦绣","千门次第开：宫门一道接一道打开。次第，依次","一骑红尘：一匹驿马飞驰、扬起红尘。骑音jì","妃子：杨贵妃","荔枝：杨贵妃喜食鲜荔枝，驿马自岭南（或蜀）日夜驰送"],"m":"一骑红尘妃子笑，无人知是荔枝来。","r":"四句按「回望锦绣—千门开启—一骑妃笑—荔枝驰来」背；「骑」读jì；以史讽今是目的。"},"长安秋望|杜牧":{"s":"前两句写天：楼高出霜树之外，天空明净如镜、纤云不染，已见高远；后两句更出新意——终南山是有形之高，秋色（秋空清气）是无形之高，二者气势互不相让、争相比高。把抽象的「秋色」写得有气势、可与高山争衡，构思奇特、笔力遒劲。","b":"杜牧这首五绝写秋日登楼、天高云净、终南耸翠的寥廓景象，表现高朗开阔的胸襟。","n":["长安秋望：秋日远望长安（或终南山）","霜树外：高出经霜的树林（言楼之高）","镜天：天空明净如镜","无一毫：没有一丝云彩","南山：终南山","气势两相高：南山的高峻与秋色的高远争相比高"],"m":"南山与秋色，气势两相高。","r":"四句按「楼高霜树—镜天无云—南山—秋色两相高」背；「两相高」的拟人是诗眼。"},"将赴吴兴登乐游原一绝|杜牧":{"s":"前两句写在「清时」只爱孤云、静爱高僧，看似闲适，「无能」实为牢骚反语；后两句写将持麾远去江南，临行登乐游原遥望太宗昭陵——望昭陵正是追慕贞观盛世、慨叹今世不遇明主，去国恋阙之情尽在一望中，含蓄沉郁。","b":"大中四年（850）杜牧将离长安赴湖州刺史任，登乐游原远望昭陵而作，于自嘲中寓盛世不再、壮志难酬之慨。","n":["吴兴：今浙江湖州，杜牧将赴任湖州刺史","乐游原：长安东南登高胜地","清时：政治清明之时（反语，含不遇之慨）","有味是无能：闲静有味反因自己「无能」，自嘲","一麾：一面刺史旌麾，此指出任外官。麾音huī","江海去：到江南（湖州）去","昭陵：唐太宗陵墓，含追慕贞观盛世之意"],"m":"欲把一麾江海去，乐游原上望昭陵。","r":"四句按「清时无能—爱云爱僧—持麾赴江海—登原望昭陵」背；「麾」读huī；望昭陵的深意是关键。"},"齐安郡后池绝句|杜牧":{"s":"前两句写得极热闹：菱透浮萍、池如绿锦，夏莺在蔷薇间千啭，色彩与声音交织；后两句却以「尽日无人」一转，转入极静——唯有鸳鸯相对、于微雨中浴其红衣，以鸳鸯之成双、自得，反衬人之独处，动静相衬，「红衣」喻羽，鲜丽传神。","b":"杜牧任黄州刺史时作，写夏日后池细雨中菱萍、夏莺、鸳鸯构成的明丽幽静画面。","n":["齐安郡：今湖北黄冈，杜牧曾任黄州刺史","菱透浮萍：菱叶从浮萍间透出","绿锦池：池塘美如绿色锦缎","千啭：鸣声婉转多变。啭，鸟鸣","蔷薇：花木名","微雨：细雨","浴红衣：鸳鸯戏水、梳理红色羽毛。红衣喻鸳鸯彩羽"],"m":"尽日无人看微雨，鸳鸯相对浴红衣。","r":"四句按「菱萍绿池—莺弄蔷薇—尽日无人微雨—鸳鸯对浴」背；「红衣」喻鸳鸯羽毛是巧喻。"},"鹭鸶|杜牧":{"s":"前两句写静：白鹭雪衣青喙、群立溪影中捕鱼，颜色相映；后两句写动——白鹭惊起、远衬碧山飞去，恰似一树洁白梨花在晚风中纷纷飘落。以梨花喻群鹭，色白形似，化动为静又化无生为有生，清新奇丽，是咏物佳句。","b":"杜牧这首咏物小诗写白鹭溪中捕鱼、惊飞远映碧山的姿态，比喻新巧、画面清雅。","n":["鹭鸶：白鹭。鸶音sī","雪衣雪发：羽毛洁白如雪","青玉觜：青玉般的长喙。觜同「嘴」","群捕：成群捕食","溪影：溪水中的倒影","碧山：青山","一树梨花落晚风：喻白鹭惊飞如梨花被晚风扬起"],"m":"惊飞远映碧山去，一树梨花落晚风。","r":"四句按「雪衣青嘴—溪影捕鱼—惊飞映山—如梨花落」背；「觜」同嘴、「鸶」读sī。"},"题乌江亭|杜牧":{"s":"首句立论——兵家胜败本难预料；次句提出「包羞忍耻」方为男儿，暗批项羽经不起一败；后两句假设推论：江东子弟人才济济，若能重返江东、重整旗鼓，胜负尚未可知。咏史而不囿成说，以假设作结，议论警拔、气势豪宕，体现杜牧咏史绝句善作翻案的特色。","b":"杜牧过乌江亭，针对项羽「无颜见江东父老」而自刎的史事作翻案诗，认为大丈夫当忍辱负重、以待再起。","n":["乌江亭：在今安徽和县，项羽兵败自刎处","事不期：胜败之事难以预料","包羞忍耻：能忍受羞耻挫折","江东：长江下游南岸，项羽起兵之地","才俊：才能出众的人","卷土重来：失败后重新恢复势力"],"m":"江东子弟多才俊，卷土重来未可知。","r":"四句按「胜败难期—包羞忍耻—江东才俊—卷土重来」背；这是翻案诗，观点要与项羽自刎史实对看。"},"题木兰庙|杜牧":{"s":"前两句写木兰的双重身份：弯弓征战、不输男儿是其表，梦里画眉、不忘女儿身是其里；后两句更妙——木兰几度思乡把酒，却在边地拂云堆上祭奠明妃王昭君：两位女子一征战、一和亲，皆为家国远走绝域，异代相怜，把木兰的情感世界写得深婉，构思巧妙。","b":"杜牧游木兰庙所作，既写木兰代父从军的英勇，又体贴其女儿本色与思乡之情，立意新颖。","n":["木兰庙：祭祀花木兰的庙","作男儿：女扮男装","与画眉：（梦中）和女伴一起描眉（恢复女儿本色）","把酒：举酒","拂云堆：地名，在今内蒙古，有神祠","祝明妃：祭奠王昭君（明妃即王昭君，和亲匈奴，和木兰一样远涉边地）"],"m":"几度思归还把酒，拂云堆上祝明妃。","r":"四句按「征战男儿—梦里画眉—思乡把酒—祭奠明妃」背；木兰与昭君的精神联系是理解关键。"},"21537:遣怀|杜牧":{"s":"前两句以近乎格言的语言慨叹时命：道「泰」之时时运却不至，透出才命相妨的无奈；后两句表达志向——何时才能离开喧嚣城市，到博山深处高卧归隐。语言简淡，却可见诗人在党争倾轧的晚唐渴望全身远害的心境。","b":"此为杜牧《遣怀》的另一首（库内文本，与传诵的「落魄江湖载酒行」非同一篇），写时命未至、渴望离城归隐的情怀。","n":["遣怀：排遣情怀","道泰：世道（或个人时运）安泰","时来：时机到来","何当：何时才能","博山隈：博山（今山东或泛指山林）的弯曲幽深处。隈，山曲处，音wēi","高卧：高枕闲居、归隐"],"m":"何当离城市，高卧博山隈。","r":"四句按「道泰命不来—何当离城—高卧山隈」背；「隈」读wēi；注意与「落魄江湖」篇区分。"},"叹花|杜牧":{"s":"全诗以花喻人、通篇比兴：自恨寻芳来迟，往年曾见花在「未开」之时（少女年幼），如今风摆花落、狼藉满地，绿叶成荫、子实满枝——花之已谢正喻人之已嫁、儿女成行。不着一情语而怅惘无尽，比喻贴切，成为「绿叶成荫」成语的出处。","b":"相传杜牧早年游湖州识一少女、约以十年内来娶，十四年后再至，女子已嫁三年、生二子，因作此诗叹惋。","n":["叹花：叹惜花朵（一作怅诗，本事与杜牧早年邂逅湖州女子、十年后再来已嫁人生子有关）","寻芳：寻访春花（喻寻访意中人）","狼籍：纵横散乱貌，此指花已凋零。籍同「藉」","绿叶成阴子满枝：绿树成荫、果实满枝（喻女子已出嫁生子）"],"m":"如今风摆花狼籍，绿叶成阴子满枝。","r":"四句按「寻芳已迟—昔见未开—花落狼藉—叶荫子满」背；以花喻人的比兴贯穿全篇。"},"秋夕|杜牧":{"s":"首句「冷」字奠定基调：秋光、画屏皆带寒意，既是天凉也是心冷；次句以「扑流萤」写宫女百无聊赖——唯有流萤相伴，见深宫之冷落；后两句夜色凉如水、坐看牵牛织女，双星尚有一年一度之会，自己却长闭深宫、相逢无期，以乐景（双星相会）写哀，含蓄不尽。","b":"杜牧这首宫怨诗写七夕之夜宫女扑萤、坐看双星的孤寂，以清冷之景写失意之情。","n":["秋夕：七夕之夜（一作七夕）","红烛：一作「银烛」","冷画屏：烛光使画屏生出寒意","轻罗小扇：轻薄丝绢制成的小团扇","流萤：飞动的萤火虫","天阶：宫中石阶","牵牛织女：牛郎、织女星，七夕鹊桥相会"],"m":"天阶夜色凉如水，坐看牵牛织女星。","r":"四句按「烛冷画屏—小扇扑萤—夜凉如水—坐看双星」背；「天阶」指宫中、扑萤见孤寂。"},"金谷园|杜牧":{"s":"首句「繁华事散逐香尘」总括金谷园昔日繁华尽随香尘消散；次句「流水无情草自春」，以自然之无情反衬人之有情；后两句是名句——日暮东风中啼鸟如怨，飘落的花瓣多像当年坠楼的绿珠！以落花喻堕楼人，人花同命，凄艳绝伦，吊古与怜人融为一体。","b":"杜牧过洛阳金谷园遗址，凭吊石崇与绿珠故事，写繁华散尽、落花如人的深沉感伤。","n":["金谷园：西晋富豪石崇的名园，在洛阳，绿珠坠楼于此","香尘：石崇曾以沉香屑铺象牙床、令姬妾踏之，此代指昔日繁华","草自春：春草自绿，不管兴亡","堕楼人：绿珠，石崇爱妾，孙秀强索不得、石崇获罪，绿珠坠楼殉情"],"m":"日暮东风怨啼鸟，落花犹似堕楼人。","r":"四句按「繁华逐尘—流水草春—啼鸟如怨—落花似人」背；绿珠坠楼典必知；「犹似」是诗眼。"},"旅宿|杜牧":{"s":"首联无良伴、自悄然，已见孤寂；颔联寒灯思旧事、断雁警愁眠，视听交织，以雁之孤衬人之孤；颈联是名句——梦归要到拂晓、家书隔年才到，极写乡关之远、音信之疏；尾联忽转，以湘江烟月、门系钓船的闲适画面反衬自己不能归去，以景结情，余味悠然。","b":"杜牧旅宿湘江边旅馆，寒灯孤雁、家书难达，写尽羁旅之愁与对闲适生活的向往。","n":["凝情：凝神沉思","悄然：忧愁寂静貌","断雁：离群的孤雁","警愁眠：惊醒愁眠之人","远梦归侵晓：归乡的梦遥远，做到天将晓才醒","家书到隔年：家信要隔一年才到","烟月：烟水月色"],"m":"远梦归侵晓，家书到隔年。","r":"按「旅馆无伴—寒灯断雁—远梦家书—湘江钓船」背；「侵晓」即拂晓。"},"游龙门奉先寺|杜甫":{"s":"首联点题游寺宿寺；颔联写夜宿所闻所见：阴壑生虚籁、月林散清影，声色俱幽；颈联「天阙象纬逼，云卧衣裳冷」以夸张写寺之高峻——星辰可扪、云气侵衣，气象阔大；尾联将醒未醒闻晨钟，顿生深省，由景入理，禅意悠然，是杜诗中少见的清远之作。","b":"杜甫青年时期游洛阳龙门、夜宿奉先寺所作，是其早期山水纪游诗，已见沉郁雄浑的笔力。","n":["龙门奉先寺：在洛阳龙门石窟，奉先寺为唐代大像窟","招提：梵语拓斗提奢的省称，此指寺院","阴壑：幽深的山谷","虚籁：空谷中的自然声响。籁，从孔穴发出的声音","天阙：即龙门两山如天阙（宫门双阙）","象纬逼：星辰仿佛逼近。象纬，日月星辰","云卧：高卧云间","发深省：引发深刻的省悟"],"m":"欲觉闻晨钟，令人发深省。","r":"按「游寺宿寺—夜壑月林—天阙云卧—晨钟深省」背；「象纬」指星辰。"},"贫交行|杜甫":{"s":"首句以「翻云覆雨」的比喻写尽人情反复，成为千古成语；次句「何须数」三字冷峻，不屑之情溢于言表；后两句以管鲍贫交作对照——古人贫贱相交、生死相托之道，今人竟弃如粪土。以古衬今，愤激深沉，短短二十八字道尽世态炎凉。","b":"杜甫困居长安时，见世态炎凉、人情反复，借管鲍之交的典故慨叹当世再无贫贱之交。","n":["贫交行：写贫贱之交的乐府诗。行，歌行体","翻手作云覆手雨：翻手为云、覆手为雨，喻人情反复无常","纷纷轻薄：众多轻薄之徒","何须数：哪值得一一数说","管鲍：管仲与鲍叔牙，春秋时贫贱之交的典范","此道：指贫贱相交之道","弃如土：被抛弃如粪土"],"m":"翻手作云覆手雨，纷纷轻薄何须数。","r":"四句按「翻云覆雨—轻薄何须数—管鲍贫交—今人弃如土」背；管鲍典故是核心。"},"秋雨叹三首·一|杜甫":{"s":"首联以雨中百草烂死反衬决明颜色独鲜，赞其坚韧；颔联以翠羽盖、黄金钱两个比喻写决明叶之茂、花之艳，色彩明丽；颈联忽转忧——凉风急吹，恐其错过花期、难以独立，既是惜花也是自伤；尾联书生白头、临风三嗅而泣，花与人合而为一，物我同悲。","b":"杜甫《秋雨叹》三首之一，天宝十三载秋长安久雨成灾，诗人借阶下决明花在秋雨中独鲜、又恐被秋风摧折，自伤身世。","n":["决明：草本植物，夏秋开黄花，种子可入药","著叶满枝翠羽盖：叶子满枝如翠羽伞盖","开花无树黄金钱：花开如黄金钱（决明花黄色圆形）","凉风萧萧：秋风萧瑟","后时：晚于时节、错过花期","堂上书生：杜甫自指","三齅馨香：多次嗅其香气。齅同「嗅」"],"m":"凉风萧萧吹汝急，恐汝后时难独立。","r":"按「百草烂死—决明独鲜—翠羽金钱—凉风恐独立—书生泣」背；「齅」同嗅。"},"秋雨叹三首·二|杜甫":{"s":"首联以「四海八荒同一云」极写雨势之大、范围之广；颔联化用《庄子》牛马不辨之典，又以泾渭清浊难分写雨雾迷蒙，用典而不见痕迹；颈联写禾穗生耳、黍穗发黑，农田绝收的惨状如在目前；尾联写城中灾民卖被换米、不计价钱，以具体交易写饥荒之重，沉郁痛切。","b":"杜甫《秋雨叹》之二，写天宝十三载长安久雨成灾、农田受损、米价飞涨的民生惨状，是现实主义的实录。","n":["阑风长雨：连绵不断的风雨。阑，残、尽","四海八荒同一云：天下各处都笼罩在同一片阴云下","去马来牛不复辨：雨大到牛马不辨（用《庄子》「两涘渚崖之间不辨牛马」意）","浊泾清渭何当分：泾水浊、渭水清，大雨中也无法分辨","禾头生耳：雨后禾穗发芽如耳（霉变）","黍穗黑：黍穗因雨发黑","斗米换衾裯：一斗米就能换被子（言粮贵物贱、灾民卖物换粮）。衾裯，被子","相许宁论两相直：双方同意就换，哪还论价钱相当。直同「值」"],"m":"去马来牛不复辨，浊泾清渭何当分。","r":"按「久雨成灾—牛马不辨—禾黍受损—卖被换米」背；「直」同值。"},"房兵曹胡马诗|杜甫":{"s":"首联点出大宛名马；颔联以「锋棱」「竹批」写马的骨相耳形，工笔细描而见神骏；颈联由形入神——所向无阻、可托死生，马之品格跃然；尾联「万里可横行」由马及人，既是赞马也是期许房兵曹能驰骋疆场，咏物即咏人，雄健豪迈。","b":"杜甫早期咏物诗，为友人房兵曹的胡马画像，借马言志，抒发青年时期建功立业的豪情。","n":["房兵曹：一位姓房的兵曹参军","胡马大宛名：大宛（今中亚费尔干纳）出产的名马。宛音yuān","锋棱瘦骨成：瘦骨棱棱如刀锋，写马的神骏","竹批双耳峻：双耳如削竹般尖锐挺立（良马特征）","风入四蹄轻：跑起来四蹄生风、轻快如飞","所向无空阔：所到之处没有能阻挡它的空阔之地","真堪托死生：真可以把生死托付给它","骁腾：矫健奔腾"],"m":"所向无空阔，真堪托死生。骁腾有如此，万里可横行。","r":"按「大宛名马—骨相耳蹄—可托死生—万里横行」背；「宛」读yuān。"},"画鹰|杜甫":{"s":"首联「风霜起」三字破空而来，写画鹰气势逼人；颔联写画中鹰竦身侧目、欲捕狡兔的神态，「愁胡」喻鹰眼，形神兼备；颈联写画之逼真——绦旋可摘、呼之欲出，以假乱真；尾联由画及真，盼此鹰能搏击凡鸟、血染原野，借鹰言志，抒发扫除奸邪的豪情，咏物诗的典范。","b":"杜甫早期咏画诗，为一幅苍鹰画题咏，借画鹰抒发嫉恶如仇、搏击凡庸的壮志。","n":["素练：白绢，画鹰所用","风霜起：画上仿佛有风霜之气涌起","画作殊：画得特别出色","身：竦身、耸身。同「竦」","思狡兔：想捕捉狡兔","俱目似愁胡：鹰眼锐利如愁胡（胡人，其目深碧锐利）","绦旋：系鹰的丝绳和转轴。绦音tāo","光堪擿：光彩耀眼几乎可摘下。擿同「摘」","轩楹：廊柱，此指画鹰悬挂之处","势可呼：气势如生，仿佛呼之欲出","凡鸟：凡庸的鸟","平芜：平坦的原野"],"m":"何当击凡鸟，毛血洒平芜。","r":"按「素练风霜起—竦身侧目—可摘可呼—搏击凡鸟」背；「」同竦、「擿」同摘。"},"春日忆李白|杜甫":{"s":"首联「诗无敌」「思不群」直抒对李白的推崇；颔联以庾信之清新、鲍照之俊逸比李白诗风，用典精当；颈联是千古名句——渭北春树、江东暮云，两地之景各自在目，而思念之情尽在不言中，情景交融、含蓄不尽；尾联盼重聚把酒论文，情深意切，是李杜交谊的见证。","b":"天宝五载（746）前后杜甫在长安，思念漫游江东的李白而作，盛赞李白诗才，表达重聚论诗的渴望。","n":["白也：李白，「也」为语气词","无敌：无人能比","飘然思不群：才思飘逸、卓尔不群","庾开府：庾信，北周文学家，官至开府仪同三司","鲍参军：鲍照，南朝宋诗人，曾任临海王参军","渭北：渭水以北，指杜甫所在长安","江东：长江以东，指李白所在吴越","一尊酒：一杯酒。尊同「樽」","细论文：细细讨论诗文"],"m":"渭北春天树，江东日暮云。","r":"按「赞李白无敌—庾鲍比诗—渭北江东—把酒论文」背；「尊」同樽。"},"九日曲江|杜甫":{"s":"首联写重阳茱萸、菡萏已衰，秋意萧瑟；颔联点出九月将半、重阳含悲，「意兼悲」三字定下全诗基调；颈联写江水曲折、荆门路疑，借地理写仕途方向之迷茫；尾联写游兴已尽、重阳赏菊之约也被摇荡，由景入情，含蓄写出贬谪前夕的失意与彷徨。","b":"杜甫乾元元年（758）任左拾遗时，重阳日游曲江所作，写秋景衰飒、仕途失意的悲慨。","n":["缀席茱萸：茱萸插在坐席旁（重阳节佩茱萸避邪）","浮舟菡萏衰：泛舟曲江，荷花已凋零。菡萏，荷花","季秋：秋季第三个月，即九月","意兼悲：心意中兼有悲意","江水清源曲：江水清澈、源流曲折","荆门此路疑：此去荆门之路令人疑虑（荆门在湖北，曲江在长安，方向不合）","高兴尽：高情逸兴已尽","摇荡菊花期：动摇了重阳赏菊的约期"],"m":"季秋时欲半，九日意兼悲。","r":"按「茱萸菡萏—九日含悲—江水荆门—兴尽菊期」背；「菡萏」读hàndàn。"},"春宿左省|杜甫":{"s":"首联写薄暮花隐、栖鸟飞过，交代值班时分；颔联是名句——星光下临、万户闪动，月近九霄、高处得月，以夸张写宫殿之高峻壮丽，气象雄浑；颈联写不寐听锁、因风想珂，勤于王事之态如见；尾联写明日有封事、屡问夜如何，以细节写尽尽职的急切，严谨中见忠恳。","b":"杜甫任左拾遗时，春夜在门下省值班所作，写宫中夜景与勤于职守的心情，是其早期宫廷诗。","n":["左省：门下省，在宫殿左侧，杜甫时任左拾遗属门下省","掖垣：宫门旁的墙，此指左省。掖音yè","栖鸟：归巢的鸟","星临万户动：星光下照，宫中千门万户仿佛闪动","月傍九霄多：月光靠近高天，宫殿高处得月最多","金钥：宫中门锁","玉珂：马勒上的玉饰，此指百官上朝的马铃声","封事：密封的奏章","数问夜如何：屡次询问夜到几更（盼天亮好上朝）"],"m":"星临万户动，月傍九霄多。","r":"按「花隐栖鸟—星月宫阙—听钥想珂—封事问夜」背；「掖」读yè。"},"秦州杂诗二十首·一|杜甫":{"s":"首联「满目悲生事」总起，「因人作远游」交代漂泊之由；颔联写度陇胆怯、及关愁生，行旅之苦与心理之惧交织；颈联是名句——以鱼龙川、鸟鼠山两个秦州地名入对，水落山空、夜色秋声，边地荒寒如在目前，对仗工稳而意境苍凉；尾联写西征问烽火、心折淹留，战乱未息、归乡无日，悲慨深沉。","b":"杜甫乾元二年（759）弃官西行、初到秦州所作《秦州杂诗》二十首之一，写战乱中漂泊边地的愁苦。","n":["秦州：今甘肃天水，杜甫乾元二年弃官后寓居于此","悲生事：为生计而悲","因人：依靠他人（指投奔在秦州的侄儿杜佐等）","迟回：徘徊犹豫","度陇：越过陇山。陇，陇山，在陕甘交界处","浩荡及关愁：到了边关，愁思浩荡","鱼龙夜：鱼龙川的夜晚（秦州附近水名，秋夜水寒）","鸟鼠秋：鸟鼠山的秋色（秦州附近山名）","西征问烽火：西行路上探问战火（吐蕃侵扰）","心折：心碎、伤心","淹留：久留"],"m":"水落鱼龙夜，山空鸟鼠秋。","r":"按「悲生事远游—度陇及关—鱼龙鸟鼠—问烽火心折」背；鱼龙、鸟鼠是秦州地名。"},"3176:卜居|杜甫":{"s":"首联点题——浣花溪畔、主人为卜林塘幽处；颔联写出郭少尘事、澄江销客愁，环境宜人；颈联是名句——蜻蜓齐飞上下、㶉𫛶成对浮沉，以两个特写镜头写草堂前的生机与闲适，对仗工细、画面明丽；尾联用王子猷山阴乘兴典故，写在此可乘兴东游、旷达自适，欣喜之情溢于言表。","b":"杜甫上元元年（760）初到成都、在浣花溪畔营建草堂时所作，写卜居环境的清幽与欣喜。","n":["浣花流水：浣花溪的流水，在成都西郊","主人：指当地友人（或指成都尹裴冕）为杜甫卜居","卜林塘幽：选择了一处林木池塘清幽的地方。卜，选择","出郭：出城","澄江：清澈的锦江","㶉𫛶：水鸟，似鸳鸯而大，羽毛五彩。音xīchì","沈浮：在水中浮沉。沈同「沉」","乘兴：趁着兴致","山阴：今浙江绍兴，用王子猷雪夜访戴逵「乘兴而行，兴尽而返」典故"],"m":"无数蜻蜓齐上下，一双㶉𫛶对沈浮。","r":"按「卜居浣花—出郭澄江—蜻蜓㶉𫛶—乘兴山阴」背；「㶉𫛶」读xīchì、「沈」同沉。"},"江村|杜甫":{"s":"首联「清江一曲抱村流，长夏江村事事幽」总写环境清幽；颔联以燕子自来自去、鸥鸟相亲相近，写物态的自在，也暗示人的闲适；颈联写老妻画棋盘、稚子敲钓钩，两个生活细节写尽天伦之乐，朴素而温馨；尾联「多病所须唯药物，微躯此外更何求」，在欣喜中透出一丝苦涩——多病之身只求药物，别无所求，乐中含悲，沉郁底色仍在。","b":"杜甫上元元年（760）成都草堂建成后所作，写江村夏日的闲适生活与老妻稚子的天伦之乐，是杜诗中少有的轻快之作。","n":["清江一曲：锦江一弯","抱村流：环绕村庄流淌","长夏：漫长的夏日","事事幽：事事都显得清幽","自去自来堂上燕：堂上燕子自来自去","相亲相近水中鸥：水中鸥鸟相亲相近","画纸为碁局：在纸上画棋盘。碁同「棋」","敲针作钓钩：把针敲弯做成钓钩","微躯：微贱的身躯，杜甫自指"],"m":"自去自来堂上燕，相亲相近水中鸥。","r":"按「清江抱村—燕鸥自在—老妻稚子—多病何求」背；「碁」同棋。"},"南邻|杜甫":{"s":"首联写南邻形象——乌角巾、园收芋粟，隐士风度与清贫生活并见；颔联写儿童惯看宾客而喜、鸟雀得食阶除而驯，以两个细节写主人的好客与环境的宁静；颈联是名句——秋水才四五尺深、小船正好坐两三人，数字入诗而意境清幽，田园气息浓郁；尾联写白沙翠竹、江村日暮、柴门相对月色新，以景结情，两人交往的闲适尽在画面中。","b":"杜甫在成都草堂时，写其南邻一位隐士的生活与二人交往，是田园诗的佳作。","n":["锦里先生：指杜甫南邻朱山人（隐士），锦里为成都地名","乌角巾：黑色的方巾，隐士所戴","芋粟：芋头和小米","不全贫：不算太穷","阶除：台阶","鸟雀驯：鸟雀被驯化、不怕人","野航：乡村小船","恰受：正好容纳","柴门：简陋的门"],"m":"秋水才深四五尺，野航恰受两三人。","r":"按「乌角巾芋粟—儿童鸟雀—秋水野航—白沙翠竹」背；「恰受」即正好容纳。"},"江亭|杜甫":{"s":"首联写坦腹江亭、长吟野望，闲适之态如见；颔联是名句——水流而心不竞逐、云在而意兴俱迟，以水云之自在写心境之超然，情景交融、物我两忘，是杜诗中极富禅意的一联；颈联写春将晚、物自私，万物自得而人独寂寞；尾联点出故林归未得、只能强裁诗排闷，闲适背后是深沉的乡思，乐中含悲。","b":"杜甫成都草堂时期春日江亭闲坐所作，写闲适心境中暗藏的归乡之思。","n":["坦腹：坦露腹部，用王羲之东床坦腹典故，写闲适不拘","长吟：长声吟咏","野望：眺望原野","水流心不竞：江水自流，我心已无竞逐之意","云在意俱迟：白云自在，我的意兴也同样舒缓","寂寂：寂静貌","欣欣：草木茂盛貌","物自私：万物各自得其乐","故林：故乡的树林，代指故乡","排闷：排遣烦闷","强裁诗：勉强作诗。裁，制作"],"m":"水流心不竞，云在意俱迟。","r":"按「坦腹长吟—水云心闲—春晚物私—归未裁诗」背；「竞」读jìng。"},"琴台|杜甫":{"s":"首联写相如晚年多病仍爱文君，以「尚爱」二字见爱情之坚；颔联「酒肆人间世，琴台日暮云」，将当年当垆卖酒的热闹与今日琴台空对暮云的荒凉对举，盛衰之感油然而生；颈联是名句——野花如文君的酒窝、蔓草如她的罗裙，以眼前景物想象古人芳踪，亦真亦幻，凄艳动人；尾联叹凤求凰之意已寥寥不闻，怀古伤今，余韵悠然。","b":"杜甫成都时期凭吊司马相如琴台所作，借相如文君爱情故事抒发对真挚爱情的追慕与对世事变迁的感慨。","n":["琴台：司马相如与卓文君当垆卖酒处，在成都","茂陵多病后：司马相如晚年多病居茂陵（汉武帝陵邑）","尚爱卓文君：仍然深爱卓文君","酒肆人间世：在酒肆中度过人间岁月（卓文君当垆、相如涤器）","琴台日暮云：琴台之上只有日暮浮云","宝靥：女子的酒窝，此指卓文君的遗迹。靥音yè","罗裙：丝罗裙，代指卓文君","归凤求皇：司马相如以《凤求凰》琴曲打动卓文君。皇同「凰」","寥寥：稀少、断绝"],"m":"野花留宝靥，蔓草见罗裙。","r":"按「茂陵多病—酒肆琴台—野花蔓草—凤求凰寥寥」背；「靥」读yè、「皇」同凰。"},"江畔独步寻花七绝句·一|杜甫":{"s":"首句「被花恼不彻」出新意——花本可赏，诗人却说被花搅扰，以嗔写爱，花之繁密、人之痴爱尽在「恼」字中；次句写无处诉说、只能独自颠狂，痴态可掬；后两句写去找南邻爱酒的朋友，可友人已出门十天、只剩空床，欲共赏而不得，小小的失望中见春日的烂漫与诗人的天真，语言口语化而情致盎然。","b":"杜甫成都草堂时期《江畔独步寻花》七首之一，写春日被花撩拨、欲寻酒友共赏而友人不在的小烦恼，诙谐有趣。","n":["被花恼不彻：被花搅扰得无法排遣。恼，撩拨、搅扰","无处告诉：无处诉说","颠狂：放浪形骸","南邻爱酒伴：南边邻居爱喝酒的朋友（指斛斯融等）","经旬：十天、很长时间","独空床：独自空床（言友人外出未归）"],"m":"江上被花恼不彻，无处告诉只颠狂。","r":"四句按「被花恼—无处诉—觅酒伴—独空床」背；「恼」是撩拨而非真恼。"},"戏为六绝句·一|杜甫":{"s":"首两句高度评价庾信——文章越老越成熟、笔力凌云、才思纵横，为庾信正名；后两句讽刺今人——轻薄之徒嗤笑指点庾信流传的赋作，却不知「前贤畏后生」本是褒义，这里反用：你们这些后生如此狂妄，只怕前贤见了也要「畏惧」你们的无知！以戏谑之笔写严肃的文学批评，锋芒毕露而幽默隽永。","b":"杜甫《戏为六绝句》之一，针对当时文坛轻薄之徒妄议前贤而发，提出正确评价前代作家的态度，是最早的论诗绝句。","n":["庾信：南北朝文学家，由南入北，诗赋沉郁","老更成：越老越成熟、越有成就","凌云健笔：笔力雄健、直上云霄","意纵横：才思奔放自如","嗤点：嗤笑指点。嗤音chī","流传赋：流传下来的赋作","前贤畏后生：前贤也会畏惧后生可畏（反语，讽刺今人狂妄）"],"m":"庾信文章老更成，凌云健笔意纵横。","r":"四句按「赞庾信—健笔纵横—嗤点流传赋—前贤畏后生（反讽）」背；「嗤」读chī。"},"水槛遣心二首·一|杜甫":{"s":"首联写草堂环境——去郭轩敞、眺望辽远；颔联写澄江平岸、幽树多花，远景近景相映；颈联是名句——细雨中鱼儿跃出水面、微风里燕子斜飞，「出」「斜」二字极炼，以细腻观察写春日生机，体物工细；尾联以城中十万户与草堂两三家对比，以城市的繁华反衬此处的清幽，表达对闲适田园生活的喜爱，悠然自得。","b":"杜甫成都草堂时期《水槛遣心》二首之一，写凭栏远眺所见的江村春色与闲适心境。","n":["水槛：草堂水边的栏杆。槛音jiàn","遣心：排遣心情","去郭：离开城郭","轩楹敞：廊柱宽敞。轩楹，廊柱","眺望赊：眺望得很远。赊，远","澄江平少岸：清澈的江水上涨、几乎与岸平","幽树晚多花：幽静的树木傍晚时花开正多","城中十万户：成都城中有十万户","此地两三家：草堂附近只有两三家"],"m":"细雨鱼儿出，微风燕子斜。","r":"按「去郭眺望—澄江幽树—细雨微风—城中此地」背；「槛」读jiàn、「赊」读shē（远）。"},"不见|杜甫":{"s":"首联写不见李白已久、他佯狂避世，令人哀怜；颔联是千古名句——「世人皆欲杀，吾意独怜才」，以世人的态度与自己的立场强烈对比，在众人喊杀声中独持怜才之论，胆识与深情并见；颈联「敏捷诗千首，飘零酒一杯」以千首诗与一杯酒对举，才高命蹇的反差令人扼腕；尾联盼李白头白归匡山隐居，深情厚谊，感人至深。","b":"李白因永王李璘案获罪、流放夜郎（后遇赦），杜甫在成都闻讯而作，表达对李白的深切同情与对其才华的高度推崇。","n":["李生：李白","佯狂：假装癫狂","世人皆欲杀：当时世人都想杀李白（李白因永王李璘案下狱流放）","吾意独怜才：我唯独爱惜他的才华","敏捷诗千首：才思敏捷、作诗千首","飘零酒一杯：漂泊四方、以酒为伴","匡山：大匡山，在四川江油，李白少年读书处","头白好归来：头发白了正好归来隐居"],"m":"世人皆欲杀，吾意独怜才。敏捷诗千首，飘零酒一杯。","r":"按「不见佯狂—世人吾意—诗千首酒一杯—匡山归来」背；「怜才」是全诗核心。"},"武侯庙|杜甫":{"s":"首联写武侯庙的荒凉——丹青剥落、空山草木，以景写情，古庙的荒凉暗喻诸葛亮身后的寂寞；颔联「犹闻辞后主，不复卧南阳」是全诗核心：仿佛还能听到他辞别后主、北伐中原的誓言，可他再也不能回到南阳隐居了——「犹闻」写精神长存，「不复」写身死志决，鞠躬尽瘁、死而后已的形象跃然纸上，短短二十字，沉郁悲壮。","b":"杜甫大历元年（766）寓居夔州时谒武侯庙所作，缅怀诸葛亮鞠躬尽瘁、死而后已的一生。","n":["武侯庙：诸葛亮庙，在夔州（今重庆奉节）","遗庙丹青落：古庙中壁画的丹青颜料已经剥落","空山草木长：空山中草木茂盛生长。长音zhǎng","辞后主：辞别后主刘禅（指诸葛亮北伐前上《出师表》辞朝）","不复卧南阳：不能再回到南阳隐居了（诸葛亮早年隐居南阳隆中）"],"m":"犹闻辞后主，不复卧南阳。","r":"四句按「遗庙空山—辞后主—卧南阳」背；「长」读zhǎng；「犹闻」与「不复」的对比是核心。"},"秋兴八首·一|杜甫":{"s":"首联以玉露凋伤、巫山萧森奠定全诗萧瑟苍凉的基调；颔联「江间波浪兼天涌，塞上风云接地阴」是千古名句——波浪滔天、风云接地，既写峡中秋景的险恶，也暗喻时局的动荡不安，情景交融、气象雄浑；颈联「丛菊两开他日泪，孤舟一系故园心」，菊开两次、泪流两次，孤舟长系、故园心系，以工整对仗写羁旅之愁与乡思之苦；尾联以寒衣处处、白帝城高、暮砧急促收束，捣衣声中尽是思归之情，沉郁顿挫。","b":"杜甫大历元年（766）秋寓居夔州所作《秋兴八首》之首，是组诗的总纲，写夔州秋景与对长安故园的思念。","n":["玉露：白露如玉","凋伤：使草木凋落衰败","巫山巫峡：长江三峡中的巫峡，在今重庆巫山","萧森：萧瑟阴森","兼天涌：波浪滔天","接地阴：云层低垂、仿佛接地，阴晦","丛菊两开：杜甫到夔州已两年，菊开两次","他日泪：为往事（故乡）而流泪","孤舟一系：孤舟一系于此（不能归乡）","故园心：思念故园之心","催刀尺：赶制寒衣（刀尺为裁衣工具）","白帝城：在夔州，三峡入口","急暮砧：傍晚捣衣声急促。砧，捣衣石，音zhēn"],"m":"江间波浪兼天涌，塞上风云接地阴。丛菊两开他日泪，孤舟一系故园心。","r":"按「玉露萧森—江间塞上—丛菊孤舟—寒衣暮砧」背；「砧」读zhēn；此为《秋兴八首》总纲。"},"咏怀古迹五首·一|杜甫":{"s":"首联「支离东北风尘际，漂泊西南天地间」总写自己在安史之乱中流离东北、漂泊西南的身世，「天地间」三字写尽漂泊之广、之孤；颔联写三峡久留、五溪共居，滞留边地的苦闷；颈联以「羯胡无赖」指安禄山叛乱、「词客未还」写自己不能还朝，家国之恨交织；尾联以庾信自比——庾信萧瑟一生、暮年诗赋动江关，正是杜甫自身的写照，借古人写己悲，沉郁苍凉。","b":"杜甫《咏怀古迹》五首之一，借庾信身世自比，写自己在战乱中漂泊西南、不能还朝的身世之悲。","n":["支离：流离分散","东北风尘际：安史之乱中（东北方向战火纷飞）","漂泊西南：漂泊到西南（蜀地）","三峡楼台淹日月：在三峡一带的楼台间久留、虚度岁月。淹，滞留","五溪衣服共云山：与五溪少数民族共居云山之间。五溪，湘西黔东五条溪流，少数民族聚居地","羯胡事主终无赖：安禄山（羯胡）侍奉君主最终反复无常。羯胡，古族名，此指安禄山","词客衰时且未还：诗人（词客，杜甫自指）在衰乱之时尚未还朝","庾信平生最萧瑟：庾信一生最是凄凉萧瑟（庾信由南入北，常有乡关之思）","暮年诗赋动江关：晚年诗赋震撼江关（指其《哀江南赋》等名作）"],"m":"庾信平生最萧瑟，暮年诗赋动江关。","r":"按「支离漂泊—三峡五溪—羯胡词客—庾信自比」背；「羯」读jié；庾信典故是核心。"},"江汉|杜甫":{"s":"首联「江汉思归客，乾坤一腐儒」，以「思归客」与「腐儒」自指，漂泊之苦与自嘲之悲并见，「乾坤」二字写尽孤独；颔联「片云天共远，永夜月同孤」，以片云、孤月自比，情景交融，孤独之感深入骨髓；颈联是名句——落日喻暮年而壮心犹在，秋风起而病体渐疏，一「犹」一「欲」，老而弥坚的精神跃然纸上；尾联用老马识途典故，自比老马虽老仍有用，旷达中见自信，是杜甫晚年精神的写照。","b":"杜甫大历三年（768）漂泊江陵时所作，写暮年多病、漂泊江汉而壮心不已的情怀。","n":["江汉：长江汉水之间，指湖北江陵一带，杜甫晚年漂泊至此","思归客：思归故乡的游子，杜甫自指","乾坤一腐儒：天地间一个迂腐的书生（自谦兼自伤）","片云天共远：一片孤云与天共远","永夜月同孤：漫长的夜晚与月同孤","落日心犹壮：落日（喻暮年）时分壮心犹在","秋风病欲疏：秋风起时病体渐有好转。疏，疏缓、减轻","古来存老马：自古以来存养老马（用「老马识途」典故）","不必取长途：不一定非要它跑长途（自比老马，虽老仍有用）"],"m":"落日心犹壮，秋风病欲疏。","r":"按「思归腐儒—片云孤月—落日秋风—老马自比」背；「疏」是减轻；老马识途典故是核心。"},"孤雁|杜甫":{"s":"首联写孤雁不饮不啄、飞鸣念群，以反常行为写失群之痛；颔联「谁怜一片影，相失万重云」是名句——一片孤影与万重云层对比，孤雁的渺小与天空的辽阔形成强烈反差，「谁怜」二字写尽无人同情的孤独；颈联「望尽似犹见，哀多如更闻」，以幻觉写思念之深——望到极处仿佛看见同伴、哀鸣太多仿佛听到回应，痴情可悯；尾联以野鸦的无情喧闹反衬孤雁的孤独，物我同悲，沉郁动人。","b":"杜甫大历初年寓居夔州时所作，借孤雁失群写自己在战乱中漂泊、亲友离散的孤独与哀痛。","n":["不饮啄：不饮水不啄食","飞鸣声念群：边飞边鸣、声声呼唤同伴","一片影：一片孤影","相失万重云：在万重云层中失散","望尽似犹见：望到极处仿佛还能看见同伴","哀多如更闻：哀鸣太多仿佛又听到同伴的回应","野鸦无意绪：野鸦全不理会（孤雁的哀鸣）","鸣噪自纷纷：只顾自己纷纷喧闹"],"m":"谁怜一片影，相失万重云。","r":"按「不饮啄念群—一片影万重云—望尽哀多—野鸦反衬」背；「噪」读zào。"},"春宫怨|杜荀鹤":{"s":"首联写早被美貌耽误、欲妆临镜又慵，点出宫怨主题；颔联「承恩不在貌，教妾若为容」是全诗警句——既然受宠不在于容貌，叫我如何去梳妆呢？以反问写尽宫女的绝望与无奈，对宫廷制度的批判含蓄而深刻；颈联「风暖鸟声碎，日高花影重」，以乐景写哀，春光越美、宫怨越深；尾联写年年忆越溪女、相忆采芙蓉，以故乡的自由快乐反衬深宫的孤寂，余味悠然。","b":"杜荀鹤（晚唐诗人）这首宫怨诗写宫女因美貌入宫、却因承恩不在貌而无心梳妆，怀念故乡的自由生活。","n":["婵娟：美貌，此指美貌的宫女","误：被（美貌）耽误","临镜慵：对着镜子懒得梳妆。慵，慵懒","承恩：承受皇帝恩宠","若为容：怎样去梳妆打扮。若为，如何","鸟声碎：鸟鸣声细碎","花影重：花影层叠。重音chóng","越溪女：越地（今浙江）溪边的女子，此指西施当年浣纱的同伴","采芙蓉：采荷花（指当年在故乡的快乐生活）"],"m":"承恩不在貌，教妾若为容。","r":"按「婵娟误—承恩不在貌—风暖日高—忆越溪采芙蓉」背；「重」读chóng。"},"送人游吴|杜荀鹤":{"s":"首联「君到姑苏见，人家尽枕河」，以叮嘱口吻写苏州最典型的景观——家家临河而居，画面感极强；颔联「古宫闲地少，水港小桥多」，以「闲地少」写城市的繁华密集、以「小桥多」写水乡的特色，对仗工稳；颈联「夜市卖菱藕，春船载绮罗」，写夜市的热闹与春船的华丽，商业繁荣与水乡风情并见；尾联「遥知未眠月，乡思在渔歌」，由景入情，想象友人月下未眠、乡思尽在渔歌中，以景结情，余韵悠长。","b":"杜荀鹤这首诗写苏州水乡的独特风貌——人家尽枕河、水港小桥多，是描写江南水乡的千古名篇。","n":["姑苏：苏州的别称","枕河：房屋临河而建（枕，临、靠近）","古宫：古代吴国的宫殿","闲地少：空闲的土地少","水港：水巷","绮罗：丝织品，此指穿着华丽的游人","未眠月：月下尚未入眠","乡思：思乡之情","渔歌：渔人之歌"],"m":"君到姑苏见，人家尽枕河。古宫闲地少，水港小桥多。","r":"按「人家枕河—古宫小桥—夜市春船—未眠乡思」背；「枕」是临、靠近。"},"小松|杜荀鹤":{"s":"前两句写小松的生长环境——自小埋在深草里、如今才渐渐高出蓬蒿，以「刺头」写小松的坚韧与不起眼；后两句是全诗主旨——时人不识这将来能凌云的树木，一直等它真的高耸入云了才称赞它高，以小松喻人才，讽刺世人不识人才于微时、只会在人才成功后跟风称赞，咏物即咏人，寓意深刻。","b":"杜荀鹤这首咏物诗借小松不被时人识、直到凌云才被称高，讽刺世人不识人才、目光短浅。","n":["刺头：长满尖刺的小松苗头","蓬蒿：蓬草和蒿草，泛指野草","凌云木：可以高耸入云的树木（喻栋梁之材）","直待：一直等到","始道高：才说它高大"],"m":"时人不识凌云木，直待凌云始道高。","r":"四句按「刺头深草—出蓬蒿—不识凌云木—待凌云始道高」背；「凌云木」是比喻。"},"从军行|杨炯":{"s":"首联「烽火照西京，心中自不平」，以烽火报警写边情紧急、书生内心激愤；颔联「牙璋辞凤阙，铁骑绕龙城」，写出师出征、包围敌城的雄壮场面；颈联「雪暗凋旗画，风多杂鼓声」，以风雪昏暗、鼓声杂风写战场的艰苦与激烈，视听结合；尾联「宁为百夫长，胜作一书生」，直抒胸臆，宁愿做下级军官冲锋陷阵，也胜过做一介书生，投笔从戎的豪情跃然纸上，刚健豪迈。","b":"杨炯（初唐四杰之一）这首《从军行》写书生投笔从戎、渴望建功立业的豪情，是初唐边塞诗的名篇。","n":["西京：长安","牙璋：古代发兵的符信，此指将帅。璋音zhāng","凤阙：皇宫的美称，此指长安","铁骑：精锐的骑兵","龙城：匈奴祭天处，此指敌方要地","凋旗画：使旗帜上的彩绘褪色。凋，使……凋零","百夫长：下级军官，统率百人","胜作一书生：胜过做一个书生"],"m":"宁为百夫长，胜作一书生。","r":"按「烽火西京—辞阙围城—雪风战场—百夫长书生」背；「璋」读zhāng。"},"与浩初上人同看山寄京华亲故|柳宗元":{"s":"首两句「海畔尖山似剑铓，秋来处处割愁肠」，以剑铓喻尖山，写山形的尖利，而这尖山处处在割我的愁肠，以比喻写乡愁之痛，想象奇特；后两句「若为化得身千亿，散上峰头望故乡」，更进一层——恨不得化身千亿，分散到每座山峰顶上眺望故乡，以夸张写思乡之切、之深，奇想惊人，深情动人，是柳宗元贬谪诗的代表作。","b":"柳宗元被贬柳州（今广西）时，与僧人浩初同看山，寄给京城亲友，写被贬边地的思乡之苦。","n":["浩初上人：僧人浩初，上人是对僧人的敬称","京华亲故：京城的亲友","剑铓：剑锋。铓同「芒」，刀剑的尖端","割愁肠：割我的愁肠","若为化得身千亿：怎能把身体化作千亿个","散上峰头：分散到各个山峰顶上","望故乡：眺望故乡"],"m":"若为化得身千亿，散上峰头望故乡。","r":"四句按「尖山似剑—割愁肠—化身千亿—峰头望乡」背；「铓」同芒；化身千亿的夸张是核心。"},"登柳州城楼寄漳汀封连四州|柳宗元":{"s":"首联「城上高楼接大荒，海天愁思正茫茫」，登楼远眺、愁思茫茫，奠定全诗基调；颔联「惊风乱飐芙蓉水，密雨斜侵薜荔墙」，写急风乱吹荷花、密雨斜侵薜荔墙，既是眼前实景，也暗喻政治风暴对自己的打击，情景交融；颈联「岭树重遮千里目，江流曲似九回肠」，岭树遮望眼、江流如愁肠，以景写情，对仗工稳；尾联写共来百越文身之地、音书阻隔，同病相怜的悲慨深沉，是柳宗元七律的压卷之作。","b":"柳宗元元和十年（815）被贬柳州，与友人韩泰、韩晔、陈谏、刘禹锡同贬南方四州，登柳州城楼寄给四州友人，写共同的贬谪之悲与相思之苦。","n":["漳汀封连四州：漳州、汀州、封州、连州，指与柳宗元同时被贬的四位友人（韩泰、韩晔、陈谏、刘禹锡）","大荒：荒远的边地","海天愁思：愁思如海天般茫茫","惊风：急风","飐：吹动。音zhǎn","芙蓉水：长着荷花的水面","薜荔墙：爬满薜荔的墙。薜荔，常绿藤本植物","岭树：五岭上的树木","重遮：重重遮蔽","九回肠：愁肠九转（喻愁思之深）","百越：南方少数民族地区","文身：纹身（古越地风俗）","音书滞一乡：音信阻隔在各自的贬所。滞，阻隔"],"m":"惊风乱飐芙蓉水，密雨斜侵薜荔墙。岭树重遮千里目，江流曲似九回肠。","r":"按「高楼大荒—惊风密雨—岭树江流—百越音书」背；「飐」读zhǎn、「薜荔」读bìlì。"},"酬曹侍御过象县见寄|柳宗元":{"s":"首两句「破额山前碧玉流，骚人遥驻木兰舟」，写友人在碧玉般的江流中停舟，画面清丽；后两句「春风无限潇湘意，欲采蘋花不自由」，春风中充满了潇湘的诗情画意，想采一朵蘋花寄给友人却身不由己——「不自由」三字一语双关，既是被贬谪的不自由，也是对友人思念而不得相见的不自由，含蓄蕴藉，余味悠长。","b":"柳宗元被贬柳州时，友人曹侍御路过象县寄诗给他，他以此诗酬答，写对友人的思念与被贬不能自由归去的苦闷。","n":["曹侍御：曹姓侍御史","象县：今广西象县","见寄：寄诗给我","破额山：在柳州附近","碧玉流：碧绿如玉的江水","骚人：诗人，此指曹侍御","木兰舟：用木兰木造的船（船的美称）","潇湘意：潇湘一带的诗情画意（潇湘在湖南，柳宗元故乡附近）","蘋花：浮萍的花。蘋音pín","不自由：身不由己（指被贬不能自由归去）"],"m":"春风无限潇湘意，欲采蘋花不自由。","r":"四句按「碧玉流—木兰舟—潇湘意—采蘋不自由」背；「蘋」读pín；「不自由」双关是核心。"},"溪居|柳宗元":{"s":"首联「久为簪组累，幸此南夷谪」，说久被官职拖累，幸而被贬南方得以闲适，「幸」字是反语，含被贬的苦涩；颔联「闲依农圃邻，偶似山林客」，写与农田为邻、偶尔像山林隐士，闲适中有自嘲；颈联「晓耕翻露草，夜榜响溪石」，写清晨耕地翻草、夜晚摇船碰石，田园生活的画面清新；尾联「来往不逢人，长歌楚天碧」，写独来独往、对天长歌，闲适背后是孤独，乐中含悲，是柳宗元贬谪诗的复杂心境。","b":"柳宗元被贬永州（今湖南零陵）时，在溪边闲居，写农耕泛舟的闲适生活与被贬的复杂心情。","n":["簪组：古代官员的冠簪和印绶，代指官职。簪音zān","累：拖累","南夷谪：被贬到南方少数民族地区","农圃邻：与农田菜园为邻","山林客：山林中的隐士","榜：摇船的桨，此指摇船","响溪石：船桨碰击溪石发出声响","楚天：楚地的天空（永州古属楚）"],"m":"晓耕翻露草，夜榜响溪石。来往不逢人，长歌楚天碧。","r":"按「簪组累南夷谪—农圃山林—晓耕夜榜—长歌楚天」背；「簪」读zān、「榜」读bàng（摇船）。"},"小石潭记|柳宗元":{"s":"全文按游踪展开：先闻声（如鸣珮环）、再见潭（水尤清冽、全石为底），再写潭中鱼——「皆若空游无所依」以鱼写水之清，「佁然不动」「俶尔远逝」动静结合，「似与游者相乐」物我同乐；再写潭西南望，斗折蛇行、犬牙差互，写水源之幽；最后写坐潭上，四面竹树环合、寂寥无人、凄神寒骨，以其境过清不可久居，乐中转悲，贬谪的孤寂尽在「悄怆幽邃」四字中。","b":"柳宗元被贬永州时所作《永州八记》之一，写发现小石潭的经过与小石潭的清幽景色，是山水游记的千古名篇。","n":["篁竹：成林的竹子。篁音huáng","鸣珮环：像佩玉碰撞的声音。珮同「佩」","清冽：清凉。冽音liè","坻：水中高地。音chí","屿：小岛","嵁：不平的岩石。音kān","翠蔓：翠绿的藤蔓","蒙络摇缀：覆盖缠绕、摇动连结","参差披拂：长短不齐、随风飘拂","佁然：呆呆的样子。佁音yǐ","俶尔：忽然。俶音chù","翕忽：轻快敏捷。翕音xī","斗折蛇行：像北斗星那样曲折、像蛇那样蜿蜒前行","犬牙差互：像狗牙那样交错不齐","悄怆幽邃：寂静凄凉、幽深。悄怆音qiǎochuàng；邃音suì","隶而从者：跟随我来的人"],"m":"潭中鱼可百许头，皆若空游无所依。日光下澈，影布石上，佁然不动；俶尔远逝，往来翕忽，似与游者相乐。","r":"按「闻声见潭—潭中鱼—潭水源—潭上感受」背；生僻字多：篁huáng、冽liè、坻chí、嵁kān、佁yǐ、俶chù、翕xī、邃suì。"},"捕蛇者说|柳宗元":{"s":"全文用对比和衬托手法：先写异蛇之毒——触草木尽死、啮人无御之者，而永州人却争着捕蛇，以蛇之毒衬赋之重；再写蒋氏三代捕蛇、祖死父死己几死者数矣，而他却不愿更换差役——因为乡邻们被赋税逼得非死即徙，而他以捕蛇独存；悍吏来乡、鸡狗不宁，而他视缶中蛇尚存则弛然而卧，以捕蛇之「幸」衬赋税之「不幸」；最后引孔子「苛政猛于虎」作结，发出「赋敛之毒有甚是蛇」的呐喊，现实主义的批判力透纸背。","b":"柳宗元被贬永州时所作，通过捕蛇者蒋氏的遭遇，揭露中唐时期赋税苛重、民不聊生的社会现实，提出「苛政猛于虎」的批判。","n":["黑质而白章：黑色的底子、白色的花纹","腊之以为饵：把它晾干做成药饵。腊音xī，晾干","已大风：治愈麻风病。已，治愈；大风，麻风病","挛踠：手脚弯曲不能伸展。挛音luán、踠音wǎn","瘘疠：脖子肿和恶疮。瘘音lòu、疠音lì","去死肌：去除坏死的肌肉","杀三虫：杀死人体内的寄生虫","岁赋其二：每年征收两次","当其租入：抵他的租税","莅事者：管这事的官吏。莅音lì","更若役：更换你的差役","复若赋：恢复你的赋税","生日蹙：生活一天天窘迫。蹙音cù","殚其地之出：把地里的出产全部拿出。殚音dān","竭其庐之入：把家里的收入全部用尽","顿踣：跌倒在地。踣音bó","隳突：骚扰冲撞。隳音huī","恂恂：小心谨慎的样子。恂音xún","缶：瓦罐。音fǒu","弛然：放心的样子","食之：喂养它。食音sì","观人风者：考察民情的官员。人风，民风（避李世民讳）"],"m":"孰知赋敛之毒有甚是蛇者乎！","r":"按「异蛇之毒—蒋氏遭遇—乡邻之苦—悍吏骚扰—赋敛毒于蛇」背；生僻字多：腊xī、挛luán、踠wǎn、瘘lòu、疠lì、莅lì、蹙cù、殚dān、踣bó、隳huī、恂xún、缶fǒu。"},"黔之驴|柳宗元":{"s":"全文按虎对驴的认识过程展开：初见驴以为神、藏林偷看；驴一鸣虎大骇远遁、以为要咬自己；往来视之觉无异能、益习其声、终不敢搏；稍近益狎、荡倚冲冒，驴不胜怒蹄之，虎才识破其技不过如此——跳踉大㘎、断喉尽肉而去。故事生动地写出虎从惧到识的心理变化，也写出驴的外强中干；末段议论「形之庞也类有德，声之宏也类有能」，点明寓意——没有真本领而虚张声势，终会暴露，讽刺深刻。","b":"柳宗元被贬永州时所作《三戒》之一，借驴被虎识破而食的故事，讽刺那些外强中干、虚有其表的人。","n":["黔：贵州一带的简称","好事者：喜欢多事的人","庞然大物：庞大的家伙","蔽林间窥之：藏在树林里偷看它。窥音kuī","慭慭然：小心谨慎的样子。慭音yìn","莫相知：不知道它是什么东西","大骇：非常害怕","远遁：逃到远处。遁音dùn","且噬己：将要咬自己。噬音shì","异能：特殊的本领","益习其声：渐渐习惯了它的叫声","终不敢搏：始终不敢扑击它","益狎：更加亲近而不庄重。狎音xiá","荡倚冲冒：摇晃、倚靠、冲撞、冒犯","不胜怒：禁不住发怒。胜音shēng","蹄之：用蹄子踢它","技止此耳：本领不过如此罢了","跳踉：跳跃。踉音liáng","㘎：虎叫声。音hǎn","类有德：好像有德行","类有能：好像有本领"],"m":"虎因喜，计之曰：「技止此耳！」","r":"按「虎初见驴—驴鸣虎逃—虎识驴—驴蹄虎—虎食驴—议论」背；生僻字：窥kuī、慭yìn、遁dùn、噬shì、狎xiá、踉liáng、㘎hǎn。"},"杂曲歌辞·独不见|沈佺期":{"s":"首联「卢家小妇郁金堂，海燕双栖玳瑁梁」，以华丽的居室和海燕双栖反衬少妇的孤独；颔联「九月寒砧催下叶，十年征戍忆辽阳」是名句——九月寒砧声催落树叶，丈夫征戍辽阳已十年，捣衣声与落叶声交织，时间之长、思念之深尽在其中；颈联「白狼河北音书断，丹凤城南秋夜长」，写音信断绝、秋夜漫长，两地相思；尾联「谁知含愁独不见，使妾明月照流黄」，以明月照流黄（征衣）作结，物是人非，愁思不尽，是初唐七律的成熟之作。","b":"沈佺期（初唐诗人）这首乐府诗写少妇思念远征辽阳的丈夫，是初唐闺怨诗的名篇，对后世影响很大。","n":["卢家小妇：莫愁女（古乐府「河中之水向东流，洛阳女儿名莫愁，十五嫁为卢家妇」），此泛指少妇","郁金堂：用郁金香涂壁的华丽堂屋","玳瑁梁：用玳瑁装饰的屋梁。玳瑁音dàimào，海龟类，甲壳可作装饰","寒砧：寒风中的捣衣声。砧音zhēn","催下叶：催促树叶落下","辽阳：今辽宁辽阳，唐代东北边防要地，此指征人戍守之地","白狼河：即今辽宁大凌河，在辽阳北","丹凤城：指长安（传说秦穆公女弄玉吹箫引凤，凤降咸阳，故称丹凤城）","流黄：黄色的绢，此指征人衣（或指帷帐）"],"m":"九月寒砧催下叶，十年征戍忆辽阳。","r":"按「郁金堂玳瑁梁—寒砧辽阳—白狼丹凤—明月流黄」背；「玳瑁」读dàimào、「砧」读zhēn。"},"商山早行|温庭筠":{"s":"首联「晨起动征铎，客行悲故乡」，清晨车铃响起、游子悲故乡，点明题旨；颔联「鸡声茅店月，人迹板桥霜」是千古名句——十个字六个名词（鸡声、茅店、月、人迹、板桥、霜），不用动词形容词，纯用意象叠加，勾勒出一幅清冷的早行图，「状难写之景如在目前」；颈联「槲叶落山路，枳花明驿墙」，写山路槲叶、驿墙枳花，继续写早行所见；尾联「因思杜陵梦，凫雁满回塘」，以昨夜梦中故乡凫雁满塘的温暖反衬早行的清冷，乡愁更深，余味悠然。","b":"温庭筠（晚唐诗人）这首诗写清晨离开商山（在今陕西商洛）时的所见所感，是写羁旅乡愁的千古名篇。","n":["征铎：车行时的铃声。铎音duó","悲故乡：为故乡而悲","茅店：乡村客店","板桥：木板桥","槲叶：槲树的叶子。槲音hú，落叶乔木","枳花：枳树的花。枳音zhǐ，灌木或小乔木","明驿墙：照亮驿站的墙","杜陵梦：梦见杜陵（杜甫祖籍，在长安东南，此指故乡）","凫雁：野鸭和大雁。凫音fú","回塘：曲折的池塘"],"m":"鸡声茅店月，人迹板桥霜。","r":"按「征铎悲乡—鸡声茅店—槲叶枳花—杜陵梦」背；「铎」读duó、「槲」读hú、「枳」读zhǐ、「凫」读fú；颔联六个名词意象是核心。"},"送人东游|温庭筠":{"s":"首联「荒戍落黄叶，浩然离故关」，以荒戍黄叶的萧瑟反衬友人浩然离去的豪迈；颔联「高风汉阳渡，初日郢门山」，写友人行程所经——汉阳渡的秋风、郢门山的初日，以地名入对，气象阔大；颈联「江上几人在，天涯孤櫂还」是名句——江上旧友还有几人在？你却要孤舟远游天涯，对故人凋零的感慨与对友人孤身的担忧交织；尾联「何当重相见，尊酒慰离颜」，以盼重逢、把酒慰别作结，深情厚谊，余味不尽。","b":"温庭筠这首诗写送别友人东游，表达对友人的惜别与对故人凋零的感慨。","n":["荒戍：荒废的戍楼、营垒","浩然：豪迈的样子","故关：故乡的关隘","高风：秋风","汉阳渡：汉阳的渡口（在今武汉）","郢门山：荆门山（在今湖北宜昌，郢为楚都）","江上几人在：江上（指友人中）还有几人在","孤櫂：孤舟。櫂同「棹」，船桨，代指船","尊酒：一杯酒。尊同「樽」","离颜：离别后的容颜"],"m":"江上几人在，天涯孤櫂还。","r":"按「荒戍浩然—高风初日—江上孤櫂—何当尊酒」背；「櫂」同棹、「尊」同樽。"},"望江南·梳洗罢|温庭筠":{"s":"全词仅二十七个字，却写尽思妇一天的等待：「梳洗罢」写她精心梳妆、满怀希望；「独倚望江楼」写她独自登楼、痴痴等待；「过尽千帆皆不是」是全词核心——上千只船都过去了，都不是丈夫的船，希望一次次破灭；「斜晖脉脉水悠悠」以夕阳含情、江水悠长写她的失望与愁思，情景交融；「肠断白蘋洲」以白蘋洲（当年送别之处）作结，愁肠寸断。短短小令，情节完整、情感跌宕，是词中精品。","b":"温庭筠这首《望江南》（又名《忆江南》）写思妇登楼望归、从希望到失望的全过程，是晚唐小令的千古名篇。","n":["梳洗罢：梳妆完毕","望江楼：临江的楼","过尽千帆：上千只船都过去了","皆不是：都不是（丈夫所乘的船）","斜晖脉脉：夕阳含情不语。脉脉，含情相视貌，音mòmò","悠悠：悠长不尽","白蘋洲：长满白蘋的水洲（蘋，水草，古人常采以赠别）。蘋音pín"]},"生查子·二|牛希济":{"s":"上片「新月曲如眉，未有团𪢮意。红豆不堪看，满眼相思泪」，以新月如眉、尚未团圆起兴，以红豆不堪看、满眼相思泪写相思之苦；下片「终日劈桃穰，人在心儿里」是名句——整天劈桃核，因为桃仁（「人」谐音）在核儿里，双关所爱之人在自己心里，比喻巧妙；「两朵隔墙花，早晚成连理」，以隔墙花终会连理比喻两人终会团圆，表达对爱情的坚定信念，语言朴素而情意深挚。","b":"牛希济（五代前蜀词人）这首《生查子》写女子对爱情的忠贞与对团圆的渴望，是五代词的名篇。","n":["团𪢮：团圆。𪢮同「圞」，音luán","红豆：相思豆，象征爱情","不堪看：不忍心看","桃穰：桃核里的仁。穰同「瓤」","人在心儿里：人（所爱之人）在我心里","连理：两棵树的枝干连生在一起，喻恩爱夫妻"],"m":"终日劈桃穰，人在心儿里。两朵隔墙花，早晚成连理。","r":"按「新月团𪢮—红豆相思泪—劈桃穰人在心—隔墙花成连理」背；「𪢮」同圞、「穰」同瓤；「人在心儿里」谐音双关是核心。"},"山中|王勃":{"s":"首两句「长江悲已滞，万里念将归」，以长江水之「滞」写自己滞留异乡之悲，以「万里」写空间之远、「将归」写归心之切，情景交融；后两句「况属高风晚，山山黄叶飞」，以秋风萧瑟、黄叶纷飞的秋景渲染乡愁，「山山」叠字写出秋意的辽阔与无处不在，以景结情，不言愁而愁自深，短短二十字，意境苍凉，是初唐五绝的精品。","b":"王勃（初唐四杰之首）这首小诗写在长江边滞留、秋风起时思念故乡的心情，是初唐五言绝句的名篇。","n":["长江悲已滞：长江水仿佛也为我滞留而悲（滞，滞留，指自己久留异乡）","万里念将归：在万里之外思念将要归去","况属：更何况正值","高风：秋风","山山黄叶飞：座座山上黄叶纷飞"],"m":"况属高风晚，山山黄叶飞。","r":"四句按「长江悲滞—万里念归—高风晚—山山叶飞」背；「滞」读zhì；以景结情是核心。"},"新嫁娘词三首·一|王建":{"s":"这首小诗截取新婚生活的一个有趣片段：新娘刚到婆家，邻居还不认识她，她坐在床上一动不动（堆堆），新郎来到门边，她却满口索要钱财——写的是新婚时的讨喜钱习俗，以口语化的语言、生动的细节，写出新婚生活的诙谐与热闹，朴素自然，富有民间生活气息，体现王建乐府诗善于捕捉生活细节的特色。","b":"王建（中唐诗人）《新嫁娘词》三首之一，写新婚次日的一个生活场景，语言口语化、富有生活气息。（注意：传诵的「三日入厨下」是其三，此为其一。）","n":["堆堆：形容新娘端坐着一动不动的样子","郎来傍门户：新郎来到门边","满口索钱财：满口索要钱财（指婚礼中的讨喜钱习俗）"],"m":"郎来傍门户，满口索钱财。","r":"四句按「邻人未识—床上堆堆—郎来门户—满口索钱」背；此为《新嫁娘词》其一，与「三日入厨下」（其三）不同。"},"雨过山村|王建":{"s":"首两句「雨里鸡鸣一两家，竹溪村路板桥斜」，以鸡鸣、竹溪、村路、板桥勾勒出一幅清新的山村雨景图，「一两家」写出山村的幽静；后两句「妇姑相唤浴蚕去，闲看中庭栀子花」，写嫂嫂小姑互相呼唤着去浴蚕，庭院里只有栀子花在雨中静静开放——以人的忙碌与花的「闲」对比，写出山村农事的繁忙与生活的宁静美好，语言清新自然，充满田园气息。","b":"王建这首小诗写山村雨后的景象与农妇浴蚕的农事活动，是中唐田园诗的名篇。","n":["雨里鸡鸣一两家：雨天里只有一两户人家的鸡鸣","竹溪村路板桥斜：竹林、溪水、村路、板桥斜横","妇姑：嫂嫂和小姑（或婆媳）","相唤：互相呼唤","浴蚕：浸洗蚕种（养蚕的准备工作）","闲看：悠闲地看着","栀子花：常绿灌木，花白色芳香，初夏开放"],"m":"妇姑相唤浴蚕去，闲看中庭栀子花。","r":"四句按「雨里鸡鸣—竹溪板桥—妇姑浴蚕—闲看栀花」背；「闲」是反衬，以花之闲衬人之忙。"},"十五夜望月寄杜郎中|王建":{"s":"首两句「中庭地白树栖鸦，冷露无声湿桂花」，写中秋月夜的清幽——月光照地如霜、树上栖鸦、冷露无声打湿桂花，视觉、听觉、触觉交织，意境清冷幽美；后两句「今夜月明人尽望，不知秋思在谁家」是名句——中秋之夜人人都在望月，可那秋日的思念究竟落在谁家呢？以委婉的疑问写自己的思乡之情，不直说自己思家，而说「不知在谁家」，含蓄蕴藉，余味悠长，是中秋诗的绝唱。","b":"王建这首中秋望月诗写中秋之夜人人望月思乡的情景，是写中秋的千古名篇。","n":["十五夜：农历八月十五中秋夜","杜郎中：一位杜姓郎中（官职）","地白：月光照地洁白如霜","树栖鸦：树上栖息着乌鸦","冷露：清冷的露水","湿桂花：打湿了桂花","人尽望：人人都在仰望（明月）","秋思：秋日的思念（此指中秋思乡之情）","在谁家：（那秋思）落在谁的家中呢"],"m":"今夜月明人尽望，不知秋思在谁家。","r":"四句按「地白栖鸦—冷露桂花—人尽望—秋思谁家」背；「不知秋思在谁家」的委婉是核心。"},"横吹曲辞·出塞·一|王昌龄":{"s":"首句「秦时明月汉时关」以互文手法，将明月与关隘的历史追溯到秦汉，千年的边关、千年的征战，时空感极强；次句「万里长征人未还」写征人久戍不归的悲剧，「万里」写空间之远、「未还」写时间之久；后两句「但使龙城飞将在，不教胡马度阴山」，以假设写出对良将的渴望——只要有李广那样的飞将军在，就不会让胡马越过阴山，既是对历史名将的追慕，也是对当朝将帅无能的讽刺，气势雄浑，意境苍凉，是边塞诗的巅峰之作。","b":"王昌龄（盛唐边塞诗人）这首《出塞》被明代李攀龙推为唐人七绝压卷之作，写边塞将士对良将的渴望与对和平的向往。","n":["秦时明月汉时关：秦汉时的明月和关隘（互文，即明月和关隘自秦汉以来一直如此）","万里长征：远征万里","人未还：出征的人还没有回来","但使：只要","龙城飞将：龙城（匈奴祭天处）的飞将军李广（一说卫青曾龙城大捷）","不教：不让","胡马：胡人的战马","度阴山：越过阴山（阴山在今内蒙古，是中原与北方游牧民族的界山）"],"m":"秦时明月汉时关，万里长征人未还。但使龙城飞将在，不教胡马度阴山。","r":"四句按「秦汉明月关—万里人未还—但使飞将在—不教度阴山」背；「龙城飞将」有李广/卫青两说；互文手法是核心。"},"相和歌辞·从军行·四|王昌龄":{"s":"首两句「青海长云暗雪山，孤城遥望雁门关」，以青海长云、雪山暗淡、孤城遥望写边塞的荒凉与将士的孤独，境界阔大而苍凉；后两句「黄沙百战穿金甲，不破楼兰终不还」是千古名句——在黄沙中经历百战、铠甲都磨穿了，不打败敌人绝不回去，「百战」写战斗之多、「穿金甲」写战斗之苦，「终不还」写将士的坚定誓言，以艰苦的环境反衬将士的豪情，刚健豪迈，是盛唐气象的典型体现。","b":"王昌龄《从军行》七首之四（库文标为「四」），写边塞将士在艰苦环境中立下不破敌不还的誓言，是盛唐边塞诗的名篇。","n":["青海：青海湖，在今青海","长云：层层浓云","暗雪山：使雪山（祁连山）暗淡","孤城：孤立的城池（指玉门关）","遥望：远远望去","雁门关：在今山西代县，北方要塞（通行本作「玉门关」，库文作「雁门关」）","黄沙百战：在黄沙中经历百战","穿金甲：磨穿了金属铠甲","不破楼兰：不打败楼兰（楼兰，西域古国，此泛指敌方）","终不还：终究不回去"],"m":"黄沙百战穿金甲，不破楼兰终不还。","r":"四句按「青海雪山—孤城遥望—黄沙百战—不破楼兰终不还」背；库文作「雁门关」，通行本多作「玉门关」，以库文为准。"},"采莲曲二首·一|王昌龄":{"s":"首两句「吴姬越艳楚王妃，争弄莲舟水湿衣」，以吴姬越艳楚王妃形容采莲女的美丽，写她们争着划莲船、水打湿衣裳的欢快，活泼生动；后两句「来时浦口花迎入，采罢江头月送归」是名句——来时渡口的荷花迎接她们进入，采完莲后江边的月亮送她们归去，以花迎月送的拟人手法写采莲生活的美好，人与自然融为一体，意境清新优美，语言明丽自然，是王昌龄七绝的清新之作。","b":"王昌龄这首《采莲曲》写江南采莲女的美丽与采莲生活的欢快，是盛唐山水田园诗的清新之作。","n":["吴姬越艳楚王妃：吴地的美女、越地的艳女、楚王的妃嫔（形容采莲女之美）","争弄莲舟：争着划动采莲船","水湿衣：水打湿了衣裳","浦口：水边、渡口","花迎入：荷花迎接（采莲女）进入","采罢：采完莲","江头：江边","月送归：月亮送（采莲女）归去"]},"春宫曲|王昌龄":{"s":"首两句「昨夜风开露井桃，未央前殿月轮高」，以春风吹开井边桃花、未央前殿月轮高悬写宫廷春夜的美好，「昨夜」点明时间；后两句「平阳歌舞新承宠，帘外春寒赐锦袍」，以平阳歌舞（卫子夫故事）写宫女新近受宠，皇帝因帘外春寒赐给她锦袍——全诗不写失宠者的怨，只写得宠者的荣，以他人之宠反衬自己之失，含蓄蕴藉，怨而不怒，是宫怨诗的高妙之作。","b":"王昌龄这首《春宫曲》写宫女新承宠的情景，以他人得宠反衬自己失宠，是宫怨诗的含蓄之作。","n":["风开露井桃：春风吹开了井边的桃花。露井，没有井亭覆盖的井","未央：未央宫，汉代宫殿，此指唐宫","前殿：宫殿的前殿","月轮高：月亮高高升起","平阳：平阳公主（汉武帝的姐姐，其家歌女卫子夫后为皇后，此以平阳歌舞指宫女）","新承宠：新近受到宠爱","帘外春寒：帘外春寒料峭","赐锦袍：（皇帝）赐给锦袍"],"m":"平阳歌舞新承宠，帘外春寒赐锦袍。","r":"四句按「风开露井桃—未央月轮高—平阳新承宠—春寒赐锦袍」背；以得宠衬失宠的反衬手法是核心。"},"西宫春怨|王昌龄":{"s":"首两句「西宫夜静百花香，欲卷珠帘春恨长」，写西宫夜静、百花飘香，宫女想卷珠帘却因春恨悠长而作罢，「欲卷」与「不卷」的矛盾写尽她的犹豫与愁闷；后两句「斜抱云和深见月，朦胧树色隐昭阳」是名句——她斜抱着琴瑟、深深望着月亮，朦胧的树色遮蔽了昭阳宫（君王所在之处），以「斜抱」「深见」的动作写她的痴情与失望，以树色隐昭阳写她见不到君王的惆怅，情景交融，含蓄不尽，是宫怨诗的精品。","b":"王昌龄这首《西宫春怨》写失宠宫女在西宫春夜抱琴望月、思念君王的情景，是宫怨诗的名篇。","n":["西宫：西边的宫殿（失宠宫女所居）","百花香：百花飘香","珠帘：珍珠串成的帘子","春恨长：春愁悠长","斜抱：斜抱着","云和：云和（地名，产琴瑟，此代指琴瑟）","深见月：（透过帘子）深深看见月亮","朦胧树色：朦胧的树影","隐昭阳：遮蔽了昭阳宫（昭阳宫是得宠妃子所居，汉成帝时赵飞燕居昭阳宫）"],"m":"斜抱云和深见月，朦胧树色隐昭阳。","r":"四句按「西宫夜静—欲卷珠帘—斜抱见月—树色隐昭阳」背；「昭阳」代指君王/得宠者；以景结情是核心。"},"长信秋词五首·一|王昌龄":{"s":"首两句「金井梧桐秋叶黄，珠帘不卷夜来霜」，以金井梧桐、秋叶黄、夜来霜写长信宫秋夜的清冷，「珠帘不卷」写宫女的孤寂无心；后两句「熏笼玉枕无颜色，卧听南宫清漏长」是名句——熏笼玉枕都失去了光彩（暗指主人公的孤寂憔悴），她躺着听南宫（君王所在）传来的清晰漏声，一夜漫长，以「无颜色」写物之冷、以「清漏长」写夜之长，失宠之苦尽在其中，含蓄凄清，是宫怨诗的典范。","b":"王昌龄《长信秋词》五首之一（库文标为「一」），写失宠宫女在长信宫秋夜的孤寂，是宫怨诗的名篇。（长信宫用汉代班婕妤失宠后居长信宫的典故。）","n":["金井：井栏有金属装饰的井","秋叶黄：秋天的梧桐叶黄了","珠帘不卷：珍珠帘子不卷起来","夜来霜：夜里下了霜","熏笼：熏香用的竹笼（取暖熏香用）","玉枕：玉制的枕头","无颜色：没有光彩（暗指主人公孤寂）","卧听：躺着听","南宫：南面的宫殿（君王/得宠者所居）","清漏长：清晰的漏壶声悠长（漏壶，古代计时工具）"],"m":"熏笼玉枕无颜色，卧听南宫清漏长。","r":"四句按「金井秋叶—珠帘夜霜—熏笼玉枕—卧听南宫漏」背；长信宫/班婕妤典故是背景；以冷景写怨情是核心。"},"青楼曲二首·一|王昌龄":{"s":"首两句「白马金鞍从武皇，旌旗十万宿长杨」，写丈夫白马金鞍随从皇帝狩猎、十万旌旗驻扎长杨，场面盛大，气象雄浑；后两句「楼头小妇鸣筝坐，遥见飞尘入建章」是名句——少妇在楼上弹着筝，远远望见飞扬的尘土进入建章宫（知道丈夫归来了），以少妇的悠闲与丈夫的荣耀对比，写出盛唐时期将士的荣耀与家庭的和乐，视角独特，气象开阔，是王昌龄七绝的别致之作。","b":"王昌龄这首《青楼曲》写少妇在楼上望见丈夫随从皇帝狩猎归来的情景，以少妇的视角写盛唐气象，是边塞/宫廷诗的别致之作。","n":["白马金鞍：白马配金鞍","从武皇：跟随汉武帝（此指唐玄宗）","旌旗十万：十万大军的旌旗","宿长杨：驻扎在长杨宫（长杨宫，汉代行宫，在今陕西周至，汉武帝曾在此狩猎）","楼头小妇：楼上的少妇","鸣筝：弹筝","飞尘：飞扬的尘土","建章：建章宫（汉代宫殿，此指唐宫）"],"m":"楼头小妇鸣筝坐，遥见飞尘入建章。","r":"四句按「白马金鞍—旌旗长杨—楼头鸣筝—飞尘建章」背；以少妇视角写盛唐气象是特色。"},"闺怨|王昌龄":{"s":"首两句「闺中少妇不曾愁，春日凝妆上翠楼」，写少妇本来没有忧愁，春日精心梳妆登上翠楼，「不曾愁」为后文的「悔」作铺垫；后两句「忽见陌头杨柳色，悔教夫婿觅封侯」是千古名句——她忽然看见路边的杨柳春色，顿时后悔让丈夫去从军觅封侯了，「忽见」写心理转变的突然，「悔」字写尽少妇对丈夫的思念与对功名的反思，柳色既写春景，又暗含「折柳送别」的回忆，以乐景写哀，心理刻画细腻入微，是七绝中的精品。","b":"王昌龄这首《闺怨》写少妇春日登楼、忽见杨柳春色而后悔让丈夫从军觅封侯的心理变化，是写闺怨的千古名篇。","n":["闺中少妇：闺房中的年轻妻子","不曾愁：从来没有忧愁","凝妆：精心梳妆打扮","翠楼：华美的楼","陌头：路边","杨柳色：杨柳的春色","悔教：后悔让","夫婿：丈夫","觅封侯：去寻求封侯（指从军建功立业）"],"m":"忽见陌头杨柳色，悔教夫婿觅封侯。","r":"四句按「不曾愁—凝妆上楼—忽见杨柳—悔教觅封侯」背；「悔」的心理转变是核心；折柳送别的联想是关键。"},"听流人水调子|王昌龄":{"s":"首两句「孤舟微月对枫林，分付鸣筝与客心」，以孤舟、微月、枫林写环境的凄清，写弹筝人将一腔心事托付给筝声、打动了游子的心；后两句「岭色千重万重雨，断弦收与泪痕深」是名句——山岭的景色在层层雨幕中朦胧不清，弹筝人弹断了琴弦、收起来时泪痕已深，以「千重万重雨」写环境的凄迷、以「断弦」「泪痕深」写弹筝人的悲苦，音乐、景色、身世融为一体，凄婉动人，是王昌龄七绝的深沉之作。","b":"王昌龄这首诗写在孤舟微月中听流落艺人弹《水调子》、为其凄苦身世感动的情景，是写音乐与身世的名篇。","n":["流人：流落江湖的人（此指弹筝的艺人）","水调子：即《水调歌》，曲调名，声情凄苦","分付：托付、交给","鸣筝：弹筝","客心：游子的心","岭色：山岭的景色","千重万重：层层叠叠","断弦：弹断了琴弦","收与：收起来给","泪痕深：泪痕很深"],"m":"岭色千重万重雨，断弦收与泪痕深。","r":"四句按「孤舟微月—分付鸣筝—岭色千重雨—断弦泪痕深」背；以景衬情、以乐写悲是核心。"},"野望|王绩":{"s":"首联「东皋薄暮望，徙倚欲何依」，写傍晚在东皋眺望、徘徊无依，「欲何依」用曹操典故写孤独；颔联「树树皆秋色，山山唯落晖」是名句——树树秋色、山山落晖，以「树树」「山山」叠字写秋景的辽阔与萧瑟，意境开阔；颈联「牧人驱犊返，猎马带禽归」，写牧人猎人傍晚归来，以人的活动反衬自己的孤独；尾联「相顾无相识，长歌怀采薇」，写与众人互不相识，只能长歌怀念伯夷叔齐，表达隐居不仕的志向，孤独中见清高，是初唐律诗的奠基之作。","b":"王绩（初唐诗人，自号东皋子）这首《野望》写傍晚在东皋眺望所见的秋景与孤独的心境，是初唐五言律诗的成熟之作，也是现存最早的五言律诗之一。","n":["东皋：东边的高地（王绩隐居处，在今山西河津）。皋音gāo","薄暮：傍晚","徙倚：徘徊、来回走。徙音xǐ","欲何依：想要依靠什么呢（用曹操「绕树三匝，何枝可依」意，写孤独无依）","树树皆秋色：每棵树都呈现秋天的颜色","山山唯落晖：每座山都只有落日的余晖","牧人驱犊返：牧人赶着牛犊回来。犊音dú，小牛","猎马带禽归：猎人骑着马带着猎物回来","相顾无相识：互相看看都不认识","长歌怀采薇：长声歌唱、怀念采薇而食的伯夷叔齐（采薇，代指隐居不仕）"],"m":"树树皆秋色，山山唯落晖。","r":"按「东皋望徙倚—树树山山—牧人猎马—相顾怀采薇」背；「皋」读gāo、「徙」读xǐ、「犊」读dú；采薇典故是核心。"},"春中田园作|王维":{"s":"首联以春鸠鸣、杏花白写春日田园的明丽，视听结合；颔联写农人持斧伐桑、荷锄看泉，农事繁忙而有序；颈联写归燕识巢、旧人看新历，以燕子的恋旧与人的迎新写岁月流转；尾联「临觞忽不御，惆怅远行客」陡然一转，端杯不饮、惆怅远行，由田园之乐转入对漂泊者的同情，乐中含悲，余味悠然。","b":"王维这首诗写春日田园的生机与农忙，结尾由乐景转入对远行客的惆怅，是其田园诗的名篇。","n":["春鸠：春天的斑鸠","伐远扬：砍掉过长高扬的桑枝（为了让桑树长得更好）","荷锄觇泉脉：扛着锄头察看泉水的脉络。觇音chān，察看","归燕识故巢：归来的燕子认得旧巢","新历：新的历书","临觞忽不御：端起酒杯忽然又不饮了。觞，酒杯；御，进、用","远行客：远行在外的人（诗人自指，或指思念的远行之人）"],"m":"屋上春鸠鸣，村边杏花白。","r":"按「春鸠杏花—伐桑觇泉—归燕新历—临觞惆怅」背；「觇」读chān、「觞」读shāng。"},"新晴野望|王维":{"s":"首联「新晴原野旷，极目无氛垢」总写雨后初晴、原野开阔、一尘不染；颔联写郭门临渡、村树连溪，层次分明；颈联「白水明田外，碧峰出山后」是名句——田外白水闪亮、山后碧峰显现，「明」「出」二字极炼，以动写静，色彩明丽；尾联写农月无闲人、倾家事南亩，以人的忙碌反衬田园的生机，画面开阔而充满生活气息，是王维「诗中有画」的典范。","b":"王维这首诗写雨后初晴眺望原野所见的明丽景色与农忙景象，是其山水田园诗的名篇。","n":["新晴：雨后初晴","原野旷：原野开阔","极目无氛垢：放眼望去没有尘埃。氛垢，尘埃","郭门：外城的门","谿口：溪水的入口。谿同「溪」","白水明田外：田埂外白水闪亮","碧峰出山后：青山从山后显现","农月：农忙月份","倾家事南亩：全家都到田里耕作。南亩，田地"],"m":"白水明田外，碧峰出山后。","r":"按「新晴原野—郭门村树—白水碧峰—农月倾家」背；「谿」同溪；「明」「出」是炼字。"},"辋川闲居赠裴秀才迪|王维":{"s":"首联「寒山转苍翠，秋水日潺湲」写寒山由苍转翠、秋水日日潺湲，色彩与声音交织；颔联「倚杖柴门外，临风听暮蝉」写诗人拄杖柴门、临风听蝉，神态悠然；颈联「渡头余落日，墟里上孤烟」是千古名句——渡口边还留着落日的余晖，村落里升起一缕炊烟，以「余」「上」二字写尽黄昏的宁静与温暖，是「诗中有画」的典范；尾联以接舆比裴迪、以五柳自比，写两人的醉歌闲逸，物我两忘，意境清远。","b":"王维晚年隐居辋川时，与好友裴迪唱和，这首诗写秋日傍晚辋川的清幽景色与两人的闲逸生活，是山水田园诗的千古名篇。","n":["辋川：王维在陕西蓝田的辋川别业","裴秀才迪：裴迪，王维的好友，秀才是对读书人的称呼","苍翠：青绿","潺湲：水缓慢流动的样子。音chányuán","倚杖：拄着拐杖","暮蝉：秋蝉","渡头：渡口","墟里：村落","孤烟：一缕炊烟","复值：又遇到","接舆：春秋楚国隐士接舆，此指裴迪（以隐士比之）","五柳：五柳先生陶渊明，此指王维自己（以隐士自比）"],"m":"倚杖柴门外，临风听暮蝉。渡头余落日，墟里上孤烟。","r":"按「寒山秋水—倚杖听蝉—渡头落日—接舆五柳」背；「潺湲」读chányuán；接舆、五柳两个典故是核心。"}};
